// Karteikarten-Datenbank. Jede Karte: {id, module, subtopic, front, back}
// module/subtopic-IDs müssen zu data/curriculum.js passen.
window.FLASHCARDS = [
  // ===== ANATOMIE =====
  { id: "fc-anat-001", module: "anatomie", subtopic: "atemwege", front: "Auf welcher Wirbelkörperhöhe liegt die Bifurkation der Trachea (Carina)?", back: "Etwa Th4/Th5 (Höhe des Angulus sterni / Ludovici)." },
  { id: "fc-anat-002", module: "anatomie", subtopic: "atemwege", front: "Welcher Nerv versorgt die Schleimhaut oberhalb der Glottis sensibel und den M. cricothyroideus motorisch?", back: "N. laryngeus superior (R. internus = sensibel, R. externus = motorisch für M. cricothyroideus)." },
  { id: "fc-anat-003", module: "anatomie", subtopic: "atemwege", front: "Welcher Nerv versorgt motorisch alle inneren Kehlkopfmuskeln außer dem M. cricothyroideus?", back: "N. laryngeus recurrens (N. laryngeus inferior)." },
  { id: "fc-anat-004", module: "anatomie", subtopic: "atemwege", front: "Welcher Kehlkopfmuskel ist der einzige Abduktor der Stimmbänder?", back: "M. cricoarytenoideus posterior (Posticus)." },
  { id: "fc-anat-005", module: "anatomie", subtopic: "atemwege", front: "Welcher Knorpel bildet den einzigen vollständig geschlossenen Knorpelring des Kehlkopf-/Trachealsystems?", back: "Der Ringknorpel (Cartilago cricoidea)." },

  { id: "fc-anat-006", module: "anatomie", subtopic: "wirbelsaeule", front: "Wo endet der Conus medullaris beim Erwachsenen typischerweise?", back: "Etwa auf Höhe LWK1/2 (L1/L2)." },
  { id: "fc-anat-007", module: "anatomie", subtopic: "wirbelsaeule", front: "Wo endet der Duralsack beim Erwachsenen typischerweise?", back: "Etwa auf Höhe S2." },
  { id: "fc-anat-008", module: "anatomie", subtopic: "wirbelsaeule", front: "Was markiert die Linea intercristalis (Tuffier-Linie) näherungsweise?", back: "Die Verbindungslinie beider Beckenkämme, entspricht ungefähr LWK4 bzw. dem Zwischenraum L3/4-L4/5." },
  { id: "fc-anat-009", module: "anatomie", subtopic: "wirbelsaeule", front: "Welche Strukturen werden bei medianem Zugang zur Spinalanästhesie nacheinander durchstochen (nach Haut/Subkutis)?", back: "Lig. supraspinale → Lig. interspinale → Lig. flavum → Periduralraum → Dura mater → Arachnoidea → Subarachnoidalraum." },
  { id: "fc-anat-010", module: "anatomie", subtopic: "wirbelsaeule", front: "Ab welcher Punktionshöhe gilt eine lumbale Punktion beim Erwachsenen als sicher unterhalb des Conus medullaris?", back: "L3/4 oder tiefer (unterhalb der Tuffier-Linie)." },

  { id: "fc-anat-011", module: "anatomie", subtopic: "gefaesse-nerven", front: "Welcher Nervenplexus versorgt sensibel und motorisch die obere Extremität?", back: "Plexus brachialis (C5–Th1)." },
  { id: "fc-anat-012", module: "anatomie", subtopic: "gefaesse-nerven", front: "Wo liegt der Zugang zur interskalenären Plexusblockade anatomisch?", back: "Zwischen M. scalenus anterior und M. scalenus medius, etwa auf Höhe des Ringknorpels (C6)." },
  { id: "fc-anat-013", module: "anatomie", subtopic: "gefaesse-nerven", front: "Welcher Nerv wird bei interskalenärer Plexusblockade regelhaft mitblockiert (Zwerchfellparese)?", back: "N. phrenicus." },
  { id: "fc-anat-014", module: "anatomie", subtopic: "gefaesse-nerven", front: "Wie verläuft die V. jugularis interna typischerweise relativ zur A. carotis communis?", back: "Anterolateral zur A. carotis communis, innerhalb der Karotisscheide." },
  { id: "fc-anat-015", module: "anatomie", subtopic: "gefaesse-nerven", front: "Welche Komplikation ist bei blinder (landmarkenbasierter) V.-subclavia-Punktion am meisten gefürchtet?", back: "Pneumothorax." },

  { id: "fc-anat-016", module: "anatomie", subtopic: "thorax-herz", front: "Wie sind die beiden Blätter des Perikards genannt und was liegt dazwischen?", back: "Lamina visceralis (Epikard) und Lamina parietalis, dazwischen die Cavitas pericardialis (Perikardhöhle)." },
  { id: "fc-anat-017", module: "anatomie", subtopic: "thorax-herz", front: "Wo verläuft der N. phrenicus in Bezug zum Perikard?", back: "Beidseits ventral des Lungenhilus, dem Perikard direkt anliegend – bei Herzchirurgie gefährdet." },
  { id: "fc-anat-018", module: "anatomie", subtopic: "thorax-herz", front: "Welche Koronararterie versorgt bei den meisten Menschen (rechtsdominant) den AV-Knoten?", back: "Die rechte Koronararterie (RCA)." },
  { id: "fc-anat-019", module: "anatomie", subtopic: "thorax-herz", front: "In welcher Beziehung steht der Aortenbogen zur Carina?", back: "Der Aortenbogen überkreuzt den linken Hauptbronchus knapp oberhalb der Carina." },
  { id: "fc-anat-020", module: "anatomie", subtopic: "thorax-herz", front: "Warum ist eine versehentliche Intubation des rechten Hauptbronchus häufiger als links?", back: "Der rechte Hauptbronchus ist kürzer, weiter und zweigt in einem spitzeren (steileren) Winkel von der Trachea ab." },

  // ===== PHYSIOLOGIE =====
  { id: "fc-phys-001", module: "physiologie", subtopic: "atmung", front: "Was ist die funktionelle Residualkapazität (FRC)?", back: "Das Lungenvolumen am Ende einer normalen Exspiration (ERV + Residualvolumen)." },
  { id: "fc-phys-002", module: "physiologie", subtopic: "atmung", front: "Was bewirkt eine Linksverschiebung der O2-Bindungskurve?", back: "Erhöhte Hb-Affinität für O2 (erschwerte Abgabe ans Gewebe) – z.B. durch Alkalose, Hypothermie, ↓2,3-DPG, CO-Hb, fetales Hb." },
  { id: "fc-phys-003", module: "physiologie", subtopic: "atmung", front: "Welche Faktoren verschieben die O2-Bindungskurve nach rechts?", back: "Azidose, Hyperkapnie, Hyperthermie, ↑2,3-DPG (Bohr-Effekt) – erleichterte O2-Abgabe ans Gewebe." },
  { id: "fc-phys-004", module: "physiologie", subtopic: "atmung", front: "Wo ist das V/Q-Verhältnis in der aufrecht stehenden Lunge am höchsten?", back: "In der Lungenspitze (Apex)." },
  { id: "fc-phys-005", module: "physiologie", subtopic: "atmung", front: "Was bewirkt die hypoxische pulmonale Vasokonstriktion (HPV)?", back: "Umverteilung des Blutflusses weg von schlecht ventilierten Arealen zur Optimierung des V/Q-Verhältnisses." },

  { id: "fc-phys-006", module: "physiologie", subtopic: "kreislauf", front: "Was bestimmt die Vorlast (Preload) des Herzens physiologisch am ehesten?", back: "Das enddiastolische Volumen/die enddiastolische Wandspannung des Ventrikels (venöser Rückstrom)." },
  { id: "fc-phys-007", module: "physiologie", subtopic: "kreislauf", front: "Was besagt der Frank-Starling-Mechanismus?", back: "Mit zunehmender diastolischer Vordehnung des Myokards steigt die Kontraktionskraft/das Schlagvolumen bis zu einem Optimum." },
  { id: "fc-phys-008", module: "physiologie", subtopic: "kreislauf", front: "Wo liegen die arteriellen Barorezeptoren zur kurzfristigen Blutdruckregulation?", back: "Karotissinus (N. glossopharyngeus) und Aortenbogen (N. vagus)." },
  { id: "fc-phys-009", module: "physiologie", subtopic: "kreislauf", front: "Wie reagiert der Körper reflektorisch auf akuten Blutdruckabfall (Barorezeptorreflex)?", back: "Verminderte Barorezeptor-Afferenz → gesteigerte Sympathikusaktivität, verminderter Vagotonus → Tachykardie, Vasokonstriktion." },
  { id: "fc-phys-010", module: "physiologie", subtopic: "kreislauf", front: "Näherungsformel für den mittleren arteriellen Druck (MAP)?", back: "MAP ≈ diastolischer Druck + 1/3 × (systolischer − diastolischer Druck)." },

  { id: "fc-phys-011", module: "physiologie", subtopic: "niere-saeure-basen", front: "Winter-Formel zur Beurteilung der respiratorischen Kompensation bei metabolischer Azidose?", back: "Erwartetes pCO2 = 1,5 × [HCO3⁻] + 8 (± 2)." },
  { id: "fc-phys-012", module: "physiologie", subtopic: "niere-saeure-basen", front: "Wie wird die Anionenlücke berechnet und was ist der Normalwert?", back: "AG = Na⁺ − (Cl⁻ + HCO3⁻); normal ca. 8–12 mmol/l." },
  { id: "fc-phys-013", module: "physiologie", subtopic: "niere-saeure-basen", front: "Nenne zwei Ursachen einer metabolischen Azidose mit erhöhter Anionenlücke.", back: "Laktatazidose, Ketoazidose (auch Urämie, Intoxikationen z.B. Methanol/Ethylenglykol)." },
  { id: "fc-phys-014", module: "physiologie", subtopic: "niere-saeure-basen", front: "Wo im Nephron findet die Hauptresorption von Natrium und Wasser statt?", back: "Im proximalen Tubulus (ca. 65%)." },
  { id: "fc-phys-015", module: "physiologie", subtopic: "niere-saeure-basen", front: "Welches Hormon steigert die Wasserpermeabilität des Sammelrohrs?", back: "Antidiuretisches Hormon (ADH/Vasopressin) über Aquaporin-2-Kanäle." },

  { id: "fc-phys-016", module: "physiologie", subtopic: "leber-stoffwechsel", front: "Welches Cytochrom-P450-Isoenzym metabolisiert quantitativ die meisten Medikamente?", back: "CYP3A4." },
  { id: "fc-phys-017", module: "physiologie", subtopic: "leber-stoffwechsel", front: "Unterschied Phase-I- vs. Phase-II-Reaktionen der Biotransformation?", back: "Phase I: Oxidation/Reduktion/Hydrolyse (oft CYP450). Phase II: Konjugation (z.B. Glucuronidierung) – erhöht Wasserlöslichkeit zur Ausscheidung." },
  { id: "fc-phys-018", module: "physiologie", subtopic: "leber-stoffwechsel", front: "Welcher Gerinnungsfaktor wird überwiegend nicht in der Leber gebildet?", back: "Faktor VIII (v.a. endothelial gebildet)." },
  { id: "fc-phys-019", module: "physiologie", subtopic: "leber-stoffwechsel", front: "Was ist der First-Pass-Effekt?", back: "Hepatischer Metabolismus oral aufgenommener Substanzen über die Pfortader vor Erreichen des systemischen Kreislaufs – reduziert Bioverfügbarkeit." },
  { id: "fc-phys-020", module: "physiologie", subtopic: "leber-stoffwechsel", front: "Welches Plasmaprotein bindet vorwiegend saure Medikamente (viele Hypnotika/Lokalanästhetika)?", back: "Albumin (basische Medikamente binden v.a. an α1-saures Glykoprotein)." },

  { id: "fc-phys-021", module: "physiologie", subtopic: "zns", front: "Formel und Normalwert des zerebralen Perfusionsdrucks (CPP)?", back: "CPP = MAP − ICP; normal ca. 70–90 mmHg." },
  { id: "fc-phys-022", module: "physiologie", subtopic: "zns", front: "In welchem MAP-Bereich funktioniert die zerebrale Autoregulation normalerweise?", back: "Etwa MAP 60–150 mmHg (bei Gesunden)." },
  { id: "fc-phys-023", module: "physiologie", subtopic: "zns", front: "Wie wirkt Hyperventilation (↓paCO2) auf den zerebralen Blutfluss?", back: "CO2 ist ein starker zerebraler Vasodilatator; Hyperventilation → zerebrale Vasokonstriktion → CBF sinkt (Ischämierisiko beachten)." },
  { id: "fc-phys-024", module: "physiologie", subtopic: "zns", front: "Normalwert des intrakraniellen Drucks (ICP)?", back: "< 15 mmHg in Rückenlage; > 20–22 mmHg gilt als behandlungsbedürftig." },
  { id: "fc-phys-025", module: "physiologie", subtopic: "zns", front: "Was besagt die Monro-Kellie-Doktrin?", back: "Das intrakranielle Gesamtvolumen (Hirn, Blut, Liquor) ist konstant; Zunahme eines Kompartiments muss durch Abnahme eines anderen kompensiert werden, sonst steigt der ICP." },

  { id: "fc-phys-026", module: "physiologie", subtopic: "temperatur-endokrin", front: "Wodurch ist die erste (meist stärkste) Phase des perioperativen Wärmeverlusts bedingt?", back: "Umverteilung (Redistribution) von Kernwärme in die Peripherie durch anästhesiebedingte Vasodilatation, in den ersten 30–60 min." },
  { id: "fc-phys-027", module: "physiologie", subtopic: "temperatur-endokrin", front: "Wie beeinflusst Anästhesie die Thermoregulationsschwellen?", back: "Allgemein- und Regionalanästhesie senken die zentrale Schwelle für Vasokonstriktion/Shivering (verbreiterte interthreshold range)." },
  { id: "fc-phys-028", module: "physiologie", subtopic: "temperatur-endokrin", front: "Wodurch ist die chirurgische Stressantwort hormonell gekennzeichnet?", back: "Anstieg von Kortisol, Katecholaminen, ADH, Glukagon; verminderte Insulinwirkung → katabole Stoffwechsellage, Hyperglykämie." },
  { id: "fc-phys-029", module: "physiologie", subtopic: "temperatur-endokrin", front: "Welches Hormon muss bei bekannter Nebenniereninsuffizienz perioperativ substituiert werden?", back: "Hydrocortison (Glukokortikoid-Stressdosis)." },
  { id: "fc-phys-030", module: "physiologie", subtopic: "temperatur-endokrin", front: "Zugrunde liegender Mechanismus der malignen Hyperthermie?", back: "Unkontrollierte Kalziumfreisetzung aus dem sarkoplasmatischen Retikulum (meist RYR1-Mutation) durch Triggersubstanzen → hypermetabole Krise." },

  // ===== PHARMAKOLOGIE =====
  { id: "fc-pharm-001", module: "pharmakologie", subtopic: "pk-pd", front: "Was ist die kontextsensitive Halbwertszeit?", back: "Die Zeit bis zum 50%igen Abfall der Plasmakonzentration nach Ende einer kontinuierlichen Infusion – abhängig von der Infusionsdauer." },
  { id: "fc-pharm-002", module: "pharmakologie", subtopic: "pk-pd", front: "Welches Kompartimentmodell wird typischerweise für TCI von Propofol verwendet?", back: "Ein Dreikompartimentmodell (z.B. Marsh- oder Schnider-Modell)." },
  { id: "fc-pharm-003", module: "pharmakologie", subtopic: "pk-pd", front: "Was beschreibt das Verteilungsvolumen (Vd)?", back: "Ein rechnerisches Volumen, in dem sich die Dosis verteilen müsste, um die gemessene Plasmakonzentration zu ergeben – kein reales anatomisches Volumen." },
  { id: "fc-pharm-004", module: "pharmakologie", subtopic: "pk-pd", front: "Was ist der 'Ceiling-Effekt' bei partiellen Opioidagonisten wie Buprenorphin?", back: "Ab einer bestimmten Dosis steigt die Wirkung trotz Dosissteigerung nicht weiter an." },
  { id: "fc-pharm-005", module: "pharmakologie", subtopic: "pk-pd", front: "Unterschied zwischen Potency und Efficacy?", back: "Potency = benötigte Dosis für einen Effekt (Lage der Dosis-Wirkungs-Kurve); Efficacy = maximal erreichbarer Effekt (Höhe des Plateaus)." },

  { id: "fc-pharm-006", module: "pharmakologie", subtopic: "hypnotika", front: "Wichtigste kardiovaskuläre Nebenwirkung von Propofol bei Bolusgabe?", back: "Ausgeprägter Blutdruckabfall durch Vasodilatation und negative Inotropie, oft ohne kompensatorische Tachykardie." },
  { id: "fc-pharm-007", module: "pharmakologie", subtopic: "hypnotika", front: "Warum wird Etomidat trotz guter hämodynamischer Stabilität zurückhaltend eingesetzt?", back: "Suppression der adrenalen Steroidsynthese (11β-Hydroxylase-Hemmung), auch nach Einzeldosis." },
  { id: "fc-pharm-008", module: "pharmakologie", subtopic: "hypnotika", front: "Charakteristische kardiovaskuläre Wirkung von Ketamin?", back: "Sympathomimetisch (↑HF, ↑RR) durch Hemmung der Katecholamin-Wiederaufnahme; direkt myokarddepressiv bei kritisch Kranken mit Katecholaminmangel." },
  { id: "fc-pharm-009", module: "pharmakologie", subtopic: "hypnotika", front: "Wirkmechanismus von Propofol?", back: "Positive Modulation des GABA-A-Rezeptors (verlängerte Öffnung des Chloridkanals)." },
  { id: "fc-pharm-010", module: "pharmakologie", subtopic: "hypnotika", front: "Wirkmechanismus von Ketamin?", back: "Nichtkompetitiver Antagonist am NMDA-Rezeptor." },

  { id: "fc-pharm-011", module: "pharmakologie", subtopic: "inhalationsanaesthetika", front: "Definition der MAC (Minimal Alveolar Concentration)?", back: "Alveoläre Konzentration bei 1 Atmosphäre, bei der 50% der Patienten auf chirurgischen Hautschnitt nicht mit Abwehrbewegung reagieren." },
  { id: "fc-pharm-012", module: "pharmakologie", subtopic: "inhalationsanaesthetika", front: "Was bestimmt v.a. die Geschwindigkeit der An-/Abflutung eines Inhalationsanästhetikums?", back: "Der Blut-Gas-Verteilungskoeffizient (niedriger Koeffizient = schnellere An-/Abflutung, z.B. Sevofluran/Desfluran vs. Isofluran)." },
  { id: "fc-pharm-013", module: "pharmakologie", subtopic: "inhalationsanaesthetika", front: "Welches volatile Anästhetikum ist wegen Atemwegsreizung für Maskeneinleitung ungeeignet?", back: "Desfluran." },
  { id: "fc-pharm-014", module: "pharmakologie", subtopic: "inhalationsanaesthetika", front: "Was ist der 'Second Gas Effect'?", back: "Hohe Lachgasaufnahme konzentriert das gleichzeitig verabreichte volatile Anästhetikum/O2 in der Alveole und beschleunigt deren Anflutung." },
  { id: "fc-pharm-015", module: "pharmakologie", subtopic: "inhalationsanaesthetika", front: "Wodurch wird die MAC reduziert?", back: "Höheres Alter, Hypothermie, Opioide/Sedativa, Schwangerschaft, akute Alkoholintoxikation." },

  { id: "fc-pharm-016", module: "pharmakologie", subtopic: "muskelrelaxanzien", front: "Wirkmechanismus von Succinylcholin?", back: "Depolarisierendes Muskelrelaxans – Agonist am nikotinischen ACh-Rezeptor, erzeugt Dauerdepolarisation der Endplatte." },
  { id: "fc-pharm-017", module: "pharmakologie", subtopic: "muskelrelaxanzien", front: "Wichtigste Kontraindikationen für Succinylcholin?", back: "Malignes-Hyperthermie-Risiko, Hyperkaliämie-Risiko (z.B. Verbrennung >24h, Immobilisation, neuromuskuläre Erkrankung), Pseudocholinesterasemangel." },
  { id: "fc-pharm-018", module: "pharmakologie", subtopic: "muskelrelaxanzien", front: "Wirkmechanismus von Sugammadex?", back: "Bildet Einschlusskomplex (Chelator) mit steroidalen Muskelrelaxanzien (Rocuronium/Vecuronium) und inaktiviert sie im Plasma." },
  { id: "fc-pharm-019", module: "pharmakologie", subtopic: "muskelrelaxanzien", front: "Wirkmechanismus von Neostigmin?", back: "Reversibler Acetylcholinesterase-Hemmer – erhöht ACh-Konzentration am synaptischen Spalt." },
  { id: "fc-pharm-020", module: "pharmakologie", subtopic: "muskelrelaxanzien", front: "Warum wird Neostigmin meist mit einem Anticholinergikum kombiniert?", back: "Um muskarinerge Nebenwirkungen (Bradykardie, Hypersalivation, Bronchospasmus) zu antagonisieren." },

  { id: "fc-pharm-021", module: "pharmakologie", subtopic: "opioide", front: "Welches Opioid wird durch unspezifische Plasma-/Gewebeesterasen metabolisiert (organunabhängig)?", back: "Remifentanil." },
  { id: "fc-pharm-022", module: "pharmakologie", subtopic: "opioide", front: "Wirkmechanismus von Opioiden?", back: "Agonismus an Opioidrezeptoren (v.a. µ), G-Protein-gekoppelt – präsynaptische Hemmung der Transmitterfreisetzung, postsynaptische Hyperpolarisation." },
  { id: "fc-pharm-023", module: "pharmakologie", subtopic: "opioide", front: "Aktiver Metabolit von Morphin mit renaler Kumulationsgefahr?", back: "Morphin-6-Glucuronid." },
  { id: "fc-pharm-024", module: "pharmakologie", subtopic: "opioide", front: "Wirkmechanismus von Naloxon?", back: "Kompetitiver Opioidrezeptor-Antagonist (v.a. µ-Rezeptor)." },
  { id: "fc-pharm-025", module: "pharmakologie", subtopic: "opioide", front: "Was ist Remifentanil-induzierte Hyperalgesie?", back: "Gesteigerte Schmerzempfindlichkeit nach (v.a. hochdosierter) Remifentanil-Gabe, vermutlich NMDA-vermittelte Sensibilisierung." },

  { id: "fc-pharm-026", module: "pharmakologie", subtopic: "lokalanaesthetika", front: "Wirkmechanismus von Lokalanästhetika?", back: "Reversible Blockade spannungsabhängiger Natriumkanäle von intrazellulär – verhindert Aktionspotential-Ausbreitung." },
  { id: "fc-pharm-027", module: "pharmakologie", subtopic: "lokalanaesthetika", front: "Welche Nervenfasertypen werden bei LA-Gabe zuerst blockiert?", back: "Kleine, marklose/dünn myelinisierte Fasern (autonome C-Fasern, Schmerz/Temperatur Aδ) vor dicken motorischen Fasern." },
  { id: "fc-pharm-028", module: "pharmakologie", subtopic: "lokalanaesthetika", front: "Erste Therapie bei systemischer LA-Intoxikation (LAST) mit kardiovaskulärem Kollaps?", back: "20%ige Lipidemulsion ('Lipid Rescue') plus supportive/erweiterte Reanimation." },
  { id: "fc-pharm-029", module: "pharmakologie", subtopic: "lokalanaesthetika", front: "Warum ist Bupivacain kardiotoxischer als Lidocain?", back: "Höhere Proteinbindung/langsamere Dissoziation vom Natriumkanal ('fast-in, slow-out') → ausgeprägtere Natriumkanalblockade im Myokard." },
  { id: "fc-pharm-030", module: "pharmakologie", subtopic: "lokalanaesthetika", front: "Welcher Zusatz verlängert die LA-Wirkdauer durch lokale Vasokonstriktion?", back: "Adrenalin (Epinephrin)." },

  { id: "fc-pharm-031", module: "pharmakologie", subtopic: "kardiovaskulaer", front: "Wirkmechanismus von Noradrenalin als Vasopressor?", back: "Vorwiegend α1-Agonist (Vasokonstriktion), zusätzlich mäßige β1-Wirkung (Inotropie)." },
  { id: "fc-pharm-032", module: "pharmakologie", subtopic: "kardiovaskulaer", front: "Wirkmechanismus von Vasopressin in der Schocktherapie?", back: "V1-Rezeptor-Aktivierung an glatter Gefäßmuskulatur → Vasokonstriktion, unabhängig von adrenergen Rezeptoren." },
  { id: "fc-pharm-033", module: "pharmakologie", subtopic: "kardiovaskulaer", front: "Wirkmechanismus von Amiodaron (Vaughan-Williams)?", back: "Klasse III (Kaliumkanalblocker, verlängert Repolarisation), zusätzlich Klasse I/II/IV-Eigenschaften." },
  { id: "fc-pharm-034", module: "pharmakologie", subtopic: "kardiovaskulaer", front: "Wirkmechanismus von Adenosin bei SVT?", back: "Kurzfristige AV-Knoten-Blockade über A1-Rezeptoren (Hyperpolarisation) – unterbricht Reentry-Kreisläufe." },
  { id: "fc-pharm-035", module: "pharmakologie", subtopic: "kardiovaskulaer", front: "Wirkmechanismus von Milrinon?", back: "Phosphodiesterase-III-Hemmer → ↑cAMP → positive Inotropie und Vasodilatation ('Inodilatator')." },

  { id: "fc-pharm-036", module: "pharmakologie", subtopic: "sonstige-pharmaka", front: "Wirkmechanismus von Ondansetron?", back: "Selektiver 5-HT3-Rezeptor-Antagonist (zentral in der Area postrema und peripher im Darm)." },
  { id: "fc-pharm-037", module: "pharmakologie", subtopic: "sonstige-pharmaka", front: "Wirkweise von Dexamethason zur PONV-Prophylaxe?", back: "Antiinflammatorisch/antiemetisch über zentrale Glukokortikoidrezeptoren, genauer Mechanismus unvollständig geklärt." },
  { id: "fc-pharm-038", module: "pharmakologie", subtopic: "sonstige-pharmaka", front: "Wirkmechanismus von unfraktioniertem Heparin?", back: "Bindet Antithrombin III und verstärkt dessen Hemmung von v.a. Faktor Xa und Thrombin (IIa)." },
  { id: "fc-pharm-039", module: "pharmakologie", subtopic: "sonstige-pharmaka", front: "Wirkmechanismus von Tranexamsäure?", back: "Kompetitive Hemmung der Plasminogenaktivierung (antifibrinolytisch)." },
  { id: "fc-pharm-040", module: "pharmakologie", subtopic: "sonstige-pharmaka", front: "Warum wird Metoclopramid bei Parkinson-Patienten vermieden?", back: "Zentraler D2-Antagonismus kann extrapyramidale Symptome auslösen/verstärken." },

  // ===== PHYSIK & MESSTECHNIK =====
  { id: "fc-phys2-001", module: "physik-messtechnik", subtopic: "gasgesetze", front: "Was besagt das Gay-Lussac-Gesetz?", back: "Bei konstantem Volumen ist der Druck eines Gases proportional zu seiner absoluten Temperatur (P/T = konstant)." },
  { id: "fc-phys2-002", module: "physik-messtechnik", subtopic: "gasgesetze", front: "Grundprinzip eines variablen Bypass-Verdampfers?", back: "Ein Teil des Frischgasflusses wird durch die gesättigte Verdampferkammer geleitet, der Rest umgeht sie (Bypass); Mischungsverhältnis bestimmt Konzentration, temperaturkompensiert." },
  { id: "fc-phys2-003", module: "physik-messtechnik", subtopic: "gasgesetze", front: "Warum benötigt Desfluran einen elektrisch beheizten, druckregulierten Spezialverdampfer?", back: "Sehr niedriger Siedepunkt (ca. 23,5°C) nahe Raumtemperatur mit hohem Dampfdruck." },
  { id: "fc-phys2-004", module: "physik-messtechnik", subtopic: "gasgesetze", front: "Was ist die kritische Temperatur eines Gases?", back: "Die Temperatur, oberhalb derer das Gas durch Druck allein nicht mehr verflüssigt werden kann." },
  { id: "fc-phys2-005", module: "physik-messtechnik", subtopic: "gasgesetze", front: "Warum liegt Lachgas in der Gasflasche teilweise flüssig vor, Sauerstoff nicht?", back: "Lachgas hat eine kritische Temperatur oberhalb Raumtemperatur (36,4°C); Sauerstoffs kritische Temperatur liegt weit darunter (-118°C)." },

  { id: "fc-phys2-006", module: "physik-messtechnik", subtopic: "monitoring", front: "Welche Kapnographie-Phase entspricht dem alveolären Plateau?", back: "Phase III – Mischung aus alveolärer Luft, endet mit dem endtidalen CO2 (etCO2)." },
  { id: "fc-phys2-007", module: "physik-messtechnik", subtopic: "monitoring", front: "Messprinzip der Pulsoxymetrie?", back: "Unterschiedliche Lichtabsorption von oxygeniertem/desoxygeniertem Hämoglobin bei zwei Wellenlängen (Rot ~660nm, Infrarot ~940nm), pulsatiler Signalanteil wird ausgewertet." },
  { id: "fc-phys2-008", module: "physik-messtechnik", subtopic: "monitoring", front: "Referenzpunkt für die Nullung invasiver arterieller Druckmessung?", back: "Höhe des rechten Vorhofs (phlebostatische Achse)." },
  { id: "fc-phys2-009", module: "physik-messtechnik", subtopic: "monitoring", front: "Was passiert bei Unterdämpfung ('Überschwingen') eines invasiven Drucksystems?", back: "Fälschlich hohe systolische und niedrige diastolische Werte, MAP meist noch relativ korrekt." },
  { id: "fc-phys2-010", module: "physik-messtechnik", subtopic: "monitoring", front: "Was misst der Bispektralindex (BIS)?", back: "Einen aus dem EEG abgeleiteten Index (0–100) als Surrogat für die Hypnosetiefe unter Anästhesie." },

  { id: "fc-phys2-011", module: "physik-messtechnik", subtopic: "elektrische-sicherheit", front: "Warum werden im OP oft isolierte Netzsysteme (IT-Netz) verwendet?", back: "Bei einem ersten Erdschluss fließt kein großer Fehlerstrom über einen Patienten mit direktem Herzkontakt – reduziert Mikroschock-Risiko." },
  { id: "fc-phys2-012", module: "physik-messtechnik", subtopic: "elektrische-sicherheit", front: "Unterschied Makroschock vs. Mikroschock?", back: "Makroschock wirkt über die Haut (höhere Stromstärke nötig); Mikroschock wirkt direkt am/im Herzen (z.B. über Katheter), schon sehr geringe Ströme (<1mA) können Kammerflimmern auslösen." },
  { id: "fc-phys2-013", module: "physik-messtechnik", subtopic: "elektrische-sicherheit", front: "Funktion eines Fehlerstromschutzschalters (RCD)?", back: "Erkennt Differenzstrom zwischen Außen- und Neutralleiter und schaltet den Stromkreis sehr schnell ab." },
  { id: "fc-phys2-014", module: "physik-messtechnik", subtopic: "elektrische-sicherheit", front: "Welche Frequenz nutzt monopolare Elektrochirurgie, um Muskel-/Nervenstimulation zu vermeiden?", back: "Hochfrequenzstrom (typischerweise 300 kHz bis mehrere MHz)." },
  { id: "fc-phys2-015", module: "physik-messtechnik", subtopic: "elektrische-sicherheit", front: "Warum sollte die Neutralelektrode bei monopolarer Diathermie großflächig anliegen?", back: "Um die Stromdichte an dieser Stelle gering zu halten und lokale Verbrennungen zu vermeiden." },

  { id: "fc-phys2-016", module: "physik-messtechnik", subtopic: "statistik-ebm", front: "Definition Sensitivität eines Tests?", back: "Anteil der tatsächlich Erkrankten, die korrekt als positiv erkannt werden (Richtig-positiv-Rate)." },
  { id: "fc-phys2-017", module: "physik-messtechnik", subtopic: "statistik-ebm", front: "Definition Spezifität eines Tests?", back: "Anteil der tatsächlich Gesunden, die korrekt als negativ erkannt werden (Richtig-negativ-Rate)." },
  { id: "fc-phys2-018", module: "physik-messtechnik", subtopic: "statistik-ebm", front: "Wovon hängt der positive prädiktive Wert (PPV) stark ab?", back: "Von der Prävalenz der Erkrankung in der untersuchten Population." },
  { id: "fc-phys2-019", module: "physik-messtechnik", subtopic: "statistik-ebm", front: "Unterschied Typ-I- vs. Typ-II-Fehler?", back: "Typ-I (α): fälschliches Verwerfen einer wahren Nullhypothese (falsch-positiv). Typ-II (β): fälschliches Nicht-Verwerfen einer falschen Nullhypothese (falsch-negativ)." },
  { id: "fc-phys2-020", module: "physik-messtechnik", subtopic: "statistik-ebm", front: "Höchste Evidenzstufe in klassischen Evidenzhierarchien?", back: "Systematische Übersichtsarbeiten/Metaanalysen randomisiert-kontrollierter Studien (RCTs)." },

  // ===== ALLGEMEINANÄSTHESIE =====
  { id: "fc-ga-001", module: "allgemeinanaesthesie", subtopic: "praeoperativ", front: "Was klassifiziert der ASA-Status?", back: "Den präoperativen körperlichen Gesamtzustand des Patienten (ASA I–VI), unabhängig vom geplanten Eingriff." },
  { id: "fc-ga-002", module: "allgemeinanaesthesie", subtopic: "praeoperativ", front: "Aktuelle Nüchternheitsgrenze für klare Flüssigkeiten vor Elektiveingriffen?", back: "Bis 2 Stunden präoperativ erlaubt (feste Nahrung/Milch i.d.R. 6 Stunden vorher)." },
  { id: "fc-ga-003", module: "allgemeinanaesthesie", subtopic: "praeoperativ", front: "Was beurteilt die Mallampati-Klassifikation?", back: "Sichtbarkeit oropharyngealer Strukturen bei maximal geöffnetem Mund als Prädiktor für schwierige Laryngoskopie (Grad I–IV)." },
  { id: "fc-ga-004", module: "allgemeinanaesthesie", subtopic: "praeoperativ", front: "Was misst der Upper Lip Bite Test zusätzlich?", back: "Beweglichkeit/Prognathie des Unterkiefers als Prädiktor für schwierige Laryngoskopie." },
  { id: "fc-ga-005", module: "allgemeinanaesthesie", subtopic: "praeoperativ", front: "Wie wird häufig mit ACE-Hemmern/AT1-Blockern am OP-Tag verfahren?", back: "Oft pausiert wegen Risikos schwerer intraoperativer Hypotonie (individuelle Abwägung, aktuelle Leitlinien beachten)." },

  { id: "fc-ga-006", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", front: "Grundprinzip der Rapid Sequence Induction (RSI)?", back: "Schnelle Abfolge Präoxygenierung – schnellwirksames Hypnotikum – Muskelrelaxans, ohne Zwischenbeatmung, zur Minimierung der Aspirationszeit." },
  { id: "fc-ga-007", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", front: "Was beschreibt der Cormack-Lehane-Score?", back: "Die laryngoskopische Sicht auf die Glottis (Grad I–IV) unter direkter Laryngoskopie." },
  { id: "fc-ga-008", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", front: "Definitive Rettungsmaßnahme bei 'Cannot Intubate, Cannot Oxygenate' (CICO)?", back: "Chirurgischer/notfallmäßiger Atemwegszugang (Front-of-Neck-Access/Koniotomie)." },
  { id: "fc-ga-009", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", front: "Standard-Präoxygenierungsdauer vor Narkoseeinleitung?", back: "Ca. 3 Minuten Spontanatmung mit 100% O2 (oder 8 tiefe Atemzüge), Ziel endtidale O2-Fraktion ≥90%." },
  { id: "fc-ga-010", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", front: "Welche Larynxmaskengeneration erlaubt zusätzliche Magensondenplatzierung?", back: "Zweite Generation (z.B. LMA ProSeal, LMA Supreme, i-gel mit Drainagekanal)." },

  { id: "fc-ga-011", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", front: "Nenne die vier Hauptrisikofaktoren des Apfel-Scores für PONV.", back: "Weibliches Geschlecht, Nichtraucherstatus, PONV/Reisekrankheit in der Anamnese, postoperativer Opioidbedarf." },
  { id: "fc-ga-012", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", front: "Was ist 'Awareness' unter Allgemeinanästhesie?", back: "Ungewollte intraoperative Wachheit/Bewusstsein mit expliziter Erinnerung trotz beabsichtigt ausreichender Anästhesietiefe." },
  { id: "fc-ga-013", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", front: "Welche Kriterien werden für die Extubation gefordert?", back: "Ausreichende Spontanatmung, Schutzreflexe vorhanden, hämodynamische Stabilität, adäquate neuromuskuläre Erholung (TOF-Ratio ≥0,9), Erweckbarkeit." },
  { id: "fc-ga-014", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", front: "Wie wird neuromuskuläre Restblockade am zuverlässigsten überwacht?", back: "Quantitative Relaxometrie (z.B. TOF-Ratio mittels Akzeleromyographie), Ziel ≥0,9 vor Extubation." },
  { id: "fc-ga-015", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", front: "Therapieoption bei postoperativem Shivering?", back: "Clonidin oder Pethidin (Meperidin), zusätzlich aktive Wärmung." },
  { id: "fc-ga-016", module: "allgemeinanaesthesie", subtopic: "praeoperativ", front: "Nenne Beispiele für ASA III und ASA IV.", back: "ASA III: z.B. schlecht eingestellte arterielle Hypertonie, COPD, BMI ≥40. ASA IV: z.B. Myokardinfarkt <3 Monate, Ejektionsfraktion <30%, terminale Organinsuffizienz – konstante Lebensbedrohung." },
  { id: "fc-ga-017", module: "allgemeinanaesthesie", subtopic: "praeoperativ", front: "Welche sechs Faktoren umfasst der Revised Cardiac Risk Index (Lee-Index)?", back: "Ischämische Herzerkrankung, Herzinsuffizienz, zerebrovaskuläre Erkrankung, insulinpflichtiger Diabetes mellitus, Niereninsuffizienz (Kreatinin >2 mg/dl), Hochrisikoeingriff – je 1 Punkt, steigendes MACE-Risiko mit Punktzahl." },
  { id: "fc-ga-018", module: "allgemeinanaesthesie", subtopic: "praeoperativ", front: "Wie wird Metformin perioperativ meist gehandhabt?", back: "Bei normaler Nierenfunktion und ohne geplante jodhaltige Kontrastmittelgabe wird Metformin aktuell weitergeführt (kein routinemäßiges Pausieren mehr); pausiert wird gezielt nur bei geplanter Kontrastmittelgabe mit eGFR <60 ml/min/1,73m² (am Tag der Prozedur und 48h danach) – Hintergrund ist das Laktatazidose-Risiko bei Niereninsuffizienz/Hypoxie." },
  { id: "fc-ga-019", module: "allgemeinanaesthesie", subtopic: "praeoperativ", front: "Wie lange werden direkte orale Antikoagulanzien (DOAC) vor Eingriffen meist pausiert?", back: "Ca. 24h vor Eingriffen mit niedrigem, ca. 48h vor Eingriffen mit hohem Blutungsrisiko (bei Dabigatran und eingeschränkter Nierenfunktion länger, bis 4 Tage); vor rückenmarksnaher Anästhesie oft konservativer (z.B. 72h)." },
  { id: "fc-ga-020", module: "allgemeinanaesthesie", subtopic: "praeoperativ", front: "Sind präoperative Routinelaboruntersuchungen bei gesunden ASA-I/II-Patienten indiziert?", back: "Nein – gezielte Diagnostik anhand Anamnese/körperlicher Untersuchung statt ungezielter Routinetests, da diese Mortalität/Komplikationsraten kaum beeinflussen (ESAIC-Leitlinie)." },
  { id: "fc-ga-021", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", front: "Wofür steht die Mnemonik LEMON beim Atemwegsassessment?", back: "Look external, Evaluate 3-3-2-Regel, Mallampati, Obstruction/Obesity, Neck mobility – Prädiktoren eines schwierigen Atemwegs." },
  { id: "fc-ga-022", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", front: "Welcher thyromentale Abstand gilt als Hinweis auf einen potenziell schwierigen Atemweg?", back: "Ein Abstand von unter ca. 6–6,5 cm (kurzer Abstand Kinnspitze–Schildknorpel) – Einzelprädiktor mit begrenzter Aussagekraft, sollte mit weiteren Tests kombiniert werden." },
  { id: "fc-ga-023", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", front: "Wie wird Krikoiddruck (Sellick-Handgriff) heute bewertet?", back: "Umstritten/nicht sicher evidenzbasiert; kann laryngoskopische Sicht verschlechtern – bei Beeinträchtigung von Sicht/Beatmung soll er reduziert oder aufgehoben werden." },
  { id: "fc-ga-024", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", front: "Wie wird eine korrekte endotracheale Tubuslage sicher bestätigt?", back: "Kontinuierliche Kapnographie mit anhaltender, regelrechter CO2-Wellenform über mehrere Atemzüge (Goldstandard) – kein CO2-Nachweis bedeutet ösophageale Fehllage ('no trace = wrong place')." },
  { id: "fc-ga-025", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", front: "Welche Maskenbeatmungstechnik ist bei erschwerter Beatmung dem Einhand-C-Griff überlegen?", back: "Die Zweihandtechnik (beidhändiger Esmarch-Handgriff/Jaw-Thrust) verbessert die Atemwegsöffnung und erzielt höhere Tidalvolumina als die Einhand-C-E-Technik." },
  { id: "fc-ga-026", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", front: "Wie ist die minimale alveoläre Konzentration (MAC) definiert?", back: "Die alveoläre Konzentration eines volatilen Anästhetikums, bei der 50% der Patienten auf einen Hautschnitt nicht mit Abwehrbewegung reagieren (Steady State)." },
  { id: "fc-ga-027", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", front: "Nenne Faktoren, die den MAC-Wert senken bzw. steigern.", back: "Senkend: hohes Alter, Hypothermie, Opioide/Sedativa, Schwangerschaft, Hyponatriämie. Steigernd: Hyperthermie, chronischer Alkoholabusus, Hypernatriämie, junges Alter." },
  { id: "fc-ga-028", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", front: "Welcher BIS-Zielbereich gilt intraoperativ als anzustreben zur Awareness-Prophylaxe?", back: "BIS 40–60 (deutet auf adäquate Hypnosetiefe hin, reduziert Awareness-Risiko, ersetzt aber keine balancierte Anästhesieführung)." },
  { id: "fc-ga-029", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", front: "Ab welcher Körperkerntemperatur spricht man von perioperativer Hypothermie und welche Folge ist am besten belegt?", back: "Kerntemperatur <36°C; am besten belegte Folge ist die Koagulopathie (erhöhter Blutverlust/Transfusionsbedarf), zusätzlich erhöhtes Wundinfektionsrisiko und kardiale Ereignisse." },
  { id: "fc-ga-030", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", front: "Wie unterscheidet sich das Aufwachdelir (Emergence Delirium) bei Kindern vom postoperativen Delir?", back: "Emergence Delirium tritt unmittelbar beim Erwachen auf (v.a. nach Sevofluran, hohe Inzidenz bei Kindern), meist selbstlimitierend; postoperatives Delir tritt Stunden bis Tage später auf, v.a. bei älteren Patienten, mit fluktuierendem Bewusstsein/Aufmerksamkeitsstörung." },

  // ===== REGIONALANÄSTHESIE & SCHMERZ =====
  { id: "fc-reg-001", module: "regional-schmerz", subtopic: "neuraxial-verfahren", front: "Hauptunterschied im Wirkeintritt: Spinal- vs. Periduralanästhesie?", back: "Spinal: sehr schnell (Minuten) durch direkte intrathekale Applikation. Periduralanästhesie: langsamer (10–20 min) durch Diffusion durch die Dura." },
  { id: "fc-reg-002", module: "regional-schmerz", subtopic: "neuraxial-verfahren", front: "Typische Komplikation nach versehentlicher Duraperforation bei PDA?", back: "Postpunktioneller Kopfschmerz (PDPH), meist lageabhängig." },
  { id: "fc-reg-003", module: "regional-schmerz", subtopic: "neuraxial-verfahren", front: "Kausale Standardtherapie bei therapierefraktärem PDPH?", back: "Epiduraler Blutpatch." },
  { id: "fc-reg-004", module: "regional-schmerz", subtopic: "neuraxial-verfahren", front: "Wesentliche Kontraindikation für neuraxiale Verfahren bezüglich Gerinnung?", back: "Relevante Koagulopathie/therapeutische Antikoagulation (leitliniengerechte Zeitabstände beachten)." },
  { id: "fc-reg-005", module: "regional-schmerz", subtopic: "neuraxial-verfahren", front: "Was ist eine totale Spinalanästhesie?", back: "Zu hohe kraniale Ausbreitung der Blockade mit Atemlähmung, schwerer Hypotonie und Bewusstlosigkeit." },

  { id: "fc-reg-006", module: "regional-schmerz", subtopic: "periphere-blockaden", front: "Hauptvorteil ultraschallgestützter peripherer Blockaden?", back: "Direkte Visualisierung von Nerv, Nadel und umliegenden Strukturen (Gefäße, Pleura)." },
  { id: "fc-reg-007", module: "regional-schmerz", subtopic: "periphere-blockaden", front: "Welche Blockade eignet sich für die distale Hand bei Kontraindikation proximalerer Verfahren?", back: "Handgelenksblockade (N. medianus, N. ulnaris, N. radialis) oder axilläre Plexusblockade." },
  { id: "fc-reg-008", module: "regional-schmerz", subtopic: "periphere-blockaden", front: "Welcher Block deckt die Analgesie der lateralen Bauchwand ab (z.B. bei Sectio)?", back: "TAP-Block (Transversus-abdominis-plane-Block)." },
  { id: "fc-reg-009", module: "regional-schmerz", subtopic: "periphere-blockaden", front: "Welche Muskelgruppe wird durch Femoralisblockade v.a. motorisch beeinflusst?", back: "M. quadriceps femoris (Cave: Sturzrisiko)." },
  { id: "fc-reg-010", module: "regional-schmerz", subtopic: "periphere-blockaden", front: "Häufigste Nebenwirkung der interskalenären Plexusblockade?", back: "Vorübergehende ipsilaterale Zwerchfellparese durch N.-phrenicus-Blockade." },

  { id: "fc-reg-011", module: "regional-schmerz", subtopic: "schmerztherapie", front: "Was beschreibt das WHO-Stufenschema der Schmerztherapie?", back: "Klassisch (1986): Stufe 1 Nicht-Opioid-Analgetika; Stufe 2 schwache Opioide (+/- Stufe 1); Stufe 3 starke Opioide (+/- Stufe 1), ggf. mit Koanalgetika. Die WHO-Leitlinie von 2018 hat die feste Stufe-2-Empfehlung ('schwache Opioide') aufgehoben, da niedrig dosierte starke Opioide pharmakologisch günstiger sein können; das 3-Stufen-Grundprinzip bleibt aber gebräuchlich." },
  { id: "fc-reg-012", module: "regional-schmerz", subtopic: "schmerztherapie", front: "Was bedeutet multimodale Analgesie?", back: "Kombination verschiedener Analgetika/Verfahren mit unterschiedlichen Wirkmechanismen zur additiven Wirkung bei reduzierten Nebenwirkungen (Opioid-Einsparung)." },
  { id: "fc-reg-013", module: "regional-schmerz", subtopic: "schmerztherapie", front: "Was ist präemptive Analgesie?", back: "Analgetische Maßnahmen vor dem schmerzhaften Reiz mit dem Ziel, zentrale Sensibilisierung zu vermindern." },
  { id: "fc-reg-014", module: "regional-schmerz", subtopic: "schmerztherapie", front: "Welche Substanzklassen werden typisch als Koanalgetika bei neuropathischem Schmerz eingesetzt?", back: "Antikonvulsiva (Gabapentin, Pregabalin) und/oder trizyklische Antidepressiva (z.B. Amitriptylin)." },
  { id: "fc-reg-015", module: "regional-schmerz", subtopic: "schmerztherapie", front: "Grober zeitlicher Rahmen für 'chronischen postoperativen Schmerz'?", back: "Schmerz, der über mindestens 3 Monate nach einer OP persistiert und nicht anderweitig erklärbar ist." },
  { id: "fc-reg-016", module: "regional-schmerz", subtopic: "neuraxial-verfahren", front: "Was ist die Kombinierte Spinal-Epiduralanästhesie (CSE) und ihr Hauptvorteil?", back: "Kombination aus Spinalanästhesie (rascher, dichter Block) und Epiduralkatheter (Titrierbarkeit/Verlängerung der Anästhesie sowie postoperative Analgesie); meist als Needle-through-needle-Technik in einem Interspinalraum durchgeführt." },
  { id: "fc-reg-017", module: "regional-schmerz", subtopic: "neuraxial-verfahren", front: "Welche Faktoren erhöhen das Risiko für einen postpunktionellen Kopfschmerz (PDPH)?", back: "Junges Alter, weibliches Geschlecht, Schwangerschaft, vorbestehende Kopfschmerzen sowie Verwendung dicklumiger, scharfer (Cutting-)Nadeln statt atraumatischer Pencil-Point-Nadeln (z.B. Whitacre/Sprotte)." },
  { id: "fc-reg-018", module: "regional-schmerz", subtopic: "neuraxial-verfahren", front: "Welche Warnzeichen sprechen für ein epidurales Hämatom nach Neuraxialverfahren, und warum ist rasches Handeln entscheidend?", back: "Zunehmende motorische Schwäche/Sensibilitätsausfälle trotz nachlassender Blockwirkung, neu aufgetretene starke Rückenschmerzen sowie Blasen-/Mastdarmstörung; neurologische Defizite sind bei früher Dekompression oft reversibel, bei Verzögerung droht Irreversibilität – daher sofortige MRT-Diagnostik und ggf. notfallmäßige Laminektomie." },
  { id: "fc-reg-019", module: "regional-schmerz", subtopic: "neuraxial-verfahren", front: "Warum wird bei Säuglingen/Kleinkindern für infraumbilikale Eingriffe bevorzugt die Kaudalanästhesie statt einer lumbalen PDA gewählt?", back: "Das Rückenmark endet bei Neugeborenen/Säuglingen tiefer (ca. L3), sodass eine lumbale Punktion ein höheres Verletzungsrisiko birgt; die Kaudalanästhesie über den Hiatus sacralis (zwischen den Cornua sacralia) ist technisch einfacher und sicherer." },
  { id: "fc-reg-020", module: "regional-schmerz", subtopic: "neuraxial-verfahren", front: "Wozu dient die epidurale Testdosis (typischerweise Lidocain mit Adrenalin) und wie werden Fehllagen erkannt?", back: "Ausschluss einer intravasalen oder intrathekalen Katheterfehllage: intravasal → Herzfrequenzanstieg (>10/min) durch das Adrenalin; intrathekal → rasch einsetzender sensorischer/motorischer Block innerhalb weniger Minuten." },
  { id: "fc-reg-021", module: "regional-schmerz", subtopic: "periphere-blockaden", front: "Was unterscheidet die In-plane- von der Out-of-plane-Technik bei ultraschallgesteuerten Blockaden?", back: "In-plane: Nadel verläuft in der Bildebene, gesamte Nadel inkl. Spitze sichtbar (bessere Kontrolle, Standard bei oberflächlichen Nerven). Out-of-plane: Nadel kreuzt die Bildebene senkrecht, nur ein Punkt sichtbar – weniger Platzbedarf, aber schwerer die exakte Spitzenposition zu bestimmen." },
  { id: "fc-reg-022", module: "regional-schmerz", subtopic: "periphere-blockaden", front: "Warum wird der Adduktorenkanalblock dem Femoralisblock bei Knie-Eingriffen zunehmend vorgezogen?", back: "Er ist überwiegend sensorisch (N.-saphenus-dominiert) und erhält die Quadrizepskraft weitgehend, während der Femoralisblock zu ausgeprägter motorischer Schwäche mit erhöhtem Sturzrisiko führt – bei vergleichbarer Analgesiequalität." },
  { id: "fc-reg-023", module: "regional-schmerz", subtopic: "periphere-blockaden", front: "Wie unterscheiden sich die Indikationen von interskalenärem, supraklavikulärem und infraklavikulärem Plexusblock?", back: "Interskalenär: Schulter-/proximale Oberarmchirurgie (hohe Phrenikusparese-Rate). Supraklavikulär: gesamter Arm ab Oberarmmitte distal ('Spinalanästhesie des Arms', dichter Block, Pneumothorax-Risiko). Infraklavikulär: Ellenbogen bis Hand, geringeres Pneumothorax-Risiko, gut katheterfähig." },
  { id: "fc-reg-024", module: "regional-schmerz", subtopic: "periphere-blockaden", front: "Wofür werden perineurale Kathetertechniken eingesetzt?", back: "Kontinuierliche postoperative Analgesie über mehrere Tage durch fortlaufende Lokalanästhetika-Applikation an einem peripheren Nerven (z.B. interskalenär, popliteal); reduziert Opioidbedarf und ermöglicht frühe Mobilisation." },
  { id: "fc-reg-025", module: "regional-schmerz", subtopic: "periphere-blockaden", front: "Welche Nerven werden durch den Fascia-iliaca-Block erreicht und wofür wird er typischerweise eingesetzt?", back: "N. femoralis und N. cutaneus femoris lateralis (der N. obturatorius wird unzuverlässig erreicht); Standardindikation ist die frühe Analgesie bei proximaler Femurfraktur, z.B. bereits in der Notaufnahme." },
  { id: "fc-reg-026", module: "regional-schmerz", subtopic: "schmerztherapie", front: "Was ist der Hauptgrund für eine Opioidrotation bei unzureichender Wirkung oder inakzeptablen Nebenwirkungen?", back: "Unvollständige Kreuztoleranz zwischen verschiedenen Opioiden: Beim Wechsel wird die errechnete äquianalgetische Dosis um ca. 25–50% reduziert, um eine Überdosierung durch die neue Substanz zu vermeiden." },
  { id: "fc-reg-027", module: "regional-schmerz", subtopic: "schmerztherapie", front: "Welche Parameter werden bei einer patientenkontrollierten Analgesie (PCA) programmiert, und wie wird eine Basalrate bei opioidnaiven Patienten gehandhabt?", back: "Bolusdosis, Sperrintervall (Lockout, meist 5–15 min) und optionale Basalrate; bei opioidnaiven Patienten wird i.d.R. KEINE kontinuierliche Basalinfusion eingesetzt, da sie das Atemdepressionsrisiko erhöht, ohne die Analgesie zu verbessern." },
  { id: "fc-reg-028", module: "regional-schmerz", subtopic: "schmerztherapie", front: "Nach welchem Kriterienschema wird ein CRPS klinisch diagnostiziert, und welche Kategorien umfasst es?", back: "Budapest-Kriterien: anhaltender, zum auslösenden Ereignis unverhältnismäßiger Schmerz plus Symptome/Zeichen in den Kategorien sensorisch, vasomotorisch, sudomotorisch/Ödem und motorisch/trophisch (mind. 1 Symptom in 3 und 1 Zeichen in 2 der 4 Kategorien), ohne bessere Erklärung durch eine andere Diagnose." },
  { id: "fc-reg-029", module: "regional-schmerz", subtopic: "schmerztherapie", front: "Wie unterscheidet sich der Schmerzmechanismus bei Fibromyalgie von neuropathischem Schmerz?", back: "Fibromyalgie gilt als 'nociplastic pain' (veränderte zentrale Schmerzverarbeitung ohne nachweisbare Nerven- oder Gewebeläsion, meist diffus), während neuropathischer Schmerz durch eine Läsion/Erkrankung des somatosensorischen Systems verursacht wird (typisch dermatombezogen oder strumpf-/handschuhförmig)." },
  { id: "fc-reg-030", module: "regional-schmerz", subtopic: "schmerztherapie", front: "Welche Faktoren erhöhen das Risiko, dass akuter postoperativer Schmerz chronifiziert?", back: "Hohe Intensität/lange Dauer des akuten postoperativen Schmerzes, präoperativ bereits bestehender Schmerz, intraoperative Nervenverletzung, psychologische Faktoren (Angst, Depression, Katastrophisieren) sowie ausgedehnte/lang dauernde Operationen." },

  // ===== INTENSIVMEDIZIN =====
  { id: "fc-icu-001", module: "intensivmedizin", subtopic: "beatmung", front: "Hauptkriterien der Berlin-Definition des ARDS?", back: "Akuter Beginn (≤1 Woche), bilaterale Infiltrate (nicht vollständig kardial erklärt), PaO2/FiO2 ≤300 mmHg unter PEEP ≥5 cmH2O." },
  { id: "fc-icu-002", module: "intensivmedizin", subtopic: "beatmung", front: "Empfohlenes Tidalvolumen bei lungenprotektiver Beatmung?", back: "Ca. 6 ml/kg Idealgewicht (ARDSnet-Standard)." },
  { id: "fc-icu-003", module: "intensivmedizin", subtopic: "beatmung", front: "Warum wird bei ARDS ein begrenzter Plateaudruck angestrebt?", back: "Zur Vermeidung von Baro-/Volutrauma – Ziel meist Plateaudruck < 30 cmH2O." },
  { id: "fc-icu-004", module: "intensivmedizin", subtopic: "beatmung", front: "Was bewirkt PEEP physiologisch?", back: "Verhindert alveolären Kollaps am Exspirationsende, erhöht FRC, verbessert Oxygenierung – kann aber venösen Rückstrom/HZV reduzieren." },
  { id: "fc-icu-005", module: "intensivmedizin", subtopic: "beatmung", front: "Anerkanntes Rescue-Verfahren bei schwerem, refraktärem ARDS?", back: "Bauchlagerung (Prone Positioning); bei weiterhin refraktärer Hypoxämie ggf. ECMO." },

  { id: "fc-icu-006", module: "intensivmedizin", subtopic: "sepsis-schock", front: "Aktuelle Sepsis-Definition (Sepsis-3)?", back: "Lebensbedrohliche Organdysfunktion durch dysregulierte Wirtsantwort auf Infektion (SOFA-Anstieg ≥2 Punkte)." },
  { id: "fc-icu-007", module: "intensivmedizin", subtopic: "sepsis-schock", front: "Definition des septischen Schocks (Sepsis-3)?", back: "Sepsis mit trotz adäquater Volumentherapie persistierender Hypotonie, Vasopressorbedarf für MAP≥65mmHg, und Laktat >2 mmol/l." },
  { id: "fc-icu-008", module: "intensivmedizin", subtopic: "sepsis-schock", front: "Vasopressor erster Wahl beim septischen Schock?", back: "Noradrenalin." },
  { id: "fc-icu-009", module: "intensivmedizin", subtopic: "sepsis-schock", front: "Empfohlenes Zeitfenster für Breitbandantibiotika bei Sepsis/septischem Schock?", back: "So schnell wie möglich, idealerweise innerhalb 1 Stunde nach Erkennen." },
  { id: "fc-icu-010", module: "intensivmedizin", subtopic: "sepsis-schock", front: "Was misst der Laktatwert im Schock funktionell?", back: "Surrogatmarker für Gewebehypoperfusion/anaeroben Stoffwechsel." },

  { id: "fc-icu-011", module: "intensivmedizin", subtopic: "sedierung-delir", front: "Was misst die RASS-Skala?", back: "Sedierungs-/Agitationsgrad (-5 tief sediert bis +4 sehr agitiert, 0 = wach und ruhig)." },
  { id: "fc-icu-012", module: "intensivmedizin", subtopic: "sedierung-delir", front: "Validiertes Instrument zur Delirdiagnostik auf der Intensivstation?", back: "CAM-ICU oder ICDSC." },
  { id: "fc-icu-013", module: "intensivmedizin", subtopic: "sedierung-delir", front: "Welches Sedativum wird bei ICU-Sedierung wegen analgetischer, atemdepressionsarmer Eigenschaften bevorzugt?", back: "Dexmedetomidin (α2-Agonist)." },
  { id: "fc-icu-014", module: "intensivmedizin", subtopic: "sedierung-delir", front: "Angestrebte Sedierungstiefe bei den meisten beatmeten Intensivpatienten?", back: "Möglichst leichte Sedierung (z.B. RASS -2 bis 0), sofern klinisch vertretbar." },
  { id: "fc-icu-015", module: "intensivmedizin", subtopic: "sedierung-delir", front: "Welche Medikamentenklasse sollte bei Delir möglichst vermieden werden?", back: "Benzodiazepine." },

  { id: "fc-icu-016", module: "intensivmedizin", subtopic: "nierenersatz", front: "Hauptunterschied CRRT vs. intermittierende Hämodialyse?", back: "CRRT arbeitet über 24h kontinuierlich, langsamere Flüssigkeits-/Stoffentfernung – hämodynamisch schonender." },
  { id: "fc-icu-017", module: "intensivmedizin", subtopic: "nierenersatz", front: "Klassische akute Indikation zur Notfalldialyse?", back: "Schwere therapierefraktäre Hyperkaliämie (auch schwere Azidose, Urämie, Volumenüberladung, bestimmte Intoxikationen)." },
  { id: "fc-icu-018", module: "intensivmedizin", subtopic: "nierenersatz", front: "Was klassifiziert das KDIGO-System?", back: "Stadien des akuten Nierenversagens (AKI) anhand Kreatininanstieg und Urinausscheidung." },
  { id: "fc-icu-019", module: "intensivmedizin", subtopic: "nierenersatz", front: "Bevorzugtes Antikoagulans für regionale Antikoagulation bei CRRT?", back: "Regionale Citrat-Antikoagulation." },
  { id: "fc-icu-020", module: "intensivmedizin", subtopic: "nierenersatz", front: "Was ist prärenales Nierenversagen im Kern?", back: "Funktionelle Einschränkung durch verminderte renale Perfusion ohne primären strukturellen Schaden – bei rechtzeitiger Korrektur reversibel." },

  { id: "fc-icu-021", module: "intensivmedizin", subtopic: "ernaehrung", front: "Empfehlung zum Zeitpunkt des Ernährungsbeginns beim kritisch Kranken?", back: "Frühzeitige enterale Ernährung, meist innerhalb 24–48h nach ICU-Aufnahme, sofern keine Kontraindikation." },
  { id: "fc-icu-022", module: "intensivmedizin", subtopic: "ernaehrung", front: "Was ist das Refeeding-Syndrom?", back: "Lebensbedrohliche Elektrolytverschiebungen (v.a. Hypophosphatämie) und Flüssigkeitsretention bei zu schneller Wiederernährung nach Katabolie." },
  { id: "fc-icu-023", module: "intensivmedizin", subtopic: "ernaehrung", front: "Warum wird enterale Ernährung gegenüber parenteraler bevorzugt?", back: "Erhalt der Darmmukosa-Barriere, geringeres Infektionsrisiko, physiologischer." },
  { id: "fc-icu-024", module: "intensivmedizin", subtopic: "ernaehrung", front: "Welcher Score erfasst das Ernährungsrisiko kritisch Kranker?", back: "NUTRIC-Score." },
  { id: "fc-icu-025", module: "intensivmedizin", subtopic: "ernaehrung", front: "Risiko einer aggressiven frühen Vollkalorien-parenteralen Ernährung laut neuerer Evidenz?", back: "Erhöhtes Infektionsrisiko, ggf. verlängerte ICU-Verweildauer (z.B. EPaNIC-Studie)." },
  { id: "fc-icu-026", module: "intensivmedizin", subtopic: "beatmung", front: "Welcher RSBI-Grenzwert (f/VT) gilt klassisch als Prädiktor für erfolgreiches Weaning?", back: "RSBI <105/min/L spricht für hohe Extubations-Erfolgswahrscheinlichkeit; deutlich höhere Werte für Weaning-Versagen." },
  { id: "fc-icu-027", module: "intensivmedizin", subtopic: "beatmung", front: "Für welche zwei Indikationen ist der Nutzen von NIV am besten belegt?", back: "Akut exazerbierte COPD mit respiratorischer Azidose und kardiogenes Lungenödem." },
  { id: "fc-icu-028", module: "intensivmedizin", subtopic: "beatmung", front: "Nenne zentrale Maßnahmen des VAP-Präventionsbundles.", back: "Oberkörperhochlagerung 30–45°, subglottische Sekretdrainage, Cuffdruck 20–25 cmH2O, tägliche Sedierungspause mit Extubationsbereitschaftsprüfung." },
  { id: "fc-icu-029", module: "intensivmedizin", subtopic: "sepsis-schock", front: "Woraus besteht der qSOFA-Score?", back: "Atemfrequenz ≥22/min, systolischer RR ≤100 mmHg, verändertes Bewusstsein (GCS<15); ≥2 Kriterien → erhöhtes Risiko, v.a. außerhalb der ICU." },
  { id: "fc-icu-030", module: "intensivmedizin", subtopic: "sepsis-schock", front: "Wie unterscheidet sich das hämodynamische Muster von septischem und kardiogenem Schock?", back: "Septischer Schock (initial): hohes HZV, niedriger SVR (Vasoplegie); kardiogener Schock: niedriges HZV, hoher SVR, hohe Füllungsdrücke." },
  { id: "fc-icu-031", module: "intensivmedizin", subtopic: "sepsis-schock", front: "Welchen zusätzlichen Perfusionsmarker empfiehlt die Surviving Sepsis Campaign 2026 neben Laktat zur Schocksteuerung?", back: "Kapillarfüllungszeit (CRT) als adjunkten Parameter (ANDROMEDA-SHOCK-Studie)." },
  { id: "fc-icu-032", module: "intensivmedizin", subtopic: "sedierung-delir", front: "Welche 4 Merkmale prüft der CAM-ICU zur Delirdiagnose?", back: "Akuter Beginn/fluktuierender Verlauf, Aufmerksamkeitsstörung, unorganisiertes Denken, verändertes Bewusstseinsniveau – Delir positiv bei 1+2 und (3 oder 4)." },
  { id: "fc-icu-033", module: "intensivmedizin", subtopic: "sedierung-delir", front: "Was kennzeichnet das Propofol-Infusionssyndrom (PRIS)?", back: "Metabolische Azidose, Rhabdomyolyse, Herzversagen, Hyperlipidämie – Risiko steigt bei Hochdosis (>4 mg/kg/h) und/oder Infusionsdauer >48h." },
  { id: "fc-icu-034", module: "intensivmedizin", subtopic: "sedierung-delir", front: "Was bedeutet das Analgosedierungskonzept 'Analgesia-first'?", back: "Erst adäquate Analgesie sicherstellen, Sedativa nachrangig und niedrigstmöglich dosieren – reduziert Delir- und Beatmungsdauer." },
  { id: "fc-icu-035", module: "intensivmedizin", subtopic: "nierenersatz", front: "Wofür steht das Merkschema AEIOU (Indikation Nierenersatztherapie)?", back: "Acidosis, Electrolytes (Hyperkaliämie), Intoxication, Overload (Flüssigkeit), Uremia – jeweils schwer/therapierefraktär." },
  { id: "fc-icu-036", module: "intensivmedizin", subtopic: "nierenersatz", front: "Welche Kriterien definieren KDIGO-Stadium 3 des akuten Nierenversagens?", back: "Kreatinin ≥3-facher Ausgangswert (oder ≥4 mg/dl) ODER Dialysebeginn ODER Urinausscheidung <0,3 ml/kg/h ≥24h bzw. Anurie ≥12h." },
  { id: "fc-icu-037", module: "intensivmedizin", subtopic: "nierenersatz", front: "Warum wird CRRT bei hämodynamisch instabilen ICU-Patienten gegenüber IHD bevorzugt?", back: "Langsamerer, kontinuierlicher Flüssigkeits-/Soluteentzug vermeidet große Volumen-/osmotische Schwankungen und RR-Abfälle (KDIGO, Empfehlungsgrad 2B)." },
  { id: "fc-icu-038", module: "intensivmedizin", subtopic: "ernaehrung", front: "Welche Zielkalorienmenge nennt die ESPEN-Leitlinie 2023 ohne indirekte Kalorimetrie?", back: "Ca. 20–25 kcal/kg/Tag (gewichtsbasierte Formel)." },
  { id: "fc-icu-039", module: "intensivmedizin", subtopic: "ernaehrung", front: "Welcher Proteinzielwert wird für kritisch Kranke laut ESPEN empfohlen?", back: "Ca. 1,3 g/kg/Tag, schrittweise im Verlauf erreicht; höher (1,5–1,7 g/kg/Tag) unter Nierenersatztherapie." },
  { id: "fc-icu-040", module: "intensivmedizin", subtopic: "ernaehrung", front: "Wie wird das Refeeding-Syndrom bei Risikopatienten präventiv vermieden?", back: "Langsamer, schrittweiser Kalorienaufbau, engmaschige Elektrolytkontrolle/-substitution (Phosphat, Kalium, Magnesium) und Thiamingabe vor/bei Ernährungsbeginn." },

  // ===== NOTFALLMEDIZIN & REANIMATION =====
  { id: "fc-not-001", module: "notfall-reanimation", subtopic: "als-bls", front: "Kompressions-Ventilations-Verhältnis bei Erwachsenen-BLS mit einem Helfer?", back: "30:2." },
  { id: "fc-not-002", module: "notfall-reanimation", subtopic: "als-bls", front: "Empfohlene Kompressionsfrequenz und -tiefe (Erwachsener, ERC)?", back: "Frequenz 100–120/min, Tiefe ca. 5–6 cm." },
  { id: "fc-not-003", module: "notfall-reanimation", subtopic: "als-bls", front: "Welche Rhythmen sind primär defibrillierbar?", back: "Kammerflimmern (VF) und pulslose ventrikuläre Tachykardie (pVT)." },
  { id: "fc-not-004", module: "notfall-reanimation", subtopic: "als-bls", front: "Standarddosis Adrenalin bei Erwachsenenreanimation und Intervall?", back: "1 mg i.v./i.o., Wiederholung alle 3–5 Minuten." },
  { id: "fc-not-005", module: "notfall-reanimation", subtopic: "als-bls", front: "Wann wird Amiodaron bei schockbarem Rhythmus gegeben, welche Initialdosis?", back: "Nach dem 3. erfolglosen Schock, initial 300 mg i.v./i.o." },

  { id: "fc-not-006", module: "notfall-reanimation", subtopic: "trauma", front: "Reihenfolge des primären Traumaassessments nach ATLS?", back: "A (Airway mit HWS-Schutz) – B (Breathing) – C (Circulation) – D (Disability) – E (Exposure)." },
  { id: "fc-not-007", module: "notfall-reanimation", subtopic: "trauma", front: "Grundprinzip der permissiven Hypotonie bei unkontrollierter Blutung?", back: "Zurückhaltende Flüssigkeits-/Blutdrucktherapie zur Vermeidung von Gerinnselverdrängung/Verdünnungskoagulopathie bis zur definitiven Blutungskontrolle." },
  { id: "fc-not-008", module: "notfall-reanimation", subtopic: "trauma", front: "Was ist die 'letale Triade' beim Schwerverletzten?", back: "Hypothermie, Azidose und Koagulopathie – gegenseitige Verstärkung, hohe Mortalität." },
  { id: "fc-not-009", module: "notfall-reanimation", subtopic: "trauma", front: "Zeitfenster für maximalen Nutzen von Tranexamsäure beim Traumapatienten (CRASH-2)?", back: "Innerhalb 3 Stunden nach Trauma." },
  { id: "fc-not-010", module: "notfall-reanimation", subtopic: "trauma", front: "Sofortmaßnahme bei Spannungspneumothorax?", back: "Notfalldekompression (Nadeldekompression oder Thoraxdrainage/Finger-Thorakostomie)." },

  { id: "fc-not-011", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", front: "Erstlinientherapie der Anaphylaxie?", back: "Intramuskuläres Adrenalin (anterolateraler Oberschenkel), zusätzlich O2, Flüssigkeit, Allergenexposition beenden." },
  { id: "fc-not-012", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", front: "Welcher Laborparameter kann eine anaphylaktische Reaktion retrospektiv bestätigen?", back: "Mastzelltryptase (Serumspiegel, zeitversetzte Abnahmen)." },
  { id: "fc-not-013", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", front: "Klassische schwerste Transfusionsreaktion durch ABO-Inkompatibilität?", back: "Akute hämolytische Transfusionsreaktion (intravasale Hämolyse)." },
  { id: "fc-not-014", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", front: "Was ist TRALI?", back: "Transfusionsassoziierte akute Lungeninsuffizienz – akutes nichtkardiales Lungenödem innerhalb 6h nach Transfusion." },
  { id: "fc-not-015", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", front: "Grobes Prinzip eines Massentransfusionsprotokolls?", back: "Standardisierte, frühzeitige Gabe von EK, FFP und Thrombozyten in festem Verhältnis (oft ca. 1:1:1) bei massiver Blutung." },

  // ===== SPEZIELLE ANÄSTHESIE =====
  { id: "fc-spez-001", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", front: "Warum sind Schwangere ab ca. der 20. SSW in Rückenlage aortokavaler Kompression ausgesetzt?", back: "Der gravide Uterus komprimiert die V. cava inferior in Rückenlage → vermindert venösen Rückstrom/HZV; Prävention durch Linksseitenlagerung." },
  { id: "fc-spez-002", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", front: "Warum gelten Schwangere ab dem 2. Trimenon als 'nicht nüchtern'?", back: "Verzögerte Magenentleerung, erhöhter intraabdomineller Druck, verminderter unterer Ösophagussphinktertonus durch Progesteron." },
  { id: "fc-spez-003", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", front: "Bevorzugtes Anästhesieverfahren für elektive Sectio caesarea?", back: "Neuraxiale Anästhesie (Spinal- oder Periduralanästhesie)." },
  { id: "fc-spez-004", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", front: "Mittel der Wahl bei geburtshilflicher Hypotonie unter Spinalanästhesie?", back: "Phenylephrin (zunehmend bevorzugt gegenüber Ephedrin), Noradrenalin ebenfalls zunehmend genutzt." },
  { id: "fc-spez-005", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", front: "Warum sind hohe Konzentrationen volatiler Anästhetika bei geburtshilflicher Vollnarkose ungünstig?", back: "Dosisabhängige Relaxierung der Uterusmuskulatur → erhöhtes Risiko einer Uterusatonie/postpartalen Blutung." },

  { id: "fc-spez-006", module: "spezielle-anaesthesie", subtopic: "kinderanaesthesie", front: "Wie unterscheidet sich der O2-Verbrauch pro kg beim Säugling vom Erwachsenen?", back: "Deutlich höher (ca. doppelt) – rasche Entsättigung bei Apnoe." },
  { id: "fc-spez-007", module: "spezielle-anaesthesie", subtopic: "kinderanaesthesie", front: "Historische Begründung für ungecuffte Tuben bei kleinen Kindern?", back: "Annahme des Ringknorpels als engster, funktionell abdichtender Punkt; moderne Studien favorisieren zunehmend gecuffte Tuben mit Cuffdruck-Management." },
  { id: "fc-spez-008", module: "spezielle-anaesthesie", subtopic: "kinderanaesthesie", front: "Pharmakokinetische Besonderheit bei Neugeborenen bezüglich Proteinbindung?", back: "Niedrigere Albuminkonzentration → höherer freier (wirksamer) Anteil proteingebundener Medikamente." },
  { id: "fc-spez-009", module: "spezielle-anaesthesie", subtopic: "kinderanaesthesie", front: "Übliche Nüchternheitsempfehlung für Muttermilch bei Säuglingen?", back: "Meist 4 Stunden (feste Nahrung/Formula 6h, klare Flüssigkeiten 1–2h)." },
  { id: "fc-spez-010", module: "spezielle-anaesthesie", subtopic: "kinderanaesthesie", front: "Warum sind Kinder besonders anfällig für Laryngospasmus?", back: "Erhöhte Reflexerregbarkeit der Larynxschleimhaut, v.a. bei oberflächlicher Anästhesietiefe (Exzitationsstadium)." },

  { id: "fc-spez-011", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", front: "Hämodynamisches Ziel bei Aortenklappenstenose intraoperativ?", back: "Erhalt ausreichender Vorlast/Sinusrhythmus, Vermeidung von Tachykardie und starken Blutdruckabfällen." },
  { id: "fc-spez-012", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", front: "Grundprinzip der Ein-Lungen-Ventilation?", back: "Isolierte Beatmung einer Lunge (Doppellumentubus/Bronchusblocker), während die andere Lunge für chirurgischen Zugang kollabiert wird." },
  { id: "fc-spez-013", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", front: "Wie wirkt sich HPV günstig bei Ein-Lungen-Ventilation aus?", back: "Reduziert Durchblutung der nicht-ventilierten Lunge, mindert Rechts-Links-Shunt." },
  { id: "fc-spez-014", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", front: "Warum ist Protamin nach kardiopulmonalem Bypass notwendig?", back: "Es antagonisiert (neutralisiert) die Wirkung von unfraktioniertem Heparin." },
  { id: "fc-spez-015", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", front: "Was misst die ACT während des kardiopulmonalen Bypasses?", back: "Den Grad der Heparin-Antikoagulation (Ziel meist >400–480 Sekunden während Bypass)." },

  { id: "fc-spez-016", module: "spezielle-anaesthesie", subtopic: "neuroanaesthesie", front: "Warum werden hohe Konzentrationen volatiler Anästhetika bei erhöhtem Hirndruck eher vermieden?", back: "Dosisabhängige zerebrale Vasodilatation mit Anstieg des zerebralen Blutvolumens/ICP." },
  { id: "fc-spez-017", module: "spezielle-anaesthesie", subtopic: "neuroanaesthesie", front: "Welche Lagerung fördert bei Kraniotomien den venösen Abfluss?", back: "Oberkörperhochlagerung (ca. 15–30°) mit neutraler Kopf-/Halsposition." },
  { id: "fc-spez-018", module: "spezielle-anaesthesie", subtopic: "neuroanaesthesie", front: "Welche Anästhesietechnik wird bei MEP-Monitoring bevorzugt?", back: "Totale intravenöse Anästhesie (TIVA) – volatile Anästhetika supprimieren evozierte Potentiale dosisabhängig." },
  { id: "fc-spez-019", module: "spezielle-anaesthesie", subtopic: "neuroanaesthesie", front: "CPP-Zielbereich bei schwerem Schädel-Hirn-Trauma (Brain Trauma Foundation)?", back: "Meist 60–70 mmHg." },
  { id: "fc-spez-020", module: "spezielle-anaesthesie", subtopic: "neuroanaesthesie", front: "Warum ist bei Verdacht auf erhöhten Hirndruck Vorsicht vor Lumbalpunktion geboten?", back: "Risiko einer Herniation durch abrupten Druckgradienten zwischen intrakraniellem und spinalem Kompartiment." },

  { id: "fc-spez-021", module: "spezielle-anaesthesie", subtopic: "hno-augen-ambulant", front: "Warum ist die Tonsillektomie-Nachblutung anästhesiologisch besonders riskant?", back: "Verschlucktes Blut erhöht Aspirationsrisiko, Hypovolämie kann maskiert sein, Atemweg kann durch Blut/Ödem erschwert sein (RSI empfohlen)." },
  { id: "fc-spez-022", module: "spezielle-anaesthesie", subtopic: "hno-augen-ambulant", front: "Was ist der okulokardiale Reflex?", back: "Bradykardie bis Asystolie durch Zug an äußeren Augenmuskeln/Druck auf den Bulbus (Trigeminus-Vagus-vermittelt)." },
  { id: "fc-spez-023", module: "spezielle-anaesthesie", subtopic: "hno-augen-ambulant", front: "Warum wird Lachgas bei intraokularer Gasfüllung (z.B. SF6) vermieden?", back: "Lachgas diffundiert schneller in die Gasblase als heraus, kann intraokularen Druck gefährlich erhöhen." },
  { id: "fc-spez-024", module: "spezielle-anaesthesie", subtopic: "hno-augen-ambulant", front: "Welche Eigenschaften machen Anästhetika für die Tageschirurgie geeignet?", back: "Kurze Wirkdauer, schnelles Erwachen, geringe Nachwirkungen, niedrige PONV-Rate." },
  { id: "fc-spez-025", module: "spezielle-anaesthesie", subtopic: "hno-augen-ambulant", front: "Typisches Entlassungskriterium bei ambulanten Eingriffen bezüglich Begleitung?", back: "Ein verantwortlicher Erwachsener zur Begleitung nach Hause und Beaufsichtigung in den ersten 24 Stunden." },

  // ===== PERIOPERATIVE MEDIZIN, SICHERHEIT & ETHIK =====
  { id: "fc-eth-001", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", front: "Zweck der WHO Surgical Safety Checklist?", back: "Standardisierte Teamkommunikation und Verifikation kritischer Sicherheitsschritte (Sign-in, Time-out, Sign-out)." },
  { id: "fc-eth-002", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", front: "Was ist ein 'Never Event'?", back: "Schwerwiegendes, weitgehend vermeidbares Ereignis, das bei korrekter Anwendung vorhandener Sicherheitsmaßnahmen praktisch nicht auftreten sollte." },
  { id: "fc-eth-003", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", front: "Was beschreibt das Swiss-Cheese-Modell von James Reason?", back: "Fehler entstehen meist durch das zufällige Ausrichten von Lücken mehrerer aufeinanderfolgender Sicherheitsbarrieren." },
  { id: "fc-eth-004", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", front: "Sinn eines 'Time-out' vor Hautschnitt?", back: "Finale Verifikation von Patientenidentität, Eingriffsort/-seite und geplanter Prozedur durch das gesamte Team." },
  { id: "fc-eth-005", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", front: "Warum gelten standardisierte Checklisten als wichtiges Sicherheitsinstrument?", back: "Sie reduzieren die Abhängigkeit von individuellem Erinnerungsvermögen und helfen, Fehler unter Stress/Routine zu vermeiden." },

  { id: "fc-eth-006", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", front: "Was misst TEG/ROTEM im Vergleich zu INR/aPTT?", back: "Die globale, dynamische viskoelastische Gerinnselbildung/-stabilität (inkl. Fibrinolyse) im Vollblut in Echtzeit." },
  { id: "fc-eth-007", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", front: "Zweck von PPSB bei Vitamin-K-Antagonisten-Blutung?", back: "Schnelle Substitution der Vitamin-K-abhängigen Faktoren (II, VII, IX, X)." },
  { id: "fc-eth-008", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", front: "Spezifisches Antidot für Dabigatran?", back: "Idarucizumab." },
  { id: "fc-eth-009", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", front: "Spezifisches Antidot für Faktor-Xa-Inhibitoren (z.B. Apixaban)?", back: "Andexanet alfa – wegen erhöhtem Thromboserisiko (ANNEXA-I) Ende 2025 in den USA vom Markt genommen und nur noch eingeschränkt verfügbar; PPSB (25–50 IE/kg) ist die praktisch relevante Alternative." },
  { id: "fc-eth-010", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", front: "Übliche Transfusionsschwelle bei restriktiver Strategie für stabile Patienten?", back: "Häufig Hämoglobin ca. 7–8 g/dl (individuell anzupassen, z.B. höher bei akutem Koronarsyndrom)." },

  { id: "fc-eth-011", module: "periop-sicherheit-ethik", subtopic: "ethik-recht", front: "Vier klassische medizinethische Grundprinzipien nach Beauchamp und Childress?", back: "Autonomie, Nichtschaden (Non-Malefizienz), Fürsorge (Benefizienz), Gerechtigkeit." },
  { id: "fc-eth-012", module: "periop-sicherheit-ethik", subtopic: "ethik-recht", front: "Voraussetzungen für wirksame Einwilligung (Informed Consent)?", back: "Aufklärung über Art/Risiken/Alternativen, Einwilligungsfähigkeit, Freiwilligkeit." },
  { id: "fc-eth-013", module: "periop-sicherheit-ethik", subtopic: "ethik-recht", front: "Wie ist mit einer gültigen, zutreffenden Patientenverfügung umzugehen, die Reanimation ablehnt?", back: "Sie ist grundsätzlich bindend und muss respektiert werden." },
  { id: "fc-eth-014", module: "periop-sicherheit-ethik", subtopic: "ethik-recht", front: "Was bedeutet Therapiezieländerung am Lebensende im Gegensatz zu aktiver Sterbehilfe?", back: "Umstellung von kurativer auf palliative/symptomorientierte Therapie – klar unterschieden von aktiver Tötung auf Verlangen." },
  { id: "fc-eth-015", module: "periop-sicherheit-ethik", subtopic: "ethik-recht", front: "Zweck einer Vorsorgevollmacht im medizinischen Kontext?", back: "Eine bevollmächtigte Person kann bei Einwilligungsunfähigkeit stellvertretend medizinische Entscheidungen treffen." },
  { id: "fc-eth-016", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", front: "Was wird in der Sign-In-Phase der WHO-Checkliste (vor Anästhesieeinleitung) geprüft?", back: "Patientenidentität, Eingriff, Einwilligung und Markierung der Eingriffsseite; Narkosegerät/Medikamente; Pulsoxymeter; bekannte Allergien, Aspirationsrisiko und erwarteter Blutverlust." },
  { id: "fc-eth-017", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", front: "Was wird in der Sign-Out-Phase der WHO-Checkliste (vor Verlassen des OP) bestätigt?", back: "Laut ausgesprochener durchgeführter Eingriff, korrekte Instrumenten-/Tupfer-/Nadelzählung, korrekte Beschriftung von Proben sowie Besprechung wichtiger Punkte für die postoperative Versorgung." },
  { id: "fc-eth-018", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", front: "Grundprinzip eines Critical Incident Reporting Systems (CIRS)?", back: "Freiwillige, anonyme und sanktionsfreie Meldung kritischer Ereignisse/Beinahe-Schäden zum systemischen Lernen – nicht zur Schuldzuweisung." },
  { id: "fc-eth-019", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", front: "Wofür stehen die vier Elemente des SBAR-Übergabeschemas?", back: "Situation – Background (Hintergrund) – Assessment (Einschätzung) – Recommendation (Empfehlung)." },
  { id: "fc-eth-020", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", front: "Nenne zwei klassische Beispiele für 'Never Events' in der Chirurgie.", back: "Eingriffsverwechslung (falscher Patient/falsche Seite/falscher Eingriff) und im Operationsgebiet zurückgelassene Fremdkörper (z.B. Tupfer, Instrumente)." },
  { id: "fc-eth-021", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", front: "Welches Verhältnis von Erythrozytenkonzentrat (EK) : Fresh Frozen Plasma (FFP) : Thrombozytenkonzentrat (TK) wird im Massivtransfusionsprotokoll angestrebt?", back: "Ein ausgeglichenes Verhältnis von ca. 1:1:1 (bzw. 4:4:1 bei gepoolten TK), um die physiologische Blutzusammensetzung nachzubilden." },
  { id: "fc-eth-022", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", front: "Wirkmechanismus von Tranexamsäure?", back: "Kompetitive Blockade der Lysinbindungsstellen von Plasminogen; verhindert dessen Aktivierung zu Plasmin und hemmt so die Fibrinolyse (Antifibrinolytikum)." },
  { id: "fc-eth-023", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", front: "Die drei Säulen des Patient Blood Management (PBM)?", back: "Optimierung der präoperativen Anämie, Minimierung des perioperativen Blutverlusts, rationaler/patientenzentrierter Einsatz allogener Blutprodukte." },
  { id: "fc-eth-024", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", front: "Wesentlicher pathophysiologischer Unterschied zwischen TRALI und TACO?", back: "TRALI: immunvermittelte akute Lungenschädigung durch Antileukozyten-Antikörper des Spenders (nicht-kardiogenes Lungenödem). TACO: kardiogenes Lungenödem durch Volumenüberladung." },
  { id: "fc-eth-025", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", front: "Welche Komponenten bilden die 'letale Trias' bei Massivblutung, heute oft erweitert zum 'letalen Diamant'?", back: "Hypothermie, Azidose, Koagulopathie – erweitert um Hypokalzämie (durch Citrat aus Blutprodukten)." },
  { id: "fc-eth-026", module: "periop-sicherheit-ethik", subtopic: "ethik-recht", front: "Unterschied zwischen Einwilligungsfähigkeit und Geschäftsfähigkeit?", back: "Einwilligungsfähigkeit betrifft die natürliche Einsichts- und Urteilsfähigkeit für eine konkrete medizinische Maßnahme und ist von der (rechtlichen) Geschäftsfähigkeit unabhängig – sie bleibt z.B. bei bestellter Betreuung grundsätzlich bestehen." },
  { id: "fc-eth-027", module: "periop-sicherheit-ethik", subtopic: "ethik-recht", front: "Wann muss die ärztliche Aufklärung nach § 630e BGB spätestens erfolgen?", back: "So rechtzeitig, dass eine wohlüberlegte Entscheidung möglich ist; eine feste Mindestfrist existiert nicht – bei planbaren größeren Eingriffen genügt meist Aufklärung am Vortag, bei Dringlichkeit kann sie verkürzt sein." },
  { id: "fc-eth-028", module: "periop-sicherheit-ethik", subtopic: "ethik-recht", front: "Umgang mit einer bestehenden DNR-Anordnung vor einem geplanten elektiven Eingriff?", back: "Keine automatische Fortgeltung – präoperative Neubesprechung mit Patient/Team und explizite Festlegung für die perioperative Phase, da ein intraoperativer Kreislaufstillstand oft anders (reversibler) zu bewerten ist." },
  { id: "fc-eth-029", module: "periop-sicherheit-ethik", subtopic: "ethik-recht", front: "Worauf kommt es beim Umgang mit der Bluttransfusionsverweigerung eines Zeugen Jehovas an?", back: "Auf die individuelle, dokumentierte Entscheidung des einzelnen Patienten (nicht die der Glaubensgemeinschaft); eine wirksame Ablehnung ist bindend, blutsparende Alternativen (Patient Blood Management) sollten angeboten werden." },
  { id: "fc-eth-030", module: "periop-sicherheit-ethik", subtopic: "ethik-recht", front: "Rechtliche Folge einer lückenhaften Behandlungsdokumentation nach § 630h BGB?", back: "Beweislastumkehr zulasten des Behandelnden: Fehlt ein Eintrag zu einer gebotenen Maßnahme, wird vermutet, dass sie nicht durchgeführt wurde." },

  // ===== ORTHOPÄDIE & GEFÄSSCHIRURGIE =====
  { id: "fc-ortho-001", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", front: "Wie lange sollte die Anwendungsdauer einer pneumatischen Blutsperre (Tourniquet) an der Extremität in der Regel nicht überschreiten, und was folgt bei Öffnung?", back: "In der Regel nicht länger als ca. 2 Stunden (Empfehlung: alle 90–120 min für 5–15 min öffnen); bei Deflation können Laktat und anaerobe Stoffwechselprodukte aus der ischämischen Extremität anfluten und eine ausgeprägte Hypotonie auslösen." },
  { id: "fc-ortho-002", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", front: "Was ist das Knochenzementimplantationssyndrom (BCIS) und wann tritt es typischerweise auf?", back: "Akute kardiopulmonale Reaktion bei zementierter Endoprothetik (v.a. Hüft-TEP) durch Embolisation von Fett, Knochenmark, Luft oder Zementpartikeln bei Erhöhung des intramedullären Drucks; klinisch Hypoxie, Hypotonie, pulmonale Hypertonie, Arrhythmien bis Herzstillstand, meist bei Zementierung/Protheseneinbringung oder Reposition." },
  { id: "fc-ortho-003", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", front: "Wie ist das Fettembolie-Syndrom nach den Gurd-und-Wilson-Kriterien definiert?", back: "Diagnose bei ≥1 Hauptkriterium (respiratorische Insuffizienz/Hypoxämie, zerebrale Symptome, petechiale Blutungen z.B. axillär/konjunktival) plus ≥4 Nebenkriterien (u.a. Tachykardie, Fieber, retinale Veränderungen, Fettglobuli in Sputum/Urin, Thrombozytenabfall, erhöhte BSG) ODER 2 Hauptkriterien." },
  { id: "fc-ortho-004", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", front: "Welche hämodynamischen Veränderungen treten proximal und distal beim Aorten-Cross-Clamping auf?", back: "Proximal (oberhalb der Klemme): Anstieg von Blutdruck und systemischem Gefäßwiderstand durch erhöhte Nachlast. Distal: Ischämie mit Anstieg von Laktat und Azidose; bei Freigabe ('Declamping') Hypotonie durch Volumenverschiebung und Freisetzung vasodilatierender Metabolite (Laktat, Adenosin, CO2)." },
  { id: "fc-ortho-005", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", front: "Welche Methoden dienen dem intraoperativen zerebralen Monitoring bei Karotis-Endarteriektomie?", back: "Stumpfdruckmessung, transkranielle Dopplersonographie der A. cerebri media, Nah-Infrarot-Spektroskopie (NIRS), EEG, somatosensorisch evozierte Potenziale (SEP) sowie Wachtestung bei Lokoregionalanästhesie." },
  { id: "fc-ortho-006", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", front: "Welche Komplikation droht bei Wirbelsäulenchirurgie in Bauchlage besonders und welche Risikofaktoren begünstigen sie?", back: "Perioperativer Visusverlust (POVL), meist durch (posteriore) ischämische Optikusneuropathie (PION); begünstigt durch perioperative Anämie, arterielle Hypotension, lange OP-Dauer in Bauchlage und äußeren/inneren Druck auf die Augen." },

  // ===== TRANSPLANTATIONSANÄSTHESIE =====
  { id: "fc-transplant-001", module: "spezielle-anaesthesie", subtopic: "transplantationsanaesthesie", front: "Welche Voraussetzungen müssen vor Einleitung der Hirntoddiagnostik erfüllt bzw. ausgeschlossen sein?", back: "Nachweis einer schweren Hirnschädigung bekannter Ursache (Trauma, Blutung, Infarkt, Hypoxie u.a.); auszuschließen sind Intoxikation, sedierende Medikamentenwirkung, neuromuskuläre Blockade, primäre Hypothermie, Kreislaufschock sowie endokrines/metabolisches/entzündliches Koma als Ursache der Ausfallsymptomatik." },
  { id: "fc-transplant-002", module: "spezielle-anaesthesie", subtopic: "transplantationsanaesthesie", front: "Wie lange muss die Beobachtungszeit zwischen zwei Untersuchungen zur Hirntodfeststellung bei Erwachsenen mit primärer bzw. sekundärer Hirnschädigung mindestens betragen (ohne ergänzende apparative Diagnostik)?", back: "Mindestens 12 Stunden bei primärer (direkter) Hirnschädigung, mindestens 72 Stunden bei sekundärer (z.B. hypoxischer) Hirnschädigung; durch ergänzende Untersuchungen (Null-Linien-EEG, evozierte Potenziale, Doppler/Duplex, Perfusionsszintigraphie, CT-Angiographie) kann die Wartezeit verkürzt werden." },
  { id: "fc-transplant-003", module: "spezielle-anaesthesie", subtopic: "transplantationsanaesthesie", front: "Was kennzeichnet die anhepatische Phase der Lebertransplantation hämodynamisch?", back: "Nach Entfernung der Empfängerleber kommt es durch Abklemmen der V. cava/Pfortader zu vermindertem venösem Rückstrom (Preload) mit Abfall des Herzzeitvolumens (bis ca. 50%); zudem fällt jegliche Leberstoffwechsel-/Syntheseleistung aus, mit Hypothermie und Verschlechterung der Gerinnung." },
  { id: "fc-transplant-004", module: "spezielle-anaesthesie", subtopic: "transplantationsanaesthesie", front: "Was ist das Postreperfusionssyndrom bei Lebertransplantation und wodurch ist es gekennzeichnet?", back: "Akute hämodynamische Reaktion nach Freigabe der Lebergefäße mit Anstieg des systemischen Gefäßwiderstands, akuter Rechtsherzbelastung durch pulmonale Hypertonie, Hyperkaliämie (Auswaschung aus dem Transplantat) und Gefahr von Arrhythmien bis zur kardialen Dekompensation." },
  { id: "fc-transplant-005", module: "spezielle-anaesthesie", subtopic: "transplantationsanaesthesie", front: "Worauf muss bei der Anästhesie zur Nierentransplantation bezüglich Kalium besonders geachtet werden?", back: "Der Serumkaliumspiegel sollte präoperativ und intraoperativ mittels Blutgasanalyse engmaschig kontrolliert werden, da Dialysepatienten häufig prädisponiert für Hyperkaliämie sind, die kardiale Rhythmusstörungen begünstigt; Flüssigkeits- und Elektrolyttherapie zielen auf optimale renale Perfusion des Transplantats." },
  { id: "fc-transplant-006", module: "spezielle-anaesthesie", subtopic: "transplantationsanaesthesie", front: "Welche Medikamentengruppen bilden die Basis der perioperativ relevanten Immunsuppression nach Organtransplantation und welche Nebenwirkung ist anästhesiologisch besonders relevant?", back: "Calcineurininhibitoren (Tacrolimus, Ciclosporin), Antimetabolite (Mycophenolat, Azathioprin), mTOR-Inhibitoren und Kortikosteroide (meist Tripeltherapie); Calcineurininhibitoren und Steroide sind nephrotoxisch und können Hypertonie sowie Glukoseintoleranz verursachen – perioperativ ist ggf. eine Steroid-Stressdosis zu beachten." },

  // ===== TOXIKOLOGIE & VERBRENNUNGEN =====
  { id: "fc-toxi-001", module: "notfall-reanimation", subtopic: "toxikologie-verbrennungen", front: "Nach welcher Formel wird der initiale Flüssigkeitsbedarf bei Verbrennungen berechnet?", back: "Parkland(-Baxter)-Formel: 4 ml × kg KG × % verbrannte Körperoberfläche (VKOF, Grad ≥2a) in den ersten 24h (kristalloide Lösung), davon die Hälfte in den ersten 8h post trauma, die restliche Hälfte in den folgenden 16h; Steuerung zusätzlich nach Ziel-Urinausscheidung von ca. 0,5 ml/kg/h." },
  { id: "fc-toxi-002", module: "notfall-reanimation", subtopic: "toxikologie-verbrennungen", front: "Warum ist die Pulsoxymetrie zur Diagnose einer CO-Vergiftung ungeeignet und wie wird Carboxyhämoglobin stattdessen bestimmt?", back: "Pulsoxymeter können nicht zwischen Oxy- und Carboxyhämoglobin unterscheiden und zeigen trotz Vergiftung falsch-hohe SpO2-Werte; die CO-Hb-Bestimmung erfolgt mittels CO-Oxymetrie aus arterieller oder venöser Blutgasanalyse." },
  { id: "fc-toxi-003", module: "notfall-reanimation", subtopic: "toxikologie-verbrennungen", front: "Wie wirkt sich hyperbare Sauerstofftherapie (HBO) auf die Eliminationshalbwertszeit von CO aus und wann sollte sie idealerweise begonnen werden?", back: "Unter Raumluft beträgt die CO-Halbwertszeit ca. 4–5h, unter 100% O2 bei Normaldruck ca. 60–90 min, unter HBO bei 2,5–3 bar nur noch ca. 20–25 min; Beginn sollte möglichst innerhalb von 4 Stunden nach Exposition erfolgen." },
  { id: "fc-toxi-004", module: "notfall-reanimation", subtopic: "toxikologie-verbrennungen", front: "Welche sicheren Zeichen sprechen für ein Inhalationstrauma bei Verbrennungspatienten und was ist die Konsequenz?", back: "Gesichtsverbrennungen, versengte Nasen-/Gesichtsbehaarung, Ruß im Mund-/Rachenraum, Heiserkeit/Stridor und Dyspnoe; bei diesen Zeichen sollte die Indikation zur frühzeitigen endotrachealen Intubation großzügig gestellt werden, da sich die Atemwegsschwellung dynamisch verschlechtern kann." },
  { id: "fc-toxi-005", module: "notfall-reanimation", subtopic: "toxikologie-verbrennungen", front: "Womit wird eine Zyanidvergiftung bei Rauchgasinhalation spezifisch behandelt und wie wirkt das Antidot?", back: "Hydroxocobalamin (Cyanokit®), initial 5g i.v. beim Erwachsenen (ggf. Wiederholung, max. 10g/Tag); es bindet Zyanidionen direkt und bildet das renal eliminierbare Cyanocobalamin (Vitamin B12)." },
  { id: "fc-toxi-006", module: "notfall-reanimation", subtopic: "toxikologie-verbrennungen", front: "Welche typische Trias und welches Antidot kennzeichnen die Opioidintoxikation?", back: "Trias aus Miosis, Atemdepression/Bradypnoe und Bewusstseinstrübung/Koma; spezifisches Antidot ist Naloxon (titriert i.v., ggf. wiederholt wegen kürzerer Halbwertszeit als viele Opioide)." },

  // ===== NOTFALLMEDIZIN & REANIMATION (Vertiefung) =====
  { id: "fc-not-016", module: "notfall-reanimation", subtopic: "als-bls", front: "Wie lässt sich ein Return of Spontaneous Circulation (ROSC) während laufender Reanimation kapnographisch erkennen?", back: "Ein plötzlicher Anstieg des endtidalen CO2 (ETCO2) um ≥10 mmHg bzw. auf Normwerte ist mit ca. 97% Spezifität hinweisend auf ROSC, oft noch vor tastbarem Puls." },
  { id: "fc-not-017", module: "notfall-reanimation", subtopic: "als-bls", front: "Welchen ETCO2-Wert sollte man während qualitativ guter Herzdruckmassage anstreben, und was bedeutet ein dauerhaft niedriger Wert?", back: "Ziel sind ETCO2-Werte ≥10–20 mmHg als Zeichen adäquater Kompressionsqualität; ein persistierend niedriger Wert (<10 mmHg) trotz guter Compressions spricht für eine schlechte Prognose und kann in die Entscheidung zum Reanimationsabbruch einfließen." },
  { id: "fc-not-018", module: "notfall-reanimation", subtopic: "als-bls", front: "Welchen Stellenwert haben mechanische Kompressionshilfen (z.B. LUCAS, AutoPulse) laut ERC?", back: "Kein routinemäßiger Einsatz empfohlen; sinnvolle Alternative, wenn kontinuierliche manuelle Kompressionen guter Qualität praktisch nicht durchführbar sind (z.B. Transport, Herzkatheterlabor, Helfermangel)." },
  { id: "fc-not-019", module: "notfall-reanimation", subtopic: "als-bls", front: "Worauf ist bei der Reanimation Schwangerer ab ca. 20. SSW bezüglich der Lagerung zu achten?", back: "Manuelle Verlagerung des Uterus nach links (statt Seitenlagerung/Kippung), um die aortokavale Kompression zu entlasten, ohne die Kompressionsqualität/Defibrillation zu beeinträchtigen – Patientin bleibt dabei flach auf dem Rücken." },
  { id: "fc-not-020", module: "notfall-reanimation", subtopic: "als-bls", front: "Ab welchem Zeitpunkt und mit welchem Ziel sollte bei erfolgloser Reanimation einer Schwangeren eine Perimortem-Sectio erwogen werden?", back: "Bei fehlendem ROSC spätestens 4 Minuten nach Kreislaufstillstand (ab ca. SSW 20), am Ort des Geschehens; Ziel ist die Entlastung der V. cava/Aorta zur Verbesserung der mütterlichen Reanimationsbedingungen (und ggf. fetales Outcome)." },
  { id: "fc-not-021", module: "notfall-reanimation", subtopic: "als-bls", front: "Was unterscheidet den BLS-Algorithmus bei Ertrinkungsunfällen initial von der Standardreanimation?", back: "Wegen der primär hypoxischen Genese werden zunächst 5 initiale Beatmungen gegeben, bevor mit Thoraxkompressionen begonnen wird." },
  { id: "fc-not-022", module: "notfall-reanimation", subtopic: "als-bls", front: "Welches Grundprinzip gilt für die Reanimation bei schwerer akzidenteller Hypothermie, und wie werden Medikamente/Schocks angepasst?", back: "'Nobody is dead until warm and dead' – Reanimation wird trotz scheinbar frustraner Situation fortgeführt; unter 30°C wird Adrenalin zurückgehalten, bei 30–35°C werden die Intervalle für Adrenalingaben verdoppelt (bis Normothermie wieder Standardschema gilt)." },
  { id: "fc-not-023", module: "notfall-reanimation", subtopic: "als-bls", front: "Welches Rewarming-Verfahren ist bei Kreislaufstillstand durch schwere Hypothermie Mittel der Wahl?", back: "Extrakorporale Life-Support-Systeme (bevorzugt ECMO, alternativ Herz-Lungen-Maschine) an einem dafür ausgerüsteten Zentrum, insbesondere bei instabilen Patienten mit Risikofaktoren für Kreislaufstillstand oder bereits eingetretenem Arrest." },
  { id: "fc-not-024", module: "notfall-reanimation", subtopic: "als-bls", front: "Welche zentralen Zielwerte gelten in der Post-ROSC-Phase für Temperatur, Oxygenierung und Hämodynamik?", back: "Zieltemperatur konstant 32–36°C für mind. 24h (Fieber >72h vermeiden), SpO2 94–98% (Hyper- und Hypoxie vermeiden), mittlerer arterieller Druck ausreichend hoch halten (üblich >65 mmHg) zur Sicherung von Organperfusion und Urinausscheidung." },
  { id: "fc-not-025", module: "notfall-reanimation", subtopic: "als-bls", front: "Wie ist die Atemwegssicherung während laufender Reanimation aktuell im Stufenkonzept geregelt (SGA vs. endotracheale Intubation)?", back: "Nach Basismaßnahmen (Beutel-Masken-Beatmung) primär supraglottische Atemwegshilfe oder endotracheale Intubation – je nachdem, womit der Anwender eine hohe Erfolgsrate bei minimaler Kompressionsunterbrechung (Ziel <5s) erzielt; keine generelle Überlegenheit einer Methode belegt." },
  { id: "fc-not-026", module: "notfall-reanimation", subtopic: "trauma", front: "Was ist das Grundprinzip des REBOA-Konzepts (Resuscitative Endovascular Balloon Occlusion of the Aorta) und wann wird Zone 1 eingesetzt?", back: "Über einen Ballonkatheter (meist femoral) wird die Aorta passager okkludiert, um eine nicht komprimierbare Rumpfblutung zu kontrollieren und die proximale Perfusion (Herz/Gehirn) zu sichern; Zone 1 (oberhalb des Truncus coeliacus) bei Kreislaufstillstand oder lebensbedrohlicher intraabdomineller Blutung, Zone 3 bei Becken-/Beinblutung." },
  { id: "fc-not-027", module: "notfall-reanimation", subtopic: "trauma", front: "Wie wird ein Tourniquet bei lebensbedrohlicher Extremitätenblutung angewendet und wie lange gilt die Anwendung als sicher?", back: "Proximal der Blutungsquelle straff anlegen, bis die Blutung sistiert (Pulsverlust distal), Anlagezeit dokumentieren; eine Anwendungsdauer bis ca. 2 Stunden gilt als sicher ohne relevantes Amputationsrisiko." },
  { id: "fc-not-028", module: "notfall-reanimation", subtopic: "trauma", front: "Wann und wie wird eine Beckenschlinge bei Traumapatienten angelegt?", back: "Bei Verdacht auf instabile Beckenfraktur (Mechanismus, Schmerz, Hypotonie) auf Höhe der Trochanteren zirkulär angelegt; reduziert das Beckenvolumen und tamponiert venöse/ossäre Blutungen, kontrolliert aber keine arterielle Blutung." },
  { id: "fc-not-029", module: "notfall-reanimation", subtopic: "trauma", front: "Was ist das Prinzip der Damage-Control-Chirurgie?", back: "Kurze, auf Blutungs- und Kontaminationskontrolle beschränkte Erstoperation (z.B. Packing, temporärer Bauchverschluss) beim instabilen Schwerverletzten statt definitiver Versorgung, gefolgt von Stabilisierung auf der Intensivstation vor Second-Look-Operation." },
  { id: "fc-not-030", module: "notfall-reanimation", subtopic: "trauma", front: "Was beinhaltet das Konzept der Damage-Control-Resuscitation?", back: "Frühzeitige, ausgewogene Gabe von Blutprodukten (EK, Plasma, Thrombozyten) statt kristalloider Volumentherapie, permissive Hypotonie bis zur Blutungskontrolle sowie konsequente Vermeidung/Behandlung von Hypothermie und Azidose zur Durchbrechung der letalen Triade." },
  { id: "fc-not-031", module: "notfall-reanimation", subtopic: "trauma", front: "Welche Zielwerte gelten beim Schädel-Hirn-Trauma für zerebralen Perfusionsdruck (CPP) und intrakraniellen Druck (ICP)?", back: "CPP üblich 60–70 mmHg, ICP <22 mmHg; entscheidend ist zudem die konsequente Vermeidung von Hypotonie (SBP <90 mmHg) und Hypoxie, da beide die Sekundärschädigung deutlich verschlechtern." },
  { id: "fc-not-032", module: "notfall-reanimation", subtopic: "trauma", front: "Wie hat sich der Ansatz zur Wirbelsäulenimmobilisation beim Traumapatienten verändert?", back: "Weg von der routinemäßigen Vollimmobilisation auf der langen Rückenschale hin zur selektiven 'Spinal Motion Restriction': Verzicht auf das Backboard bei wachen, kooperativen Patienten ohne fokal-neurologisches Defizit, relevante Schmerzen oder Ablenkungsverletzung, um Druckulzera, Schmerzen und Aspirationsrisiko zu vermeiden." },
  { id: "fc-not-033", module: "notfall-reanimation", subtopic: "trauma", front: "Welche vier anatomischen Regionen werden bei der FAST-Sonographie untersucht?", back: "Perikard (Perikarderguss/Tamponade), rechter oberer Quadrant (Morison-Pouch/hepatorenaler Raum), linker oberer Quadrant (Milz-Nieren-Raum) und Becken – jeweils Suche nach freier Flüssigkeit." },
  { id: "fc-not-034", module: "notfall-reanimation", subtopic: "trauma", front: "Nach welchem Verhältnis werden Blutprodukte im Rahmen eines Massentransfusionsprotokolls bei traumainduzierter Koagulopathie klassischerweise verabreicht?", back: "Erythrozytenkonzentrate : Frischplasma : Thrombozytenkonzentrate im Verhältnis ca. 1:1:1, um eine Verdünnungskoagulopathie zu vermeiden und die Überlebensrate zu verbessern." },
  { id: "fc-not-035", module: "notfall-reanimation", subtopic: "trauma", front: "Welche Substanzen eignen sich bevorzugt zur prähospitalen Analgesie beim Traumapatienten je nach Kreislaufsituation?", back: "Bei hämodynamisch stabilem Patienten Fentanyl/Morphin; bei hämorrhagischem Schock oder respiratorischer Instabilität Ketamin (geringere kardiodepressive/atemdepressive Wirkung)." },
  { id: "fc-not-036", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", front: "Wie klassifiziert die Ring-Messmer-Einteilung die Schwere anaphylaktischer Reaktionen?", back: "Grad I: Hautsymptome (Erythem, Urtikaria); Grad II: zusätzlich mäßige Kreislauf-/Atemwegsbeteiligung (Hypotonie, Tachykardie, Bronchospasmus); Grad III: anaphylaktischer Schock, Bewusstlosigkeit, lebensbedrohlicher Bronchospasmus; Grad IV: Kreislauf-/Atemstillstand." },
  { id: "fc-not-037", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", front: "Was versteht man unter einer biphasischen anaphylaktischen Reaktion und welche Konsequenz hat dies für die Überwachung?", back: "Erneutes Auftreten anaphylaktischer Symptome nach initialem Ansprechen auf Therapie, meist innerhalb von Stunden (im Mittel ca. 11h, aber auch später möglich); bei relevanten Risikofaktoren wird eine Nachbeobachtung von mindestens 6h oder länger empfohlen." },
  { id: "fc-not-038", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", front: "Welche Differentialdiagnose ist bei rezidivierenden anaphylaktischen Reaktionen ohne erkennbaren Auslöser zu bedenken, und wie wird sie gestützt?", back: "Mastozytose (bzw. Mastzellaktivierungssyndrom); Hinweis liefert eine dauerhaft erhöhte Basaltryptase (auch im symptomfreien Intervall), im Gegensatz zum nur passager erhöhten Wert bei akuter Anaphylaxie." },
  { id: "fc-not-039", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", front: "Welche Substanzgruppe ist perioperativ die häufigste Ursache einer IgE-vermittelten Anaphylaxie?", back: "Neuromuskuläre Blocker (Muskelrelaxanzien) – gefolgt von Antibiotika; die relative Rangfolge variiert je nach Land/Register." },
  { id: "fc-not-040", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", front: "Welche zwei weiteren typischen perioperativen Anaphylaxie-Auslöser sollten bedacht werden?", back: "Chlorhexidin (Hautdesinfektion, Kathetermaterialien) und Latex (Handschuhe, Katheter) – beide werden als Ursache oft erst verzögert erkannt." },
  { id: "fc-not-041", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", front: "Wie unterscheiden sich febrile nicht-hämolytische und allergische (urtikarielle) Transfusionsreaktionen?", back: "Febril nicht-hämolytisch: Fieber/Schüttelfrost durch Zytokine aus gelagerten Blutprodukten, Therapie meist nur symptomatisch (Antipyretika); allergisch/urtikariell: IgE-vermittelte Reaktion auf Plasmaproteine des Spenders mit Juckreiz/Urtikaria, Therapie mit Antihistaminika – beide meist ohne vitale Bedrohung, im Gegensatz zur hämolytischen Reaktion." },
  { id: "fc-not-042", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", front: "Wie unterscheidet man klinisch TACO von TRALI?", back: "TACO (Transfusion-assoziierte Kreislaufüberladung): Hypertonie, Zeichen der Flüssigkeitsüberladung (Halsvenenstauung, Ödeme), erhöhtes BNP, Ansprechen auf Diuretika; TRALI: Hypotonie oder Normotonie, keine Überladungszeichen, meist normales BNP, kein Ansprechen auf Diuretika." },
  { id: "fc-not-043", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", front: "Warum ist bei Massentransfusion eine Kalzium-Substitution notwendig?", back: "Das in Blutprodukten enthaltene Citrat (Konservierungsmittel) chelatiert Kalzium und kann eine relevante Hypokalzämie verursachen (mit negativ inotroper Wirkung/Gerinnungsstörung); daher wird das ionisierte Kalzium engmaschig kontrolliert und substituiert." },
  { id: "fc-not-044", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", front: "Welcher Gerinnungsfaktor wird bei massiver Blutung typischerweise zuerst kritisch niedrig, und welcher Zielwert wird angestrebt?", back: "Fibrinogen ist meist der erste kritisch abfallende Gerinnungsfaktor bei massiver Blutung; angestrebt wird üblicherweise ein Fibrinogenspiegel von mindestens ca. 1,5–2 g/L." },
  { id: "fc-not-045", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", front: "Wie entsteht eine Rh-Inkompatibilität bei Transfusion, und wie wird ihr vorgebeugt?", back: "Eine Rh(D)-negative Person bildet nach Kontakt mit Rh(D)-positiven Erythrozyten (Transfusion oder Schwangerschaft) Anti-D-Antikörper (Sensibilisierung), die bei erneutem Kontakt eine hämolytische Reaktion auslösen können; Prophylaxe erfolgt durch Gabe von Anti-D-Immunglobulin und strikte Beachtung der Rh-Kompatibilität bei Transfusionen." },
  { id: "fc-toxi-007", module: "notfall-reanimation", subtopic: "toxikologie-verbrennungen", front: "Wie werden Verbrennungen nach Tiefe eingeteilt und welches klinische Bild zeigt sich jeweils?", back: "Grad I (oberflächlich, nur Epidermis): Rötung, Schmerz, keine Blasenbildung; Grad IIa (oberflächlich dermal): Blasen, schmerzhaft, rosig, Rekapillarisierung vorhanden; Grad IIb (tief dermal): blasser, weniger schmerzhaft, verzögerte/fehlende Rekapillarisierung; Grad III (Vollhaut): trocken, lederartig, schmerzlos (Nervenendigungen zerstört), keine Rekapillarisierung." },
  { id: "fc-toxi-008", module: "notfall-reanimation", subtopic: "toxikologie-verbrennungen", front: "Wann wird zur Bestimmung der verbrannten Körperoberfläche die Neuner-Regel und wann das Lund-Browder-Schema bevorzugt?", back: "Neuner-Regel: schnelle grobe Schätzung bei Erwachsenen; Lund-Browder-Schema: genauer, weil altersadaptiert – wird v.a. bei Kindern bevorzugt, da die Neuner-Regel dort die Verbrennungsfläche (insbesondere am Kopf) deutlich überschätzt." },
  { id: "fc-toxi-009", module: "notfall-reanimation", subtopic: "toxikologie-verbrennungen", front: "Wann ist eine Eskharotomie bei Verbrennungspatienten indiziert?", back: "Bei zirkulären tief-dermalen/Vollhautverbrennungen an Extremitäten mit Zeichen einer eingeschränkten Perfusion (Kompartmentsyndrom) oder am Thorax mit eingeschränkter Beatmung/Thoraxexkursion; die unelastische Verbrennungsnarbe (Eschar) wirkt sonst wie ein einschnürendes Tourniquet." },
  { id: "fc-toxi-010", module: "notfall-reanimation", subtopic: "toxikologie-verbrennungen", front: "Welche Komplikation droht bei Elektrounfällen und Crush-Verletzungen durch Muskelschädigung, und wie wird sie initial behandelt?", back: "Rhabdomyolyse mit Myoglobinämie/-urie und Gefahr des akuten Nierenversagens; Therapie primär durch aggressive Volumengabe zur Aufrechterhaltung einer hohen Urinausscheidung, ggf. ergänzend Alkalisierung des Urins." },
  { id: "fc-toxi-011", module: "notfall-reanimation", subtopic: "toxikologie-verbrennungen", front: "Wie wird eine Paracetamol-Intoxikation behandelt und wonach richtet sich die Therapieentscheidung?", back: "Antidot ist N-Acetylcystein (NAC, Glutathion-Vorstufe), das die Bildung von hepatotoxischem NAPQI abfängt; die Therapieindikation richtet sich anhand des Serumspiegels 4–24h nach Ingestion nach dem Rumack-Matthew-Nomogramm, Beginn der NAC-Gabe möglichst innerhalb von 8h." },
  { id: "fc-toxi-012", module: "notfall-reanimation", subtopic: "toxikologie-verbrennungen", front: "Welche spezifischen Therapieoptionen stehen bei schwerer Betablocker- oder Kalziumantagonisten-Intoxikation zur Verfügung?", back: "Kalzium (i.v.), Glukagon (v.a. bei Betablockern) sowie die hochdosierte Insulin-Euglykämie-Therapie (HIET, positiv inotrop wirksam) unter engmaschiger Glukose-/Kaliumkontrolle; in Extremfällen Lipidemulsion oder ECMO." },
  { id: "fc-toxi-013", module: "notfall-reanimation", subtopic: "toxikologie-verbrennungen", front: "Welches Antidot steht bei Benzodiazepin-Intoxikation zur Verfügung, und wann ist es kontraindiziert?", back: "Flumazenil; kontraindiziert bzw. nur mit großer Zurückhaltung bei Mischintoxikation mit prokonvulsiven Substanzen (z.B. trizyklische Antidepressiva), bekannter Krampfanfallneigung oder chronischem Benzodiazepin-Gebrauch, da Entzugs- bzw. TCA-induzierte Krampfanfälle ausgelöst werden können." },

  // ===== ANATOMIE (Vertiefung) =====
  { id: "fc-anat-021", module: "anatomie", subtopic: "atemwege", front: "Wie ist die Cormack-Lehane-Klassifikation der laryngoskopischen Sicht aufgebaut?", back: "Grad I: vollständige Stimmritzensicht; Grad II: partielle Sicht auf Glottis/Aryknorpel; Grad III: nur Epiglottis sichtbar; Grad IV: weder Epiglottis noch Glottis sichtbar (Grad I-II = leichte, III-IV = schwierige Laryngoskopie)." },
  { id: "fc-anat-022", module: "anatomie", subtopic: "atemwege", front: "Was misst die (modifizierte) Mallampati-Klassifikation und wie wird sie erhoben?", back: "Präoperative Einschätzung des Atemwegs anhand der bei maximaler Mundöffnung und vorgestreckter Zunge sichtbaren pharyngealen Strukturen (weicher Gaumen, Uvula, Gaumenbögen); Klasse I-IV, höhere Klasse = höheres Risiko für schwierige Laryngoskopie." },
  { id: "fc-anat-023", module: "anatomie", subtopic: "atemwege", front: "Welche Besonderheiten kennzeichnen den kindlichen im Vergleich zum erwachsenen Atemweg?", back: "Kranialerer/anteriorer liegender Kehlkopf (~C3/4 statt C4/6), relativ große Zunge, lange, schmale, omegaförmige und weichere ('floppy') Epiglottis, insgesamt eher trichterförmige statt zylindrische Atemwegsform." },
  { id: "fc-anat-024", module: "anatomie", subtopic: "atemwege", front: "Welche Form und Funktion hat die Epiglottis?", back: "Blattförmiger elastischer Knorpel, über das Lig. hyoepiglotticum am Zungenbein fixiert; klappt beim Schlucken über den Kehlkopfeingang und schützt so vor Aspiration." },
  { id: "fc-anat-025", module: "anatomie", subtopic: "atemwege", front: "Wie ist die Innervation der Zunge aufgeteilt (motorisch/sensibel)?", back: "Motorisch fast vollständig N. hypoglossus (XII); sensibel vordere 2/3 allgemein N. lingualis (V3), Geschmack Chorda tympani (VII); hinteres Drittel allgemein und Geschmack N. glossopharyngeus (IX)." },
  { id: "fc-anat-026", module: "anatomie", subtopic: "wirbelsaeule", front: "Wie viele Spinalnervenpaare gibt es insgesamt und wie verteilen sie sich?", back: "31 Paare: 8 zervikal, 12 thorakal, 5 lumbal, 5 sakral, 1 coccygeal (C1 tritt oberhalb, C8 unterhalb des 7. Halswirbels aus)." },
  { id: "fc-anat-027", module: "anatomie", subtopic: "wirbelsaeule", front: "Wie verteilt sich die arterielle Versorgung des Rückenmarksquerschnitts?", back: "Unpaare A. spinalis anterior versorgt die vorderen 2/3 (Vorderhörner, Tractus corticospinalis/spinothalamicus); paarige Aa. spinales posteriores versorgen das hintere Drittel (Hinterstränge)." },
  { id: "fc-anat-028", module: "anatomie", subtopic: "wirbelsaeule", front: "Was ist die A. radicularis magna (Adamkiewicz) und wo entspringt sie meist?", back: "Größte segmentale Zuflussarterie zur A. spinalis anterior im thorakolumbalen Bereich; entspringt meist linksseitig aus einer Interkostal-/Lumbalarterie zwischen etwa Th9 und L2 – bei Verletzung Risiko eines Spinalis-anterior-Syndroms." },
  { id: "fc-anat-029", module: "anatomie", subtopic: "wirbelsaeule", front: "Aus welchen Strukturen besteht eine Bandscheibe?", back: "Äußerer, straffer Anulus fibrosus umschließt den zentralen, gallertigen Nucleus pulposus; gemeinsam dienen sie als Stoßdämpfer und ermöglichen Beweglichkeit der Wirbelsäule." },
  { id: "fc-anat-030", module: "anatomie", subtopic: "wirbelsaeule", front: "Wie ist der sympathische Grenzstrang angeordnet und was ist das Ganglion stellatum?", back: "Paravertebrale Kette sympathischer Ganglien beidseits der Wirbelsäule von zervikal bis sakral; das Ganglion stellatum entsteht meist durch Fusion des Ganglion cervicale inferius mit dem 1. Thorakalganglion." },
  { id: "fc-anat-031", module: "anatomie", subtopic: "gefaesse-nerven", front: "Aus welchen Rückenmarksegmenten stammt der N. femoralis und was versorgt er?", back: "Aus dem Plexus lumbalis (L2-L4); motorisch v.a. Hüftbeugung (M. iliopsoas) und Kniestreckung (M. quadriceps), sensibel vorderer Oberschenkel und über den N. saphenus die mediale Unterschenkelseite." },
  { id: "fc-anat-032", module: "anatomie", subtopic: "gefaesse-nerven", front: "Aus welchen Segmenten stammt der N. ischiadicus und wo tritt er aus dem Becken aus?", back: "Aus dem Plexus sacralis (L4-S3); Austritt aus dem Becken durch das Foramen ischiadicum majus, meist unterhalb des M. piriformis." },
  { id: "fc-anat-033", module: "anatomie", subtopic: "gefaesse-nerven", front: "Wonach sind die drei Faszikel (Cordae) des Plexus brachialis benannt?", back: "Nach ihrer Lage relativ zur A. axillaris in deren Pars 2 (hinter M. pectoralis minor): Fasciculus lateralis, medialis und posterior." },
  { id: "fc-anat-034", module: "anatomie", subtopic: "gefaesse-nerven", front: "Welche Strukturen begrenzen das Trigonum lumbale (Petit'sches Dreieck), Landmarke des klassischen TAP-Blocks?", back: "Dorsal M. latissimus dorsi, ventral M. obliquus externus abdominis, kaudal Crista iliaca; Boden bildet der M. obliquus internus abdominis." },
  { id: "fc-anat-035", module: "anatomie", subtopic: "gefaesse-nerven", front: "Wie ist das Femoralisdreieck (Trigonum femorale) begrenzt?", back: "Kranial Leistenband, lateral M. sartorius, medial M. adductor longus; Boden aus M. iliopsoas und M. pectineus – enthält von lateral nach medial N., A. und V. femoralis." },
  { id: "fc-anat-036", module: "anatomie", subtopic: "thorax-herz", front: "Wie verläuft die Erregung nach dem AV-Knoten weiter durch das Reizleitungssystem?", back: "AV-Knoten → His-Bündel → rechter und linker Tawara-Schenkel → Purkinje-Fasern → Arbeitsmyokard der Kammern." },
  { id: "fc-anat-037", module: "anatomie", subtopic: "thorax-herz", front: "Wie ist die Koronardominanz definiert?", back: "Nach dem Ursprung des Ramus interventricularis posterior (PDA): aus der RCA = rechtsdominant (häufigste Variante, ca. 70-85%), aus dem Ramus circumflexus = linksdominant (ca. 7-13%), aus beiden = codominant." },
  { id: "fc-anat-038", module: "anatomie", subtopic: "thorax-herz", front: "Wie viele bronchopulmonale Segmente haben rechte und linke Lunge?", back: "Rechts klassisch 10 Segmente (3 Oberlappen, 2 Mittellappen, 5 Unterlappen); links 8-10, da einzelne Segmente häufig fusioniert sind." },
  { id: "fc-anat-039", module: "anatomie", subtopic: "thorax-herz", front: "Auf welcher Rippenhöhe kreuzt die untere Pleuragrenze die Medioklavikular-, Mittelaxillar- und Paravertebrallinie?", back: "8. Rippe (Medioklavikularlinie), 10. Rippe (Mittelaxillarlinie), 12. Rippe (paravertebral) – der Recessus costodiaphragmaticus liegt zwischen unterem Lungen- und Pleuragrenze." },
  { id: "fc-anat-040", module: "anatomie", subtopic: "thorax-herz", front: "Wie wird das Mediastinum gegliedert?", back: "Transversale Ebene auf Höhe Angulus sterni/Th4-5 trennt oberes von unterem Mediastinum; unteres Mediastinum weiter unterteilt in vorderes, mittleres (Herz/Perikard) und hinteres (Ösophagus, Aorta descendens, Ductus thoracicus)." },

  // ===== PHYSIOLOGIE (Vertiefung) =====
  { id: "fc-phys-031", module: "physiologie", subtopic: "atmung", front: "Was bezeichnen Closing Volume und Closing Capacity?", back: "Closing Volume: Lungenvolumen, ab dem kleine Atemwege in abhängigen Lungenarealen bei Exspiration zu kollabieren beginnen; Closing Capacity = Closing Volume + Residualvolumen. Übersteigt sie die FRC, kommt es zu Atemwegsverschluss während normaler Exspiration." },
  { id: "fc-phys-032", module: "physiologie", subtopic: "atmung", front: "Was unterscheidet statische von dynamischer Lungencompliance?", back: "Statische Compliance = ΔVolumen/ΔDruck ohne Gasfluss (Plateaubedingungen, ~100ml/cmH2O); dynamische Compliance wird während des Gasflusses gemessen und zusätzlich vom Atemwegswiderstand beeinflusst (daher meist niedriger)." },
  { id: "fc-phys-033", module: "physiologie", subtopic: "atmung", front: "Aus welchen Komponenten setzt sich die Atemarbeit (Work of Breathing) zusammen?", back: "Elastische Arbeit (gegen die Compliance von Lunge/Thorax) und resistive Arbeit (gegen den Atemwegs-/Gewebewiderstand); erhöht bei restriktiven (elastisch) bzw. obstruktiven (resistiv) Erkrankungen." },
  { id: "fc-phys-034", module: "physiologie", subtopic: "atmung", front: "Was unterscheidet anatomischen von alveolärem Totraum?", back: "Anatomischer Totraum: Volumen der leitenden Atemwege ohne Gasaustausch (~150ml); alveolärer Totraum: belüftete, aber nicht/schlecht perfundierte Alveolen (z.B. Lungenembolie). Summe = physiologischer Totraum (Bohr-Formel)." },
  { id: "fc-phys-035", module: "physiologie", subtopic: "atmung", front: "Wie verändert sich die CO2-Antwortkurve unter Opioiden/Anästhetika?", back: "Rechtsverschiebung und Abflachung der Kurve: Das Atemzentrum reagiert schwächer und erst bei höherem paCO2 mit gesteigertem Atemminutenvolumen – Grundlage der medikamentösen Atemdepression." },
  { id: "fc-phys-036", module: "physiologie", subtopic: "kreislauf", front: "Was zeigt die Druck-Volumen-Kurve (PV-Loop) eines Herzzyklus und was repräsentiert ihre Fläche?", back: "Die vier Phasen isovolumetrische Kontraktion, Austreibung, isovolumetrische Relaxation und Füllung; die eingeschlossene Fläche entspricht der externen Schlagarbeit (Stroke Work) des Ventrikels." },
  { id: "fc-phys-037", module: "physiologie", subtopic: "kreislauf", front: "Welche Faktoren bestimmen die Nachlast des linken Ventrikels?", back: "Vor allem der periphere Gefäßwiderstand (SVR), zusätzlich die ventrikuläre Wandspannung (Laplace-Gesetz), die Aortenimpedanz und die Blutviskosität." },
  { id: "fc-phys-038", module: "physiologie", subtopic: "kreislauf", front: "Welche Funktion hat die Windkesselfunktion der Aorta?", back: "Elastische Dehnung der Aorta/großen Arterien während der Systole puffert den pulsatilen Auswurf und wandelt ihn in einen kontinuierlicheren peripheren Blutfluss um; Elastizitätsverlust im Alter erhöht systolischen Druck und Pulsdruck." },
  { id: "fc-phys-039", module: "physiologie", subtopic: "kreislauf", front: "Wodurch wird die koronare Durchblutung an den myokardialen Sauerstoffbedarf gekoppelt?", back: "Primär durch lokale metabolische Faktoren, v.a. Adenosinfreisetzung bei erhöhtem O2-Bedarf/relativer Ischämie, das die Koronarwiderstandsgefäße dilatiert (zusätzlich ATP, K+, CO2, H+); über weiten Druckbereich autoreguliert." },
  { id: "fc-phys-040", module: "physiologie", subtopic: "kreislauf", front: "Was ist der Schockindex und wofür wird er genutzt?", back: "Herzfrequenz/systolischer Blutdruck; Normwert ca. 0,5-0,7. Ein Wert >1 gilt als sensitiver Frühindikator einer relevanten Hypovolämie/Blutung, auch wenn der Blutdruck (kompensierte Schockphase) noch normwertig ist." },
  { id: "fc-phys-041", module: "physiologie", subtopic: "niere-saeure-basen", front: "Wie entsteht der kortikomedulläre osmotische Gradient der Niere?", back: "Durch den Gegenstromvervielfältiger-Mechanismus der Henle-Schleife (aktiver NaCl-Transport im dicken aufsteigenden Teil); die Vasa recta wirken als Gegenstromaustauscher und erhalten den Gradienten – Voraussetzung für ADH-abhängige Harnkonzentrierung." },
  { id: "fc-phys-042", module: "physiologie", subtopic: "niere-saeure-basen", front: "Welche Kräfte bestimmen den glomerulären Filtrationsdruck?", back: "Hydrostatischer Druck in den Glomeruluskapillaren (treibend) minus hydrostatischer Druck in der Bowman-Kapsel minus onkotischer Druck der Kapillaren; zusätzlich moduliert durch Filtrationskoeffizient Kf und Tonus der afferenten/efferenten Arteriole." },
  { id: "fc-phys-043", module: "physiologie", subtopic: "niere-saeure-basen", front: "Wie wird eine akute Hyperkaliämie durch Insulin/Beta2-Agonisten behandelt (Wirkprinzip)?", back: "Beide steigern die Aktivität der Na+/K+-ATPase und verschieben Kalium akut nach intrazellulär – rasche Senkung des Serumkaliums, ohne das Gesamtkörperkalium zu verändern (im Gegensatz zu eliminierenden Verfahren wie Dialyse)." },
  { id: "fc-phys-044", module: "physiologie", subtopic: "niere-saeure-basen", front: "Wie lautet die Henderson-Hasselbalch-Gleichung und was zeigt sie?", back: "pH = 6,1 + log([HCO3-]/(0,03×pCO2)); zeigt, dass der pH vom Verhältnis aus renal reguliertem Bikarbonat und respiratorisch reguliertem CO2 abhängt (physiologisches Verhältnis ca. 20:1)." },
  { id: "fc-phys-045", module: "physiologie", subtopic: "niere-saeure-basen", front: "Wie verändert eine Hypalbuminämie die Interpretation der Anionenlücke?", back: "Die albuminkorrigierte Anionenlücke steigt um ca. 2,5mmol/l pro 1g/dl Albuminabfall unter den Normwert – ohne Korrektur kann eine erhöhte AG-Azidose bei kritisch Kranken mit Hypalbuminämie leicht übersehen werden." },
  { id: "fc-phys-046", module: "physiologie", subtopic: "leber-stoffwechsel", front: "Wie verteilt sich die Blutversorgung der Leber auf Pfortader und A. hepatica?", back: "V. portae liefert ca. 70-75% des Blutflusses (nährstoffreich, aber partiell desoxygeniert), A. hepatica propria ca. 25-30%; da arterielles Blut sauerstoffreicher ist, tragen beide Gefäße jeweils etwa hälftig zur hepatischen Sauerstoffversorgung bei." },
  { id: "fc-phys-047", module: "physiologie", subtopic: "leber-stoffwechsel", front: "Wie verläuft der Bilirubinstoffwechsel von der Bildung bis zur Ausscheidung?", back: "Hämabbau → unkonjugiertes (indirektes) Bilirubin, wasserunlöslich, albumingebunden im Plasma → hepatische Aufnahme und Konjugation durch UDP-Glucuronyltransferase → konjugiertes (direktes), wasserlösliches Bilirubin → aktive Sekretion in die Galle." },
  { id: "fc-phys-048", module: "physiologie", subtopic: "leber-stoffwechsel", front: "Welche CYP450-Isoenzyme sind für die Anästhesie besonders relevant (neben CYP3A4)?", back: "CYP2D6 (z.B. Aktivierung von Codein zu Morphin, Tramadol zu O-Desmethyltramadol – genetischer Polymorphismus mit relevanten Wirkunterschieden), CYP2E1 (Metabolisierung volatiler Anästhetika, v.a. Halothan, in geringerem Maß Sevofluran)." },
  { id: "fc-phys-049", module: "physiologie", subtopic: "leber-stoffwechsel", front: "Wie wird Ammoniak im Körper entgiftet und was passiert bei Leberinsuffizienz?", back: "Ammoniak entsteht v.a. beim Aminosäureabbau und durch bakterielle Darmflora; der hepatische Harnstoffzyklus wandelt es in Harnstoff zur renalen Ausscheidung um. Bei Leberinsuffizienz akkumuliert Ammoniak und trägt zur hepatischen Enzephalopathie bei." },
  { id: "fc-phys-050", module: "physiologie", subtopic: "leber-stoffwechsel", front: "Welche Parameter fließen in den Child-Pugh-Score ein und wozu dient er?", back: "Bilirubin, Albumin, INR/Quick, Aszites und hepatische Enzephalopathie (je 1-3 Punkte); Summe 5-15 Punkte klassifiziert die Leberfunktionsreserve in Child A (5-6), B (7-9), C (10-15) – relevant für die perioperative Risikoabschätzung." },
  { id: "fc-phys-051", module: "physiologie", subtopic: "zns", front: "Wo wird Liquor produziert und resorbiert, und wie hoch ist die Produktionsrate?", back: "Produktion v.a. im Plexus choroideus, ca. 500ml/Tag bei einem Gesamtvolumen von nur ca. 150ml (mehrfacher täglicher Austausch); Resorption über Arachnoidalzotten in die venösen Sinus durae matris." },
  { id: "fc-phys-052", module: "physiologie", subtopic: "zns", front: "Wodurch wird die Blut-Hirn-Schranke strukturell gebildet?", back: "Durchgehende Tight Junctions zwischen den Endothelzellen zerebraler Kapillaren, unterstützt durch Perizyten und astrozytäre Endfüße; lipophile Substanzen passieren leichter als polare/große Moleküle." },
  { id: "fc-phys-053", module: "physiologie", subtopic: "zns", front: "Was versteht man unter der Kopplung von CMRO2 und zerebralem Blutfluss?", back: "Zerebraler Blutfluss (CBF) und zerebraler Sauerstoffverbrauch (CMRO2) sind normalerweise eng gekoppelt (metabolic flow coupling); die meisten Anästhetika senken CMRO2 und CBF parallel, volatile Anästhetika können diese Kopplung bei höherer Dosierung durch direkte zerebrale Vasodilatation teilweise aufheben." },
  { id: "fc-phys-054", module: "physiologie", subtopic: "zns", front: "Aus welchen Kategorien besteht die Glasgow Coma Scale und was gilt als Schwellenwert für eine Atemwegssicherung?", back: "Augenöffnung (max. 4), verbale Reaktion (max. 5), motorische Reaktion (max. 6), Summe 3-15; ein Wert ≤8 gilt klassisch als Indikation zur Atemwegssicherung." },
  { id: "fc-phys-055", module: "physiologie", subtopic: "zns", front: "Wie wirken die gängigen intravenösen Hypnotika im Vergleich zu Ketamin auf CBF/ICP?", back: "Propofol, Barbiturate und Benzodiazepine senken CMRO2, zerebralen Blutfluss und ICP parallel; Ketamin gilt traditionell als CBF/ICP-steigernd, zeigt unter kontrollierter Normoventilation und in Kombination mit einem GABAergen Sedativum jedoch meist stabile oder sogar gesenkte Werte." },
  { id: "fc-phys-056", module: "physiologie", subtopic: "temperatur-endokrin", front: "Welche Mechanismen dominieren den perioperativen Wärmeverlust nach der initialen Redistributionsphase?", back: "Radiation (Wärmestrahlung, meist größter Einzelanteil), Konvektion, Evaporation und Konduktion an die Umgebung übersteigen die anästhesiebedingt verminderte metabolische Wärmeproduktion (lineare zweite Phase)." },
  { id: "fc-phys-057", module: "physiologie", subtopic: "temperatur-endokrin", front: "Wie beeinflussen Schilddrüsenfunktionsstörungen die Anästhesieführung?", back: "Hyperthyreose: erhöhter Grundumsatz, Tachykardie, erhöhte Katecholaminempfindlichkeit, Risiko der thyreotoxischen Krise; Hypothyreose: verminderter Metabolismus, verzögerte Medikamentenclearance, Kälteintoleranz, Risiko des Myxödemkomas." },
  { id: "fc-phys-058", module: "physiologie", subtopic: "temperatur-endokrin", front: "Worin unterscheiden sich primäre und sekundäre NNR-Insuffizienz laborchemisch?", back: "Primär (M. Addison): Ausfall aller NNR-Zonen inkl. Mineralokortikoide → Hyponatriämie, Hyperkaliämie; sekundär (ACTH-Mangel, z.B. Langzeit-Steroidtherapie): Mineralokortikoidachse über RAAS meist erhalten → Elektrolyte meist nahezu normal." },
  { id: "fc-phys-059", module: "physiologie", subtopic: "temperatur-endokrin", front: "Wie reagiert der Stoffwechsel eines Diabetikers auf chirurgischen Stress?", back: "Anstieg kontrainsulinärer Hormone (Kortisol, Katecholamine, Glukagon, Wachstumshormon) verstärkt die ohnehin bestehende Insulinresistenz → ausgeprägte perioperative Hyperglykämie mit erhöhtem Risiko für diabetische Ketoazidose bzw. hyperosmolares Koma." },
  { id: "fc-phys-060", module: "physiologie", subtopic: "temperatur-endokrin", front: "Was unterscheidet zentralen von nephrogenem Diabetes insipidus?", back: "Zentraler DI: verminderte hypophysäre ADH-Sekretion (z.B. nach Hypophysenchirurgie/SHT), spricht auf Desmopressin an; nephrogener DI: renale ADH-Resistenz, kein Ansprechen auf Desmopressin. Beide führen zu Polyurie mit hypotonem Urin und drohender Hypernatriämie." },

  // ===== PHYSIK & MESSTECHNIK (Vertiefung) =====
  { id: "fc-phys2-021", module: "physik-messtechnik", subtopic: "gasgesetze", front: "Wie ändert sich der laminare Gasfluss durch einen Tubus nach dem Hagen-Poiseuille-Gesetz, wenn sich der Innenradius verdoppelt (Druckgradient konstant)?", back: "Der Fluss steigt auf das 16-fache (Fluss ∝ Radius^4 bei laminarer Strömung); Radius ist somit der dominante Faktor für den Atemwegswiderstand." },
  { id: "fc-phys2-022", module: "physik-messtechnik", subtopic: "gasgesetze", front: "Was beschreibt der MAC-Wert (minimale alveoläre Konzentration)?", back: "Die alveoläre Konzentration eines Inhalationsanästhetikums bei 1 Atmosphäre, bei der 50% der Patienten auf einen Hautschnitt keine motorische Abwehrreaktion zeigen (ED50-Konzept)." },
  { id: "fc-phys2-023", module: "physik-messtechnik", subtopic: "gasgesetze", front: "Nenne je einen Faktor, der die MAC senkt bzw. erhöht.", back: "MAC-senkend: Hypothermie, hohes Alter, Opioide/Sedativa, N2O-Komedikation, Schwangerschaft. MAC-erhöhend: Hyperthermie, chronischer Alkoholabusus, Säuglingsalter (Gipfel um den 6. Lebensmonat)." },
  { id: "fc-phys2-024", module: "physik-messtechnik", subtopic: "gasgesetze", front: "Was versteht man unter dem 'kritischen Punkt' eines Stoffes im Phasendiagramm (im Unterschied zur kritischen Temperatur allein)?", back: "Die Kombination aus kritischer Temperatur UND kritischem Druck; oberhalb dieses Punktes existiert kein Unterschied mehr zwischen flüssiger und gasförmiger Phase (überkritischer Zustand)." },
  { id: "fc-phys2-025", module: "physik-messtechnik", subtopic: "gasgesetze", front: "Unterscheide Second-Gas-Effekt und Diffusionshypoxie bei Lachgas-Anästhesie.", back: "Second-Gas-Effekt: bei Induktion beschleunigt die rasche Aufnahme großer N2O-Mengen die alveoläre Anflutung von O2 und dem Begleit-Anästhetikum. Diffusionshypoxie: bei Beendigung diffundiert N2O rasch aus dem Blut zurück in die Alveolen und verdünnt dort O2/CO2 – deshalb kurzzeitig 100% O2 geben." },
  { id: "fc-phys2-026", module: "physik-messtechnik", subtopic: "monitoring", front: "Welche Kapnogramm-Veränderung tritt bei Rebreathing auf und warum?", back: "Die Basislinie (Phase I) steigt nicht mehr auf Null, da CO2-haltiges Gas rückgeatmet wird – meist durch unzureichenden Frischgasfluss oder erschöpften CO2-Absorber." },
  { id: "fc-phys2-027", module: "physik-messtechnik", subtopic: "monitoring", front: "Wie sieht das typische Kapnogramm bei Bronchospasmus aus?", back: "'Shark-Fin'-Muster: verlängerte, träge ansteigende Phase II und eine schräg (statt horizontal) ansteigende Phase III, durch verzögerte und ungleichmäßige alveoläre Entleerung." },
  { id: "fc-phys2-028", module: "physik-messtechnik", subtopic: "monitoring", front: "Welches physikalische Grundprinzip liegt der Lichtabsorptionsmessung der Pulsoxymetrie zugrunde, und wie wird daraus SpO2 abgeleitet?", back: "Beer-Lambert-Gesetz (Absorption ∝ Konzentration × Schichtdicke); aus dem pulsatilen Signal bei zwei Wellenlängen wird ein Absorptionsverhältnis (R-Wert) gebildet und anhand einer empirischen Kalibrierungskurve (aus Humanstudien mit bekannter SaO2) in SpO2 übersetzt." },
  { id: "fc-phys2-029", module: "physik-messtechnik", subtopic: "monitoring", front: "Was ist die Resonanzfrequenz eines invasiven Drucksystems und warum ist ein optimaler Dämpfungskoeffizient (~0,6-0,7) wichtig?", back: "Die Resonanz-/Eigenfrequenz von Schlauch-Transducer-System; liegt sie zu nah an den Frequenzanteilen der realen Druckkurve, kommt es zu Über- oder Unterdämpfung. Ein optimal gedämpftes System bildet die tatsächliche arterielle Druckkurve am genauesten ab." },
  { id: "fc-phys2-030", module: "physik-messtechnik", subtopic: "monitoring", front: "Was ist der Unterschied zwischen TOF-Ratio und Post-Tetanic-Count (PTC) im neuromuskulären Monitoring?", back: "TOF-Ratio (Verhältnis 4. zu 1. Reizantwort) beurteilt die Erholung bei vorhandenen TOF-Antworten (Extubationskriterium ≥0,9). PTC schätzt die Tiefe einer profunden Blockade (TOF-Count=0) mittels 5-Sekunden-Tetanus gefolgt von Einzelreizen, wenn keine TOF-Antworten mehr auslösbar sind." },
  { id: "fc-phys2-031", module: "physik-messtechnik", subtopic: "elektrische-sicherheit", front: "Was unterscheidet die Anwendungsteil-Klassen Typ B, BF und CF nach IEC 60601?", back: "Typ B = geerdeter Anwendungsteil, kein direkter Herzkontakt vorgesehen. Typ BF = potentialgetrennt ('floating'), kein direkter Herzkontakt. Typ CF = potentialgetrennt mit den niedrigsten zulässigen Ableitströmen, für Anwendungsteile mit direktem Herzkontakt (z.B. PA-Katheter, invasive Druckmessung)." },
  { id: "fc-phys2-032", module: "physik-messtechnik", subtopic: "elektrische-sicherheit", front: "Welche Funktion hat der Isolationswächter im IT-Netz des OP?", back: "Kontinuierliche Überwachung des Isolationswiderstands zwischen Leitern und Erde; löst beim ersten Fehler (Erdschluss) einen Alarm aus, OHNE die Stromversorgung zu unterbrechen – ein zweiter, unabhängiger Fehler müsste erst hinzukommen, um gefährlichen Fehlerstrom zu erzeugen." },
  { id: "fc-phys2-033", module: "physik-messtechnik", subtopic: "elektrische-sicherheit", front: "Ab welchem typischen Differenzstrom löst ein für den Personenschutz ausgelegter Fehlerstromschutzschalter (RCD) aus, und wovor schützt er primär?", back: "Typischerweise 30 mA (teils 10mA); schützt primär vor Makroschock-bedingtem Kammerflimmern durch schnelle Abschaltung. Vor Mikroschock (<1mA am Herzen) schützt diese Schwelle NICHT zuverlässig." },
  { id: "fc-phys2-034", module: "physik-messtechnik", subtopic: "elektrische-sicherheit", front: "Ab welcher Stromstärke besteht bei Makroschock (Strom über die intakte Haut) typischerweise Kammerflimmer-Gefahr?", back: "Ab ca. 50-100mA Wechselstrom (Netzfrequenz) bei Durchtritt durch den Thorax – deutlich höher als bei Mikroschock (<1mA direkt am Herzen), da sich der Strom über einen viel größeren Körperquerschnitt verteilt." },
  { id: "fc-phys2-035", module: "physik-messtechnik", subtopic: "elektrische-sicherheit", front: "Welche Sicherheitsmaßnahmen sind bei Elektrokauter-Einsatz an Patienten mit Schrittmacher/ICD zu beachten?", back: "Wenn möglich bipolare statt monopolare Diathermie; kurze Energieabgaben (<5s) mit Pausen statt Dauerkoagulation; Neutralelektrode so platzieren, dass der Stromweg nicht über Aggregat/Sonden verläuft; präoperative Umprogrammierung/Deaktivierung der Tachykardie-Therapie und postoperative Rückstellung; externe Defibrillation/Stimulation bereithalten." },
  { id: "fc-phys2-036", module: "physik-messtechnik", subtopic: "statistik-ebm", front: "Was gibt die Number Needed to Treat (NNT) an, und wie wird sie berechnet?", back: "Anzahl der Patienten, die behandelt werden müssen, um ein zusätzliches unerwünschtes Ereignis zu verhindern; NNT = 1 / ARR (absolute Risikoreduktion)." },
  { id: "fc-phys2-037", module: "physik-messtechnik", subtopic: "statistik-ebm", front: "Wann nähert sich die Odds Ratio (OR) dem relativen Risiko (RR) an, und wann weichen beide stark voneinander ab?", back: "Bei seltenen Ereignissen (Prävalenz/Inzidenz <~10%) approximiert die OR das RR gut. Bei häufigen Ereignissen überschätzt die OR das RR zunehmend – die OR liegt dann weiter von 1 entfernt als das RR." },
  { id: "fc-phys2-038", module: "physik-messtechnik", subtopic: "statistik-ebm", front: "Erkläre kurz Selektionsbias und Publikationsbias.", back: "Selektionsbias: systematische Verzerrung durch die Art der Teilnehmer-Auswahl (z.B. Ein-/Ausschlusskriterien, Non-Responder), sodass die Stichprobe nicht repräsentativ ist. Publikationsbias: Tendenz, dass Studien mit signifikanten/positiven Ergebnissen eher publiziert werden als neutrale/negative – verzerrt Metaanalysen." },
  { id: "fc-phys2-039", module: "physik-messtechnik", subtopic: "statistik-ebm", front: "Wie unterscheidet sich die Ausgangsbewertung von RCTs und Beobachtungsstudien im GRADE-System, und was kann diese verändern?", back: "RCTs starten als hochwertige Evidenz, Beobachtungsstudien (Kohorten-/Fall-Kontroll-Studien) starten niedrig. Die Einstufung kann durch Verzerrungsrisiko, Inkonsistenz, Ungenauigkeit oder Publikationsbias abgewertet, durch z.B. große Effektstärke aufgewertet werden." },
  { id: "fc-phys2-040", module: "physik-messtechnik", subtopic: "statistik-ebm", front: "Wie interpretiert man ein 95%-Konfidenzintervall für ein relatives Risiko, das den Wert 1 einschließt?", back: "Der beobachtete Unterschied ist statistisch nicht signifikant (auf dem 5%-Niveau) – ein tatsächlicher Effekt kann nicht zuverlässig von 'kein Unterschied' abgegrenzt werden." },

  // ===== LEITLINIEN-EMPFEHLUNGSKARTEN =====
  { id: "fc-ll-001", module: "intensivmedizin", subtopic: "sepsis-schock", guideline: "Surviving Sepsis Campaign 2026", front: "Was empfiehlt die Surviving Sepsis Campaign (SSC) 2021 zur initialen Flüssigkeitstherapie bei sepsisinduzierter Hypoperfusion oder septischem Schock?", back: "Innerhalb der ersten 3 Stunden mindestens 30 ml/kg KG kristalloide Lösung i.v. (schwache Empfehlung, niedrige Evidenzqualität – gegenüber früheren Fassungen abgeschwächt). Danach soll die weitere Flüssigkeitsgabe individualisiert anhand dynamischer Parameter und wiederholter Reassessment erfolgen, nicht schematisch bis zur Laktat-Normalisierung." },
  { id: "fc-ll-002", module: "intensivmedizin", subtopic: "sepsis-schock", guideline: "Surviving Sepsis Campaign 2026", front: "Welche Zeitvorgabe macht die Surviving Sepsis Campaign für den Beginn der antimikrobiellen Therapie bei Patienten mit septischem Schock bzw. hoher Sepsis-Wahrscheinlichkeit?", back: "SSC 2026 differenziert präziser: Bei möglichem/wahrscheinlichem/sicherem septischem Schock UND bei wahrscheinlicher/sicherer Sepsis ohne Schock sofort/idealerweise innerhalb 1 Stunde. Nur bei 'möglicher' Sepsis ohne Schock und unklarer Diagnose ist eine rasche, zeitlich begrenzte Abklärung infektiös vs. nicht-infektiös erlaubt, mit Antibiotikagabe spätestens innerhalb von 3 Stunden." },
  { id: "fc-ll-003", module: "intensivmedizin", subtopic: "sepsis-schock", guideline: "Surviving Sepsis Campaign 2026", front: "Welchen Vasopressor empfiehlt die Surviving Sepsis Campaign 2026 als Mittel der ersten Wahl beim septischen Schock?", back: "Noradrenalin als First-Line-Vasopressor (starke Empfehlung), bevorzugt gegenüber Dopamin, Adrenalin oder Selepressin. Bei unzureichendem MAP unter Noradrenalin wird die zusätzliche Gabe von Vasopressin vorgeschlagen, statt die Noradrenalin-Dosis weiter zu eskalieren." },
  { id: "fc-ll-004", module: "intensivmedizin", subtopic: "beatmung", guideline: "ARDS-Beatmungsleitlinien (ATS/ESICM/SCCM, ESICM 2023)", front: "Was empfiehlt die aktuelle ATS/ESICM/SCCM-Leitlinie zur invasiven Beatmung bei ARDS hinsichtlich Tidalvolumen und Plateaudruck?", back: "Lungenprotektive Beatmung mit Tidalvolumen ca. 4–8 ml/kg Standard-(Ideal-)Körpergewicht (meist Zielwert 6 ml/kg) und Begrenzung des Plateaudrucks auf < 30 cmH2O (starke Empfehlung)." },
  { id: "fc-ll-005", module: "intensivmedizin", subtopic: "beatmung", guideline: "ARDS-Beatmungsleitlinien (ATS/ESICM/SCCM, ESICM 2023)", front: "Ab welchem Oxygenierungsgrenzwert empfiehlt die ESICM-Leitlinie 2023 die Bauchlagerung bei ARDS, und für welche Mindestdauer?", back: "Bei PaO2/FiO2 < 150 mmHg (unter PEEP > 5 cmH2O) frühzeitige Bauchlagerung, für mindestens 16 Stunden pro Zyklus." },
  { id: "fc-ll-006", module: "intensivmedizin", subtopic: "nierenersatz", guideline: "KDIGO-Leitlinie (Nierenersatztherapie)", front: "Wann soll laut KDIGO-Leitlinie eine Nierenersatztherapie bei akuter Nierenschädigung (AKI) unbedingt (emergent) begonnen werden?", back: "Sofort bei lebensbedrohlichen Störungen des Flüssigkeits-, Elektrolyt- oder Säure-Basen-Haushalts (z.B. therapierefraktäre Hyperkaliämie, schwere Azidose, Lungenödem). Außerhalb solcher Notfallindikationen soll eher der klinische Gesamtkontext und der Verlaufstrend als ein einzelner Kreatinin-/Diurese-Wert entscheiden – gestützt u.a. durch die STARRT-AKI-Studie, die keinen generellen Vorteil einer frühzeitigen ('akzelerierten') Initiierung zeigte." },
  { id: "fc-ll-007", module: "intensivmedizin", subtopic: "nierenersatz", guideline: "KDIGO-Leitlinie (Nierenersatztherapie)", front: "Welche Modalität der Nierenersatztherapie empfiehlt KDIGO bevorzugt bei hämodynamisch instabilen Intensivpatienten?", back: "Kontinuierliche Nierenersatztherapie (CRRT) statt intermittierender Hämodialyse (schwache Empfehlung) – hämodynamisch meist besser toleriert, ohne in RCTs gesicherten Mortalitätsvorteil." },
  { id: "fc-ll-008", module: "intensivmedizin", subtopic: "ernaehrung", guideline: "ESPEN-Leitlinie 2023 (Klinische Ernährung)", front: "Welchen Proteinzielwert nennt die ESPEN-Leitlinie 2023 für erwachsene Intensivpatienten, und wie soll er erreicht werden?", back: "Etwa 1,3 g Proteinäquivalente/kg KG/Tag, progressiv im Verlauf des ICU-Aufenthalts gesteigert – nicht als sofortiges Vollziel ab Tag 1." },
  { id: "fc-ll-009", module: "intensivmedizin", subtopic: "ernaehrung", guideline: "ESPEN-Leitlinie 2023 (Klinische Ernährung)", front: "Ab wann soll laut ESPEN 2023 das volle Energieziel bei kritisch Kranken erreicht werden – und warum erst dann?", back: "In der Regel nicht vor 48–72 Stunden nach ICU-Aufnahme, sondern schrittweise gesteigert nach lokalem Protokoll, um eine Überernährung ('Overfeeding') in der frühen Akutphase zu vermeiden." },
  { id: "fc-ll-010", module: "intensivmedizin", subtopic: "ernaehrung", guideline: "ESPEN-Leitlinie 2023 (Klinische Ernährung)", front: "Welchen Kalorien-Zielkorridor (bezogen auf den Ruheenergieumsatz, REE) nennt ESPEN 2023 für die volle medizinische Ernährungstherapie?", back: "Mehr als 70%, aber nicht über 100% des – idealerweise per indirekter Kalorimetrie gemessenen – Ruheenergieumsatzes." },
  { id: "fc-ll-011", module: "intensivmedizin", subtopic: "sedierung-delir", guideline: "PADIS-Leitlinien (Sedierung & Delir)", front: "Was versteht man unter dem von den PADIS-Leitlinien propagierten 'Analgesia-first'-Prinzip (Analgosedierung)?", back: "Vor bzw. anstelle einer Sedativagabe wird zunächst ein Opioid zur Schmerzkontrolle titriert; der Sedierungsbedarf soll, wo möglich, primär durch adäquate Analgesie statt durch zusätzliche Sedativa gedeckt werden." },
  { id: "fc-ll-012", module: "intensivmedizin", subtopic: "sedierung-delir", guideline: "PADIS-Leitlinien (Sedierung & Delir)", front: "Welche Sedativaklasse soll laut PADIS-Leitlinien bei erwachsenen Intensivpatienten möglichst vermieden werden?", back: "Benzodiazepine – eine nicht-benzodiazepinbasierte Sedierung (z.B. Propofol oder Dexmedetomidin) wird bevorzugt empfohlen, da Benzodiazepine mit ungünstigeren Outcomes (u.a. mehr Delir, längere Beatmungsdauer) assoziiert sind." },
  { id: "fc-ll-013", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "ESAIC Perioperative Fasting Guideline (Erwachsene, Update 2026)", front: "Was empfiehlt die aktuelle ESAIC-Leitlinie 'Perioperative Fasting' bezüglich klarer Flüssigkeiten vor elektiven Eingriffen?", back: "Klare Flüssigkeiten dürfen bis 2 Stunden vor Anästhesiebeginn getrunken werden (auch vor elektiver Sectio caesarea); Tee/Kaffee mit etwas Milch gelten weiterhin als klare Flüssigkeit. NEU (ESAIC-2026-Update mit EAES): eine Flüssigkeitsaufnahme <2h vor Anästhesie ist ALLEIN kein Grund, den Eingriff zu verschieben oder abzusagen – Einzelfallentscheidung statt starrer Absage." },
  { id: "fc-ll-014", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "ESAIC Perioperative Fasting Guideline (Erwachsene, Update 2026)", front: "Welche Nüchternheitszeit für feste Nahrung/Milchprodukte empfiehlt die aktuelle ESAIC-Leitlinie vor elektiven Eingriffen bei Erwachsenen?", back: "Leichte Mahlzeit ca. 6 Stunden 'oder länger', fett-/proteinreiche/üppige Mahlzeit ca. 8 Stunden 'oder länger' (Zusatz 'oder länger' im 2026-Update explizit wegen verzögerter Magenentleerung z.B. unter GLP-1-Rezeptoragonisten oder bei Gastroparese – individuelle Beurteilung statt starrer Zeitgrenze)." },
  { id: "fc-ll-015", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "ESAIC Perioperative Fasting Guideline (Erwachsene, Update 2026)", front: "Ist Kaugummikauen unmittelbar vor Anästhesieeinleitung laut aktueller Nüchternheits-Leitlinie ein Grund für eine OP-Verschiebung?", back: "Nein – Kaugummikauen oder das Lutschen eines Bonbons unmittelbar vor Einleitung rechtfertigt laut aktueller Empfehlung keine Verschiebung oder Absage der Operation." },
  { id: "fc-ll-016", module: "notfall-reanimation", subtopic: "als-bls", guideline: "ERC-Leitlinien 2021/2025 (Reanimation)", front: "In welchem Intervall soll laut ERC-Leitlinien (2025) Adrenalin während der Reanimation beim Erwachsenen wiederholt gegeben werden?", back: "Etwa alle 3–5 Minuten (im ERC-Algorithmus konkret alle 4 Minuten); bei nicht-schockbarem Rhythmus so früh wie möglich, bei schockbarem Rhythmus erst nach der 3. erfolglosen Defibrillation." },
  { id: "fc-ll-017", module: "notfall-reanimation", subtopic: "als-bls", guideline: "ERC-Leitlinien 2021/2025 (Reanimation)", front: "Was empfehlen die ERC/ESICM-Leitlinien (2021, aktualisiert 2025) zum Temperaturmanagement komatöser Patienten nach ROSC?", back: "Aktive Fiebervermeidung (Fieber definiert als >37,7°C, Ziel meist ≤37,5°C) für MINDESTENS 72 Stunden nach ROSC mittels Antipyretika/Exposition, bei Bedarf Kühlgerät – die genaue Zeitfensterangabe variiert zwischen Quellen leicht (teils '36–72h' zitiert), maßgeblich ist die ERC-ESICM-Temperaturleitlinie 2022/2025 mit 'mindestens 72h'. Eine generelle Zielhypothermie 32–36°C wird nicht mehr empfohlen; spontan leicht hypotherme Patienten sollen nicht aktiv auf Normothermie aufgewärmt werden, präklinische Kaltinfusionen werden ebenfalls nicht empfohlen." },
  { id: "fc-ll-018", module: "notfall-reanimation", subtopic: "als-bls", guideline: "ERC-Leitlinien 2021/2025 (Reanimation)", front: "Welche Kompressionsfrequenz, -tiefe und welches Kompressions-Beatmungs-Verhältnis empfehlen die ERC-Leitlinien (2025) für die Basisreanimation beim Erwachsenen ohne gesicherten Atemweg?", back: "Frequenz 100–120/min, Tiefe 5–6cm, Verhältnis 30 Kompressionen zu 2 Beatmungen (30:2) – unverändert seit 2021." },
  { id: "fc-ll-019", module: "regional-schmerz", subtopic: "neuraxial-verfahren", guideline: "ESRA-Leitlinie (Neuraxiale Verfahren & Antikoagulation)", front: "Welches Zeitintervall empfiehlt die ESRA-Leitlinie zwischen der letzten LMWH-Dosis und einer neuraxialen Punktion/Katheteranlage?", back: "Mindestens 12 Stunden nach einer prophylaktischen LMWH-Dosis, mindestens 24 Stunden nach einer therapeutischen LMWH-Dosis." },
  { id: "fc-ll-020", module: "regional-schmerz", subtopic: "neuraxial-verfahren", guideline: "ESRA-Leitlinie (Neuraxiale Verfahren & Antikoagulation)", front: "Welches Zeitintervall empfiehlt die ESRA-Leitlinie zwischen der Entfernung eines Periduralkatheters und der nächsten LMWH-Gabe?", back: "Mindestens 4 Stunden nach Katheterentfernung bis zur nächsten LMWH-Dosis; umgekehrt soll auch die Katheterentfernung selbst zeitlich passend zum LMWH-Spiegel geplant werden (analog dem präprozeduralen Intervall). Eine gleichzeitige Gabe weiterer gerinnungswirksamer Substanzen bei liegendem Katheter wird nicht empfohlen." },
  { id: "fc-ll-021", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", guideline: "ESAIC Bleeding-Management-Leitlinie", front: "Ab welchem Fibrinogen-Trigger empfiehlt die ESAIC-Leitlinie 'Management of severe peri-operative bleeding' (2. Update 2022/2023) eine Substitution mit Fibrinogenkonzentrat/Kryopräzipitat?", back: "Bei klinisch relevanter Blutung mit viskoelastischen Zeichen eines funktionellen Fibrinogenmangels oder einem Plasma-Fibrinogen (Clauss) von etwa ≤ 1,5 g/l." },
  { id: "fc-ll-022", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", guideline: "ESAIC Bleeding-Management-Leitlinie", front: "Welches Transfusionsverhältnis (Erythrozyten:Plasma:Thrombozyten) legt die ESAIC-Bleeding-Management-Leitlinie im Rahmen eines Massivtransfusionsprotokolls nahe, solange keine labor-/viskoelastisch gesteuerte Therapie verfügbar ist?", back: "Ein frühes, meist fixes Verhältnis von etwa 1:1:1 (EK:FFP:Thrombozytenkonzentrat), bis eine ziel- bzw. laborgesteuerte Gerinnungstherapie (z.B. viskoelastische Verfahren) etabliert werden kann." },
  { id: "fc-ll-023", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", guideline: "ASA Practice Guidelines for Obstetric Anesthesia", front: "Welche medikamentöse Aspirationsprophylaxe empfiehlt die aktuelle geburtshilfliche Anästhesie-Leitlinie (ASA Practice Guidelines for Obstetric Anesthesia) vor Sectio caesarea, insbesondere bei Allgemeinanästhesie?", back: "Zeitnahe Gabe eines nichtpartikulären Antazidums (z.B. Natriumcitrat 0,3 M oral), ggf. zusätzlich ein H2-Blocker oder Protonenpumpeninhibitor sowie ein Prokinetikum (z.B. Metoclopramid)." },
  { id: "fc-ll-024", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", guideline: "ASA Practice Guidelines for Obstetric Anesthesia", front: "Was empfiehlt die aktuelle geburtshilfliche Anästhesie-Leitlinie zur oralen Flüssigkeitsaufnahme bei Sectio-Patientinnen ohne zusätzliche Aspirationsrisikofaktoren?", back: "Moderate Mengen klarer Flüssigkeiten können auch bei elektiver Sectio bis kurz vor Anästhesie erlaubt werden (analog der 2h-Regel); feste Nahrung soll dagegen 6–8 Stunden vorher gemieden werden." },
  { id: "fc-ll-025", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", guideline: "DAS-Leitlinien (Schwieriger Atemweg, Update 2025)", front: "Welches Grundprinzip verfolgen die DAS-Leitlinien zur unerwarteten schwierigen Atemwegssicherung (Plan A–D)?", back: "Die Pläne A–D bilden eine gestufte Eskalation mit dem Ziel, jederzeit die Oxygenierung zu sichern (nicht die Intubation um jeden Preis): Plan A (Präoxygenierung + Intubationsversuch, max. 3 Versuche plus ggf. 1 Versuch durch einen erfahreneren Kollegen; DAS 2025: Videolaryngoskopie ist jetzt First-Line-Standardverfahren für JEDE Intubation, nicht nur 'frühzeitig einsetzbar'), Plan B (Etablierung der Oxygenierung über eine supraglottische Atemwegshilfe der 2. Generation, max. 3 Versuche), Plan C (Rückkehr zur Maskenbeatmung, bei Misserfolg Aufwachen als Standardoption) und Plan D (notfallmäßiger invasiver Atemweg / 'Front-of-Neck-Access')." },
  { id: "fc-ll-026", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", guideline: "DAS-Leitlinien (Schwieriger Atemweg, Update 2025)", front: "Welche Technik empfehlen die DAS-Leitlinien als bevorzugtes Vorgehen bei der 'Cannot-Intubate-Cannot-Oxygenate' (CICO)-Situation (Plan D)?", back: "Die notfallmäßige chirurgische Krikothyreotomie ('Scalpel-Bougie-Tubus'-Technik), in DAS 2025 als Standard für ALLE Patienten vereinheitlicht/präzisiert: vertikale Hautinzision über der Membrana cricothyroidea (ca. bis 8cm), horizontale Stichinzision durch die Membran, Einführen einer Bougie zur Führung, anschließend Vorschieben eines Tubus (Größe ~6.0) über die Bougie – Standardausrüstung: Skalpell Nr. 10, Bougie, 6.0er-Tubus." },
  { id: "fc-ll-027", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", guideline: "DAS-Leitlinien (Schwieriger Atemweg, Update 2025)", front: "Welchen Stellenwert räumen aktuelle Atemwegs-Leitlinien (DAS 2025) der Videolaryngoskopie gegenüber der konventionellen direkten Laryngoskopie ein?", back: "DAS 2025 (Nachfolger von DAS 2015): Videolaryngoskopie ist der ausdrückliche First-Line-Standard für JEDE Intubation unter Allgemeinanästhesie (nicht mehr nur 'zunehmend bevorzugt' oder Sonderfall), da sie im Vergleich zur direkten Laryngoskopie eine bessere glottische Sicht ermöglicht und mit weniger Fehlintubationen sowie selteneren Hypoxämie-Episoden assoziiert ist; zusätzlicher Fokus auf Erfolg beim ersten Versuch und vollständige Relaxierung vor Intubationsversuch." },
  { id: "fc-ll-028", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "5th Consensus Guideline PONV (Gan et al. 2025)", front: "Welche vier Risikofaktoren umfasst der Apfel-Score zur Einschätzung des PONV-Risikos, und wie verändert sich das Risiko mit deren Anzahl?", back: "Weibliches Geschlecht, Nichtraucher-Status, (Reisekrankheit-/PONV-)Anamnese und postoperativer Opioidbedarf. Mit 0/1/2/3/4 vorhandenen Faktoren steigt das PONV-Risiko jeweils um etwa 10/20/40/60/80%." },
  { id: "fc-ll-029", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "5th Consensus Guideline PONV (Gan et al. 2025)", front: "Wie viele antiemetische Prophylaxe-Maßnahmen empfiehlt die aktuelle PONV-Konsensus-Leitlinie je nach Anzahl der Apfel-Risikofaktoren?", back: "5th Consensus (2025) – Paradigmenwechsel weg von strikter Risikostratifizierung: routinemäßig 1–2 Antiemetika für ALLE chirurgischen Patienten, da sich Risikoscores (z.B. Apfel) in der Praxis als zu unzuverlässig erwiesen haben, um Patienten mit Prophylaxebedarf zuverlässig zu identifizieren. Bei moderatem/hohem Risiko wird eine 2- bis 3-fach-Kombination aus unterschiedlichen Wirkklassen (5-HT3-Antagonisten, Kortikosteroide, NK1-Antagonisten, Dopaminantagonisten, Anticholinergika, Antihistaminika) empfohlen, ggf. ergänzt durch eine Propofol-TIVA. (Frühere 4th-Consensus-Fassung 2020: Prophylaxe nur gestuft nach Risikofaktoren, bei niedrigem Risiko optional.)" },
  { id: "fc-ll-030", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "ASA Practice Advisory (Intraoperative Awareness)", front: "Was empfiehlt die ASA Practice Advisory zur intraoperativen Awareness bezüglich des routinemäßigen Einsatzes von BIS/EEG-basierten Monitoren?", back: "Keinen generellen Routineeinsatz bei allen Patienten – die Entscheidung für ein Bewusstseinsmonitoring (z.B. BIS) soll fallbezogen getroffen werden, insbesondere bei Patienten mit erhöhtem Awareness-Risiko (z.B. TIVA mit Muskelrelaxierung, bekannte schwierige Intubation, Herzchirurgie, Sectio, Trauma-/Notfallchirurgie, reduzierte Anästhetikadosierung)." },
  { id: "fc-ll-031", module: "regional-schmerz", subtopic: "periphere-blockaden", guideline: "ASRA/ESRA-Leitlinie (Periphere Nervenblockaden & Antikoagulation)", front: "Wie unterscheiden die ASRA/ESRA-Leitlinien zur Regionalanästhesie unter Antikoagulation periphere Nervenblockaden hinsichtlich des Blutungsrisikos?", back: "Es wird zwischen oberflächlichen/komprimierbaren Blockaden (z.B. interskalenär, femoral, axillär) mit niedrigerem Blutungsrisiko und tiefen/nicht-komprimierbaren Blockaden (z.B. Plexus-lumbalis-Block, tiefe paravertebrale Blockade) mit höherem, den neuraxialen Verfahren vergleichbarem Blutungsrisiko unterschieden." },
  { id: "fc-ll-032", module: "regional-schmerz", subtopic: "periphere-blockaden", guideline: "ASRA/ESRA-Leitlinie (Periphere Nervenblockaden & Antikoagulation)", front: "Welche zeitlichen Karenzintervalle zur Antikoagulation gelten laut ASRA/ESRA für tiefe periphere Nervenblockaden im Vergleich zu oberflächlichen Blockaden?", back: "Für tiefe/nicht-komprimierbare Blockaden gelten meist dieselben (strengen) Zeitintervalle wie für neuraxiale Verfahren; für oberflächliche/komprimierbare Blockaden werden diese strikten Karenzzeiten dagegen nicht in gleichem Maß gefordert – sie können häufig auch unter fortgeführter Antikoagulation (meist unter Ultraschallsicht) durchgeführt werden." },
  { id: "fc-ll-033", module: "regional-schmerz", subtopic: "periphere-blockaden", guideline: "ASRA/ESRA-Leitlinie (Periphere Nervenblockaden & Antikoagulation)", front: "Beeinflusst der Einsatz von Ultraschall laut ASRA/ESRA-Leitlinie die geforderten Zeitintervalle vor peripheren Nervenblockaden unter Antikoagulation?", back: "Nein – Ultraschallführung verbessert zwar die Sicherheit und Visualisierung der Punktion, ändert aber laut Leitlinie nichts an den empfohlenen Zeitintervallen zur letzten Einnahme eines Antithrombotikums vor oberflächlichen oder tiefen peripheren Blockaden." },
  { id: "fc-ll-034", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "PROSPECT-Initiative (ESRA)", front: "Was ist das Grundprinzip der PROSPECT-Initiative (ESRA) zur postoperativen Schmerztherapie?", back: "Prozedur-spezifische, evidenzbasierte Empfehlungen (statt generischer Standardschemata) für einzelne Eingriffe, basierend auf systematischen Übersichtsarbeiten randomisiert-kontrollierter Studien; Basis bildet meist ein multimodales Konzept aus Basisanalgesie (z.B. Paracetamol/NSAR), lokaler Wundinfiltration bzw. Regionalanästhesie, mit systemischen Opioiden vorwiegend als Reserve-/Rescue-Medikation." },
  { id: "fc-ll-035", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "NICE NG193 (Chronischer Schmerz)", front: "Was empfiehlt die aktuelle NICE-Leitlinie NG193 zum Beginn einer Opioidtherapie bei chronischem primärem Schmerz?", back: "Von einem Therapiebeginn mit Opioiden wird abgeraten, da die Evidenz für einen Langzeitnutzen fehlt, während das Risiko für Abhängigkeit und Schäden bei mehrmonatiger Anwendung steigt – ebenso wird von anderen Substanzklassen wie Antiepileptika, Benzodiazepinen oder NSAR als Dauertherapie bei chronischem primärem Schmerz abgeraten." },
  { id: "fc-ll-036", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "NICE NG193 (Chronischer Schmerz)", front: "Welche nichtmedikamentösen bzw. medikamentösen Alternativen empfiehlt NICE NG193 anstelle von Opioiden bei chronischem primärem Schmerz?", back: "Vorrangig nichtmedikamentöse Maßnahmen wie strukturierte Bewegungsprogramme, psychologische Therapie (z.B. Akzeptanz- und Commitmenttherapie oder kognitive Verhaltenstherapie) und Akupunktur; medikamentös kommt am ehesten ein Versuch mit einem Antidepressivum (z.B. SSRI oder trizyklisches Antidepressivum) infrage." },
  { id: "fc-ll-037", module: "notfall-reanimation", subtopic: "trauma", guideline: "ATLS (Advanced Trauma Life Support), 11. Auflage 2025", front: "Was empfiehlt die aktuelle ATLS-Leitlinie (11. Auflage 2025, ACS) zur Abfolge von Primary Survey und Secondary Survey beim Traumapatienten?", back: "Der Primary Survey (in der 11. Auflage als 'xABCDE' bezeichnet: x = Exsanguinating hemorrhage/massive äußere Blutung sofort kontrollieren, dann Airway mit HWS-Schutz, Breathing, Circulation, Disability, Exposure/Environment) dient der sofortigen Identifikation und Behandlung unmittelbar lebensbedrohlicher Zustände nach Priorität; lebensbedrohliche Probleme werden sofort behandelt, sobald sie erkannt werden, statt die Sequenz starr abzuschließen. Der Secondary Survey (Kopf-bis-Fuß-Untersuchung plus AMPLE-Anamnese) erfolgt erst, wenn Primary Survey und Erstresuscitation eingeleitet sind und der Patient darauf anspricht." },
  { id: "fc-ll-038", module: "notfall-reanimation", subtopic: "trauma", guideline: "ATLS (Advanced Trauma Life Support)", front: "Anhand welcher vier klinischen Kriterien lässt sich der ABC-Score (Assessment of Blood Consumption) zur frühen Vorhersage eines Massivtransfusionsbedarfs beim Trauma berechnen?", back: "Penetrierendes Verletzungsmuster, positives FAST (freie Flüssigkeit), systolischer Blutdruck bei Aufnahme ≤ 90 mmHg und Herzfrequenz ≥ 120/min – je Kriterium 1 Punkt. Ab einem Score ≥ 2 gilt eine Massivtransfusion als wahrscheinlich, sodass die Aktivierung des Massivtransfusionsprotokolls empfohlen wird, ohne dass Laborwerte abgewartet werden müssen." },
  { id: "fc-ll-039", module: "notfall-reanimation", subtopic: "trauma", guideline: "Europäische Leitlinie: Schwere Blutung & Koagulopathie nach Trauma", front: "Was empfiehlt die aktuelle europäische Leitlinie zum Management der schweren Blutung und Koagulopathie nach Trauma (6. Auflage, Rossaint et al. 2023) zur Gabe von Tranexamsäure?", back: "Tranexamsäure so früh wie möglich (idealerweise bereits präklinisch) und spätestens innerhalb von 3 Stunden nach Trauma bei Blutung oder Blutungsrisiko: Initialdosis 1 g über 10 Minuten i.v., gefolgt von 1 g über 8 Stunden als Infusion." },
  { id: "fc-ll-040", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "Resuscitation Council UK (Perioperative Anaphylaxie)", front: "Welche Adrenalin-Dosierung und Applikationsart empfiehlt der Resuscitation Council (UK)-Algorithmus für Anästhesist:innen bei perioperativer Anaphylaxie unter Allgemeinanästhesie, im Unterschied zur präklinischen Erstbehandlung?", back: "Da der Patient bereits intravenösen Zugang und kontinuierliches Monitoring hat, wird intravenöses Adrenalin in titrierten Boli von etwa 50 µg (bei Erwachsenen; ggf. kleinere Boli 10–50 µg) empfohlen, statt der sonst für die Erstbehandlung üblichen intramuskulären Gabe (500 µg anterolateraler Oberschenkel)." },
  { id: "fc-ll-041", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "NAP6-Leitlinie (Perioperative Anaphylaxie)", front: "Zu welchen drei Zeitpunkten empfiehlt die NAP6-Leitlinie (Royal College of Anaesthetists) die Abnahme von Serum-Tryptase nach vermuteter perioperativer Anaphylaxie?", back: "Eine erste (akute) Probe möglichst zeitnah nach Reaktionsbeginn (meist im Fenster von etwa 30 Minuten bis 2 Stunden), eine zweite Probe nach etwa 1–2 Stunden sowie eine Baseline-Probe frühestens 24 Stunden nach vollständigem Abklingen der Symptome (alternativ eine präoperative Probe), um die akute Erhöhung von der individuellen Basalkonzentration abzugrenzen." },
  { id: "fc-ll-042", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "NAP6-Leitlinie (Perioperative Anaphylaxie)", front: "Innerhalb welches Zeitraums empfiehlt NAP6 die Vorstellung in einer spezialisierten Allergieklinik nach perioperativer Anaphylaxie, und warum?", back: "Empfohlen wird ein Termin nach etwa 6 Wochen, damit sich das Immunsystem nach der akuten Reaktion 'erholen' kann und Hauttests zuverlässigere Ergebnisse liefern; jede perioperative Anaphylaxie soll in einer Spezialklinik abgeklärt werden, um das auslösende Allergen zu identifizieren und einen sicheren Anästhesieplan für Folgeeingriffe zu ermöglichen." },
  { id: "fc-ll-043", module: "notfall-reanimation", subtopic: "toxikologie-verbrennungen", guideline: "ISBI Practice Guidelines for Burn Care", front: "Wie empfiehlt die ISBI Practice Guidelines for Burn Care die Steuerung der initialen Flüssigkeitstherapie bei schweren Verbrennungen?", back: "Berechnungsformeln (z.B. Parkland- oder modifizierte Brooke-Formel, meist 2–4 ml kristalloide Lösung/kg KG/%VKOF über 24h) dienen nur als Ausgangsschätzung; die tatsächliche Infusionsrate soll stündlich anhand der Urinausscheidung titriert werden, mit einem Zielwert von etwa 0,3–0,5 ml/kg/h bei Erwachsenen und etwa 1,0 ml/kg/h bei Kindern – nicht starr nach der Formel verabreicht werden." },
  { id: "fc-ll-044", module: "notfall-reanimation", subtopic: "toxikologie-verbrennungen", guideline: "ISBI Practice Guidelines for Burn Care", front: "Welche Kriterien nennen die ISBI Practice Guidelines für die Verlegung eines Brandverletzten in ein spezialisiertes Verbrennungszentrum?", back: "U.a. zweitgradige (partial-thickness) Verbrennungen > 10% der Körperoberfläche, jede drittgradige (full-thickness) Verbrennung unabhängig von der Ausdehnung, Verbrennungen an Gesicht, Händen, Füßen, Genitale/Perineum oder über großen Gelenken, Inhalationstrauma, chemische oder elektrische Verletzungen (inkl. Blitzschlag) sowie Verbrennungen bei Kindern oder Patienten mit relevanten Komorbiditäten bzw. Begleitverletzungen." },
  { id: "fc-ll-045", module: "notfall-reanimation", subtopic: "toxikologie-verbrennungen", guideline: "ISBI Practice Guidelines for Burn Care", front: "Wann ist laut ISBI-Leitlinie eine Escharotomie bei zirkulären Verbrennungen indiziert, und wie soll sie technisch erfolgen?", back: "Bei zirkulären drittgradigen Verbrennungen an Extremitäten oder Rumpf, wenn der starre Schorf die periphere Durchblutung (Kompartmentsyndrom) oder die Thoraxexkursion beeinträchtigt bzw. zu beeinträchtigen droht. Die Inzision erfolgt längs entlang der betroffenen Region in der Nähe der neurovaskulären Bündel, von gesunder Haut zu gesunder Haut (bzw. von Gelenk zu Gelenk), mit Tiefe bis ins gesunde, gut durchblutete Gewebe." },
  { id: "fc-ll-046", module: "spezielle-anaesthesie", subtopic: "kinderanaesthesie", guideline: "APAGBI-Leitlinie (Kinderanästhesie)", front: "Was empfiehlt die aktuelle APAGBI-Leitlinie (2022) zur präoperativen Nüchternheit bei Kindern hinsichtlich klarer Flüssigkeiten und Muttermilch?", back: "Klare Flüssigkeiten dürfen bei gesunden Kindern ohne Risikofaktoren bis 1 Stunde vor Anästhesieeinleitung getrunken werden ('1-Stunden-Regel' statt der klassischen 2-Stunden-Regel bei Erwachsenen); Muttermilch soll bis 3 Stunden vorher erlaubt sein, Säuglingsnahrung/leichte Mahlzeiten bis 6 Stunden vorher." },
  { id: "fc-ll-047", module: "spezielle-anaesthesie", subtopic: "kinderanaesthesie", guideline: "APAGBI-Leitlinie (Kinderanästhesie)", front: "Welche Infusionslösung empfiehlt der aktuelle europäische/deutsche Konsensus zur perioperativen Flüssigkeitstherapie für die intraoperative Erhaltungsinfusion bei Kindern?", back: "Eine balancierte, isotone Vollelektrolytlösung mit einem Glucosezusatz von etwa 1–2,5%, um sowohl eine intraoperative Hypoglykämie als auch eine Hyperglykämie zu vermeiden und – im Vergleich zu früher üblichen hypotonen Lösungen – eine Hyponatriämie zu verhindern." },
  { id: "fc-ll-048", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", guideline: "ESC-Leitlinie 2024 (Chronisches Koronarsyndrom)", front: "Was empfiehlt die aktuelle ESC-Leitlinie (2024) zum chronischen Koronarsyndrom hinsichtlich der Entscheidung zwischen Bypass-Operation (CABG) und PCI bei komplexer Mehrgefäßerkrankung?", back: "Die Entscheidung soll durch ein interdisziplinäres Herzteam getroffen werden, wobei die Möglichkeit einer vollständigen Revaskularisation stärker gewichtet wird als der SYNTAX-Score allein (Abkehr von der reinen Score-basierten Entscheidung). Bei funktionell relevanter 3-Gefäß-Erkrankung und LVEF > 35% wird eine Revaskularisation zusätzlich zur leitliniengerechten medikamentösen Therapie empfohlen." },
  { id: "fc-ll-049", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", guideline: "ERAS-Cardiac-Society/STS-Konsensus 2024", front: "Innerhalb welches Zeitfensters nach elektiver Herzoperation empfehlen die ERAS-Cardiac-Society/STS-Konsensusempfehlungen (2024) eine 'fast-track'-Extubation anzustreben?", back: "Meist innerhalb von 6 Stunden nach OP-Ende bei unkompliziertem Verlauf, unterstützt durch multimodale, opioidsparende Analgesie (z.B. Faszienblocks wie Parasternal- oder Erector-spinae-plane-Block), zurückhaltende intraoperative Opioiddosierung und strukturierte Weaning-Protokolle." },
  { id: "fc-ll-050", module: "spezielle-anaesthesie", subtopic: "neuroanaesthesie", guideline: "Brain Trauma Foundation Guidelines (4. Auflage)", front: "Bei welchen Patienten mit schwerem Schädel-Hirn-Trauma (SHT) empfiehlt die Brain Trauma Foundation (4. Auflage) ein invasives ICP-Monitoring?", back: "Bei allen Patienten mit schwerem SHT (GCS 3–8 nach Resuscitation) und pathologischem initialem CT; bei unauffälligem CT nur, wenn mindestens zwei der folgenden Kriterien vorliegen: Alter > 40 Jahre, uni-/bilaterale motorische Beuge-/Strecksynergien, systolischer Blutdruck < 90 mmHg." },
  { id: "fc-ll-051", module: "spezielle-anaesthesie", subtopic: "neuroanaesthesie", guideline: "Brain Trauma Foundation Guidelines (4. Auflage)", front: "Welchen ICP-Behandlungsschwellenwert und welchen CPP-Zielkorridor nennt die Brain Trauma Foundation (4. Auflage) für Patienten mit schwerem SHT?", back: "Eine Therapie wird ab einem ICP > 22 mmHg empfohlen (Änderung gegenüber dem früheren Grenzwert von 20 mmHg der Vorauflage). Als CPP-Zielkorridor werden meist 60–70 mmHg genannt, wobei der genaue untere Grenzwert je nach zerebraler Autoregulation individuell variieren kann." },
  { id: "fc-ll-052", module: "spezielle-anaesthesie", subtopic: "hno-augen-ambulant", guideline: "Aldrete-Score/PADSS (Entlasskriterien)", front: "Welche Scores werden zur Beurteilung der Entlassfähigkeit nach ambulanter Anästhesie eingesetzt, und was kennzeichnet sie?", back: "Der modifizierte Aldrete-Score (Aktivität, Atmung, Kreislauf, Bewusstsein, SpO2; Summenscore meist ≥ 9 für die PACU-Entlassung/Phase I) und das Postanesthetic Discharge Scoring System (PADSS; zusätzlich Vitalzeichen, Mobilisation, Schmerz, PONV, Wundblutung; Summenscore meist ≥ 9 für die Entlassung nach Hause/Phase II)." },
  { id: "fc-ll-053", module: "spezielle-anaesthesie", subtopic: "hno-augen-ambulant", guideline: "5th Consensus Guideline PONV (Gan et al. 2025)", front: "Was empfiehlt die aktuelle PONV-Konsensus-Leitlinie (5th Consensus 2025) speziell für ambulante Patienten mit 1–2 Risikofaktoren?", back: "Die 5th Consensus Guideline (2025) empfiehlt inzwischen ohnehin 1-2 Antiemetika ROUTINEMÄSSIG für ALLE chirurgischen Patienten (nicht erst ab Risikoschwelle); bei 1–2 Risikofaktoren – wie im ambulanten Setting häufig – wird eine multimodale Prophylaxe mit mehreren Antiemetika unterschiedlicher Wirkklassen empfohlen, da PONV bei ambulanten Patienten die Entlassung verzögern und zu ungeplanter stationärer Aufnahme führen kann." },
  { id: "fc-ll-054", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", guideline: "ASH-Leitlinie 2019 (VTE-Prophylaxe)", front: "Was empfiehlt die aktuelle ASH-Leitlinie (2019) zur Wahl des Thromboseprophylaxe-Wirkstoffs nach elektiver Hüft- oder Knie-Totalendoprothese (TEP)?", back: "Sowohl Acetylsalicylsäure als auch ein Antikoagulans (bevorzugt ein direktes orales Antikoagulans gegenüber niedermolekularem Heparin) werden als akzeptable Optionen genannt (schwache Empfehlung, sehr niedrige Evidenzqualität). Die Prophylaxe soll über den stationären Aufenthalt hinaus verlängert werden (üblich meist ca. 10–14 Tage, bei Hüft-TEP z.T. bis zu 35 Tage)." },
  { id: "fc-ll-055", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", guideline: "AORN-Konsensus (Tourniquet)", front: "Welche maximale ununterbrochene Anwendungsdauer und welchen Manschettendruck empfehlen aktuelle Konsensusempfehlungen (u.a. AORN) für einen pneumatischen Tourniquet bei Erwachsenen?", back: "Meist maximal etwa 60 Minuten an der oberen und rund 90–120 Minuten an der unteren Extremität ohne Unterbrechung, danach eine Reperfusionspause von ca. 10–15 Minuten vor erneuter Inflation. Der Manschettendruck soll sich am individuell gemessenen 'Limb Occlusion Pressure' (LOP) plus Sicherheitsaufschlag orientieren statt an einem fixen Pauschalwert." },
  { id: "fc-ll-056", module: "spezielle-anaesthesie", subtopic: "transplantationsanaesthesie", guideline: "Aggarwal-Kriterien (Postreperfusionssyndrom)", front: "Wie ist das Postreperfusionssyndrom (PRS) bei Lebertransplantation nach den klassischen Aggarwal-Kriterien definiert, und welche Sofortmaßnahmen stehen im Vordergrund?", back: "Abfall des mittleren arteriellen Drucks (MAP) um mehr als 30% unter den Ausgangswert (Ende der anhepatischen Phase) für mindestens 1 Minute innerhalb der ersten 5 Minuten nach Reperfusion (Freigabe der Lebergefäße). Management: Volumengabe, Vasopressoren/Inotropika (z.B. Noradrenalin, ggf. Calciumgabe/Behandlung einer Hyperkaliämie), Korrektur von Elektrolytstörungen und Rhythmusstörungen." },
  { id: "fc-ll-057", module: "spezielle-anaesthesie", subtopic: "transplantationsanaesthesie", guideline: "Konsensus Organspender-Anästhesie (DBD)", front: "Welche intraoperativen hämodynamischen Zielwerte nennt der internationale Konsensus zur Anästhesie bei hirntoten Organspendern (Donation after Brain Death) während der Organentnahme?", back: "Ein MAP von meist mindestens 60–70 mmHg unter vorrangig vasopressorgestützter Kreislaufstabilisierung (Vasopressin wird häufig als bevorzugter Vasopressor genannt, auch zur Substitution bei zentralem Diabetes insipidus), zusätzlich Normothermie (> 35°C), adäquate Diurese und lungenprotektive Beatmung – mit dem Ziel, die Organqualität für die Empfänger zu erhalten." },
  { id: "fc-ll-058", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", guideline: "WHO Surgical Safety Checklist", front: "Welche drei Phasen umfasst die WHO Surgical Safety Checklist, und wann findet jede Phase statt?", back: "Sign In (vor Einleitung der Anästhesie), Time Out (vor Hautschnitt) und Sign Out (vor Verlassen des OP-Saals durch das Team). Jede Phase wird von einer benannten Person laut vorgelesen und vom gesamten Team mündlich bestätigt, bevor der nächste Schritt erfolgt." },
  { id: "fc-ll-059", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", guideline: "WHO Surgical Safety Checklist", front: "Welche Kernpunkte werden laut WHO-Checkliste in der 'Time Out'-Phase unmittelbar vor Hautschnitt überprüft?", back: "Vorstellung aller Teammitglieder mit Namen/Rolle, mündliche Bestätigung von Patient, Eingriffsort und geplantem Verfahren, Durchsprache antizipierter kritischer Ereignisse (aus Sicht Chirurgie, Anästhesie, Pflege), Bestätigung der Antibiotikaprophylaxe (meist innerhalb der letzten 60 Minuten) sowie Verfügbarkeit relevanter Bildgebung." },
  { id: "fc-ll-060", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", guideline: "Helsinki-Deklaration (Patientensicherheit)", front: "Was fordert die Helsinki-Deklaration zur Patientensicherheit in der Anästhesiologie (EBA/ESAIC) bezüglich kritischer Zwischenfälle?", back: "Etablierung eines strukturierten, anonymisierten Critical Incident Reporting Systems (CIRS) zur Erfassung und Auswertung kritischer Zwischenfälle ('Never Events' eingeschlossen), ergänzt durch regelmäßiges Audit und jährliche Berichte zu Patientensicherheit und Morbidität/Mortalität als Grundlage kontinuierlicher Verbesserung." },
  { id: "fc-ll-061", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", guideline: "Helsinki-Deklaration (Patientensicherheit)", front: "Nenne ein typisches anästhesiologisches 'Never Event' im Zusammenhang mit Fehlapplikationen.", back: "Die intravenöse Gabe eines für die epidurale/intrathekale Applikation vorgesehenen Medikaments (oder umgekehrt die versehentliche intrathekale Gabe eines i.v.-Chemotherapeutikums wie Vincristin) gilt als klassisches, im Prinzip vollständig vermeidbares 'Never Event'; Präventionsmaßnahmen umfassen u.a. Non-Luer-Konnektoren für neuraxiale Systeme und konsequente Beschriftung/Farbcodierung von Spritzen." },
  { id: "fc-ll-062", module: "pharmakologie", subtopic: "muskelrelaxanzien", guideline: "ASA-Konsensus (Neuromuskuläres Monitoring & Reversal)", front: "Welches quantitative Kriterium fordern aktuelle Fachgesellschafts-Leitlinien (z.B. ASA 2023) vor Extubation nach neuromuskulärer Blockade mit Rocuronium/Vecuronium?", back: "Ein quantitativ (z.B. akzeleromyographisch am M. adductor pollicis) gemessenes Train-of-Four-Ratio ≥ 0,9 gilt als Kriterium für eine ausreichende Erholung der neuromuskulären Funktion vor Extubation; eine rein klinische/taktile Beurteilung wird als unzureichend angesehen." },
  { id: "fc-ll-063", module: "pharmakologie", subtopic: "muskelrelaxanzien", guideline: "ASA-Konsensus (Neuromuskuläres Monitoring & Reversal)", front: "Wie wählt man laut aktueller Leitlinie zwischen Sugammadex und Neostigmin zur Antagonisierung einer Rocuronium-/Vecuronium-Blockade?", back: "Sugammadex wird für tiefe, moderate und flache Blockade empfohlen (insbesondere wenn ein TOF-Ratio ≥0,9 rasch und zuverlässig erreicht werden soll). Neostigmin gilt als vertretbare Alternative nur bei minimaler Restblockade (TOF-Ratio meist im Bereich 0,4 bis <0,9); bei tieferer Blockade ist Neostigmin nicht ausreichend wirksam." },
  { id: "fc-ll-064", module: "pharmakologie", subtopic: "sonstige-pharmaka", guideline: "5th Consensus Guideline PONV (Gan et al. 2025)", front: "Wie stratifiziert die aktuelle PONV-Konsensus-Leitlinie (5th Consensus 2025) die Prophylaxe anhand des (vereinfachten) Apfel-Scores?", back: "Der Apfel-Score bleibt zur Risikoeinschätzung gültig (von ca. 10% Risiko bei 0 Faktoren bis ca. 80% bei 4 Faktoren), bestimmt aber seit der 5th Consensus Guideline (2025) NICHT mehr, OB überhaupt prophylaktisch behandelt wird: routinemäßig erhalten ALLE Patienten 1–2 Antiemetika, unabhängig vom Score (da Risikoscores sich als zu unzuverlässig erwiesen haben). Der Score steuert weiterhin die INTENSITÄT: bei moderatem/hohem Risiko 2–3 Substanzen aus unterschiedlichen Klassen (z.B. 5-HT3-Antagonist, Dexamethason, NK1-Antagonist, Droperidol) plus Erwägung einer TIVA." },
  { id: "fc-ll-065", module: "pharmakologie", subtopic: "sonstige-pharmaka", guideline: "EHRA Practical Guide (DOAK perioperativ)", front: "Was empfiehlt der EHRA Practical Guide zum perioperativen Pausieren von DOAK (z.B. Apixaban, Rivaroxaban) vor einem Eingriff mit hohem Blutungsrisiko – inklusive Bridging?", back: "Absetzen meist ca. 48 Stunden vor Eingriffen mit hohem Blutungsrisiko (bei niedrigem Blutungsrisiko genügen meist ca. 24 Stunden), abgestimmt auf Nierenfunktion und Substanz (bei Dabigatran ggf. längere Intervalle je nach Kreatinin-Clearance). Ein Bridging mit Heparin wird – anders als bei Vitamin-K-Antagonisten – NICHT empfohlen, da die kurze Halbwertszeit der DOAK ein Bridging in aller Regel überflüssig und eher schädlich (erhöhtes Blutungsrisiko) macht." },
  { id: "fc-ll-066", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", guideline: "DAS-Extubationsleitlinien (2012)", front: "Wie unterscheiden die DAS-Extubationsleitlinien (2012) grundsätzlich zwischen 'Low-Risk'- und 'At-Risk'-Extubation?", back: "Low-Risk-Extubation: unauffälliger Atemweg, keine erwarteten Reintubationsprobleme, Standard-Extubation nach Erfüllen der üblichen Kriterien. At-Risk-Extubation: bekannter/vermuteter schwieriger Atemweg, eingeschränkter Zugang, oder Reintubation wäre schwierig/gefährlich – hier werden Rescue-Optionen (z.B. Extubation über einen Atemwegs-Austauschkatheter/Tubuswechselstab, Belassen einer supraglottischen Atemwegshilfe) vorab geplant." },
  { id: "fc-ll-428", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", guideline: "DAS-Extubationsleitlinien (2012)", front: "In welche vier Phasen ist jeder DAS-Extubationsalgorithmus (Low-Risk wie At-Risk) gegliedert?", back: "Planung, Vorbereitung, Durchführung der Extubation, Postextubations-Versorgung – Kernbotschaft: Extubation ist nicht einfach die Umkehrung der Intubation, sondern verdient dieselbe strukturierte Planung." },
  { id: "fc-ll-067", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "ESC/ESAIC-Leitlinie 2022 (Perioperatives kardiovaskuläres Management)", front: "Was empfiehlt die ESC/ESAIC-Leitlinie 2022 zum perioperativen Troponin-Monitoring bei nicht-kardiochirurgischen Eingriffen?", back: "Bei Patienten mit bekannter kardiovaskulärer Erkrankung oder relevanten Risikofaktoren (inkl. Alter ≥65 Jahre), die sich einem intermediär- oder hochrisikoreichen Eingriff unterziehen, wird eine Messung von hochsensitivem kardialem Troponin (hs-cTnT/I) vor sowie 24 und 48 Stunden nach der Operation empfohlen (Klasse I), um eine perioperative Myokardschädigung/-infarkt frühzeitig zu erkennen. Bei Niedrigrisiko-Patienten und niedrig-/intermediärrisikoreichen Eingriffen wird ein routinemäßiges Biomarker-Screening NICHT empfohlen." },
  { id: "fc-ll-068", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", guideline: "AABB International Guidelines 2023 (Transfusion)", front: "Welchen Hämoglobin-Schwellenwert empfehlen die AABB International Guidelines 2023 für die Transfusionsentscheidung bei hämodynamisch stabilen, hospitalisierten Erwachsenen?", back: "Eine restriktive Transfusionsstrategie mit Transfusion typischerweise erst unter Hb <7 g/dl (starke Empfehlung); bei herzchirurgischen Patienten wird ein etwas höherer Schwellenwert von ca. 7,5 g/dl, bei orthopädischen Eingriffen oder vorbestehender kardiovaskulärer Erkrankung ca. 8 g/dl als vertretbar genannt. Eine liberale Transfusion (Schwellenwert 9–10 g/dl) verbessert die Ergebnisse bei den meisten Patientengruppen nicht." },
  { id: "fc-ll-069", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "ASA/ASRA Acute Pain Management Guideline", front: "Was ist das Kernprinzip der ASA/ASRA Practice Guidelines for Acute Pain Management (2016) zur multimodalen Analgesie?", back: "Kombination von mindestens zwei Wirkprinzipien mit unterschiedlichem Wirkmechanismus statt Monotherapie: wo nicht kontraindiziert, ein Basisregime aus NSAR/COXIB oder Paracetamol 'rund um die Uhr', ergänzt durch Regionalanästhesie/Lokalinfiltration und – individualisiert dosiert – systemische Opioide als Reserve, um Wirksamkeit zu maximieren und opioidbedingte Nebenwirkungen zu minimieren." },
  { id: "fc-ll-070", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", guideline: "WHO/WOMAN-Trial (Tranexamsäure bei PPH)", front: "Was empfiehlt die WHO (gestützt auf den WOMAN-Trial) zur Tranexamsäure-Gabe bei postpartaler Hämorrhagie (PPH)?", back: "1g Tranexamsäure i.v. über 10 Minuten so früh wie möglich, spätestens innerhalb von 3 Stunden nach der Geburt bei klinisch diagnostizierter PPH (vaginal oder nach Sectio); bei anhaltender Blutung nach 30 Minuten oder erneutem Einsetzen der Blutung innerhalb von 24h nach der ersten Dosis wird eine zweite 1g-Dosis gegeben. Der WOMAN-Trial zeigte den größten Nutzen (geringeres Risiko für Hysterektomie/Tod durch Blutung) bei Gabe innerhalb der ersten 1–3 Stunden." },
  { id: "fc-ll-071", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "MHAUS (Maligne Hyperthermie)", front: "Was ist die zentrale Sofortmaßnahme laut MHAUS (Malignant Hyperthermia Association of the United States) bei Verdacht auf maligne Hyperthermie, und wie wird Dantrolen dosiert?", back: "Sofortiges Stoppen aller auslösenden Triggersubstanzen (volatile Anästhetika, Succinylcholin), Hyperventilation mit 100% O2 sowie unverzügliche Gabe von Dantrolen 2,5mg/kg i.v. als Bolus, wiederholt alle 5–10 Minuten bis zum klinischen Ansprechen (Rückgang von Tachykardie, CO2-Anstieg, Rigidität), in refraktären Fällen bis zu einer Gesamtdosis von 10mg/kg oder mehr." },
  { id: "fc-ll-072", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", guideline: "WHO Global Guidelines (Surgical Site Infection)", front: "Welchen Zeitrahmen empfiehlt die WHO-Leitlinie 'Global Guidelines for the Prevention of Surgical Site Infection' (2018) für die Gabe der perioperativen Antibiotikaprophylaxe vor Hautschnitt?", back: "Verabreichung innerhalb von 120 Minuten vor Hautschnitt, unter Berücksichtigung der Halbwertszeit des jeweiligen Antibiotikums (in der Praxis meist so nah wie möglich am Schnittzeitpunkt, oft in der 'Time Out'-Phase bestätigt); von einer routinemäßigen Fortführung der Prophylaxe über das Ende der Operation hinaus wird ausdrücklich abgeraten." },
  { id: "fc-ll-073", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "CPOC/JBDS (Perioperatives Diabetes-Management), Update 2026 (Levy et al., Anaesthesia 2026)", front: "Welchen perioperativen Blutzucker-Zielkorridor empfehlen aktuelle Leitlinien (u.a. CPOC/Joint British Diabetes Societies) für Patienten mit Diabetes mellitus?", back: "Meist ein Zielkorridor von etwa 6–10mmol/l (ca. 108–180mg/dl), mit einer akzeptierten oberen Toleranzgrenze bis ca. 12mmol/l (216mg/dl); sowohl ausgeprägte Hyperglykämie (Wundheilungsstörungen, Infektionsrisiko) als auch Hypoglykämie sollen konsequent vermieden werden, statt eine strikte Normoglykämie zu erzwingen." },
  { id: "fc-ll-074", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "ESC/ESAIC-Leitlinie 2022 (Perioperatives kardiovaskuläres Management)", front: "Wie lange sollte laut ESC/ESAIC-Leitlinie 2022 eine elektive nicht-kardiochirurgische Operation nach elektiver PCI bzw. nach akutem Koronarsyndrom (ACS) möglichst aufgeschoben werden?", back: "Wenn möglich Verschiebung der elektiven Operation um mindestens 6 Monate nach elektiver PCI und mindestens 12 Monate nach ACS (jeweils mit mindestens 1 Monat dualer Plättchenhemmung [DAPT] nach elektiver PCI bzw. mindestens 3 Monaten nach Hochrisiko-ACS). Bei zeitkritischen Eingriffen kann die DAPT-Dauer auf minimal 1 Monat (elektive PCI) bzw. 3 Monate (PCI bei ACS) verkürzt werden. Neuere Generationen von Drug-Eluting-Stents (DES) werden gegenüber Bare-Metal-Stents (BMS) bevorzugt, da sich die Empfehlungen zur DAPT-Dauer nicht mehr grundsätzlich zwischen DES und BMS unterscheiden." },
  { id: "fc-ll-075", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "ESC/ESAIC-Leitlinie 2022 (Perioperatives kardiovaskuläres Management)", front: "Was empfiehlt die ESC/ESAIC-Leitlinie 2022 zum perioperativen Umgang mit bereits bestehender Betablocker- und Statintherapie – und zum Neubeginn eines Betablockers vor der Operation?", back: "Eine bestehende Therapie mit Betablockern und Statinen soll perioperativ fortgeführt werden (Klasse I). Ein routinemäßiger präoperativer Neubeginn einer Betablockertherapie unmittelbar vor der Operation wird dagegen NICHT empfohlen (Klasse III), da dies mit einem erhöhten Risiko für Hypotonie, Bradykardie und Schlaganfall assoziiert sein kann." },
  { id: "fc-ll-076", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "ESC/ESAIC-Leitlinie 2022 (Perioperatives kardiovaskuläres Management)", front: "Wie teilt die ESC/ESAIC-Leitlinie 2022 das chirurgische Risiko für kardiale Komplikationen ein, und welche Beispieleingriffe gehören jeweils dazu?", back: "Einteilung in niedriges (<1% kardiales Risiko, z.B. oberflächliche Eingriffe, Kataraktchirurgie, kleine gynäkologische/urologische Eingriffe), intermediäres (1-5%, z.B. viszeralchirurgische Standardeingriffe, Karotis-Endarteriektomie, periphere arterielle Angioplastie) und hohes Risiko (>5%, z.B. große Gefäßchirurgie, große Thorax-/Abdominalchirurgie, Pneumonektomie). Diese Risikoklasse fließt zusammen mit patientenindividuellen kardiovaskulären Risikofaktoren in die Entscheidung über das Ausmaß der präoperativen kardialen Abklärung ein." },
  { id: "fc-ll-077", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "ESC/ESAIC-Leitlinie 2022 (Perioperatives kardiovaskuläres Management)", front: "Welche Rolle spielt die körperliche Belastbarkeit (metabolische Äquivalente, METs) in der präoperativen kardialen Risikoeinschätzung nach ESC/ESAIC 2022, und welcher Schwellenwert gilt als klinisch relevant?", back: "Die (idealerweise objektiv erfasste oder mittels Fragebogen wie dem Duke Activity Status Index [DASI] abgeschätzte) funktionelle Kapazität ist ein zentrales, einfaches Screening-Instrument: Patienten mit guter Belastbarkeit (≥4 METs, z.B. problemloses Treppensteigen von 2 Stockwerken) benötigen in der Regel keine weiterführende kardiale Diagnostik vor mittel-/hochrisikoreichen Eingriffen, während bei eingeschränkter oder unklarer Belastbarkeit (<4 METs oder nicht abschätzbar) eine weitergehende Abklärung (Biomarker, Bildgebung) erwogen werden soll." },
  { id: "fc-ll-078", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", guideline: "AABB International Guidelines 2023 (Transfusion)", front: "Was empfehlen die AABB International Guidelines 2023 zur Anzahl der pro Transfusionsanordnung verabreichten Erythrozytenkonzentrate bei stabilen, nicht akut blutenden Patienten?", back: "Eine 'Single-Unit'-Transfusionsstrategie als gute klinische Praxis: Standardmäßig wird zunächst nur EINE Erythrozyten-Einheit transfundiert und der Patient anschließend klinisch sowie laborchemisch (Hb-Kontrolle) reevaluiert, bevor über eine weitere Einheit entschieden wird – statt routinemäßig zwei Einheiten anzuordnen. Dies vermeidet unnötige Übertransfusion und ist Teil eines umfassenden Patient-Blood-Management-Ansatzes." },
  { id: "fc-ll-079", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", guideline: "AABB/ICTMG-Leitlinie Thrombozytentransfusion 2025", front: "Welche Thrombozyten-Transfusionsschwellen gelten nach der aktuellen AABB/ICTMG-Leitlinie 2025 üblicherweise für prophylaktische Gaben bei stabilen Patienten bzw. vor invasiven Eingriffen?", back: "Restriktive Strategie: bei hypoproliferativer Thrombozytopenie (z.B. Chemotherapie/allogene Stammzelltransplantation) prophylaktisch erst unter ca. 10.000/µl; vor Anlage eines ZVK an gut komprimierbarer Stelle ebenfalls <10.000/µl ausreichend; vor Lumbalpunktion <20.000/µl; bei Neugeborenen ohne Blutung <25.000/µl; vor größeren nicht-neuraxialen Operationen üblicherweise <50.000/µl. Bei neurochirurgischen Eingriffen weiterhin höhere Werte (~100.000/µl) empfohlen." },
  { id: "fc-ll-080", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", guideline: "AABB International Guidelines 2023 (Transfusion)", front: "Was empfehlen die AABB-Leitlinien zum Umgang mit einer Eisenmangelanämie ohne akute Blutung hinsichtlich der Transfusionsindikation?", back: "Eine Erythrozytentransfusion soll bei Eisenmangelanämie OHNE akute Blutung möglichst vermieden werden – auch bei niedrigen Hb-Werten, sofern der Patient hämodynamisch stabil und asymptomatisch ist. Stattdessen wird eine kausale Therapie mit oralem oder intravenösem Eisen empfohlen; eine Transfusion 'nur wegen der Zahl' ohne klinische Notwendigkeit widerspricht dem Prinzip des Patient Blood Management." },
  { id: "fc-ll-081", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "ASA/ASRA Acute Pain Management Guideline; NEU: ASA Practice Guideline Regional-/Faszienblockaden 2026", front: "Für welche Eingriffsarten empfiehlt die aktuelle ASA-Leitlinie explizit den Einsatz neuraxialer bzw. peripherer regionaler Analgesietechniken als Bestandteil der postoperativen Schmerztherapie?", back: "Ältere Fassung (2016): Für große Thorax- und Bauchchirurgie neuraxiale Analgesie (v.a. thorakale Periduralanalgesie) anbieten/empfehlen, insbesondere bei erhöhtem Risiko für kardiale/pulmonale Komplikationen bzw. verlängerten Ileus; von intrapleuraler Lokalanästhetikagabe nach Thoraxchirurgie wird abgeraten. NEU (2026 ASA Practice Guideline on Perioperative Pain Management Using Local and Regional Analgesia): STARKE Empfehlung für Faszienblöcke (z.B. PECS, Serratus-anterior-Ebene, Erector-spinae-Plane) bei offener Thorax-/Herzchirurgie, offener Abdominal- und Beckenchirurgie sowie bei Mastektomie." },
  { id: "fc-ll-082", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "ASA/ASRA Acute Pain Management Guideline", front: "Welche Position vertritt die ASA/ASRA-Leitlinie (2016) zum Einsatz von Gabapentinoiden (Gabapentin/Pregabalin) als Adjuvans in der multimodalen perioperativen Schmerztherapie?", back: "Gabapentinoide können als Bestandteil eines multimodalen Analgesiekonzepts erwogen werden, insbesondere zur Reduktion des postoperativen Opioidbedarfs. Die Leitlinie mahnt jedoch zu individualisierter, zurückhaltender Anwendung, da die Evidenzlage zum Nutzen-Risiko-Verhältnis (insb. Sedierung, Schwindel, Atemdepression in Kombination mit Opioiden bei älteren Patienten) uneinheitlich ist – kein routinemäßiger Einsatz 'für alle'." },
  { id: "fc-ll-083", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "ASA/ASRA Acute Pain Management Guideline", front: "Was fordert die ASA/ASRA-Leitlinie (2016) hinsichtlich der Erfassung und Dokumentation postoperativer Schmerzen?", back: "Eine strukturierte, regelmäßige Schmerzerfassung mittels validierter Skalen (z.B. NRS/VAS) mit wiederholtem Reassessment nach jeder analgetischen Intervention, um Therapieerfolg zu überprüfen und die Behandlung bei Bedarf zeitnah anzupassen – Schmerztherapie wird als dynamischer, kontinuierlich zu reevaluierender Prozess verstanden, nicht als einmalige Verordnung." },
  { id: "fc-ll-084", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "ASA/ASRA Acute Pain Management Guideline", front: "Wovor warnt die ASA/ASRA-Leitlinie (2016) im Zusammenhang mit einer alleinigen NSAR-Therapie (Monotherapie) bei starken postoperativen Schmerzen?", back: "Vor einem 'Ceiling-Effekt': Oberhalb einer bestimmten Dosis führt eine weitere NSAR-Dosissteigerung zu keiner zusätzlichen Analgesie mehr, erhöht aber das Risiko für Nebenwirkungen (gastrointestinal, renal, kardiovaskulär, Blutungsneigung). Bei starken Schmerzen wird daher NICHT auf eine NSAR-Monotherapie gesetzt, sondern multimodal mit unterschiedlichen Wirkmechanismen kombiniert (z.B. mit Regionalanästhesie und ggf. Opioiden als Reserve)." },
  { id: "fc-ll-085", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", guideline: "WHO/WOMAN-Trial (Tranexamsäure bei PPH)", front: "Was empfiehlt die WHO zur aktiven Leitung der dritten Plazentaperiode als First-Line-Prävention der postpartalen Hämorrhagie (PPH)?", back: "Routinemäßige Gabe eines qualitätsgesicherten Uterotonikums unmittelbar nach der Geburt bei ALLEN Geburten – Oxytocin (10 IE i.m./i.v.) ist Mittel der ersten Wahl; bei fehlender Verfügbarkeit/Kühlkette alternativ hitzestabiles Carbetocin, Ergometrin/Methylergometrin oder orales Misoprostol. Ergänzend gehören kontrollierter Nabelschnurzug und uterine Fundusmassage zur aktiven Leitung der Nachgeburtsperiode." },
  { id: "fc-ll-086", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", guideline: "WHO/WOMAN-Trial (Tranexamsäure bei PPH)", front: "Wie sieht das gestufte Vorgehen bei einer anhaltenden postpartalen Hämorrhagie trotz initialer Uterotonikagabe aus?", back: "Stufenweise Eskalation: uterine Massage, Eskalation/Kombination der Uterotonikagabe, bei persistierender atonie-bedingter Blutung Uterusballontamponade als wenig-invasive Option (Voraussetzung: Zugang zu OP-Kapazität, Blutprodukten, geschultes Personal, andere Blutungsursachen ausgeschlossen); bei Versagen chirurgische Optionen wie Uteruskompressionsnähte (z.B. B-Lynch), Gefäßligaturen bzw. als Ultima Ratio die Hysterektomie." },
  { id: "fc-ll-087", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", guideline: "WHO/WOMAN-Trial (Tranexamsäure bei PPH)", front: "Wie ist die postpartale Hämorrhagie (PPH) klassisch definiert, und ab welchem geschätzten Blutverlust spricht man von einer PPH nach vaginaler Geburt bzw. nach Sectio?", back: "Klassische Definition: Blutverlust ≥500ml innerhalb von 24h nach vaginaler Geburt bzw. ≥1000ml nach Kaiserschnitt. Da die visuelle Schätzung des Blutverlusts häufig ungenau ist, betonen aktuelle WHO-Empfehlungen zunehmend eine (quantitative) Erfassung des Blutverlusts (z.B. mittels kalibrierter Auffangsysteme) zur früheren Diagnosestellung und zeitnahen Einleitung des Behandlungsbündels." },
  { id: "fc-ll-088", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "MHAUS (Maligne Hyperthermie)", front: "Wie lange und in welcher Form empfiehlt MHAUS die Überwachung eines Patienten nach erfolgreich behandelter maligne-Hyperthermie-Krise, und warum?", back: "Mindestens 24 Stunden intensivmedizinische Überwachung (stündliche Kontrolle von Herzfrequenz, Atemfrequenz, Temperatur, etCO2, SpO2, Muskeltonus, Urinausscheidung; Labor inkl. Blutgasanalyse, Kalium, CK mind. alle 6-8h), da es bei einem relevanten Anteil der Patienten (Literaturangaben bis ca. 20-25%) zu einem Wiederauftreten ('Rebound'/Recrudescence) der MH-Symptomatik kommen kann, sobald der Dantrolen-Spiegel abfällt." },
  { id: "fc-ll-089", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "MHAUS (Maligne Hyperthermie)", front: "Was empfiehlt MHAUS nach einer überstandenen MH-Krise hinsichtlich der Testung des betroffenen Patienten und seiner Angehörigen?", back: "Der Patient (und erstgradige Angehörige, autosomal-dominanter Erbgang mit ca. 50% Risiko) sollte in einem spezialisierten Zentrum getestet werden: Goldstandard ist der In-vitro-Kontrakturtest (Koffein-Halothan-Kontrakturtest, CHCT/IVCT) an einer Muskelbiopsie; ergänzend/alternativ eine molekulargenetische Testung (v.a. RYR1-Gen, verantwortlich für einen Großteil der Fälle). Ein negativer Gentest schließt eine MH-Suszeptibilität NICHT sicher aus und ersetzt den Kontrakturtest nicht." },
  { id: "fc-ll-090", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "MHAUS (Maligne Hyperthermie)", front: "Wie muss eine Anästhesie bei bekannter oder vermuteter MH-Disposition laut MHAUS vorbereitet und durchgeführt werden ('triggerfreie' Technik)?", back: "Vollständiger Verzicht auf volatile Anästhetika und Succinylcholin; stattdessen totale intravenöse Anästhesie (TIVA, z.B. Propofol-basiert) und nicht-depolarisierende Muskelrelaxanzien. Das Anästhesiegerät muss vorbereitet werden (idealerweise dediziertes, nie mit Inhalationsanästhetika kontaminiertes Gerät, alternativ Verdampfer entfernen und Gerät mit hohem Frischgasfluss ausreichend lange spülen bzw. Aktivkohlefilter verwenden), um Restkonzentrationen volatiler Anästhetika unter die sichere Schwelle zu senken." },
  { id: "fc-ll-091", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "MHAUS (Maligne Hyperthermie)", front: "Welche Laborkonstellation stützt bei klinischem Verdacht die Diagnose einer akuten malignen Hyperthermie?", back: "Hyperkaliämie, deutlich erhöhte Kreatinkinase (CK, im Verlauf oft massiv ansteigend) und Myoglobinurie/-ämie als Zeichen der Muskelschädigung/Rhabdomyolyse, sowie in der Blutgasanalyse eine gemischt respiratorisch-metabolische Azidose mit stark erhöhtem (gemischt-)venösem pCO2 und erniedrigtem pH als Ausdruck des hypermetabolen Zustands." },
  { id: "fc-ll-092", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", guideline: "WHO Global Guidelines (Surgical Site Infection)", front: "Welche zwei perioperativen physiologischen Zielgrößen empfiehlt die WHO-Leitlinie zur SSI-Prävention explizit zu optimieren – bezüglich Körpertemperatur und Sauerstoffversorgung?", back: "Aufrechterhaltung der perioperativen Normothermie (aktive Wärmemaßnahmen wie Wärmedecken im OP, starke Empfehlung) sowie eine erhöhte inspiratorische Sauerstofffraktion (FiO2) intraoperativ und in der unmittelbaren postoperativen Phase bei intubierten Patienten mit normaler Lungenfunktion, um die Gewebeoxygenierung zur SSI-Prävention zu optimieren." },
  { id: "fc-ll-093", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", guideline: "WHO Global Guidelines (Surgical Site Infection)", front: "Was empfiehlt die WHO-Leitlinie zur präoperativen Haarentfernung im OP-Gebiet?", back: "Wenn möglich KEINE Haarentfernung; ist sie notwendig, dann ausschließlich mittels Clipping (elektrischer Haarschneider), NICHT durch Rasur – da Rasur (v.a. mit Klingen) Mikroläsionen der Haut verursacht und das SSI-Risiko erhöht. Zum optimalen Zeitpunkt des Clippings gibt die Leitlinie keine spezifische Empfehlung." },
  { id: "fc-ll-094", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", guideline: "WHO Global Guidelines (Surgical Site Infection)", front: "Welches Hautantiseptikum empfiehlt die WHO-Leitlinie bevorzugt zur präoperativen Hautvorbereitung vor Hautschnitt?", back: "Eine alkoholbasierte Chlorhexidin-Lösung wird bevorzugt empfohlen (starke Empfehlung, niedrige bis moderate Evidenzqualität); alternativ kommen alkoholbasierte Iodophor-Lösungen (z.B. Povidon-Iod) zum Einsatz. Alkoholbasierte Lösungen wirken generell schneller und nachhaltiger als rein wässrige Antiseptika." },
  { id: "fc-ll-095", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", guideline: "WHO Global Guidelines (Surgical Site Infection)", front: "Für welche Patientengruppen empfiehlt die WHO-Leitlinie eine intensivierte perioperative Blutzuckerkontrolle zur SSI-Prävention?", back: "Für Diabetiker UND Nicht-Diabetiker gleichermaßen: ein Protokoll zur intensivierten perioperativen Blutzuckerkontrolle wird für BEIDE Gruppen empfohlen, mit einem Zielkorridor von meist ca. 6-10mmol/l (108-180mg/dl, akzeptierte Obergrenze bis ca. 12mmol/l/216mg/dl) – Hyperglykämie ist unabhängig vom Diabetesstatus ein Risikofaktor für Wundinfektionen." },
  { id: "fc-ll-096", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "CPOC/JBDS (Perioperatives Diabetes-Management), Update 2026 (Levy et al., Anaesthesia 2026)", front: "Was empfehlen CPOC/JBDS zum perioperativen Umgang mit SGLT2-Inhibitoren (z.B. Dapagliflozin, Empagliflozin), und warum?", back: "Pausieren der SGLT2-Inhibitoren üblicherweise bereits am Tag VOR der Operation sowie am Operationstag selbst (bei stark reduzierter Kalorienzufuhr, z.B. bariatrische Chirurgie oder Darmvorbereitung, ggf. längere Pause), wegen des Risikos einer euglykämischen diabetischen Ketoazidose (DKA trotz nur moderat erhöhter oder sogar normaler Blutzuckerwerte). Während der Pause sollten Blutketone regelmäßig (meist täglich) kontrolliert werden." },
  { id: "fc-ll-097", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "CPOC/JBDS (Perioperatives Diabetes-Management), Update 2026 (Levy et al., Anaesthesia 2026)", front: "Was empfehlen CPOC/JBDS hinsichtlich der Reihenfolge von Diabetikern auf der OP-Liste?", back: "Patienten mit Diabetes mellitus sollten nach Möglichkeit so früh wie möglich auf der OP-Liste eingeplant werden (idealerweise als Erste des Tages), um die notwendige Fastenzeit und damit das Risiko für Hypo-/Hyperglykämie und Dekompensation zu minimieren und eine zeitnahe Rückkehr zur normalen Ernährung/Medikation zu ermöglichen." },
  { id: "fc-ll-098", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "CPOC/JBDS (Perioperatives Diabetes-Management), Update 2026 (Levy et al., Anaesthesia 2026)", front: "Wann wird laut JBDS/CPOC eine variable Insulininfusion ('Variable Rate Intravenous Insulin Infusion', VRIII) bei Diabetikern perioperativ eingesetzt, und welcher Blutzucker-Zielbereich wird angestrebt?", back: "Bei größeren Eingriffen, voraussichtlich verlängerter Nüchternphase (mehr als eine ausgelassene Mahlzeit) oder wenn die orale Medikation/das Basalinsulin-Regime perioperativ nicht sicher fortgeführt werden kann. Ziel ist ein Blutzuckerbereich von meist 6-10mmol/l (bis 12mmol/l tolerabel), mit stündlicher Blutzuckerkontrolle unter laufender VRIII und begleitender Glukose-/Kaliumsubstitution." },
  { id: "fc-ll-099", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "CPOC/JBDS (Perioperatives Diabetes-Management), Update 2026 (Levy et al., Anaesthesia 2026)", front: "Was empfehlen CPOC/JBDS zur postoperativen Wiederaufnahme der oralen Antidiabetika bzw. der Beendigung einer VRIII?", back: "Sobald der Patient wieder normal isst und trinkt und keine akuten Kontraindikationen bestehen (z.B. eingeschränkte Nierenfunktion bei Metformin, anhaltendes Erbrechen), soll die reguläre orale antidiabetische Medikation zeitnah wieder aufgenommen und die VRIII beendet werden (Basalinsulin dabei überlappend fortführen, um eine Stoffwechsellücke zu vermeiden). SGLT2-Inhibitoren werden erst nach sicherem Ausschluss einer Ketoazidose und bei stabiler oraler Zufuhr wieder angesetzt." },
  { id: "fc-ll-100", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", guideline: "DAS-Extubationsleitlinien (2012)", front: "Welche Rescue-Technik empfehlen die DAS-Extubationsleitlinien (2012) im 'At-Risk'-Algorithmus, um bei vorhersehbar schwieriger Reintubation dennoch sicher extubieren zu können?", back: "Extubation über einen liegenden Atemwegs-Austauschkatheter (Airway Exchange Catheter, AEC): Der Tubus wird über den dünnen, gut tolerierten Katheter zurückgezogen, der Katheter verbleibt in der Trachea und ermöglicht bei Bedarf eine rasche Reintubation über den liegenden Führungsdraht sowie – bei entsprechend geeignetem Katheter – eine Sauerstoffinsufflation, sofern eine Reintubation nicht sofort gelingt." },
  { id: "fc-ll-101", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", guideline: "DAS-Extubationsleitlinien (2012)", front: "Was versteht man unter dem 'Bailey-Manöver' im Kontext der DAS-Extubationsleitlinien, und wofür wird es genutzt?", back: "Der Austausch des liegenden Endotrachealtubus gegen eine supraglottische Atemwegshilfe (z.B. Larynxmaske) noch in ausreichender Anästhesietiefe VOR dem Erwachen des Patienten. Dies dient als Brücke zwischen Tubus und vollständigem Erwachen, reduziert hämodynamische Stressreaktionen und Hustenreiz beim Ausleiten und kann insbesondere bei Risikopatienten eine ruhigere Emergence ermöglichen." },
  { id: "fc-ll-102", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", guideline: "DAS-Extubationsleitlinien (2012)", front: "Welche Kriterien müssen laut DAS-Extubationsleitlinien in der 'Perform'-Phase (Durchführung der Extubation) erfüllt sein, bevor tatsächlich extubiert wird?", back: "Vollständige Reversierung der neuromuskulären Blockade (objektiv bestätigt, z.B. TOF-Ratio ≥0,9), adäquate Spontanatmung mit ausreichendem Atemminutenvolumen, hämodynamische Stabilität sowie ausreichender Schutz vor Aspiration (Schutzreflexe vorhanden, Magen wenn nötig abgesaugt). Erst wenn alle diese Kriterien erfüllt sind, erfolgt die eigentliche Extubation nach dem zuvor festgelegten Algorithmus." },
  { id: "fc-ll-103", module: "pharmakologie", subtopic: "sonstige-pharmaka", guideline: "EHRA Practical Guide (DOAK perioperativ)", front: "Wann empfiehlt der EHRA Practical Guide die postoperative Wiederaufnahme der DOAK-Therapie?", back: "Zeitpunkt richtet sich nach dem Blutungsrisiko des Eingriffs und der erreichten Hämostase: bei niedrigem Blutungsrisiko meist Wiederbeginn mit voller Dosis bereits nach ca. 24 Stunden, bei hohem Blutungsrisiko meist erst nach ca. 48-72 Stunden (ggf. zunächst überbrückend niedrig dosiertes Thromboseprophylaxe-Regime, falls eine sofortige volle Antikoagulation zu riskant erscheint)." },
  { id: "fc-ll-104", module: "pharmakologie", subtopic: "sonstige-pharmaka", guideline: "EHRA Practical Guide (DOAK perioperativ)", front: "Wie wird laut EHRA Practical Guide bei einem Notfalleingriff unter laufender DOAK-Therapie mit relevanter Blutungsgefahr vorgegangen?", back: "Bei Dabigatran steht mit Idarucizumab ein spezifisches Antidot zur sofortigen vollständigen Aufhebung der Wirkung zur Verfügung; bei den Faktor-Xa-Inhibitoren (Apixaban, Rivaroxaban, Edoxaban) war Andexanet alfa vorgesehen, wurde aber wegen erhöhten Thromboserisikos (ANNEXA-I) zum 22.12.2025 in den USA vom Markt genommen und ist praktisch nur noch eingeschränkt verfügbar – PPSB/PCC (25–50 IE/kg) ist die aktuell relevante Alternative. Ist kein spezifisches Antidot verfügbar/anwendbar, wird generell die Gabe von (aktiviertem) Prothrombinkomplex-Konzentrat (PPSB/PCC) als unspezifische Option zur Verbesserung der Hämostase empfohlen. Auch nach Reversierung ist wegen möglicher wiederkehrender Wirkspiegel eine fortgesetzte klinische/laborchemische Überwachung nötig." },
  { id: "fc-ll-105", module: "pharmakologie", subtopic: "sonstige-pharmaka", guideline: "EHRA Practical Guide (DOAK perioperativ)", front: "Empfiehlt der EHRA Practical Guide eine routinemäßige Bestimmung des DOAK-Plasmaspiegels vor elektiven Eingriffen?", back: "Nein – eine routinemäßige Spiegelbestimmung wird explizit NICHT empfohlen. Eine Spiegelmessung kann jedoch in ausgewählten Sondersituationen sinnvoll sein, z.B. bei Notfällen (schwere Blutung, dringliche Operation, Schlaganfall), stark abweichendem Körpergewicht (z.B. Adipositas permagna, sehr niedriges Gewicht), eingeschränkter Nierenfunktion oder relevanten Arzneimittelinteraktionen." },
  { id: "fc-ll-106", module: "spezielle-anaesthesie", subtopic: "hno-augen-ambulant", guideline: "Aldrete-Score/PADSS (Entlasskriterien)", front: "Wie ist die Punktevergabe (0-2 Punkte je Kategorie) im modifizierten Aldrete-Score konkret aufgebaut?", back: "Aktivität (2 = alle 4 Extremitäten bewegbar, 1 = 2 Extremitäten, 0 = keine); Atmung (2 = tief durchatmen/husten möglich, 1 = eingeschränkte/dyspnoische Atmung, 0 = Apnoe); Kreislauf (2 = RR ±20% des Ausgangswerts, 1 = ±20-49%, 0 = ±50%); Bewusstsein (2 = wach, 1 = erweckbar auf Ansprache, 0 = nicht erweckbar); SpO2 (2 = >92% unter Raumluft, 1 = Sauerstoffbedarf für >90%, 0 = <90% trotz O2). Maximal 10 Punkte, ein Summenscore ≥9 gilt meist als Voraussetzung für die PACU-Entlassung." },
  { id: "fc-ll-107", module: "spezielle-anaesthesie", subtopic: "hno-augen-ambulant", guideline: "Aldrete-Score/PADSS (Entlasskriterien)", front: "Unterscheidet sich die Notwendigkeit einer Begleitperson bei Entlassung nach rückenmarksnaher (neuraxialer) Anästhesie ohne motorisches Defizit von der nach Allgemeinanästhesie?", back: "Nach Allgemeinanästhesie (und auch nach Sedierung) ist wegen relevanter kognitiver/psychomotorischer Beeinträchtigung praktisch immer eine verantwortliche Begleitperson für den Heimtransport und die Erstversorgung zu Hause erforderlich. Nach rückenmarksnaher Anästhesie ohne verbliebenes motorisches oder sensibles Defizit (vollständige Rückbildung von Motorik, Sensibilität und Sympathikusblockade) kann im Einzelfall je nach klinischer Einschätzung auf eine obligate Begleitperson verzichtet werden." },
  { id: "fc-ll-108", module: "spezielle-anaesthesie", subtopic: "hno-augen-ambulant", guideline: "Aldrete-Score/PADSS (Entlasskriterien)", front: "Gibt es eine feste Mindestverweildauer in der Phase-1-PACU nach Allgemeinanästhesie?", back: "Nein, eine starre zeitliche Mindestverweildauer wird nicht generell vorgeschrieben – entscheidend ist das Erreichen der Entlasskriterien (z.B. Aldrete-Score ≥9), nicht eine fixe Uhrzeit. In der Praxis ist jedoch eine gewisse Mindestbeobachtungszeit üblich, um verzögert auftretende Atemdepression, Nachblutung oder kardiorespiratorische Instabilität rechtzeitig zu erkennen, bevor der Patient in Phase 2 verlegt oder (bei entsprechend stabilen Patienten im Fast-Track) direkt entlassen wird." },
  { id: "fc-ll-109", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "ASA Practice Advisory (Intraoperative Awareness)", front: "Welche konkreten Risikofaktoren für eine intraoperative Awareness nennt die ASA Practice Advisory besonders hervorgehoben?", back: "Totale intravenöse Anästhesie (TIVA) in Kombination mit Muskelrelaxierung ohne Bewusstseinsmonitoring, da hier – anders als bei volatiler Anästhesie – keine kontinuierliche endexspiratorische Konzentrationsmessung zur Verfügung steht; ausgeprägte hämodynamische Instabilität, die zu einer bewusst reduzierten Anästhetikadosierung zwingt (z.B. Herz-, Trauma- oder Sectio-Anästhesie); sowie eine bekannt schwierige Atemwegssicherung mit verlängerter Exposition gegenüber niedrig dosierter Anästhesie." },
  { id: "fc-ll-110", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "ASA Practice Advisory (Intraoperative Awareness)", front: "Was empfiehlt die ASA Practice Advisory zum Vorgehen bei einem Verdachtsfall von intraoperativer Awareness?", back: "Eine strukturierte Befragung und Dokumentation des Vorfalls (inkl. Zeitpunkt, Inhalt der Erinnerungen und Kontext) für die Qualitätssicherung, ein zeitnahes Gespräch mit dem Patienten sowie – falls die Erinnerungen belastend sind – das Angebot einer psychologischen Beratung/Nachbetreuung, da Awareness zu relevanter emotionaler Belastung bis hin zu einer posttraumatischen Belastungsstörung führen kann." },
  { id: "fc-ll-111", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "ASA Practice Advisory (Intraoperative Awareness)", front: "Welche Alternative bzw. Ergänzung zum BIS-Monitoring empfiehlt die ASA Practice Advisory speziell bei volatiler (inhalativer) Anästhesie zur Awareness-Prävention?", back: "Die kontinuierliche Messung und alarmgestützte Überwachung der endexspiratorischen Anästhetikakonzentration (z.B. MAC-Wert-Alarm) gilt als wertvolles konventionelles Monitoring, das bei volatiler Anästhesie zusätzlich zu oder anstelle eines Bewusstseinsmonitorings wie BIS eingesetzt werden soll, um eine zu flache Anästhesietiefe frühzeitig zu erkennen." },
  { id: "fc-ll-112", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "ASA Practice Advisory (Intraoperative Awareness)", front: "Was empfiehlt die ASA Practice Advisory bezüglich der präoperativen Patientenaufklärung bei Risikopatienten für intraoperative Awareness?", back: "Patient:innen mit erhöhtem Awareness-Risiko sollen bereits präoperativ identifiziert und über die Möglichkeit einer intraoperativen Wachheit aufgeklärt werden; auf dieser Grundlage kann dann fallbezogen über den Einsatz eines Bewusstseinsmonitorings (z.B. BIS) entschieden werden, statt dies allen Patienten routinemäßig anzubieten." },
  { id: "fc-ll-113", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "PROSPECT-Initiative (ESRA), Update lap. Cholezystektomie 2024", front: "Welche PROSPECT-Empfehlung gilt für die Basisanalgesie nach laparoskopischer Cholezystektomie?", back: "Update 2024 (vorher 2018): Eine Kombination aus Paracetamol und einem NSAR/COX-2-Hemmer plus intraoperativem i.v. Dexamethason (neu ergänzt) plus lokaler Wundinfiltration/Port-Site-Infiltration mit Lokalanästhetikum an den Trokareinstichstellen; Opioide sollen nur als Rescue-Analgetikum bei unzureichender Schmerzkontrolle eingesetzt werden." },
  { id: "fc-ll-114", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "PROSPECT-Initiative (ESRA), Update lap. Cholezystektomie 2024", front: "Was empfiehlt PROSPECT bezüglich des routinemäßigen Zusatzes einer TAP-/ESP-Blockade bzw. intraperitonealer Lokalanästhesie und Gabapentinoiden bei laparoskopischer Cholezystektomie, wenn bereits eine Basisanalgesie etabliert ist?", back: "Kein genereller Zusatznutzen belegt – TAP-/ESP-Blockade, intraperitoneales Lokalanästhetikum und Gabapentinoide werden NICHT routinemäßig empfohlen, sondern nur erwogen, wenn die Basisanalgesie (Paracetamol + NSAR/COX-2 + Dexamethason + Wundinfiltration) aus irgendeinem Grund nicht durchführbar ist." },
  { id: "fc-ll-115", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "PROSPECT-Initiative (ESRA)", front: "Welche PROSPECT-Kernempfehlungen bestehen für die postoperative Analgesie nach Knie-Totalendoprothese (TKA)?", back: "Paracetamol plus NSAR/COX-2-Hemmer als Basisanalgesie, kombiniert mit einer einmaligen Adductor-Canal-Blockade und periartikulärer Lokalinfiltrationsanalgesie sowie einer intraoperativen Einzeldosis Dexamethason i.v.; Opioide werden nur als Rescue-Medikation empfohlen, intrathekales Morphin nur in Ausnahmefällen, wenn Blockade und Infiltration nicht möglich sind." },
  { id: "fc-ll-116", module: "notfall-reanimation", subtopic: "trauma", guideline: "Europäische Leitlinie: Schwere Blutung & Koagulopathie nach Trauma", front: "Ab welchem Fibrinogen-Schwellenwert empfiehlt die europäische Trauma-Leitlinie (6. Auflage) die Gabe von Fibrinogenkonzentrat oder Kryopräzipitat, und welches Ziel wird verfolgt?", back: "Bei einem (funktionellen bzw. Clauss-)Fibrinogenspiegel unter etwa 1,5 g/L oder entsprechendem Hinweis in der viskoelastischen Testung wird eine initiale Fibrinogensubstitution (Fibrinogenkonzentrat oder ersatzweise Kryopräzipitat) empfohlen, mit dem Ziel, einen Plasmaspiegel von meist ≥1,5–2,0 g/L aufrechtzuerhalten, da eine Hypofibrinogenämie früh im Verlauf der Trauma-induzierten Koagulopathie auftritt." },
  { id: "fc-ll-117", module: "notfall-reanimation", subtopic: "trauma", guideline: "Europäische Leitlinie: Schwere Blutung & Koagulopathie nach Trauma", front: "Welche Empfehlung gibt die europäische Trauma-Leitlinie zur Steuerung der Gerinnungstherapie bei schwerer Blutung, im Vergleich zu Standardgerinnungstests wie PT/INR?", back: "Eine frühe und wiederholte Gerinnungsdiagnostik, bevorzugt ergänzt durch viskoelastische Verfahren (ROTEM/TEG) am Patientenbett, um Gerinnungsdefekte (z.B. Hyperfibrinolyse, Fibrinogenmangel, Thrombozytopenie) rascher zu erkennen und die Transfusions-/Gerinnungstherapie zielgerichteter zu steuern, als es mit alleinigen Standardlabortests (PT/INR, Fibrinogen nach Clauss, Thrombozytenzahl) möglich wäre." },
  { id: "fc-ll-118", module: "notfall-reanimation", subtopic: "trauma", guideline: "Europäische Leitlinie: Schwere Blutung & Koagulopathie nach Trauma", front: "Welchen Zielwert für ionisiertes Calcium nennt die europäische Trauma-Leitlinie während einer Massentransfusion?", back: "Eine ionisierte Calciumkonzentration von meist ≥0,9 mmol/L wird angestrebt; da Citrat aus Blutprodukten und die Massentransfusion selbst eine Hypokalzämie begünstigen (mit negativen Effekten auf Gerinnung und Myokardfunktion), wird eine engmaschige Kontrolle und ggf. Substitution von Calcium während der Massentransfusion empfohlen." },
  { id: "fc-ll-119", module: "notfall-reanimation", subtopic: "trauma", guideline: "Europäische Leitlinie: Schwere Blutung & Koagulopathie nach Trauma", front: "Welche Volumentherapie-Strategie empfiehlt die europäische Trauma-Leitlinie in der initialen Phase des traumatischen hämorrhagischen Schocks, vor Blutungskontrolle?", back: "Eine restriktive Strategie mit primär kristalloider Flüssigkeitsgabe (permissive Hypotonie bis zur chirurgischen/interventionellen Blutungskontrolle, sofern kein SHT vorliegt); von künstlichen Kolloiden wie Hydroxyethylstärke oder Gelatine wird abgeraten, da sie die Gerinnungs- und Thrombozytenfunktion zusätzlich beeinträchtigen können." },
  { id: "fc-ll-120", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "Resuscitation Council UK (Perioperative Anaphylaxie)", front: "Wie behandelt der Resuscitation-Council-UK-Algorithmus eine gegenüber initialen i.v. Adrenalin-Boli therapierefraktäre perioperative Anaphylaxie?", back: "Statt weiterer wiederholter Boli wird der Übergang zu einer kontinuierlichen Adrenalin-Infusion mit Titration nach Wirkung empfohlen; bleibt der Schock weiterhin refraktär, soll frühzeitig ein zweiter Vasopressor (Noradrenalin oder Vasopressin) ergänzt werden." },
  { id: "fc-ll-121", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "Resuscitation Council UK (Perioperative Anaphylaxie)", front: "Welche initiale Volumentherapie empfiehlt der Resuscitation-Council-UK-Algorithmus bei perioperativer Anaphylaxie mit Kreislaufinstabilität?", back: "Einen raschen intravenösen kristalloiden Bolus von meist 500–1000 ml (bei Erwachsenen), der bei fortbestehender Hypotonie wiederholt werden soll, als integraler Bestandteil der Akuttherapie gleichrangig neben der Adrenalingabe." },
  { id: "fc-ll-122", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "Resuscitation Council UK (Perioperative Anaphylaxie)", front: "Welche Rolle weist der Resuscitation-Council-UK-Algorithmus Antihistaminika und Kortikosteroiden in der Akutbehandlung der perioperativen Anaphylaxie zu?", back: "Beide gelten als Therapie zweiter/dritter Linie und NICHT als alleinige oder primäre Akuttherapie: Antihistaminika lindern meist nur die kutanen Symptome (Urtikaria, Flush) ohne relevante Wirkung auf Hypotonie oder Bronchospasmus, Kortikosteroide werden vor allem bei refraktärem Schock/Bronchospasmus additiv erwogen, ihr Nutzen in der akuten Phase ist begrenzt." },
  { id: "fc-ll-123", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "Resuscitation Council UK (Perioperative Anaphylaxie)", front: "Was empfiehlt der Algorithmus bei einem auf Adrenalin refraktären anaphylaktischen Schock bei einem Patienten unter Betablocker-Therapie?", back: "Die Erwägung von Glucagon i.v. (meist ca. 1–2 mg), da Betablocker die kardiale Wirkung von Adrenalin abschwächen können und ein refraktärer Schock unter Betablockade dadurch häufiger auftritt; Glucagon kann über einen adrenalinunabhängigen Wirkmechanismus die Herzfunktion unterstützen." },
  { id: "fc-ll-124", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", guideline: "ESC-Leitlinie 2024 (Chronisches Koronarsyndrom)", front: "Was empfiehlt die ESC-Leitlinie 2024 zum initialen Vorgehen bei stabiler Angina pectoris ohne Hochrisikomerkmale (z.B. keine hochgradige Hauptstammstenose, erhaltene LV-Funktion)?", back: "Primär eine Optimierung der leitliniengerechten medikamentösen (antianginösen) Therapie, da bei diesen Patienten eine Revaskularisation zusätzlich zur optimalen medikamentösen Therapie keinen belegten Überlebensvorteil bietet; eine invasive Diagnostik/Revaskularisation ist vor allem bei unter medikamentöser Therapie fortbestehenden Symptomen oder Hochrisikokonstellation indiziert." },
  { id: "fc-ll-125", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", guideline: "ESC-Leitlinie 2024 (Chronisches Koronarsyndrom)", front: "Welche Bildgebung empfiehlt die ESC-Leitlinie 2024 bevorzugt bei niedriger bis mittlerer Vortestwahrscheinlichkeit für eine obstruktive KHK, vor einer invasiven Koronarangiographie?", back: "Eine nichtinvasive Diagnostik, meist bevorzugt eine koronare CT-Angiographie (CCTA) zum Ausschluss/Nachweis einer obstruktiven KHK; bei unklarem oder auffälligem CCTA-Befund ergänzend eine funktionelle Ischämiediagnostik (z.B. Stressbildgebung), um die invasive Koronarangiographie gezielter jenen mit hoher Vortestwahrscheinlichkeit bzw. therapierefraktären Symptomen vorzubehalten." },
  { id: "fc-ll-126", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", guideline: "ESC-Leitlinie 2024 (Chronisches Koronarsyndrom)", front: "Was empfiehlt die ESC-Leitlinie 2024 zur Dauer der dualen Plättchenhemmung (DAPT) nach PCI bei chronischem Koronarsyndrom und hohem Blutungsrisiko?", back: "Eine verkürzte DAPT-Dauer von meist nur 1–3 Monaten mit anschließendem Übergang auf eine einfache Plättchenhemmung (z.B. Clopidogrel-Monotherapie), sofern kein hohes ischämisches Risiko vorliegt – als Abkehr von der früher generell empfohlenen 6-monatigen DAPT bei allen PCI-Patienten mit chronischem Koronarsyndrom." },
  { id: "fc-ll-127", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", guideline: "ERAS-Cardiac-Society/STS-Konsensus 2024", front: "Welchen Blutzucker-Zielbereich empfiehlt der ERAS-Cardiac-Society/STS-Konsensus 2024 für die perioperative/intensivmedizinische Phase nach Herzchirurgie?", back: "Einen moderaten Zielbereich von meist unter 180 mg/dl (statt einer sehr engen/strikten Blutzuckerkontrolle), da eine zu strikte Kontrolle das Hypoglykämierisiko mit konsekutiver neuronaler Schädigung erhöht; bei Bedarf wird eine intravenöse Insulininfusion zur Steuerung empfohlen, ergänzt durch präoperatives Screening auf einen unerkannten Diabetes (z.B. mittels HbA1c)." },
  { id: "fc-ll-128", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", guideline: "ERAS-Cardiac-Society/STS-Konsensus 2024", front: "Was empfiehlt der ERAS-Cardiac-Society/STS-Konsensus 2024 zur Bluttransfusion nach Herzchirurgie?", back: "Eine restriktive, individualisierte Transfusionsstrategie im Rahmen eines Patient-Blood-Management-Konzepts (unterstützt durch Point-of-Care-Gerinnungsdiagnostik und algorithmusbasierte Entscheidungen), um unnötige allogene Transfusionen zu vermeiden – jedoch ohne die individuelle Klinik (Gewebeperfusion/Sauerstoffangebot) zu vernachlässigen, da eine zu strikte Anwendung das Risiko für Gewebeischämie und postoperatives Delir erhöhen kann." },
  { id: "fc-ll-129", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", guideline: "ERAS-Cardiac-Society/STS-Konsensus 2024", front: "Welches Konzept empfiehlt der ERAS-Cardiac-Society/STS-Konsensus 2024 zur Delirprävention nach Herzchirurgie?", back: "Primär nichtpharmakologische Maßnahmen nach dem ABCDEF-Bündel (u.a. Schmerzassessment/-therapie, Spontanatmungs- und Aufwachversuche, bevorzugt opioidsparende multimodale Analgesie, tägliches Delir-Screening, frühe Mobilisation, Einbindung der Angehörigen); von einer routinemäßigen prophylaktischen Gabe von Antipsychotika oder Clonidin zur Delirprävention wird mangels Wirksamkeitsnachweis abgeraten." },
  { id: "fc-ll-130", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", guideline: "ERAS-Cardiac-Society/STS-Konsensus 2024", front: "Welchen Stellenwert hat die frühe Mobilisation im ERAS-Cardiac-Society/STS-Konsensus 2024?", back: "Sie ist fester Bestandteil des Fast-Track-Konzepts: Patient:innen sollen – unterstützt durch frühe Extubation und opioidsparende Analgesie – bereits am Operationstag bzw. spätestens am 1. postoperativen Tag zur Mobilisation aus dem Bett angeleitet werden, da eine frühe Mobilisation mit weniger pulmonalen Komplikationen, kürzerer Delirdauer und kürzerer Krankenhausverweildauer assoziiert ist." },
  { id: "fc-ll-131", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", guideline: "ASH-Leitlinie 2019 (VTE-Prophylaxe)", front: "Wie unterscheidet sich die von der ASH-Leitlinie 2019 empfohlene Dauer der medikamentösen VTE-Prophylaxe nach Hüftfraktur-Operation von der nach elektiver Hüft-/Knie-TEP?", back: "Nach Hüftfraktur-Operationen (Becken-, Hüft- oder proximale Femurfrakturen) wird eine verlängerte Prophylaxe mit niedermolekularem Heparin (oder Fondaparinux) über meist etwa 4 Wochen (ca. 1 Monat) empfohlen – tendenziell vergleichbar oder länger als die übliche Verlängerung nach elektiver TEP, da das VTE-Risiko nach Frakturchirurgie als besonders hoch eingeschätzt wird." },
  { id: "fc-ll-132", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", guideline: "ASH-Leitlinie 2019 (VTE-Prophylaxe)", front: "Was empfiehlt die ASH-Leitlinie 2019 zum zusätzlichen Einsatz mechanischer Prophylaxe (z.B. intermittierende pneumatische Kompression) neben der medikamentösen VTE-Prophylaxe bei größeren orthopädischen Eingriffen?", back: "Je nach individuellem VTE- und Blutungsrisiko wird entweder eine Kombination aus mechanischer und medikamentöser Prophylaxe oder eine alleinige mechanische Prophylaxe vorgeschlagen; insbesondere bei hohem VTE-Risiko bei gleichzeitig vertretbarem Blutungsrisiko wird die Kombination beider Verfahren gegenüber jeweils alleiniger Anwendung bevorzugt." },
  { id: "fc-ll-133", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", guideline: "ASH-Leitlinie 2019 (VTE-Prophylaxe)", front: "Wie verändert ein erhöhtes Blutungsrisiko laut ASH-Leitlinie 2019 die Empfehlung zur VTE-Prophylaxe nach großer orthopädischer Operation?", back: "Bei als hoch eingeschätztem Blutungsrisiko verschiebt sich die Empfehlung zugunsten einer rein mechanischen Prophylaxe (z.B. intermittierende pneumatische Kompression) anstelle einer medikamentösen (antikoagulativen) Prophylaxe, da hier der potenzielle Nutzen der Antikoagulation das Blutungsrisiko meist nicht mehr aufwiegt." },
  { id: "fc-ll-134", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", guideline: "ASH-Leitlinie 2019 (VTE-Prophylaxe)", front: "Welche zwei Wirkstoffklassen werden von der ASH-Leitlinie 2019 nach großer orthopädischer Chirurgie als im Wesentlichen gleichwertige medikamentöse Optionen genannt (unabhängig von der bereits behandelten TEP-Empfehlung)?", back: "Niedermolekulares Heparin (LMWH) und direkte orale Antikoagulanzien (DOAK) werden – neben Acetylsalicylsäure als möglicher Option nach TEP – als im Wesentlichen akzeptable, in ihrer Wirksamkeit vergleichbare Optionen genannt (jeweils schwache Empfehlung bei niedriger bis sehr niedriger Evidenzqualität), sodass die individuelle Wahl auch von Patientenfaktoren, Praktikabilität und Kosten abhängen kann." },
  { id: "fc-ll-135", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", guideline: "AORN-Konsensus (Tourniquet)", front: "Wie soll die Extremität laut aktuellen Tourniquet-Konsensusempfehlungen (u.a. AORN) vor Inflation exsanguiniert werden, und wann ist eine Esmarch-Bandage zu vermeiden?", back: "Üblich ist die Exsanguination mittels Esmarch-Gummibinde (Auswickeln von distal nach proximal) oder durch alleiniges Hochlagern der Extremität für einige Minuten vor Inflation; bei Verdacht auf Infektion, Tumor oder eine tiefe Venenthrombose in der betroffenen Extremität soll auf die Esmarch-Bandage verzichtet und stattdessen die schonendere Hochlagerung (ohne Auswickeln) bevorzugt werden, um eine Verschleppung von Erregern/Tumorzellen oder eine Embolisation zu vermeiden." },
  { id: "fc-ll-136", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", guideline: "AORN-Konsensus (Tourniquet)", front: "Welche Maßnahme zum Hautschutz empfehlen aktuelle Tourniquet-Konsensusempfehlungen unmittelbar unter der Manschette?", back: "Eine ausreichende, faltenfreie Polsterung zwischen Haut und Manschette sowie eine flüssigkeitsdichte Abdeckung/Barriere, um ein Eindringen von Hautdesinfektionsmitteln oder Spülflüssigkeit unter die Manschette (mit Risiko für chemische Verätzungen) und Druckschäden der Haut zu verhindern." },
  { id: "fc-ll-137", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", guideline: "AORN-Konsensus (Tourniquet)", front: "Welche typischen Warnzeichen/Komplikationen einer zu langen oder zu hoch dosierten Tourniquet-Anwendung sollten intraoperativ beachtet werden?", back: "Zunehmender, dumpfer 'Tourniquet-Schmerz' mit begleitendem Blutdruck- und Herzfrequenzanstieg trotz suffizienter Anästhesie, Nervenschädigung durch mechanische Kompression (reversible bis persistierende 'Tourniquet-Paralyse', am häufigsten N. radialis/N. ischiadicus) sowie – insbesondere bei sehr langer Ischämiezeit – ein Kompartmentsyndrom bzw. eine Ischämie-Reperfusionsschädigung der Muskulatur; die Inflationszeit soll deshalb so kurz wie möglich gehalten werden." },
  { id: "fc-ll-138", module: "spezielle-anaesthesie", subtopic: "transplantationsanaesthesie", guideline: "Aggarwal-Kriterien (Postreperfusionssyndrom)", front: "Welche pathophysiologischen Mechanismen liegen dem Postreperfusionssyndrom (PRS) bei Lebertransplantation laut aktuellem Verständnis zugrunde?", back: "Mit der Reperfusion gelangt kaltes, saures Blut aus dem Spenderorgan und der Konservierungslösung in den systemischen Kreislauf, reich an Kalium, sauren Metaboliten, Entzündungsmediatoren und vasoaktiven Substanzen aus dem ischämisch geschädigten Gewebe; dies führt akut zu Hyperkaliämie, Hypokalzämie, Hypothermie und einer Freisetzung vasodilatatorischer/negativ inotroper Mediatoren, die gemeinsam den ausgeprägten Blutdruckabfall und Rhythmusstörungen des PRS erklären." },
  { id: "fc-ll-139", module: "spezielle-anaesthesie", subtopic: "transplantationsanaesthesie", guideline: "Aggarwal-Kriterien (Postreperfusionssyndrom)", front: "Welche Risikofaktoren erhöhen laut aktueller Literatur die Wahrscheinlichkeit eines schweren Postreperfusionssyndroms bei Lebertransplantation?", back: "Eine hohe Kaliumkonzentration in der Spülflüssigkeit/dem Spenderorgan, eine lange kalte Ischämiezeit (meist ab etwa 6–8 Stunden), Organe von Donation-after-circulatory-death(DCD)-Spendern, höheres Spenderalter sowie eine ausgeprägte (v.a. makrovesikuläre) Steatose des Spenderorgans gelten als relevante Risikofaktoren für ein schweres PRS." },
  { id: "fc-ll-140", module: "spezielle-anaesthesie", subtopic: "transplantationsanaesthesie", guideline: "Aggarwal-Kriterien (Postreperfusionssyndrom)", front: "Welche präventive Maßnahme vor Reperfusion kann laut aktueller Literatur das Risiko bzw. den Schweregrad eines Postreperfusionssyndroms reduzieren?", back: "Ein Auswaschen ('Flush') des Spenderorgans mit kalter Albumin- oder Kochsalzlösung (meist mindestens 500 ml) vor Freigabe der Lebergefäße, um kaliumreiche und saure Konservierungslösung aus dem Organ zu entfernen, bevor sie in den systemischen Kreislauf gelangt; ergänzend wird häufig eine prophylaktische Bereitstellung von Calcium und Vasopressoren empfohlen, um auf die zu erwartende hämodynamische Reaktion sofort reagieren zu können." },
  { id: "fc-ll-141", module: "spezielle-anaesthesie", subtopic: "transplantationsanaesthesie", guideline: "Konsensus Organspender-Anästhesie (DBD)", front: "Welche Substanzen umfasst das hormonelle Ersatz-Protokoll (Hormone Replacement Therapy), das bei hirntoten Organspendern zur Optimierung der Organfunktion diskutiert wird?", back: "Meist eine Kombination aus Methylprednisolon (Kortikosteroid), Vasopressin bzw. Desmopressin (bei zentralem Diabetes insipidus/Hypotonie), einer Insulininfusion zur Blutzuckerkontrolle sowie – kontrovers diskutiert – einer Schilddrüsenhormon-Substitution (T3/Liothyronin oder T4/Levothyroxin); aktuelle randomisierte Studien zeigen jedoch keinen eindeutigen Zusatznutzen einer routinemäßigen Schilddrüsenhormongabe, sodass diese nicht mehr uneingeschränkt für alle Spender empfohlen wird." },
  { id: "fc-ll-142", module: "spezielle-anaesthesie", subtopic: "transplantationsanaesthesie", guideline: "Konsensus Organspender-Anästhesie (DBD)", front: "Welches Beatmungskonzept wird bei hirntoten Organspendern speziell zur Optimierung einer möglichen Lungenspende empfohlen?", back: "Eine lungenprotektive Beatmung mit niedrigen Tidalvolumina von meist 6–8 ml/kg (bezogen auf das ideale Körpergewicht), einem PEEP von meist ≥5 cmH2O sowie einem endinspiratorischen Plateaudruck unter 30 cmH2O, ergänzt durch regelmäßige Rekruitmentmanöver und wiederholtes endotracheales Absaugen/Bronchoskopie, um beatmungsassoziierte Lungenschäden zu vermeiden und die Eignung der Lunge als Spenderorgan zu erhalten." },
  { id: "fc-ll-143", module: "spezielle-anaesthesie", subtopic: "transplantationsanaesthesie", guideline: "Konsensus Organspender-Anästhesie (DBD)", front: "Warum ist trotz festgestelltem Hirntod weiterhin eine Anästhesie-/Analgesieführung während der Organentnahme erforderlich?", back: "Spinale Reflexbögen bleiben nach Hirntod erhalten (motorische Bewegungen von Rumpf/Extremitäten sowie autonome sympathische Reflexe wie Tachykardie, Hypertonie und Schwitzen auf chirurgischen Reiz, sog. 'Mass-Reflex'), da die hemmende supraspinale Kontrolle fehlt; volatile Anästhetika und/oder eine vorsichtig titrierte Analgesie zusammen mit Muskelrelaxierung werden daher eingesetzt, um diese spinalen und hämodynamischen Reaktionen abzuschwächen und die chirurgischen Bedingungen zu verbessern – nicht, weil noch eine bewusste Wahrnehmung besteht." },
  { id: "fc-ll-144", module: "intensivmedizin", subtopic: "sedierung-delir", guideline: "PADIS-Leitlinien (Sedierung & Delir)", front: "Welche sechs Elemente umfasst das ABCDEF-Bundle zur Umsetzung der PADIS-Leitlinien auf der Intensivstation?", back: "A – Assess, Prevent and Manage Pain (Schmerzerfassung/-therapie); B – Both spontaneous awakening and breathing trials (SAT/SBT, tägliche Aufwach- und Spontanatmungsversuche); C – Choice of analgesia/sedation (Auswahl der Analgosedierung); D – Delirium: Assess, Prevent, Manage (Delir-Screening/-Prävention/-Therapie); E – Early mobility and exercise (Frühmobilisation); F – Family engagement and empowerment (Einbindung der Angehörigen)." },
  { id: "fc-ll-145", module: "intensivmedizin", subtopic: "sedierung-delir", guideline: "PADIS-Leitlinien (Sedierung & Delir)", front: "Welchen Ziel-Sedierungsgrad (RASS) empfehlen die PADIS-Leitlinien bei den meisten erwachsenen Intensivpatienten anstelle einer tiefen Sedierung?", back: "Eine leichte Sedierung (RASS meist etwa −2 bis +1) mit täglicher Reevaluation wird angestrebt; eine routinemäßig tiefe Sedierung soll vermieden werden, da leichte Sedierung u.a. mit kürzerer Beatmungsdauer und kürzerem ICU-Aufenthalt assoziiert ist." },
  { id: "fc-ll-146", module: "intensivmedizin", subtopic: "sedierung-delir", guideline: "PADIS-Leitlinien (Sedierung & Delir)", front: "Mit welchem validierten Instrument wird das Delirium-Screening im Rahmen des D-Elements des ABCDEF-Bundles typischerweise durchgeführt?", back: "Mit dem CAM-ICU (Confusion Assessment Method for the ICU) oder alternativ der ICDSC (Intensive Care Delirium Screening Checklist); die PADIS-Leitlinien empfehlen ein regelmäßiges, routinemäßiges Delir-Screening mit einem validierten Tool." },
  { id: "fc-ll-147", module: "intensivmedizin", subtopic: "sedierung-delir", guideline: "PADIS-Leitlinien (Sedierung & Delir)", front: "Welche nicht-pharmakologische Maßnahme empfehlen die PADIS-Leitlinien zur Delirprävention bezogen auf den Tag-Nacht-Rhythmus?", back: "Förderung eines physiologischen Schlaf-Wach-Rhythmus (z.B. Tageslichtexposition tagsüber, Lärm-/Lichtreduktion nachts, Bündelung pflegerischer Maßnahmen) zur Schlafförderung – als Teil eines multikomponenten, nicht-medikamentösen Ansatzes zur Delirprävention." },
  { id: "fc-ll-148", module: "regional-schmerz", subtopic: "neuraxial-verfahren", guideline: "ESRA-Leitlinie (Neuraxiale Verfahren & Antikoagulation)", front: "Muss laut ESRA-Leitlinie bei alleiniger Einnahme von ASS oder NSAR vor einer neuraxialen Punktion eine zusätzliche Karenzzeit eingehalten werden?", back: "Nein – als Monotherapie stellen ASS und andere NSAR laut ESRA/ASRA-Konsens kein relevantes zusätzliches Blutungsrisiko für neuraxiale Verfahren dar; eine gesonderte Karenzzeit oder ein spezielles Timing ist nicht erforderlich (Vorsicht gilt nur bei Kombination mit weiteren gerinnungswirksamen Substanzen)." },
  { id: "fc-ll-149", module: "regional-schmerz", subtopic: "neuraxial-verfahren", guideline: "ESRA-Leitlinie (Neuraxiale Verfahren & Antikoagulation)", front: "Welches Zeitintervall wird laut ESRA/ASRA-Konsens bei therapeutischer intravenöser Heparinisierung vor einer neuraxialen Punktion bzw. Katheterentfernung empfohlen?", back: "Die i.v.-Heparin-Infusion soll etwa 4–6 Stunden vorher pausiert und die Gerinnung (aPTT) kontrolliert werden; ein Wiederbeginn der Heparingabe wird frühestens ca. 1 Stunde nach atraumatischer Punktion bzw. Katheterentfernung empfohlen. Bei niedrig dosierter s.c.-Heparin-Prophylaxe ist meist kein zusätzliches Intervall notwendig." },
  { id: "fc-ll-150", module: "regional-schmerz", subtopic: "neuraxial-verfahren", guideline: "ESRA-Leitlinie (Neuraxiale Verfahren & Antikoagulation)", front: "Welche klinischen Warnzeichen sprechen für ein epidurales Hämatom nach neuraxialer Punktion, und welche Konsequenz hat ein solcher Verdacht?", back: "Neu aufgetretene oder zunehmende motorische/sensible Ausfälle (über die erwartete Blockrückbildung hinaus), zunehmende Rückenschmerzen sowie Blasen-/Mastdarmstörungen. Bei Verdacht ist eine sofortige bildgebende Diagnostik (Notfall-MRT) und ggf. neurochirurgische Dekompression indiziert – das neurologische Outcome hängt entscheidend von einer möglichst frühen Entlastung (meist innerhalb weniger Stunden) ab." },
  { id: "fc-ll-151", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", guideline: "ASA Practice Guidelines for Obstetric Anesthesia", front: "Warum empfiehlt die ASA-Leitlinie zur Geburtshilfsanästhesie eine frühzeitige Anlage eines Periduralkatheters bei Risikoschwangeren, auch ohne aktuellen Wehenschmerz?", back: "Ein früh angelegter, liegender Periduralkatheter kann im Fall einer notfallmäßigen Sectio rasch aufgespritzt werden und reduziert so die Notwendigkeit einer Allgemeinanästhesie mit ihren spezifischen Risiken (schwieriger Atemweg, Aspiration) bei Risikogeburten (z.B. erwarteter schwieriger Atemweg, Adipositas, Mehrlingsschwangerschaft)." },
  { id: "fc-ll-152", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", guideline: "ASA Practice Guidelines for Obstetric Anesthesia", front: "Was fordert die ASA-Leitlinie bezüglich der Ausrüstung für den schwierigen Atemweg im Kreißsaal?", back: "Im Kreißsaalbereich soll jederzeit tragbare Ausrüstung für die Sicherung des schwierigen Atemwegs (z.B. verschiedene Laryngoskopspatel, Führungsstäbe, supraglottische Atemwegshilfen, Möglichkeit zur invasiven Atemwegssicherung) verfügbar sein, ebenso wie ein etablierter Prozess für die Anforderung zusätzlicher Hilfe." },
  { id: "fc-ll-153", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", guideline: "ASA Practice Guidelines for Obstetric Anesthesia", front: "Welches Anästhesieverfahren empfiehlt die ASA-Leitlinie für die überwiegende Mehrzahl der Sectiones caesareae, und warum?", back: "Neuraxiale Verfahren (Spinal-, Epidural- oder kombinierte Spinal-Epiduralanästhesie) werden gegenüber der Allgemeinanästhesie bevorzugt, da sie mit einem geringeren mütterlichen Aspirations- und Atemwegsrisiko sowie geringerer mütterlicher Morbidität/Mortalität assoziiert sind." },
  { id: "fc-ll-154", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "NAP6-Leitlinie (Perioperative Anaphylaxie)", front: "Welche Substanzklasse war laut NAP6 der häufigste identifizierte Auslöser perioperativer Anaphylaxie – vor den neuromuskulär blockierenden Substanzen?", back: "Antibiotika (v.a. Teicoplanin, Penicilline, Vancomycin, Cefuroxim) waren in NAP6 der häufigste identifizierte Auslöser (ca. 47% der Fälle), gefolgt von neuromuskulär blockierenden Substanzen (NMBA, ca. 33%), Chlorhexidin (ca. 9%) und Patentblau (ca. 4–5%)." },
  { id: "fc-ll-155", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "NAP6-Leitlinie (Perioperative Anaphylaxie)", front: "Welche NMBA war laut NAP6 unter den neuromuskulär blockierenden Substanzen am häufigsten als Auslöser identifiziert?", back: "Rocuronium war die am häufigsten als Auslöser identifizierte NMBA (ca. 42% der NMBA-assoziierten Fälle), gefolgt von Atracurium (ca. 35%) und Succinylcholin (ca. 22%)." },
  { id: "fc-ll-156", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "NAP6-Leitlinie (Perioperative Anaphylaxie)", front: "Was empfiehlt NAP6 bezüglich der Dokumentation nach einer gesicherten perioperativen Anaphylaxie?", back: "Nach gesicherter Diagnose (inkl. allergologischer Abklärung) soll der auslösende Stoff eindeutig im Patientendokument vermerkt und dem Patienten ein Allergiepass/-ausweis mit klarer Meidungsempfehlung ausgehändigt werden, zusätzlich Information von Hausarzt und ggf. Meldung an nationale Register." },
  { id: "fc-ll-157", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "NAP6-Leitlinie (Perioperative Anaphylaxie)", front: "Was empfiehlt NAP6 hinsichtlich der Notfallausstattung für perioperative Anaphylaxie im OP-Bereich?", back: "Ein standardisiertes, sofort verfügbares Anaphylaxie-/Notfall-Kit (u.a. Adrenalin in verschiedenen Konzentrationen/Applikationsformen, Volumenersatz, Zugang zu Blutentnahme-Röhrchen für Tryptase) sowie ein klar strukturierter, kognitiv entlastender Notfallalgorithmus (Kitteltaschenkarte/Cognitive Aid) sollen in jedem OP-Bereich vorgehalten werden." },
  { id: "fc-ll-158", module: "notfall-reanimation", subtopic: "trauma", guideline: "ATLS (Advanced Trauma Life Support)", front: "Wie viele Klassen des hämorrhagischen Schocks unterscheidet ATLS, und welches grobe Unterscheidungsmerkmal liegt zugrunde?", back: "Vier Klassen (I–IV), gestaffelt nach geschätztem Blutverlust in % des zirkulierenden Blutvolumens sowie den damit einhergehenden Veränderungen von Herzfrequenz, Blutdruck/Pulsdruck, Atemfrequenz und Bewusstseinslage." },
  { id: "fc-ll-159", module: "notfall-reanimation", subtopic: "trauma", guideline: "ATLS (Advanced Trauma Life Support)", front: "Welcher geschätzte Blutverlust und welche klinischen Zeichen kennzeichnen einen Schock Klasse III nach ATLS?", back: "Ein Blutverlust von etwa 30–40% des Blutvolumens; klinisch meist Tachykardie >120/min, Tachypnoe, abfallender systolischer Blutdruck (deutliche Hypotonie) sowie beginnende Bewusstseinsveränderung (Angst, Verwirrtheit) – Zeichen einer dekompensierten Kreislaufsituation." },
  { id: "fc-ll-160", module: "notfall-reanimation", subtopic: "trauma", guideline: "ATLS (Advanced Trauma Life Support)", front: "Was versteht man im Rahmen des Secondary Survey unter dem 'Log-Roll'-Manöver, und wozu dient es?", back: "Der Patient wird unter Aufrechterhaltung der Wirbelsäulen-Inline-Stabilisierung achsengerecht 'wie ein Baumstamm' auf die Seite gedreht, um Rücken, Flanken und Gesäß vollständig zu inspizieren und zu palpieren (z.B. auf Wirbelsäulendruckschmerz, penetrierende Verletzungen, per rektale Untersuchung) – wichtig, um posteriore Verletzungen nicht zu übersehen." },
  { id: "fc-ll-161", module: "notfall-reanimation", subtopic: "trauma", guideline: "ATLS (Advanced Trauma Life Support)", front: "Zu welchem Zeitpunkt im ATLS-Ablauf wird die FAST-Sonographie typischerweise eingesetzt?", back: "Bereits im Primary Survey, als Teil der Beurteilung von 'Circulation' – die fokussierte Sonographie (FAST) dient der raschen Erkennung freier intraabdomineller/perikardialer Flüssigkeit als Hinweis auf eine innere Blutungsquelle bei hämodynamisch instabilen Patienten, noch bevor der Secondary Survey beginnt." },
  { id: "fc-ll-162", module: "spezielle-anaesthesie", subtopic: "kinderanaesthesie", guideline: "APAGBI-Leitlinie (Kinderanästhesie)", front: "Welche maximale Menge klarer Flüssigkeit in der letzten Stunde vor der Anästhesie empfiehlt die APAGBI-Leitlinie bei Kindern?", back: "Üblicherweise maximal etwa 3 ml/kg Körpergewicht klarer Flüssigkeit in der letzten Stunde vor Anästhesiebeginn (die '1-Stunden-Regel' erlaubt klare Flüssigkeiten bis 1h präoperativ, jedoch nicht unbegrenzt in der Menge)." },
  { id: "fc-ll-163", module: "spezielle-anaesthesie", subtopic: "kinderanaesthesie", guideline: "APAGBI-Leitlinie (Kinderanästhesie)", front: "Bei welchen Kindern gilt die verkürzte 1-Stunden-Nüchternheitsregel für klare Flüssigkeiten laut APAGBI NICHT uneingeschränkt?", back: "Bei Kindern mit bekannten Magenentleerungsstörungen bzw. Motilitätsstörungen (z.B. Ileus, schwere gastroösophageale Refluxkrankheit) oder anderen Erkrankungen, die die Magenentleerung verzögern – hier muss die Nüchternheitsstrategie individuell durch das Anästhesieteam festgelegt werden." },
  { id: "fc-ll-164", module: "spezielle-anaesthesie", subtopic: "kinderanaesthesie", guideline: "APAGBI-Leitlinie (Kinderanästhesie)", front: "Wie bewertet die APAGBI-Leitlinie ein 'übervorsichtiges', über die empfohlenen Zeiten hinaus verlängertes präoperatives Fasten bei Kindern?", back: "Es wird explizit NICHT empfohlen – ein unnötig langes Fasten bringt keinen zusätzlichen Sicherheitsgewinn, erhöht aber das Risiko von Dehydratation, Hypoglykämie, Unruhe/Stress des Kindes und kann die Einleitungsbedingungen verschlechtern." },
  { id: "fc-ll-165", module: "spezielle-anaesthesie", subtopic: "neuroanaesthesie", guideline: "Brain Trauma Foundation Guidelines (4. Auflage)", front: "Welche Aussage trifft die 4. Auflage der Brain Trauma Foundation Guidelines zum Vergleich von Mannitol und hypertoner Kochsalzlösung bei erhöhtem intrakraniellem Druck?", back: "Mannitol bleibt die etablierte hyperosmolare Standardsubstanz; für hypertone Kochsalzlösung als Alternative sah die 4. Auflage die Evidenzlage als nicht ausreichend an, um eine der beiden Substanzen als überlegen zu empfehlen – beide werden in der Praxis zur ICP-Senkung eingesetzt." },
  { id: "fc-ll-166", module: "spezielle-anaesthesie", subtopic: "neuroanaesthesie", guideline: "Brain Trauma Foundation Guidelines (4. Auflage)", front: "In welcher klinischen Situation wird eine dekompressive Kraniektomie bei schwerem Schädel-Hirn-Trauma laut BTF-Leitlinie erwogen?", back: "Als Eskalationsmaßnahme (Rescue-Therapie) bei trotz maximaler konservativer Therapie refraktärer intrakranieller Drucksteigerung; eine großflächige fronto-temporo-parietale Kraniektomie wird dabei einer kleinflächigen vorgezogen (bessere neurologische Ergebnisse/Mortalität), während eine bifrontale Kraniektomie bei diffuser Hirnschwellung zur Verbesserung des längerfristigen funktionellen Outcomes nicht generell empfohlen wird." },
  { id: "fc-ll-167", module: "spezielle-anaesthesie", subtopic: "neuroanaesthesie", guideline: "Brain Trauma Foundation Guidelines (4. Auflage)", front: "Empfiehlt die BTF-Leitlinie eine frühe prophylaktische Hypothermie bei schwerem Schädel-Hirn-Trauma?", back: "Nein – eine früh einsetzende (innerhalb weniger Stunden), kurzzeitige prophylaktische Hypothermie zur Verbesserung des Outcomes wird bei diffuser Hirnverletzung nicht empfohlen; Hypothermie bleibt Einzelfallentscheidungen bzw. speziellen refraktären ICP-Situationen vorbehalten." },
  { id: "fc-ll-168", module: "spezielle-anaesthesie", subtopic: "neuroanaesthesie", guideline: "Brain Trauma Foundation Guidelines (4. Auflage)", front: "Welchen Blutzuckerbereich strebt man laut gängiger Praxis/Leitlinienempfehlung bei Patienten mit schwerem Schädel-Hirn-Trauma an?", back: "Sowohl ausgeprägte Hyperglykämie als auch Hypoglykämie sollen vermieden werden; angestrebt wird meist eine moderate Blutzuckereinstellung (grob im Bereich von etwa 140–180 mg/dl bzw. 6–10 mmol/l) statt einer strengen Normoglykämie, da eine zu aggressive Insulintherapie das Hypoglykämierisiko erhöht – eine einzelne exakte Zielspanne ist nicht einheitlich evidenzbasiert festgelegt." },
  { id: "fc-ll-169", module: "pharmakologie", subtopic: "muskelrelaxanzien", guideline: "ASA-Konsensus (Neuromuskuläres Monitoring & Reversal)", front: "Was empfiehlt der ASA-Konsens zum bevorzugten Monitoring-Verfahren der neuromuskulären Funktion vor Extubation?", back: "Ein quantitatives (elektromyographisches oder akzeleromyographisches) Monitoring soll gegenüber einem rein qualitativen/visuell-taktilen Monitoring (z.B. einfacher Nervenstimulator ohne Messwert) bevorzugt eingesetzt werden, um eine TOF-Ratio ≥0,9 objektiv zu bestätigen." },
  { id: "fc-ll-170", module: "pharmakologie", subtopic: "muskelrelaxanzien", guideline: "ASA-Konsensus (Neuromuskuläres Monitoring & Reversal)", front: "Warum gelten rein klinische Zeichen der neuromuskulären Erholung (z.B. 5-Sekunden-Kopfheben, kräftiger Händedruck) laut ASA-Konsens als unzuverlässig?", back: "Diese klinischen Tests können auch bei noch relevanter Restblockade (TOF-Ratio <0,9) positiv ausfallen, da sie von willkürlicher Kraftanstrengung und Kooperation abhängen; sie schließen eine subklinische Restcurarisierung mit erhöhtem Aspirations-/Hypoxierisiko nicht sicher aus – daher wird ein objektives quantitatives Monitoring empfohlen." },
  { id: "fc-ll-171", module: "pharmakologie", subtopic: "muskelrelaxanzien", guideline: "ASA-Konsensus (Neuromuskuläres Monitoring & Reversal)", front: "Welche wichtigen Vorsichtsmaßnahmen/Kontraindikationen sind beim Einsatz von Sugammadex zu beachten?", back: "Bei schwerer Niereninsuffizienz (insb. dialysepflichtig) wird Sugammadex nicht empfohlen, da die Elimination beeinträchtigt und ein Rebound (Rekurarisierung) möglich ist. Zudem kann Sugammadex durch Komplexierung von Progesteron die Wirksamkeit hormoneller Kontrazeptiva vermindern – Patientinnen sollen auf eine zusätzliche nicht-hormonelle Verhütungsmethode für die folgenden Tage hingewiesen werden." },
  { id: "fc-ll-172", module: "intensivmedizin", subtopic: "sepsis-schock", guideline: "Surviving Sepsis Campaign 2026", front: "Wie bewertet die Surviving Sepsis Campaign 2026 den qSOFA-Score als Screening-Instrument für Sepsis?", back: "Die SSC rät ausdrücklich davon ab, qSOFA als alleiniges Screening-Instrument zu verwenden (starke Empfehlung). Im Vergleich zu SIRS, NEWS oder MEWS ist qSOFA zu wenig sensitiv für die Früherkennung. Krankenhäuser sollen stattdessen strukturierte Programme zur Verbesserung der Sepsisversorgung etablieren, die ein Screening akut kranker Hochrisikopatienten einschließen (starke Empfehlung)." },
  { id: "fc-ll-173", module: "intensivmedizin", subtopic: "sepsis-schock", guideline: "Surviving Sepsis Campaign 2026", front: "Welche Perfusionsparameter sollen laut SSC die Kreislauftherapie bei Sepsis steuern?", back: "Bei Sepsisverdacht Laktat messen (schwache Empfehlung) und die Therapie so steuern, dass ein erhöhtes Laktat sinkt (schwach). Ergänzend beim septischen Schock die Rekapillarisierungszeit als Zusatzparameter nutzen (schwach, u.a. gestützt auf ANDROMEDA-SHOCK). Weitere Volumengabe nach dynamischen Parametern (z.B. Passive Leg Raising mit Schlagvolumenmessung, Puls- oder Schlagvolumenvariation) statt nach Körperuntersuchung oder statischen Werten wie dem ZVD (schwach). NEU SSC 2026: zusätzlich point-of-care-Ultraschall (POCUS) zur Steuerung der Volumentherapie erwägen (bedingte Empfehlung)." },
  { id: "fc-ll-174", module: "intensivmedizin", subtopic: "sepsis-schock", guideline: "Surviving Sepsis Campaign 2026", front: "Welche Infusionslösungen empfiehlt die SSC zur Volumentherapie bei Sepsis, und von welchen rät sie ab?", back: "Kristalloide als Mittel der ersten Wahl (stark), dabei balancierte Kristalloide statt NaCl 0,9 % (schwach). Zusätzlich Albumin bei Patienten, die bereits große Mengen Kristalloide erhalten haben (schwach). Gegen Hydroxyethylstärke (HES) spricht sie eine starke Empfehlung aus, gegen Gelatine eine schwache." },
  { id: "fc-ll-175", module: "intensivmedizin", subtopic: "sepsis-schock", guideline: "Surviving Sepsis Campaign 2026", front: "Welchen initialen MAP-Zielwert nennt die SSC beim septischen Schock, und muss man mit dem Vasopressor bis zur ZVK-Anlage warten?", back: "Initialer Ziel-MAP 65 mmHg statt höherer Zielwerte (starke Empfehlung). NEU in SSC 2026: bei Patienten ≥65 Jahre wird ein initialer Zielbereich von 60–65 mmHg statt eines höheren Werts vorgeschlagen (bedingte Empfehlung, niedrige Evidenz). Vasopressoren sollen bereits über einen peripheren Venenzugang gestartet werden (möglichst großlumig, proximal, zeitlich begrenzt), statt den Beginn bis zur zentralvenösen Anlage aufzuschieben (schwach). Eine arterielle Kanüle soll so früh wie praktikabel gelegt werden (schwach)." },
  { id: "fc-ll-176", module: "intensivmedizin", subtopic: "sepsis-schock", guideline: "Surviving Sepsis Campaign 2026", front: "Wann wird laut SSC Vasopressin ergänzt, und was folgt bei weiter unzureichendem MAP oder septischer Kardiomyopathie?", back: "Vasopressin (meist bis 0,03 U/min) wird zusätzlich zu Noradrenalin gegeben statt Noradrenalin weiter zu steigern, üblicherweise ab einer Noradrenalin-Dosis von 0,25–0,5 µg/kg/min (schwach). Reicht der MAP trotz Noradrenalin plus Vasopressin nicht, wird Adrenalin ergänzt (schwach). Bei kardialer Dysfunktion mit persistierender Hypoperfusion trotz ausreichendem Volumenstatus und Blutdruck: Dobutamin zu Noradrenalin hinzufügen oder allein auf Adrenalin wechseln (schwach). Von Levosimendan rät die Leitlinie ab (schwach)." },
  { id: "fc-ll-177", module: "intensivmedizin", subtopic: "sepsis-schock", guideline: "Surviving Sepsis Campaign 2026", front: "Wann soll die empirische Sepsistherapie laut SSC MRSA, doppelte gramnegative Abdeckung oder Antimykotika umfassen?", back: "MRSA-Abdeckung nur bei hohem MRSA-Risiko (Best Practice Statement), bei niedrigem Risiko nicht (schwach). Zwei gramnegativ wirksame Substanzen nur bei hohem Risiko für multiresistente Erreger (schwach). Sobald Erreger und Resistenz bekannt sind, keine doppelte gramnegative Abdeckung mehr (schwach). Empirische Antimykotika nur bei hohem Pilzrisiko (schwach). Die SSC 2026 wird hier noch restriktiver: Sie rät von empirischer antimykotischer Therapie eher ab." },
  { id: "fc-ll-178", module: "intensivmedizin", subtopic: "sepsis-schock", guideline: "Surviving Sepsis Campaign 2026", front: "Was empfiehlt die SSC zur Applikationsart von Betalaktamen bei Sepsis?", back: "Betalaktame nach einer initialen Bolusgabe als verlängerte Infusion statt als Kurzinfusion – in der SSC 2026 auf eine STARKE Empfehlung hochgestuft (zuvor 2021 nur schwach). Dosierung nach PK/PD-Prinzipien optimieren (Best Practice)." },
  { id: "fc-ll-429", module: "intensivmedizin", subtopic: "sepsis-schock", guideline: "Surviving Sepsis Campaign 2026", front: "Was empfiehlt die SSC zur Steuerung der antibiotischen Therapiedauer bei Sepsis (Deeskalation, Procalcitonin)?", back: "Täglich prüfen, ob deeskaliert werden kann – bei vorliegendem Antibiogramm in SSC 2026 starke Empfehlung. Kürzere statt längere Therapiedauer (schwach). Procalcitonin plus klinische Beurteilung kann bei unklarer optimaler Dauer und adäquater Fokussanierung zur Entscheidung über das Absetzen herangezogen werden (schwach); NEU 2026: Procalcitonin wird NICHT zum Start der Antibiotikatherapie empfohlen (dagegen), nur zur Steuerung des Absetzens." },
  { id: "fc-ll-179", module: "intensivmedizin", subtopic: "sepsis-schock", guideline: "Surviving Sepsis Campaign 2026", front: "Was fordert die SSC zur Fokussanierung bei Sepsis?", back: "Einen sanierungsbedürftigen Infektionsfokus rasch identifizieren oder ausschließen und jede notwendige Fokussanierung (z.B. Drainage, Débridement, Entfernung infizierter Implantate) so früh durchführen, wie es medizinisch und logistisch möglich ist (Best Practice). Möglicherweise infizierte Gefäßkatheter werden nach Anlage eines neuen Zugangs zügig entfernt (Best Practice)." },
  { id: "fc-ll-180", module: "intensivmedizin", subtopic: "sepsis-schock", guideline: "Surviving Sepsis Campaign 2026", front: "Bei welchen Patienten und in welcher Dosierung empfiehlt die SSC Kortikosteroide im septischen Schock?", back: "Bei septischem Schock mit anhaltendem Vasopressorbedarf (weiterhin bedingte Empfehlung, in SSC 2026 aber von 'moderater' auf 'niedrige' Evidenzqualität herabgestuft). Die 2021 genannte Schwelle Noradrenalin/Adrenalin ≥0,25µg/kg/min über ≥4h ist eine Orientierung aus 2021 – SSC 2026 nennt bewusst KEINEN festen Startschwellenwert mehr (Uneinigkeit im Panel) und empfiehlt KEIN zusätzliches Fludrocortison. Gegeben wird i.d.R. weiterhin Hydrocortison i.v. 200 mg/Tag, entweder 50 mg alle 6 h oder als kontinuierliche Infusion." },
  { id: "fc-ll-181", module: "intensivmedizin", subtopic: "sepsis-schock", guideline: "Surviving Sepsis Campaign 2026", front: "Was empfiehlt die SSC zu Blutzucker, Vitamin C und Natriumbikarbonat bei Sepsis?", back: "Insulin ab einem Blutzucker ≥ 180 mg/dl (10 mmol/l), Zielbereich typischerweise 144–180 mg/dl (starke Empfehlung). Kein i.v.-Vitamin C (schwach). Kein Bikarbonat zur Kreislaufverbesserung bei hypoperfusionsbedingter Laktatazidose (schwach). Bikarbonat wird nur bei schwerer metabolischer Azidose (pH ≤ 7,2) und gleichzeitiger AKI (AKIN 2–3) vorgeschlagen (schwach)." },
  { id: "fc-ll-182", module: "intensivmedizin", subtopic: "sepsis-schock", guideline: "Surviving Sepsis Campaign 2026", front: "Welche Empfehlungen gibt die SSC zu Transfusion, Thromboseprophylaxe und Stressulkusprophylaxe?", back: "Restriktive Transfusion mit einem Hb-Trigger von 7 g/dl statt liberaler Strategie (stark). Medikamentöse VTE-Prophylaxe, sofern keine Kontraindikation besteht (stark), bevorzugt mit NMH statt UFH (stark). Keine zusätzliche mechanische Prophylaxe zur medikamentösen (schwach). Stressulkusprophylaxe nur bei Risikofaktoren für eine GI-Blutung (schwach)." },
  { id: "fc-ll-183", module: "intensivmedizin", subtopic: "sepsis-schock", guideline: "Surviving Sepsis Campaign 2026", front: "Was empfiehlt die SSC zur nichtinvasiven Atemunterstützung und zum Ernährungsbeginn bei Sepsis?", back: "Bei sepsisbedingter hypoxämischer respiratorischer Insuffizienz High-Flow-Sauerstoff über Nasenkanüle (HFNO) statt NIV (schwach). Beim sepsisinduzierten ARDS gelten die lungenprotektiven Standards (6 ml/kg PBW, Pplat ≤ 30 cmH2O, Bauchlage > 12 h/Tag bei mittelschwerem bis schwerem ARDS). Enterale Ernährung, sofern möglich, früh beginnen, also innerhalb von 72 Stunden (schwach)." },
  { id: "fc-ll-184", module: "intensivmedizin", subtopic: "sepsis-schock", guideline: "Surviving Sepsis Campaign 2026", front: "Was empfiehlt die SSC zu Therapiezielgesprächen und Palliativversorgung bei Sepsis?", back: "Therapieziele und Prognose mit Patient und Angehörigen besprechen (Best Practice), und zwar früh, innerhalb von 72 Stunden, statt spät (schwach). Palliativmedizinische Prinzipien sollen in die Behandlung integriert werden. Eine routinemäßige formale Palliativ-Konsultation für alle Patienten wird nicht empfohlen, sondern nach klinischer Einschätzung (schwach)." },
  { id: "fc-ll-185", module: "notfall-reanimation", subtopic: "als-bls", guideline: "ERC-Leitlinien 2021/2025 (Reanimation)", front: "Welche Eckpunkte zur Defibrillation nennen die ERC-Leitlinien für die Erwachsenenreanimation?", back: "Den Defibrillator während laufender Kompressionen laden. Die Pause vor dem Schock unter 5 Sekunden halten. Direkt nach dem Schock ohne Puls- oder Rhythmuskontrolle 2 Minuten weiter komprimieren, danach kurze Rhythmusanalyse. Erster biphasischer Schock mit mindestens 150 J, bei Misserfolg nach Möglichkeit Energie steigern. Bei beobachtetem, monitorisiertem Kammerflimmern (z.B. Herzkatheterlabor, Intensivstation) bis zu 3 rasch aufeinanderfolgende Schocks vor Beginn der Kompressionen." },
  { id: "fc-ll-186", module: "notfall-reanimation", subtopic: "als-bls", guideline: "ERC-Leitlinien 2021/2025 (Reanimation)", front: "Wann und in welcher Dosis werden laut ERC Antiarrhythmika bei defibrillierbarem Rhythmus gegeben?", back: "Amiodaron 300 mg i.v./i.o. nach dem 3. erfolglosen Schock, weitere 150 mg nach dem 5. Schock. Alternativ Lidocain 100 mg nach dem 3. Schock und 50 mg nach dem 5. Schock, wenn Amiodaron nicht verfügbar ist oder lokal Lidocain festgelegt wurde." },
  { id: "fc-ll-187", module: "notfall-reanimation", subtopic: "als-bls", guideline: "ERC-Leitlinien 2021/2025 (Reanimation)", front: "Was empfehlen die ERC-Leitlinien 2025 bei refraktärem Kammerflimmern?", back: "Refraktäres VF bedeutet persistierendes Kammerflimmern nach 3 aufeinanderfolgenden Schocks. Nach Prüfung der korrekten anterolateralen Pad-Position soll ein Vektorwechsel erwogen werden, also Umkleben auf anterior-posterior. Die doppelt-sequenzielle Defibrillation mit zwei Geräten (DSED) wird wegen begrenzter Evidenz und praktischer Probleme nicht routinemäßig empfohlen. Reversible Ursachen sind konsequent zu suchen." },
  { id: "fc-ll-188", module: "notfall-reanimation", subtopic: "als-bls", guideline: "ERC-Leitlinien 2021/2025 (Reanimation)", front: "Welchen Gefäßzugang sollen Helfer laut ERC 2025 bei der Erwachsenenreanimation zuerst versuchen?", back: "Zuerst einen intravenösen Zugang. Gelingt i.v. nicht rasch (etwa nach zwei Versuchen), ist intraossär die Alternative. Aktuelle Daten zeigen keinen Überlebensvorteil von i.o. gegenüber i.v. bei außerklinischem Kreislaufstillstand." },
  { id: "fc-ll-189", module: "notfall-reanimation", subtopic: "als-bls", guideline: "ERC-Leitlinien 2021/2025 (Reanimation)", front: "Was empfehlen die ERC-Leitlinien zum Atemwegsmanagement während der Reanimation?", back: "Schrittweises Vorgehen: Beutel-Maske, dann supraglottischer Atemweg oder Intubation, je nach Patient und Können. Intubieren sollen nur Anwender mit hoher Erfolgsrate (etwa > 95 % in 2 Versuchen). Die Kompressionspause beim Intubieren soll unter 5 Sekunden bleiben. Die Tubuslage wird zwingend mit Kurvenkapnografie bestätigt und überwacht. Nach Sicherung des Atemwegs wird kontinuierlich komprimiert und etwa 10-mal pro Minute beatmet." },
  { id: "fc-ll-190", module: "notfall-reanimation", subtopic: "als-bls", guideline: "ERC-Leitlinien 2021/2025 (Reanimation)", front: "Nach welchem Schema sucht man laut ERC systematisch nach reversiblen Ursachen eines Kreislaufstillstands?", back: "4 H: Hypoxie, Hypovolämie, Hypo-/Hyperkaliämie und metabolisch, Hypo-/Hyperthermie. HITS: Herzbeuteltamponade, Intoxikation, Thromboembolie, Spannungspneumothorax." },
  { id: "fc-ll-430", module: "notfall-reanimation", subtopic: "als-bls", guideline: "ERC-Leitlinien 2021/2025 (Reanimation)", front: "Welche Rolle spielen laut ERC Point-of-Care-Ultraschall (POCUS) und mechanische Reanimationshilfen während der CPR?", back: "POCUS nur durch erfahrene Anwender und ohne Verlängerung der Kompressionspausen einsetzen. Mechanische Kompressionsgeräte nicht routinemäßig, aber erwägen, wenn gute manuelle Kompressionen nicht möglich oder gefährlich sind (z.B. Transport, im Herzkatheterlabor während PCI)." },
  { id: "fc-ll-431", module: "notfall-reanimation", subtopic: "als-bls", guideline: "ERC-Leitlinien 2021/2025 (Reanimation)", front: "Wann wird eine eCPR laut ERC als Rettungstherapie erwogen?", back: "Bei ausgewählten Patienten, wenn konventionelle ALS-Maßnahmen versagen und ein System (Personal, Ausrüstung, Logistik) für die extrakorporale Reanimation etabliert ist." },
  { id: "fc-ll-191", module: "notfall-reanimation", subtopic: "als-bls", guideline: "ERC-Leitlinien 2021/2025 (Reanimation)", front: "Welche Zielwerte für Oxygenierung, Ventilation und Blutdruck nennen ERC/ESICM für die Postreanimationsphase?", back: "Nach ROSC SpO2 94–98 % anstreben und sowohl Hypoxämie als auch Hyperoxie vermeiden. Normokapnie mit PaCO2 etwa 35–45 mmHg (4,7–6,0 kPa). Hypotonie vermeiden: ERC-ESICM 2025 nennt systolischen Blutdruck > 100 mmHg bzw. MAP 60–65 mmHg als Zielbereich (zuvor 2021 schlicht 'MAP > 65 mmHg'), dazu adäquate Diurese (> 0,5 ml/kg/h) und fallendes oder normales Laktat. Zusätzlich frühes 12-Kanal-EKG; bei fehlender ST-Hebung wird nach ROSC zunehmend früh ein zweiphasiges Ganzkörper-CT (inkl. CT-Pulmonalisangiografie) zur Ursachenklärung priorisiert." },
  { id: "fc-ll-192", module: "notfall-reanimation", subtopic: "als-bls", guideline: "ERC-Leitlinien 2021/2025 (Reanimation)", front: "Wann ist laut ERC/ESICM nach ROSC eine notfallmäßige Koronarangiografie indiziert?", back: "Sofort bei ST-Hebungen im EKG nach ROSC mit vermuteter kardialer Ursache. Ohne ST-Hebung nicht routinemäßig sofort, sondern nur bei hoher Wahrscheinlichkeit eines akuten Koronarverschlusses, etwa bei hämodynamischer oder elektrischer Instabilität oder anhaltender Ischämie. Sonst verzögert bzw. elektiv nach Abklärung anderer Ursachen." },
  { id: "fc-ll-193", module: "notfall-reanimation", subtopic: "als-bls", guideline: "ERC-Leitlinien 2021/2025 (Reanimation)", front: "Wie soll laut ERC/ESICM die neurologische Prognoseabschätzung bei komatösen Patienten nach Reanimation erfolgen?", back: "Nicht vor 72 Stunden nach ROSC und erst nach Ausschluss von Störfaktoren wie Sedierung, Relaxanzien, Hypothermie oder Stoffwechselstörungen. Die Einschätzung ist immer multimodal. Eine schlechte Prognose ist wahrscheinlich bei mindestens 2 Befunden aus: fehlende Pupillen- und Kornealreflexe ≥ 72 h; bilateral fehlende N20-Antwort der SSEP; hochmaligne EEG-Muster; NSE > 60 µg/l nach 48 und/oder 72 h (serielle Messungen); früher Status myoclonus; diffuse hypoxische Schädigung in CT/MRT. Das 2025-Update bestätigt den multimodalen Ansatz." },
  { id: "fc-ll-194", module: "notfall-reanimation", subtopic: "als-bls", guideline: "ERC-Leitlinien 2021/2025 (Reanimation)", front: "Welche Besonderheiten gelten laut ERC für die Reanimation einer Schwangeren ab etwa der 20. SSW?", back: "Den Uterus manuell nach links verlagern, um die aortokavale Kompression aufzuheben, während Standard-ALS mit Kompressionen und Defibrillation weiterläuft. Kommt es nicht rasch zu ROSC, die Notfall-Hysterotomie (perimortale Sectio) vorbereiten: Entscheidung ca. 4 Minuten nach Beginn des Kreislaufstillstands, Entwicklung des Kindes möglichst innerhalb von 5 Minuten. Indiziert ab etwa der 20. SSW bzw. wenn der Fundus auf oder über Nabelhöhe steht." },
  { id: "fc-ll-195", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", guideline: "DAS-Leitlinien (Schwieriger Atemweg)", front: "Was empfehlen die DAS-Leitlinien 2025 zur Präoxygenierung und Oxygenierung während der Atemwegssicherung?", back: "Präoxygenierung mit dicht sitzender Maske bis zu einer endtidalen O2-Fraktion ≥ 0,9, in Oberkörperhochlage bzw. Rampenlagerung. Ab Präoxygenierung über die gesamte Atemwegssicherung hinweg kontinuierlich Sauerstoff geben (apnoische Oxygenierung per Nasenbrille, idealerweise HFNO), besonders bei Patienten mit rascher Entsättigung oder physiologisch bzw. anatomisch schwierigem Atemweg. Die Leitlinie 2025 legt den Schwerpunkt auf Erfolg beim ersten Versuch statt auf das Management des Scheiterns." },
  { id: "fc-ll-196", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", guideline: "DAS-Leitlinien (Schwieriger Atemweg)", front: "Wie ist die '3 + 1'-Regel für Intubationsversuche in den DAS-Leitlinien 2025 zu verstehen?", back: "Maximal 3 Intubationsversuche, dazu 1 weiterer Versuch durch einen erfahreneren Anwender. Das ist eine harte Obergrenze, kein Kontingent, das ausgeschöpft werden soll. Jeder Versuch soll optimiert sein: Videolaryngoskop als Standard, Lagerung, Bougie oder Führungsstab, externe Larynxmanipulation, vollständige Muskelrelaxierung, ausreichende Narkosetiefe. Scheitert ein Versuch, rasch Hilfe holen, die Schwierigkeit laut 'deklarieren' und zu Plan B übergehen." },
  { id: "fc-ll-197", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", guideline: "DAS-Leitlinien (Schwieriger Atemweg)", front: "Was geschieht in Plan B der DAS-Leitlinien, und welche Optionen folgen bei erfolgreicher SGA-Oxygenierung?", back: "Oxygenierung über einen supraglottischen Atemweg, bevorzugt der 2. Generation (DAS 2015: maximal 3 Einführversuche, ggf. Größe oder Modell wechseln). DAS 2025 versteht den SGA als Werkzeug für Oxygenierung und eine strategische Pause, nicht als Zeichen des Scheiterns. Gelingt die Oxygenierung: innehalten und entscheiden zwischen (1) Patient aufwachen lassen, (2) fiberoptisch geführte Intubation über den SGA, (3) Eingriff mit SGA fortsetzen (nur in Ausnahmefällen) oder (4) Tracheotomie bzw. Krikothyreotomie. Ist die SGA-Beatmung schwierig, schon jetzt den Front-of-Neck-Zugang vorbereiten." },
  { id: "fc-ll-198", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", guideline: "DAS-Leitlinien (Schwieriger Atemweg)", front: "Was umfasst Plan C der DAS-Leitlinien, und wie geht es weiter, wenn die Maskenbeatmung gelingt oder scheitert?", back: "Plan C ist der letzte optimierte Versuch der Maskenbeatmung: vollständige Muskelrelaxierung, ausreichende Narkosetiefe, optimale Lagerung, Oro- und/oder Nasopharyngealtubus und Zwei-Personen-Technik. Gelingt die Beatmung, den Patienten aufwachen lassen (nach Rocuronium z.B. Sugammadex 16 mg/kg). Gelingt sie nicht, CICO ('Cannot Intubate, Cannot Oxygenate') laut ausrufen und sofort Plan D beginnen." },
  { id: "fc-ll-199", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", guideline: "DAS-Leitlinien (Schwieriger Atemweg)", front: "Welche Ausrüstung und welche Schnittführung nennen die DAS-Leitlinien 2025 für den notfallmäßigen Front-of-Neck-Zugang (eFONA)?", back: "Ausrüstung: Skalpell mit Klinge Nr. 10, Bougie und geblockter Tubus mit 6,0 mm Innendurchmesser. DAS 2025 standardisiert den Zugang über eine vertikale Inzision, die am Schildknorpel beginnt und von kranial nach kaudal verläuft. Die 2015 bei tastbarer Membran vorgesehene horizontale Stichinzision ist damit nicht mehr Standard. Günstig ist, wenn ein rechtshändiger Anwender auf der rechten Patientenseite steht. Vollständige Relaxierung und fortgesetzte Oxygenierung von oben sind sicherzustellen." },
  { id: "fc-ll-200", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", guideline: "DAS-Leitlinien (Schwieriger Atemweg)", front: "Wie soll laut DAS-Leitlinie mit dem Krikoiddruck umgegangen werden, wenn Laryngoskopie, SGA-Einlage oder Maskenbeatmung schwierig sind?", back: "Den Krikoiddruck reduzieren oder ganz lösen, möglichst unter Sicht und mit Absaugung in Bereitschaft. Er kann die Laryngoskopiesicht verschlechtern und die Einlage eines SGA sowie die Maskenbeatmung behindern. Oxygenierung hat Vorrang vor dem theoretischen Aspirationsschutz." },
  { id: "fc-ll-201", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", guideline: "DAS-Leitlinien (Schwieriger Atemweg)", front: "Welche Kernelemente enthält die DAS-Leitlinie 2020 zur Wachintubation (Awake Tracheal Intubation, ATI)?", back: "Struktur nach 'sTOP': Sedierung, Topikalisierung, Oxygenierung, Performance (Durchführung). Sedierung nur minimal und möglichst durch einen zweiten Anästhesisten (z.B. Remifentanil oder Dexmedetomidin), niemals als Ersatz für unzureichende Topikalisierung. Die Lokalanästhesie wird getestet, Lidocain maximal 9 mg/kg Magerkörpergewicht. Während der gesamten Prozedur Sauerstoff geben, bevorzugt HFNO. Höchstens 3 Versuche plus 1 durch einen Erfahreneren. Die Narkose erst nach 'Zwei-Punkt-Kontrolle' der Tubuslage einleiten: Sicht auf die Trachea plus Kapnografie." },
  { id: "fc-ll-202", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", guideline: "DAS-Leitlinien (Schwieriger Atemweg)", front: "Wie strukturiert die DAS-Extubationsleitlinie das Vorgehen, und welche Techniken sind für die Risiko-Extubation vorgesehen?", back: "Vier Schritte: Planen, Vorbereiten, Durchführen, Nachsorge. Zunächst wird zwischen Niedrigrisiko- und Risiko-Extubation unterschieden (z.B. bekannter schwieriger Atemweg, eingeschränkter Zugang, allgemeine Risikofaktoren). Bei Risiko-Extubation kommen infrage: Wach-Extubation, Remifentanil-Technik, Wechsel auf Larynxmaske (Bailey-Manöver) oder Extubation über einen Tubuswechselkatheter. Ist eine sichere Extubation nicht möglich, die Extubation verschieben oder eine Tracheotomie erwägen." },
  { id: "fc-ll-203", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", guideline: "DAS-Leitlinien (Schwieriger Atemweg)", front: "Welche Maßnahmen nach einer schwierigen Atemwegssicherung fordern die DAS-Leitlinien zur Bestätigung, Nachsorge und Dokumentation?", back: "Tubuslage mit anhaltender Kurvenkapnografie bestätigen ('no trace = wrong place'), auch bei der Reanimation. Nach dem Ereignis: Team-Debriefing, detaillierte Dokumentation (was hat funktioniert, was nicht), mündliche und schriftliche Information des Patienten, Airway-Alert-Brief bzw. Eintrag in die Akte und Information des Hausarztes. Schwerwiegende Ereignisse werden im Zwischenfallmeldesystem gemeldet." },
  { id: "fc-ll-204", module: "intensivmedizin", subtopic: "ernaehrung", guideline: "ESPEN-Leitlinie 2023 (Klinische Ernährung)", front: "Welche Intensivpatienten gelten laut ESPEN-Leitlinie als mangelernährungsgefährdet, und wie soll das erfasst werden?", back: "Grundsätzlich jeder Patient, der länger als 48 Stunden auf der Intensivstation liegt. Eine klinische Beurteilung des Ernährungszustands (Gewichtsverlauf, Nahrungsaufnahme vor Aufnahme, Muskelmasse und -kraft) soll bei allen erfolgen, ergänzt durch Screening-Scores (z.B. NRS-2002, mNUTRIC) und idealerweise eine Einschätzung von Körperzusammensetzung und Muskelmasse." },
  { id: "fc-ll-205", module: "intensivmedizin", subtopic: "ernaehrung", guideline: "ESPEN-Leitlinie 2023 (Klinische Ernährung)", front: "Welcher Ernährungsweg und welcher Zeitpunkt werden laut ESPEN 2023 bei kritisch Kranken bevorzugt?", back: "Kann der Patient essen, hat orale Kost Vorrang. Ist das nicht möglich, frühe enterale Ernährung innerhalb von 48 Stunden, und zwar sowohl gegenüber verzögerter EN als auch gegenüber früher parenteraler Ernährung. Standard ist der gastrale Zugang. Postpylorisch (jejunal) wird ernährt bei gastraler Intoleranz, die auf Prokinetika nicht anspricht, oder bei hohem Aspirationsrisiko." },
  { id: "fc-ll-206", module: "intensivmedizin", subtopic: "ernaehrung", guideline: "ESPEN-Leitlinie 2023 (Klinische Ernährung)", front: "In welchen Situationen soll die enterale Ernährung laut ESPEN verschoben werden?", back: "Bei unkontrolliertem Schock, unkontrollierter lebensbedrohlicher Hypoxämie, Hyperkapnie oder Azidose, aktiver oberer GI-Blutung, Magenreflux > 500 ml/6 h, Darmischämie, mechanischem Ileus, abdominellem Kompartmentsyndrom und High-Output-Fistel ohne distalen Ernährungszugang. Ist der Zustand stabilisiert (kontrollierter Schock, stabile Hypoxämie, permissive Hyperkapnie, gestillte Blutung), niedrig dosiert enteral beginnen, z.B. auch unter ECMO, Bauchlage, Muskelrelaxation oder Temperaturmanagement." },
  { id: "fc-ll-207", module: "intensivmedizin", subtopic: "ernaehrung", guideline: "ESPEN-Leitlinie 2023 (Klinische Ernährung)", front: "Wann ist laut ESPEN 2023 eine parenterale Ernährung bei Intensivpatienten indiziert?", back: "Sind orale und enterale Ernährung kontraindiziert, soll die PN innerhalb von 3–7 Tagen beginnen. Bei schwer mangelernährten Patienten mit EN-Kontraindikation früh und schrittweise steigernd, statt gar nicht zu ernähren. Eine supplementierende PN bei unzureichender EN wird fallbezogen erwogen, aber erst nachdem alle Maßnahmen zur Verbesserung der enteralen Toleranz ausgeschöpft sind." },
  { id: "fc-ll-208", module: "intensivmedizin", subtopic: "ernaehrung", guideline: "ESPEN-Leitlinie 2023 (Klinische Ernährung)", front: "Wie soll laut ESPEN der Energiebedarf von Intensivpatienten bestimmt werden, und was gilt bei Adipositas?", back: "Goldstandard ist die indirekte Kalorimetrie. Steht sie nicht zur Verfügung, ist die Berechnung aus VO2 (Pulmonaliskatheter) oder VCO2 (Beatmungsgerät) genauer als Formeln. Gewichtsbasierte Schätzungen (ca. 20–25 kcal/kg/Tag) sind nur die Notlösung, mit hypokalorischer Ernährung in der Frühphase. Bei Adipositas: isokalorisch-proteinreich, möglichst nach Kalorimetrie. Protein ca. 1,3 g/kg adjustiertes Körpergewicht pro Tag (adjustiertes KG = Idealgewicht + ein Drittel der Differenz zum Istgewicht)." },
  { id: "fc-ll-209", module: "intensivmedizin", subtopic: "ernaehrung", guideline: "ESPEN-Leitlinie 2023 (Klinische Ernährung)", front: "Wie soll laut ESPEN mit gastraler Intoleranz bzw. hohem Magenreflux unter enteraler Ernährung umgegangen werden?", back: "Bei einem Magenreflux > 500 ml/6 h die EN pausieren bzw. reduzieren und ein Prokinetikum erwägen. Mittel der ersten Wahl ist Erythromycin i.v. 100–250 mg 3-mal täglich für 2–4 Tage. Alternativ oder kombiniert Metoclopramid 10 mg 2–4-mal täglich. Nach etwa 72 h lässt die Wirkung der Prokinetika deutlich nach, danach absetzen. Bleibt die Intoleranz trotz Prokinetika bestehen, postpylorische Sonde legen." },
  { id: "fc-ll-210", module: "intensivmedizin", subtopic: "ernaehrung", guideline: "ESPEN-Leitlinie 2023 (Klinische Ernährung)", front: "Wie erkennt und behandelt man laut ESPEN eine Refeeding-Hypophosphatämie beim Intensivpatienten?", back: "Nach Beginn der Ernährung Phosphat regelmäßig kontrollieren. Fällt es unter 0,65 mmol/l oder um mehr als 0,16 mmol/l, Elektrolyte 2–3-mal täglich messen und gezielt substituieren. Die Energiezufuhr für 48 Stunden reduzieren und danach schrittweise wieder steigern." },
  { id: "fc-ll-211", module: "intensivmedizin", subtopic: "ernaehrung", guideline: "ESPEN-Leitlinie 2023 (Klinische Ernährung)", front: "Bei welchen Intensivpatienten empfiehlt ESPEN eine zusätzliche Glutamin-Gabe, und wann ist sie kontraindiziert?", back: "Enteral zusätzlich Glutamin bei Verbrennungen > 20 % KOF: 0,3–0,5 g/kg/Tag für 10–15 Tage ab Beginn der EN. Bei Trauma: 0,2–0,3 g/kg/Tag in den ersten 5 Tagen, bei Wundheilungsstörungen 10–15 Tage. Bei anderen Intensivpatienten keine zusätzliche enterale Glutamingabe. Glutamin i.v. nicht bei instabilen, komplexen Intensivpatienten, insbesondere nicht bei Leber- oder Nierenversagen." },
  { id: "fc-ll-212", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "ESAIC Perioperative Fasting Guideline", front: "Welche Nüchternzeiten empfiehlt die ESAIC-Leitlinie 2022 zur präoperativen Nüchternheit bei Kindern?", back: "Klare Flüssigkeiten bis 1 Stunde vor Einleitung (ausdrücklich erwünscht). Muttermilch bis 3 Stunden. Säuglingsnahrung bzw. andere Milch bis 4 Stunden. Ein leichtes Frühstück kann bis 4 Stunden vor Einleitung erlaubt werden, sonst 6 Stunden für feste Nahrung. Unnötig lange Nüchternzeiten sollen vermieden werden (Ketose, Hypotonie bei Einleitung, Unwohlsein). Nach dem Eingriff sollen Kinder früh wieder trinken und essen." },
  { id: "fc-ll-213", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "ESAIC Perioperative Fasting Guideline", front: "Muss eine elektive Narkose laut ESAIC-Nüchternheitsleitlinie verschoben werden, wenn ein Patient kurz vorher geraucht hat?", back: "Nein. Rauchen kurz vor der Einleitung ist kein Grund, die Narkose zu verschieben oder abzusagen, genauso wenig wie Kaugummikauen oder ein Bonbon. Unabhängig davon wird präoperativer Rauchverzicht aus allgemeinen Gründen (pulmonale und Wundkomplikationen) empfohlen." },
  { id: "fc-ll-214", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "ESAIC Perioperative Fasting Guideline", front: "Gelten die Standard-Nüchternzeiten laut ESAIC auch für adipöse Patienten, Patienten mit Reflux, Diabetiker und Schwangere außerhalb der Geburt?", back: "Ja. Für adipöse Patienten, Patienten mit gastroösophagealem Reflux, Diabetiker und Schwangere, die nicht unter der Geburt sind, gelten die gleichen Regeln wie für Gesunde: klare Flüssigkeiten bis 2 h, feste Nahrung bis 6 h. Diabetes allein ist keine Kontraindikation für liberale Regeln bei klaren Flüssigkeiten. Bei Gastroparese, Ileus oder Stenosen ist individuell zu entscheiden." },
  { id: "fc-ll-215", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "ESAIC Perioperative Fasting Guideline", front: "Welche Rolle spielen kohlenhydrathaltige klare Getränke präoperativ laut ESAIC, und welche Vorteile haben sie?", back: "Klare kohlenhydratreiche Getränke gelten als klare Flüssigkeit und sind bis 2 Stunden vor elektiven Eingriffen sicher, auch für Diabetiker. Sie verringern Durst, Hunger und Angst sowie die postoperative Insulinresistenz und sind Teil von ERAS-Konzepten. Die ESAIC befürwortet sie ausdrücklicher als die konservativere ASA." },
  { id: "fc-ll-216", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "ESAIC Perioperative Fasting Guideline", front: "Was empfehlen aktuelle Nüchternheitsleitlinien (ESAIC; internationaler Konsens 2026) zur Flüssigkeitsaufnahme in den letzten 2 Stunden und zur postoperativen Kostaufnahme?", back: "Patienten sollen ausdrücklich ermutigt werden, klare Flüssigkeiten bis 2 Stunden vor Anästhesiebeginn zu trinken. Kliniken sollen Protokolle einführen, die auch innerhalb der letzten 2 Stunden liberaler klare Flüssigkeit erlauben (bei Kindern laut ESAIC bereits bis 1 h). Milch in Tee oder Kaffee ist bis etwa ein Fünftel des Volumens erlaubt. Nach dem Eingriff sollen Flüssigkeit und Kost so früh wie klinisch möglich wieder aufgenommen werden." },
  { id: "fc-ll-217", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "ESAIC Perioperative Fasting Guideline (Erwachsene, Update 2026)", front: "Welchen Stellenwert hat die präoperative Magensonografie, z.B. bei unklarer Nüchternheit oder unter GLP-1-Rezeptoragonisten?", back: "Die Magensonografie durch einen geschulten Anwender kann bei Unsicherheit (unklare Nüchternheit, Notfall, GLP-1-Rezeptoragonisten, Gastroparese) helfen, Magenvolumen und -inhalt abzuschätzen und die Entscheidung zu steuern (z.B. verschieben, RSI, Regionalanästhesie). Das ESAIC-2026-Update verlängert deshalb bei entsprechendem Risiko die empfohlenen festen Nüchternzeiten auf '6h/8h oder länger' statt starrer Grenzwerte. Prospektive Daten zum Aspirationsrisiko unter GLP-1-RA fehlen weiterhin. Deshalb wird individuell nach Risiko entschieden." },
  { id: "fc-ll-218", module: "intensivmedizin", subtopic: "beatmung", guideline: "ARDS-Beatmungsleitlinien (ATS/ESICM/SCCM, ESICM 2023)", front: "Was empfiehlt die ESICM-Leitlinie 2023 zu HFNO und NIV/CPAP bei akuter hypoxämischer respiratorischer Insuffizienz (AHRF)?", back: "HFNO wird gegenüber konventioneller Sauerstofftherapie vorgeschlagen, um die Intubationsrate zu senken (bedingte Empfehlung). Das gilt für AHRF, die nicht durch kardiales Lungenödem oder eine COPD-Exazerbation bedingt ist. Zu NIV bzw. CPAP im Vergleich zu HFNO bei nicht-COVID-AHRF gibt es keine Empfehlung dafür oder dagegen, da kein gesicherter Mortalitätsvorteil belegt ist. Eine Intubation darf durch nichtinvasive Verfahren nicht verzögert werden." },
  { id: "fc-ll-219", module: "intensivmedizin", subtopic: "beatmung", guideline: "ARDS-Beatmungsleitlinien (ATS/ESICM/SCCM, ESICM 2023)", front: "Wie positioniert sich das ATS-Update 2023 zu Kortikosteroiden beim ARDS?", back: "Das ATS schlägt Kortikosteroide für Patienten mit ARDS vor (bedingte Empfehlung, moderate Evidenz). Die ESICM-Leitlinie 2023 behandelt vor allem Definition, Phänotypisierung und Atemunterstützung und äußert sich nicht zu Steroiden." },
  { id: "fc-ll-220", module: "intensivmedizin", subtopic: "beatmung", guideline: "ARDS-Beatmungsleitlinien (ATS/ESICM/SCCM, ESICM 2023)", front: "Wie unterscheiden sich ATS 2023 und ESICM 2023 in ihrer Empfehlung zum PEEP beim mittelschweren bis schweren ARDS?", back: "Das ATS schlägt einen höheren PEEP vor, aber ohne Rekrutierungsmanöver (bedingte Empfehlung, niedrige Evidenz). Die ESICM sieht die Datenlage als unzureichend an und gibt weder für noch gegen hohen PEEP oder eine individualisierte PEEP-Titration (z.B. nach Driving Pressure, EIT, Ösophagusdruck) eine Empfehlung." },
  { id: "fc-ll-221", module: "intensivmedizin", subtopic: "beatmung", guideline: "ARDS-Beatmungsleitlinien (ATS/ESICM/SCCM, ESICM 2023)", front: "Was empfehlen ATS und ESICM 2023 zu Rekrutierungsmanövern beim ARDS?", back: "Beide raten mit starker Empfehlung von anhaltenden Hochdruck-Rekrutierungsmanövern ab, etwa lang gehaltene hohe Atemwegsdrücke oder stufenweise PEEP-Steigerung nach dem ART-Protokoll. Grund sind Hinweise auf höhere Mortalität und Barotrauma. Die ESICM rät zusätzlich auch von kurzen Hochdruck-Rekrutierungsmanövern ab (bedingte Empfehlung)." },
  { id: "fc-ll-222", module: "intensivmedizin", subtopic: "beatmung", guideline: "ARDS-Beatmungsleitlinien (ATS/ESICM/SCCM, ESICM 2023)", front: "Wie bewerten ATS 2023 und ESICM 2023 den Einsatz von Muskelrelaxanzien (NMBA) beim ARDS?", back: "Das ATS schlägt Muskelrelaxanzien beim frühen schweren ARDS vor (bedingte Empfehlung). Die ESICM rät von einer routinemäßigen kontinuierlichen NMBA-Infusion beim mittelschweren bis schweren ARDS ab, u.a. wegen des neutralen Ergebnisses der ROSE-Studie. Im Einzelfall (z.B. schwere Asynchronie, refraktäre Hypoxämie) bleibt sie möglich." },
  { id: "fc-ll-223", module: "intensivmedizin", subtopic: "beatmung", guideline: "ARDS-Beatmungsleitlinien (ATS/ESICM/SCCM, ESICM 2023)", front: "Was empfehlen ESICM 2023 und ATS 2023 zu VV-ECMO und extrakorporaler CO2-Elimination (ECCO2R) beim ARDS?", back: "ESICM: starke Empfehlung für VV-ECMO bei schwerem ARDS nach EOLIA-Kriterien in einem erfahrenen ECMO-Zentrum. EOLIA-Kriterien trotz optimierter Beatmung inkl. Bauchlage: PaO2/FiO2 < 50 mmHg > 3 h, < 80 mmHg > 6 h oder pH < 7,25 mit PaCO2 ≥ 60 mmHg > 6 h. ATS: bedingte Empfehlung für VV-ECMO bei ausgewählten Patienten mit schwerem ARDS. ECCO2R soll außerhalb von Studien nicht eingesetzt werden (ESICM, starke Empfehlung)." },
  { id: "fc-ll-224", module: "intensivmedizin", subtopic: "beatmung", guideline: "ARDS-Beatmungsleitlinien (ATS/ESICM/SCCM, ESICM 2023)", front: "Welchen Stellenwert hat die Hochfrequenzoszillationsbeatmung (HFOV) laut ATS/ESICM/SCCM-Leitlinien beim ARDS?", back: "Von einer routinemäßigen HFOV beim mittelschweren oder schweren ARDS wird mit starker Empfehlung und hoher Evidenz abgeraten. Die Studien OSCILLATE und OSCAR zeigten keinen Nutzen, eher eine höhere Mortalität." },
  { id: "fc-ll-225", module: "intensivmedizin", subtopic: "nierenersatz", guideline: "KDIGO-Leitlinie (Nierenersatztherapie)", front: "Welche Antikoagulation empfiehlt KDIGO für kontinuierliche bzw. intermittierende Nierenersatzverfahren?", back: "CRRT: regionale Citrat-Antikoagulation statt Heparin, sofern keine Kontraindikation besteht (2B). Das gilt auch bei erhöhtem Blutungsrisiko. Bei Citrat-Kontraindikation UFH oder NMH. Intermittierende Dialyse: UFH oder NMH (1C). Hauptkontraindikationen für Citrat sind schweres Leberversagen und Schock mit Laktatazidose, weil Citrat dann nicht ausreichend metabolisiert wird (Citratakkumulation, Abfall des ionisierten Calciums)." },
  { id: "fc-ll-226", module: "intensivmedizin", subtopic: "nierenersatz", guideline: "KDIGO-Leitlinie (Nierenersatztherapie)", front: "Wie soll laut KDIGO bei heparininduzierter Thrombozytopenie (HIT) während einer Nierenersatztherapie antikoaguliert werden?", back: "Jedes Heparin sofort absetzen, auch Spülungen und Katheterblocks. Stattdessen direkte Thrombininhibitoren (z.B. Argatroban) oder Faktor-Xa-Inhibitoren (Danaparoid, Fondaparinux) einsetzen (1A). Ohne schwere Leberinsuffizienz wird Argatroban bevorzugt (2C)." },
  { id: "fc-ll-227", module: "intensivmedizin", subtopic: "nierenersatz", guideline: "KDIGO-Leitlinie (Nierenersatztherapie)", front: "Welche Empfehlungen gibt KDIGO zum Gefäßzugang für die akute Nierenersatztherapie?", back: "Nicht getunnelter, ungecuffter Dialysekatheter (2D). Reihenfolge der Punktionsorte: 1. V. jugularis interna rechts, 2. V. femoralis, 3. V. jugularis interna links, zuletzt V. subclavia der dominanten Seite. Anlage ultraschallgesteuert (1A). Nach jugulärer oder subklavikulärer Anlage vor der ersten Nutzung Röntgen-Thorax (1B). Keine topischen Antibiotika an der Einstichstelle und keine Antibiotika-Locks zur Infektionsprophylaxe (jeweils 2C)." },
  { id: "fc-ll-228", module: "intensivmedizin", subtopic: "nierenersatz", guideline: "KDIGO-Leitlinie (Nierenersatztherapie)", front: "Welche Dialysedosis empfiehlt KDIGO bei akuter Nierenschädigung?", back: "Die Dosis vor jeder Behandlung festlegen und die tatsächlich erreichte Dosis regelmäßig kontrollieren. Intermittierende oder verlängerte Verfahren: Kt/V von 3,9 pro Woche (1A). CRRT: Effluentfluss von 20–25 ml/kg/h als erreichte Dosis (1A). Wegen Unterbrechungen muss dafür meist höher verordnet werden, etwa 25–30 ml/kg/h. Eine höhere Intensität bringt keinen Überlebensvorteil (RENAL, ATN)." },
  { id: "fc-ll-229", module: "intensivmedizin", subtopic: "nierenersatz", guideline: "KDIGO-Leitlinie (Nierenersatztherapie)", front: "Welchen Puffer empfiehlt KDIGO für Dialysat bzw. Substitutionslösung, und wann ist ein kontinuierliches Verfahren besonders indiziert?", back: "Bikarbonat statt Laktat als Puffer (2C), besonders bei Kreislaufschock (1B) sowie bei Leberversagen oder Laktatazidose (2B). CRRT statt intermittierender Verfahren wird neben hämodynamischer Instabilität auch bei akuter Hirnschädigung, erhöhtem Hirndruck oder generalisiertem Hirnödem empfohlen (2B), weil osmotische Verschiebungen dann geringer ausfallen. Membranen sollen biokompatibel sein (2C)." },
  { id: "fc-ll-230", module: "intensivmedizin", subtopic: "nierenersatz", guideline: "KDIGO-Leitlinie (Nierenersatztherapie)", front: "Wann soll laut KDIGO eine Nierenersatztherapie beendet werden, und welche Rolle spielen Diuretika?", back: "Beenden, wenn sie nicht mehr erforderlich ist: Entweder hat sich die Nierenfunktion ausreichend erholt, oder die Therapie entspricht nicht mehr den Behandlungszielen. Diuretika sollen weder die Erholung der Nierenfunktion beschleunigen noch Dauer oder Frequenz der Dialyse verringern (2B). Zur Behandlung der AKI selbst keine Diuretika, außer bei Volumenüberladung (2C). Hinweis: Ein KDIGO-Update 2026 (AKI/AKD) lag 2026 als Entwurf zur öffentlichen Begutachtung vor." },
  { id: "fc-ll-231", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", guideline: "ESAIC Bleeding-Management-Leitlinie", front: "Was empfiehlt die ESAIC-Bleeding-Leitlinie zur präoperativen Gerinnungsanamnese und zum Anämiemanagement?", back: "Für die Gerinnungsanamnese einen strukturierten, standardisierten Blutungsfragebogen verwenden statt routinemäßiger Standard-Gerinnungstests (PT/aPTT haben geringen Vorhersagewert). Patienten mit Blutungsrisiko idealerweise mehrere Wochen vor dem Eingriff (etwa 4–8) auf Anämie untersuchen. Eine Eisenmangelanämie mit Eisen behandeln, i.v.-Eisen bei Unverträglichkeit, fehlender Wirkung oder zu kurzer Zeit bis zur OP." },
  { id: "fc-ll-232", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", guideline: "ESAIC Bleeding-Management-Leitlinie", front: "Welchen Hb-Zielbereich nennt die ESAIC-Bleeding-Leitlinie 2022 während aktiver Blutung, und wie soll postoperativ transfundiert werden?", back: "Während aktiver Blutung einen Hb von 7–9 g/dl anstreben. Bei postoperativer Anämie mit Hb unter 6–8 g/dl bzw. bei Unterschreiten physiologischer Transfusionstrigger nach der Single-Unit-Strategie transfundieren: ein EK, dann neu beurteilen." },
  { id: "fc-ll-233", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", guideline: "ESAIC Bleeding-Management-Leitlinie", front: "Welche Rolle spielen viskoelastische Tests, Algorithmen und PCC laut ESAIC-Bleeding-Leitlinie 2022?", back: "Die Gerinnungstherapie soll zielgerichtet mit viskoelastischen Tests (ROTEM/TEG) gesteuert werden, eingebettet in standardisierte Algorithmen mit vordefinierten Interventionstriggern statt Therapie nach Ermessen des Arztes. Bei Blutung mit Zeichen eines Gerinnungsfaktormangels (verlängerte CT im VHA, hohe PT-Ratio) wird PCC gegenüber FFP bevorzugt, sofern verfügbar." },
  { id: "fc-ll-234", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", guideline: "ESAIC Bleeding-Management-Leitlinie", front: "Was empfiehlt die ESAIC-Bleeding-Leitlinie zum Einsatz von Tranexamsäure?", back: "Tranexamsäure prophylaktisch bei Eingriffen mit relevantem Blutungsrisiko (z.B. Herz-, Orthopädie-, Leber-, gynäkologische Chirurgie) und therapeutisch bei Blutung, einschließlich Trauma (möglichst innerhalb von 3 h) und postpartaler Blutung (1 g i.v.). Sie kann oral, i.v. und/oder topisch gegeben werden. Systemisch plus topisch senkt den Blutverlust weiter. Beispiel gynäkologische Chirurgie: einmalig 1 g bzw. 10–15 mg/kg i.v. oder topisch." },
  { id: "fc-ll-235", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", guideline: "ESAIC Bleeding-Management-Leitlinie", front: "Wie sollen laut ESAIC-Bleeding-Leitlinie 2022 Blutungen unter oralen Antikoagulanzien behandelt werden?", back: "Vitamin-K-Antagonisten: 4-Faktoren-PCC plus Vitamin K i.v. Faktor-Xa-Inhibitoren (Rivaroxaban, Apixaban, Edoxaban): PCC mit initial 25 IE/kg statt Andexanet alfa (2C). Gründe sind Zulassung, Kosten und eine höhere Thromboserate unter Andexanet. Dabigatran: Idarucizumab erwägen. Elektiv vor Eingriffen mit DOAC die Kreatinin-Clearance bestimmen. Bei Eingriffen mit niedrigem Blutungsrisiko (Haut, Zahn, Endoskopie, meiste Augen-OPs) kann der DOAC bis zum Vortag weitergegeben werden." },
  { id: "fc-ll-236", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", guideline: "ESAIC Bleeding-Management-Leitlinie", front: "Welchen Stellenwert haben rekombinanter Faktor VIIa, Desmopressin und maschinelle Autotransfusion laut ESAIC-Bleeding-Leitlinie?", back: "rFVIIa ist eine Off-Label-Reserveoption bei Blutung, die trotz konventioneller hämostatischer Therapie nicht beherrschbar ist, unter Abwägung des Thromboserisikos. Desmopressin kann bei Thrombozytenfunktionsstörung (z.B. durch Thrombozytenaggregationshemmer oder Urämie) und beim Von-Willebrand-Syndrom erwogen werden. Maschinelle Autotransfusion (Cell Salvage) wird bei Eingriffen mit hohem Blutverlust wie Herz- und großer orthopädischer Chirurgie empfohlen, um Fremdblut zu sparen. Normothermie und physiologisches ionisiertes Calcium sind Basismaßnahmen." },
  { id: "fc-ll-237", module: "regional-schmerz", subtopic: "periphere-blockaden", guideline: "ASRA/ESRA-Leitlinie (Periphere Nervenblockaden & Antikoagulation)", front: "Welche Terminologie führt die ASRA-Leitlinie (5. Auflage, 2025) ein, und welche NMH-Intervalle gelten für neuraxiale und tiefe Blockaden?", back: "Statt 'prophylaktisch/therapeutisch' spricht ASRA 2025 von 'niedrig dosiert/hoch dosiert'. NMH niedrig dosiert: mindestens 12 h Abstand zur Punktion. NMH hoch dosiert: mindestens 24 h. Ein Katheter wird frühestens 12 h nach der letzten niedrig dosierten Gabe entfernt, die nächste Dosis frühestens 4 h nach Entfernung. Für tiefe Plexus- und periphere Blockaden gelten dieselben Intervalle wie neuraxial." },
  { id: "fc-ll-238", module: "regional-schmerz", subtopic: "periphere-blockaden", guideline: "ASRA/ESRA-Leitlinie (Periphere Nervenblockaden & Antikoagulation)", front: "Welche Pausen vor neuraxialen bzw. tiefen Blockaden nennt ASRA 2025 für Faktor-Xa-Hemmer, und welcher Spiegel gilt als sicher?", back: "Hoch dosiertes Apixaban, Rivaroxaban oder Edoxaban: 72 h Pause. Niedrig dosiertes Apixaban (2,5 mg 2-mal täglich): 36 h. Rivaroxaban 10 mg 1-mal täglich: 24 h bei CrCl > 30 ml/min, 30 h bei CrCl 15–30 ml/min. Neu ist die Absicherung per Spiegelmessung: Ein Restspiegel < 30 ng/ml bzw. Anti-Xa-Aktivität ≤ 0,1 IE/ml gilt als akzeptabel. Die Intervalle werden zudem nach Nierenfunktion individualisiert." },
  { id: "fc-ll-239", module: "regional-schmerz", subtopic: "periphere-blockaden", guideline: "ASRA/ESRA-Leitlinie (Periphere Nervenblockaden & Antikoagulation)", front: "Welche Absetzintervalle gelten laut ASRA für P2Y12-Inhibitoren vor neuraxialen bzw. tiefen Blockaden, und was gilt für liegende Katheter?", back: "Clopidogrel 5–7 Tage, Prasugrel 7–10 Tage, Ticagrelor 5–7 Tage. Wegen des raschen Wirkeintritts darf ein Katheter unter Prasugrel nicht belassen werden. Unter Clopidogrel ohne Loading Dose ist ein Liegenlassen für 1–2 Tage möglich, da die Wirkung verzögert einsetzt. ASS oder NSAR allein sind keine Kontraindikation." },
  { id: "fc-ll-240", module: "regional-schmerz", subtopic: "periphere-blockaden", guideline: "ASRA/ESRA-Leitlinie (Periphere Nervenblockaden & Antikoagulation)", front: "Welche Intervalle gelten laut ASRA für unfraktioniertes Heparin (UFH) vor Punktion bzw. um die Katheterentfernung?", back: "Niedrig dosiertes UFH s.c. (z.B. 5.000 IE 2–3-mal täglich): 4–6 h Pause vor der Punktion, alternativ normale aPTT. Therapeutisches i.v.-UFH: 4–6 h Pause und normalisierte aPTT vor Punktion oder Katheterentfernung. Die nächste Heparingabe frühestens 1 h nach Punktion bzw. Katheterentfernung. Bei mehr als 4 Tagen Heparin vorher die Thrombozyten kontrollieren (HIT)." },
  { id: "fc-ll-241", module: "regional-schmerz", subtopic: "periphere-blockaden", guideline: "ASRA/ESRA-Leitlinie (Periphere Nervenblockaden & Antikoagulation)", front: "Was gilt laut ASRA/ESRA für Vitamin-K-Antagonisten vor neuraxialen oder tiefen Blockaden und bei der Katheterentfernung?", back: "Warfarin bzw. Phenprocoumon rechtzeitig absetzen (Warfarin ca. 5 Tage vorher, Phenprocoumon wegen längerer Halbwertszeit länger), bis die INR normalisiert ist. ESAIC/ESRA verlangt meist INR ≤ 1,4. Beginnt die VKA-Therapie bei liegendem Katheter, wird die INR täglich kontrolliert. Der Katheter wird bei INR < 1,5 entfernt, die neurologische Überwachung läuft danach weiter." },
  { id: "fc-ll-242", module: "notfall-reanimation", subtopic: "toxikologie-verbrennungen", guideline: "ISBI Practice Guidelines for Burn Care", front: "Wie sieht die empfohlene Erste Hilfe bei thermischen und chemischen Verbrennungen aus?", back: "Thermisch: brennende Kleidung und Schmuck entfernen, die Wunde möglichst sofort etwa 20 Minuten mit kühlem, fließendem Leitungswasser kühlen (Nutzen bis ca. 3 h nach dem Trauma). Kein Eis. Den Patienten dabei warm halten, weil bei Kindern und großflächigen Verbrennungen Unterkühlung droht. Danach sauber und locker abdecken, z.B. mit Frischhaltefolie. Chemisch: kontaminierte Kleidung entfernen, Trockensubstanzen abbürsten und lange und reichlich mit Wasser spülen (oft 20–60 min), Augen gesondert. Keine Neutralisationsversuche." },
  { id: "fc-ll-243", module: "notfall-reanimation", subtopic: "toxikologie-verbrennungen", guideline: "ISBI Practice Guidelines for Burn Care", front: "Wie wird die verbrannte Körperoberfläche (VKOF) abgeschätzt, und ab welcher Ausdehnung ist eine formale Flüssigkeitstherapie nötig?", back: "Beim Erwachsenen mit der Neunerregel, bei Kindern besser mit dem Lund-Browder-Schema. Bei kleinen oder verstreuten Arealen hilft die Handflächenregel (Handfläche mit Fingern des Patienten ≈ 1 %). Nur zweit- und drittgradige Areale zählen, reines Erythem nicht. Formale Flüssigkeitstherapie etwa ab 20 % VKOF beim Erwachsenen und ab ca. 10 % bei Kindern. Bei großen Verbrennungen kann nach der Frühphase Albumin erwogen werden, um das Volumen zu senken und die Diurese zu verbessern." },
  { id: "fc-ll-244", module: "notfall-reanimation", subtopic: "toxikologie-verbrennungen", guideline: "ISBI Practice Guidelines for Burn Care", front: "Was empfehlen die ISBI-Leitlinien zu Ernährungsbeginn und chirurgischer Wundversorgung bei schweren Verbrennungen?", back: "Bei schweren Verbrennungen möglichst früh enteral ernähren, innerhalb von 24 Stunden nach dem Trauma. Hintergrund ist der ausgeprägte Hypermetabolismus. Tiefe Verbrennungen früh exzidieren und decken (Spalthaut, Hautersatz). Das dämpft die katabole Reaktion, senkt Infektionen und Blutverlust und verkürzt den Krankenhausaufenthalt." },
  { id: "fc-ll-245", module: "notfall-reanimation", subtopic: "toxikologie-verbrennungen", guideline: "ISBI Practice Guidelines for Burn Care", front: "Welche Grundsätze gelten laut ISBI für Infektionsprophylaxe und -therapie bei Brandverletzten?", back: "Keine routinemäßige systemische Antibiotikaprophylaxe. Systemische Antibiotika nur bei klinisch oder mikrobiologisch gesicherter Infektion bzw. Sepsis, angepasst an lokale Resistenzen und Wundabstriche. Infektionen werden getrennt nach Wunde, Pneumonie, Harnweg und Sepsis betrachtet. Die Wunde wird topisch antimikrobiell versorgt (z.B. silberhaltige Auflagen). Tetanusschutz prüfen." },
  { id: "fc-ll-246", module: "notfall-reanimation", subtopic: "toxikologie-verbrennungen", guideline: "ISBI Practice Guidelines for Burn Care", front: "Welche Transfusions- und Temperaturstrategie wird bei großflächigen Verbrennungen empfohlen?", back: "Restriktive Erythrozytentransfusion mit Hb-Schwelle von etwa 7 g/dl, sofern keine aktive Blutung, Ischämie oder Instabilität vorliegt (TRIBE-Studie). Hypothermie konsequent vermeiden: Körperkerntemperatur ≥ 36 °C, beheizte Räume, warme Infusionen, bei Transport und Wundversorgung minimale Exposition." },
  { id: "fc-ll-247", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "5th Consensus Guideline PONV (Gan et al. 2025)", front: "Mit welchen Maßnahmen lässt sich laut 4. Konsensus-Leitlinie PONV (Gan 2020) das Basisrisiko für PONV senken?", back: "Wenn möglich Regionalanästhesie statt Allgemeinanästhesie. Propofol zur Einleitung und Aufrechterhaltung (TIVA) statt volatiler Anästhetika. Lachgas bei Eingriffen > 1 h vermeiden. Intra- und postoperative Opioide durch multimodale Analgesie minimieren. Adäquate Hydrierung. Sugammadex statt Neostigmin zur Antagonisierung ist mit weniger PONV assoziiert." },
  { id: "fc-ll-248", module: "pharmakologie", subtopic: "sonstige-pharmaka", guideline: "5th Consensus Guideline PONV (Gan et al. 2025)", front: "Welche Dosierungen und Zeitpunkte nennt die 4. PONV-Konsensus-Leitlinie für gängige Antiemetika zur Prophylaxe beim Erwachsenen?", back: "Zur Einleitung: Dexamethason 4–8 mg i.v., Palonosetron 0,075 mg i.v., Aprepitant 40 mg p.o., Amisulprid 5 mg i.v. Am OP-Ende: Ondansetron 4 mg i.v., Droperidol 0,625 mg i.v., Granisetron 0,35–1,5 mg i.v. Haloperidol 0,5–2 mg i.v./i.m. Scopolamin-Pflaster am Vorabend oder 2 h vor OP. Dimenhydrinat 1 mg/kg i.v." },
  { id: "fc-ll-249", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "5th Consensus Guideline PONV (Gan et al. 2025)", front: "Wie soll laut 4. PONV-Konsensus-Leitlinie PONV trotz Prophylaxe behandelt werden?", back: "Ein Antiemetikum aus einer anderen Wirkstoffklasse als in der Prophylaxe geben. 5-HT3-Antagonisten oder Butyrophenone nur wiederholen, wenn seit der ersten Gabe mehr als 6 h vergangen sind. Dexamethason, Scopolamin-Pflaster, Aprepitant und Palonosetron nicht wiederholen. Amisulprid 10 mg ist eine wirksame Rescue-Option, auch nach 5-HT3-Prophylaxe. Ohne vorherige Prophylaxe ist ein niedrig dosierter 5-HT3-Antagonist Mittel der Wahl." },
  { id: "fc-ll-250", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "5th Consensus Guideline PONV (Gan et al. 2025)", front: "Mit welchem Score wird laut 4. PONV-Konsensus-Leitlinie das Risiko für postoperatives Erbrechen (POV) bei Kindern eingeschätzt, und wie wird prophylaktisch behandelt?", back: "POVOC-Score (Eberhart) mit 4 Faktoren: OP-Dauer ≥ 30 min, Alter ≥ 3 Jahre, Strabismus-OP, POV bzw. PONV in der Eigen- oder Familienanamnese. Bei 0/1/2/3/4 Faktoren liegt das POV-Risiko bei ca. 9/10/30/55/70 %. Kinder mit mittlerem oder hohem Risiko erhalten eine Kombination aus 5-HT3-Antagonist und Dexamethason." },
  { id: "fc-ll-251", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "NICE NG193 (Chronischer Schmerz)", front: "Wie soll laut NICE NG193 die Beurteilung jeder Form chronischer Schmerzen erfolgen?", back: "Personenzentriert: Auswirkungen auf Alltag, Arbeit, Schlaf, Stimmung und soziale Beziehungen erfassen, ebenso Vorstellungen, Sorgen und Erwartungen des Patienten. Klären, ob chronisch primärer Schmerz, chronisch sekundärer Schmerz oder beides vorliegt. Gemeinsam einen Behandlungs- und Unterstützungsplan erstellen und regelmäßig überprüfen. Die Diagnose 'chronisch primärer Schmerz' kann gestellt werden, auch wenn keine zugrunde liegende Erkrankung den Schmerz erklärt." },
  { id: "fc-ll-252", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "NICE NG193 (Chronischer Schmerz)", front: "Unter welchen Bedingungen empfiehlt NICE NG193 Akupunktur bei chronisch primärem Schmerz, und welche physikalischen Verfahren sollen nicht angeboten werden?", back: "Akupunktur bzw. Dry Needling als einmalige Behandlungsserie, nur in einem kostengünstigen Setting mit höchstens ca. 5 Stunden Zeitaufwand der Behandler. TENS, therapeutischer Ultraschall und Interferenzstrom sollen nicht angeboten werden, da kein Nutzen belegt ist. Vorrang haben supervidierte Bewegungsprogramme in der Gruppe sowie ACT oder CBT." },
  { id: "fc-ll-253", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "NICE NG193 (Chronischer Schmerz)", front: "Welche Antidepressiva kommen laut NICE NG193 bei chronisch primärem Schmerz infrage, und für wen?", back: "Für Erwachsene ab 18 Jahren kann ein Antidepressivum erwogen werden: Amitriptylin, Citalopram, Duloxetin, Fluoxetin, Paroxetin oder Sertralin. Die Indikation besteht auch ohne begleitende Depression, weil es um Lebensqualität, Schmerz, Schlaf und psychischen Stress geht. Nutzen und Risiken werden vorher offen besprochen." },
  { id: "fc-ll-254", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "NICE NG193 (Chronischer Schmerz)", front: "Welche Medikamente und Injektionen sollen laut NICE NG193 bei chronisch primärem Schmerz nicht neu begonnen werden, und was gilt für Patienten, die sie bereits nehmen?", back: "Nicht neu beginnen: Antiepileptika einschließlich Gabapentinoiden, Antipsychotika, Benzodiazepine, Ketamin, Opioide, NSAR, Paracetamol sowie Triggerpunkt-Injektionen mit Kortikosteroid oder Lokalanästhetikum/Kortikosteroid. Lokalanästhetika topisch oder i.v. nur im Rahmen von Studien bei CRPS. Wer diese Mittel bereits nimmt: gemeinsam überprüfen, über Nutzen und Risiken aufklären und bei Absetzwunsch schrittweise und unterstützt ausschleichen, nicht abrupt absetzen." },
  { id: "fc-ll-255", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", guideline: "WHO Surgical Safety Checklist", front: "Welche Punkte werden im 'Sign In' der WHO Surgical Safety Checklist vor Narkoseeinleitung geprüft?", back: "Der Patient bestätigt Identität, OP-Ort, Eingriff und Einwilligung. OP-Gebiet markiert (bzw. nicht zutreffend). Anästhesie-Sicherheitscheck (Geräte, Medikamente) abgeschlossen. Pulsoxymeter angelegt und funktionsfähig. Bekannte Allergien? Schwieriger Atemweg oder Aspirationsrisiko, und sind Ausrüstung und Hilfe verfügbar? Risiko eines Blutverlusts > 500 ml (bei Kindern > 7 ml/kg), und sind zwei Zugänge bzw. ein zentraler Zugang und Volumen geplant?" },
  { id: "fc-ll-256", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", guideline: "WHO Surgical Safety Checklist", front: "Welche Punkte umfasst das 'Sign Out' der WHO Surgical Safety Checklist vor Verlassen des OP-Saals?", back: "Die Pflegekraft bestätigt mündlich mit dem Team: Name des durchgeführten Eingriffs, Vollständigkeit der Instrumenten-, Tupfer- und Nadelzählung, korrekte Beschriftung der Präparate (laut vorgelesen, inkl. Patientenname) und aufgetretene Geräteprobleme. Chirurg, Anästhesist und Pflege besprechen gemeinsam die wichtigsten Punkte für Aufwachphase und Weiterbehandlung." },
  { id: "fc-ll-257", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", guideline: "WHO Surgical Safety Checklist", front: "Welche Evidenz liegt der WHO Surgical Safety Checklist zugrunde, und wie soll sie implementiert werden?", back: "Pilotstudie von Haynes et al. (NEJM 2009) in 8 Krankenhäusern weltweit: Die Mortalität sank von 1,5 % auf 0,8 %, schwere Komplikationen von 11 % auf 7 %. Ein benannter Koordinator (meist die Springer-Pflegekraft) führt durch die Checkliste. Die Liste darf lokal angepasst und ergänzt werden, Sicherheitsschritte sollen aber nicht entfernt werden. Sie ist kein Ersatz für Teamkommunikation, sondern ein Werkzeug dafür, und sie ist Teil der WHO-Initiative 'Safe Surgery Saves Lives'." },
  { id: "fc-ll-258", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", guideline: "Helsinki-Deklaration (Patientensicherheit)", front: "Für welche Situationen fordert die Helsinki-Deklaration zur Patientensicherheit in der Anästhesiologie (2010) Protokolle bzw. SOPs in jeder Einrichtung?", back: "Präoperative Beurteilung und Vorbereitung, Geräte- und Medikamentencheck, Spritzenbeschriftung, schwierige bzw. misslungene Intubation, maligne Hyperthermie, Anaphylaxie, Lokalanästhetika-Intoxikation, Massivblutung, Infektionskontrolle sowie postoperative Versorgung einschließlich Schmerztherapie." },
  { id: "fc-ll-259", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", guideline: "Helsinki-Deklaration (Patientensicherheit)", front: "Welche strukturellen Anforderungen stellt die Helsinki-Deklaration neben SOPs an anästhesiologische Einrichtungen?", back: "Einhaltung der EBA-Mindeststandards für Monitoring im OP und im Aufwachraum. Einhaltung anerkannter anästhesiologischer Standards bei Sedierungen, auch außerhalb des OP. Unterstützung der WHO-Initiative 'Safe Surgery Saves Lives' inklusive Checkliste. Jährlicher Bericht zu Maßnahmen und Ergebnissen der Patientensicherheit, Erfassung der Daten zu Morbidität und Mortalität sowie Teilnahme an Audits und Zwischenfallmeldesystemen." },
  { id: "fc-ll-260", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", guideline: "Helsinki-Deklaration (Patientensicherheit)", front: "Wer hat die Helsinki-Deklaration zur Patientensicherheit in der Anästhesiologie 2010 unterzeichnet?", back: "European Board of Anaesthesiology (EBA/UEMS) und European Society of Anaesthesiology, unterstützt von WHO, WFSA und European Patients' Forum." },
  { id: "fc-ll-432", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", guideline: "Helsinki-Deklaration (Patientensicherheit)", front: "Was ist neu an der 'Helsinki-Deklaration 2.0' (Mai 2025)?", back: "Neue Schwerpunkte auf Einbindung der Patienten, Transparenz, adäquater Personalausstattung, Aus- und Weiterbildung, Technologie sowie einer Sicherheits- und Lernkultur im Umgang mit Fehlern. Sie unterstützt die WHO-WFSA International Standards for a Safe Practice of Anesthesia, den WHO Global Patient Safety Action Plan 2021–2030 und die WHO Patient Safety Rights Charter." },
  { id: "fc-ll-261", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "PROSPECT-Initiative (ESRA)", front: "Welche Basisanalgesie und welche Regionalverfahren empfiehlt die aktualisierte PROSPECT-Leitlinie für die Hüft-Totalendoprothese (Update 2025, Literatur 2020–2024)?", back: "Unverändert als Basis: Paracetamol plus NSAR/COX-2-Hemmer (prä-/intraoperativ begonnen, postoperativ fortgeführt) plus eine intraoperative Einzeldosis Dexamethason i.v. (≤10 mg). Bevorzugte Regionalverfahren: suprainguinale Fascia-iliaca-Blockade oder präoperative PENG-Blockade (motorisch schonend); ist keine Regionalanästhesie möglich, alternativ eine Single-Shot-Lokalinfiltrationsanalgesie (LIA). Niedrig dosiertes intrathekales Morphin (0,1 mg) kann bei Spinalanästhesie stationärer Patienten erwogen werden; systemische Opioide nur als Rescue. (Die Version 2021 empfahl Fascia-iliaca-Block/LIA noch nur bei Kontraindikationen gegen Basisanalgetika oder hohem erwartetem Schmerz.)" },
  { id: "fc-ll-262", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "PROSPECT-Initiative (ESRA)", front: "Welches Analgesiekonzept empfiehlt PROSPECT für die elektive Sectio caesarea, und wann kommen Wundinfiltration oder Faszienblöcke zum Einsatz?", back: "Basis: Paracetamol plus NSAR/COX-2-Hemmer und Dexamethason i.v. (nach Entwicklung des Kindes), kombiniert mit intrathekalem Morphin 50–100 µg (bzw. Diamorphin 300 µg) im Rahmen der Spinalanästhesie. Nur wenn KEIN intrathekales Opioid gegeben wurde, werden Single-Shot-Wundinfiltration, kontinuierliche Wundkatheter-Infusion und/oder Faszienblöcke (TAP-, Quadratus-lumborum-Block) empfohlen – zusätzlich zu intrathekalem Morphin ist ihr Zusatznutzen minimal." },
  { id: "fc-ll-263", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "PROSPECT-Initiative (ESRA)", front: "Welche Regionalverfahren empfiehlt PROSPECT (2022) für die videoassistierte Thorakoskopie (VATS), und welche Rolle spielt die thorakale Periduralanalgesie?", back: "Erste Wahl sind Paravertebralblockade (PVB) oder Erector-spinae-plane-Block (ESP), zweite Wahl der Serratus-anterior-plane-Block; dazu Paracetamol plus NSAR/COX-2-Hemmer prä-/intraoperativ und postoperativ fortgeführt. Die thorakale Periduralanalgesie wird für VATS ausdrücklich NICHT empfohlen (PVB/ESP bieten vergleichbare Analgesie mit weniger Nebenwirkungen/Invasivität). Intraoperatives Dexmedetomidin i.v. nur, wenn Basisanalgetika nicht gegeben werden können; Opioide als Rescue." },
  { id: "fc-ll-264", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "PROSPECT-Initiative (ESRA)", front: "Was empfiehlt PROSPECT (2020) zur Analgesie bei onkologischer Brustchirurgie, insbesondere bei ausgedehnten Eingriffen (z.B. Mastektomie mit Axilladissektion)?", back: "Basisanalgesie mit Paracetamol plus NSAR/COX-2-Hemmer und einer intraoperativen Einzeldosis Dexamethason i.v.; bei größerer Brustchirurgie zusätzlich eine ultraschallgesteuerte Paravertebralblockade (senkt Schmerzscores, Opioidbedarf und PONV, ggf. als Katheter fortführbar). Interfasziale Blöcke wie der PECS-Block gelten als Alternative zur Paravertebralblockade. Opioide nur als Rescue, wenn Nicht-Opioide und Regionalanalgesie nicht ausreichen." },
  { id: "fc-ll-265", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "PROSPECT-Initiative (ESRA)", front: "Welche Maßnahmen haben laut PROSPECT (2021) nach komplexer Wirbelsäulenchirurgie (z.B. instrumentierte thorakolumbale Spondylodese) gute Evidenz, und was wird nicht empfohlen?", back: "Gute Evidenz: Paracetamol plus NSAR/COX-2-Hemmer (prä-/intraoperativ begonnen, postoperativ fortgeführt), eine intraoperative i.v.-Ketamin-Infusion sowie eine Epiduralanalgesie mit Lokalanästhetikum (± Opioid). Für Wundinfiltration, intrathekale/epidurale Opioide, ESP- und TLIP-Block, i.v.-Lidocain und Dexmedetomidin war die prozedurspezifische Evidenz begrenzt; orale Gabapentinoide werden wegen relevanter Nebenwirkungen (Sedierung, Schwindel) nicht empfohlen." },
  { id: "fc-ll-266", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", guideline: "ESC-Leitlinie 2024 (Chronisches Koronarsyndrom)", front: "Welche DAPT-Dauer gilt laut ESC-Leitlinie 2024 als Standard nach elektiver PCI bei chronischem Koronarsyndrom ohne erhöhtes Blutungsrisiko?", back: "6 Monate duale Plättchenhemmung aus ASS (75–100 mg) plus Clopidogrel (75 mg), danach Übergang auf eine Einfach-Plättchenhemmung. Potente P2Y12-Hemmer (Prasugrel, Ticagrelor) sind bei elektiver PCI nur in ausgewählten Hochrisikosituationen eine Option. Bei weder hohem Blutungs- noch hohem Ischämierisiko kann eine Verkürzung auf 1–3 Monate erwogen werden (IIb). Anästhesiologisch relevant: Elektive Eingriffe, die ein Absetzen des P2Y12-Hemmers erfordern, möglichst erst nach Abschluss der DAPT planen." },
  { id: "fc-ll-267", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", guideline: "ESC-Leitlinie 2024 (Chronisches Koronarsyndrom)", front: "Welche Langzeit-Einfach-Plättchenhemmung empfiehlt die ESC-Leitlinie 2024 nach Myokardinfarkt oder PCI im Anschluss an die DAPT-Phase?", back: "Lebenslang ASS 75–100 mg täglich; alternativ ist Clopidogrel 75 mg täglich als sichere und wirksame Alternative zu ASS empfohlen (Klasse I, Evidenzgrad A) – eine Aufwertung gegenüber früheren Leitlinien. Die Einfach-Plättchenhemmung wird perioperativ bei den meisten nicht-kardialen Eingriffen fortgeführt." },
  { id: "fc-ll-268", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", guideline: "ESC-Leitlinie 2024 (Chronisches Koronarsyndrom)", front: "Welche antiinflammatorische Therapie empfiehlt die ESC-Leitlinie 2024 zur Sekundärprävention beim chronischen Koronarsyndrom, in welcher Dosis und mit welchem Empfehlungsgrad?", back: "Colchicin 0,5 mg einmal täglich (Klasse IIa, Evidenzgrad A) bei atherosklerotischer KHK zur Senkung von Myokardinfarkt, Schlaganfall und Revaskularisationsbedarf – gestützt auf Studien wie LoDoCo2, die eine Reduktion schwerer kardiovaskulärer Ereignisse zeigten." },
  { id: "fc-ll-269", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", guideline: "ESC-Leitlinie 2024 (Chronisches Koronarsyndrom)", front: "Wie hat die ESC-Leitlinie 2024 die antianginöse Therapie beim chronischen Koronarsyndrom neu geordnet?", back: "Die starre Einteilung in First-line- und Second-line-Antianginosa wurde aufgegeben; die Auswahl erfolgt individuell nach Hämodynamik (Herzfrequenz, Blutdruck), Komorbiditäten, Begleitmedikation und Ischämiemechanismus. Begonnen wird in der Regel mit einem Betablocker und/oder Kalziumkanalblocker; kurz wirksame Nitrate zur akuten Anfallskupierung; Ranolazin, Ivabradin, Nicorandil, Trimetazidin oder lang wirksame Nitrate als Ergänzung. Antianginosa verbessern nur Symptome – prognoseverbessernd sind Lebensstil, Plättchenhemmung, Statine und (bei Indikation) RAAS-Hemmer." },
  { id: "fc-ll-270", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", guideline: "ESC-Leitlinie 2024 (Chronisches Koronarsyndrom)", front: "Wie wird laut ESC-Leitlinie 2024 die antithrombotische Therapie nach PCI bei Patienten mit chronischem Koronarsyndrom und Vorhofflimmern (OAK-Indikation) gestaltet?", back: "Triple-Therapie (OAK + ASS + Clopidogrel) nur kurz, meist bis 1 Woche nach PCI (bei hohem Stentthromboserisiko bis 1 Monat); danach duale Therapie aus OAK (DOAK bevorzugt gegenüber VKA) plus Clopidogrel für maximal 12 Monate, anschließend OAK-Monotherapie ohne Plättchenhemmer." },
  { id: "fc-ll-271", module: "spezielle-anaesthesie", subtopic: "hno-augen-ambulant", guideline: "Aldrete-Score/PADSS (Entlasskriterien)", front: "Worin unterscheidet sich der modifizierte Aldrete-Score (1995) vom ursprünglichen Aldrete-Score (1970)?", back: "Im Original-Score wurde die Oxygenierung klinisch über die Hautfarbe (rosig, blass/fleckig, zyanotisch) beurteilt; im modifizierten Score wurde dieses Kriterium durch die pulsoxymetrische Sättigung (SpO2) ersetzt, da die Hautfarbe eine Hypoxämie nur unzuverlässig anzeigt. Die übrigen Kategorien (Aktivität, Atmung, Kreislauf, Bewusstsein) und die Maximalpunktzahl von 10 blieben erhalten." },
  { id: "fc-ll-272", module: "spezielle-anaesthesie", subtopic: "hno-augen-ambulant", guideline: "Aldrete-Score/PADSS (Entlasskriterien)", front: "Welche fünf Kriterien bewertet der modifizierte PADSS (Chung 1995), und welche früheren Pflichtkriterien entfielen dabei?", back: "Vitalzeichen (Blutdruck/Puls im Vergleich zum Ausgangswert), Aktivität/Mobilisation, Übelkeit/Erbrechen, Schmerz und chirurgische Blutung – je 0–2 Punkte, maximal 10; ab ≥9 Punkten gilt der Patient als 'home-ready'. Gestrichen wurden die Pflichtkriterien orale Flüssigkeitsaufnahme und Spontanmiktion, weil sie die Entlassung verzögerten, ohne die Sicherheit zu erhöhen." },
  { id: "fc-ll-273", module: "spezielle-anaesthesie", subtopic: "hno-augen-ambulant", guideline: "Aldrete-Score/PADSS (Entlasskriterien)", front: "Muss ein Patient nach ambulanter Anästhesie vor der Entlassung routinemäßig Wasser gelassen oder getrunken haben?", back: "Nein – beides ist kein routinemäßiges Entlasskriterium. Eine nachgewiesene Spontanmiktion ist nur bei erhöhtem Risiko für einen Harnverhalt zu fordern, z.B. nach rückenmarksnaher Anästhesie (v.a. mit lang wirksamen Lokalanästhetika), nach Hernien-, anorektalen oder urogenitalen Eingriffen oder bei anamnestischem Harnverhalt. Trinken wird nicht erzwungen, da dies eher Übelkeit/Erbrechen provozieren kann." },
  { id: "fc-ll-274", module: "spezielle-anaesthesie", subtopic: "hno-augen-ambulant", guideline: "Aldrete-Score/PADSS (Entlasskriterien)", front: "Was ist der Fast-Track-Score nach White und Song, und ab welchem Wert darf die Phase-I-Aufwachraumüberwachung übersprungen werden?", back: "Eine Erweiterung des modifizierten Aldrete-Scores um die Kategorien Schmerz und Übelkeit/Erbrechen (7 Kategorien, je 0–2 Punkte, maximal 14). Bei ≥12 Punkten und keiner Kategorie mit 0 Punkten kann der Patient direkt aus dem OP in den Phase-II-Bereich (ambulante Nachbeobachtung) verlegt werden ('Fast-Tracking' unter Umgehung der Phase-I-PACU)." },
  { id: "fc-ll-275", module: "spezielle-anaesthesie", subtopic: "hno-augen-ambulant", guideline: "Aldrete-Score/PADSS (Entlasskriterien)", front: "Welche Verhaltensanweisungen erhält ein Patient bei Entlassung nach ambulanter Allgemeinanästhesie oder Sedierung?", back: "Schriftliche und mündliche Instruktionen inkl. Notfall-Kontaktnummer und Analgesieplan; für ca. 24 Stunden kein Führen eines Fahrzeugs, keine Bedienung gefährlicher Maschinen, kein Alkohol und keine rechtlich bindenden oder wichtigen Entscheidungen; Heimweg in Begleitung einer verantwortlichen erwachsenen Person, die idealerweise auch in der ersten Nacht anwesend ist." },
  { id: "fc-ll-276", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", guideline: "AORN-Konsensus (Tourniquet)", front: "Welcher Sicherheitszuschlag wird laut AORN beim Erwachsenen auf den gemessenen Limb Occlusion Pressure (LOP) addiert, um den Manschettendruck festzulegen?", back: "+40 mmHg bei einem LOP ≤130 mmHg, +60 mmHg bei einem LOP von 131–190 mmHg und +80 mmHg bei einem LOP >190 mmHg. Der so individuell bestimmte Druck liegt meist deutlich unter pauschalen Standarddrücken (z.B. 250/300 mmHg) und senkt das Risiko für Nerven-, Muskel- und Hautschäden." },
  { id: "fc-ll-277", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", guideline: "AORN-Konsensus (Tourniquet)", front: "Nach welchen Kriterien wird die Tourniquet-Manschette ausgewählt und platziert?", back: "Die breitestmögliche Manschette, die das OP-Feld nicht behindert, da breite Manschetten den Blutfluss bereits bei niedrigerem Druck unterbrechen; an konisch geformten Extremitäten (z.B. adipöser Oberschenkel) konturierte Manschetten. Platzierung am Ort des größten Extremitätenumfangs, faltenfrei, mit passender Überlappung, nicht über Knochenvorsprüngen oder oberflächlich verlaufenden Nerven (z.B. N. ulnaris am Ellenbogen, N. peroneus am Fibulaköpfchen)." },
  { id: "fc-ll-278", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", guideline: "AORN-Konsensus (Tourniquet)", front: "Welche systemischen Veränderungen treten typischerweise nach dem Öffnen eines Tourniquets auf, und was gilt bei beidseitigen Tourniquets?", back: "Einstrom hyperkapnischen, sauren und kalten Blutes aus der ischämischen Extremität: Anstieg von etCO2/PaCO2, leichter Anstieg von Kalium (ca. 0,3 mmol/l) und Laktat (Spitze ca. 3 Minuten nach Öffnen), metabolische Azidose, Abfall von MAP und ZVD (reaktive Hyperämie, Umverteilung) sowie Abfall der Kerntemperatur. Bei beidseitigen Tourniquets sollte die Öffnung zeitversetzt (ca. 30–45 Minuten) erfolgen, um kumulative hämodynamische und metabolische Effekte zu vermeiden." },
  { id: "fc-ll-279", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", guideline: "AORN-Konsensus (Tourniquet)", front: "Bei welchen Patienten bzw. Extremitätenbefunden ist ein Tourniquet (relativ) kontraindiziert oder nur mit besonderer Vorsicht einzusetzen?", back: "Schwere periphere arterielle Verschlusskrankheit, vorbestehender Gefäßbypass/Gefäßrekonstruktion an der Extremität, tiefe Venenthrombose, Quetsch-/Crush-Verletzungen oder drohendes Kompartmentsyndrom, schwere Infektionen sowie Sichelzellerkrankung (relative Kontraindikation – bei Einsatz strikt Hypoxie, Azidose, Hypothermie und Dehydratation vermeiden)." },
  { id: "fc-ll-280", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", guideline: "AORN-Konsensus (Tourniquet)", front: "Wann muss die perioperative Antibiotikaprophylaxe bei Eingriffen in Blutleere gegeben werden, und was ist zur Tourniquet-Anwendung zu dokumentieren?", back: "Die Antibiotikaprophylaxe muss vollständig VOR dem Aufblasen der Manschette infundiert sein (in der Regel mindestens ca. 5 Minuten vorher), damit ausreichende Gewebespiegel im Operationsgebiet erreicht werden. Dokumentiert werden u.a. Lokalisation und Typ der Manschette, gewählter Druck (inkl. LOP), Inflations- und Deflationszeiten, Hautzustand unter der Manschette vor und nach Anwendung sowie die verantwortliche Person; die Ischämiezeit wird dem Operateur in regelmäßigen Abständen mitgeteilt." },
  { id: "fc-ll-281", module: "spezielle-anaesthesie", subtopic: "transplantationsanaesthesie", guideline: "Aggarwal-Kriterien (Postreperfusionssyndrom)", front: "Wie unterscheidet die Klassifikation nach Hilmi (2008) ein mildes von einem signifikanten Postreperfusionssyndrom?", back: "Mild: Abfall von MAP und/oder Herzfrequenz um ≤30% des Ausgangswerts, Dauer ≤5 Minuten, Ansprechen auf Bolusgaben von Calciumchlorid (1 g) und/oder Adrenalin (≤100 µg) ohne Notwendigkeit einer Vasopressor-Dauerinfusion. Signifikant: Abfall >30%, Asystolie oder hämodynamisch relevante Arrhythmien, Notwendigkeit einer intra- und postoperativ fortgeführten Vasopressorinfusion oder eine anhaltende (>30 min) bzw. rezidivierende Fibrinolyse mit Bedarf an Antifibrinolytika." },
  { id: "fc-ll-282", module: "spezielle-anaesthesie", subtopic: "transplantationsanaesthesie", guideline: "Aggarwal-Kriterien (Postreperfusionssyndrom)", front: "Welche hämodynamischen und hämostaseologischen Veränderungen begleiten typischerweise ein Postreperfusionssyndrom über den MAP-Abfall hinaus?", back: "Abfall des systemischen Gefäßwiderstands (Vasoplegie), Bradykardie und Arrhythmien bis zur Asystolie, Anstieg von pulmonalarteriellem Druck und ZVD (rechtsventrikuläre Belastung) sowie eine Hyperfibrinolyse durch Freisetzung von t-PA aus dem Transplantat; begleitet von Hyperkaliämie, Azidose und Temperaturabfall." },
  { id: "fc-ll-283", module: "spezielle-anaesthesie", subtopic: "transplantationsanaesthesie", guideline: "Aggarwal-Kriterien (Postreperfusionssyndrom)", front: "Welche prognostische Bedeutung hat ein Postreperfusionssyndrom nach Lebertransplantation?", back: "Ein PRS ist mit einer frühen Transplantatdysfunktion, postoperativem akuten Nierenversagen, höherem Transfusionsbedarf (v.a. bei schwerer Fibrinolyse), systemischer Inflammation sowie erhöhter Mortalität assoziiert – daher ist die konsequente Prävention und rasche Therapie klinisch relevant." },
  { id: "fc-ll-284", module: "spezielle-anaesthesie", subtopic: "transplantationsanaesthesie", guideline: "Aggarwal-Kriterien (Postreperfusionssyndrom)", front: "Welche medikamentösen Sofortmaßnahmen stehen beim akuten Postreperfusionssyndrom im Vordergrund?", back: "Titrierte kleine Adrenalin-Boli (z.B. 10–20 µg, wiederholt; bis ca. 100 µg) und Calciumchlorid (ca. 1 g) gegen Hypotonie, Bradykardie und Hyperkaliämie-Effekte, Natriumbicarbonat bei ausgeprägter Azidose, Behandlung der Hyperkaliämie (z.B. Insulin-Glukose), bei Bedarf Vasopressor-Dauerinfusion (Noradrenalin, Vasopressin); bei therapierefraktärer Vasoplegie wird Methylenblau als Rescue beschrieben. Eine Hyperfibrinolyse wird nach viskoelastischem Befund antifibrinolytisch behandelt." },
  { id: "fc-ll-285", module: "spezielle-anaesthesie", subtopic: "transplantationsanaesthesie", guideline: "Aggarwal-Kriterien (Postreperfusionssyndrom)", front: "Welche Parameter sollten vor der Reperfusion der Spenderleber optimiert werden, um ein Postreperfusionssyndrom abzuschwächen?", back: "Kalium im niedrig-normalen Bereich (meist Ziel <4–4,5 mmol/l), normales ionisiertes Calcium, Korrektur der metabolischen Azidose, Normothermie, adäquater (nicht überladener) Volumenstatus sowie Absprache mit dem Chirurgen vor Freigabe; präemptive Gaben von Adrenalin oder Phenylephrin können die PRS-Inzidenz senken. Moderne Organkonservierung (Maschinenperfusion) ist mit weniger PRS assoziiert." },
  { id: "fc-ll-286", module: "spezielle-anaesthesie", subtopic: "transplantationsanaesthesie", guideline: "Konsensus Organspender-Anästhesie (DBD)", front: "Was versteht man beim Eintritt des Hirntods unter dem 'Katecholaminsturm', und wie wird er behandelt?", back: "Eine kurzdauernde (meist Minuten bis ca. 30 min) massive Sympathikusaktivierung bei Hirnstammeinklemmung mit Hypertonie, Tachykardie, Arrhythmien, Vasokonstriktion, möglicher Myokardschädigung und neurogenem Lungenödem. Wenn überhaupt, wird er mit kurz wirksamen Substanzen (z.B. Esmolol, Nitroglycerin, Clevidipin/Nitroprussid) behandelt, da regelhaft eine Phase mit Verlust des Sympathikotonus, Vasodilatation und Hypotonie folgt." },
  { id: "fc-ll-287", module: "spezielle-anaesthesie", subtopic: "transplantationsanaesthesie", guideline: "Konsensus Organspender-Anästhesie (DBD)", front: "Wie wird ein zentraler Diabetes insipidus beim hirntoten Organspender diagnostiziert und behandelt?", back: "Diagnose: Polyurie (>3 ml/kg/h beim Erwachsenen) mit niedriger Urinosmolalität bei steigendem Serumnatrium (>145 mmol/l), nach Ausschluss anderer Ursachen (osmotische Diurese bei Hyperglykämie, Mannitol, Diuretika). Therapie: Desmopressin intermittierend i.v. (v.a. bei geringem Vasopressorbedarf) oder Vasopressin-Dauerinfusion (bei zusätzlicher Hypotonie), Ersatz des freien Wasserverlusts mit hypotonen Lösungen; Natrium möglichst im Bereich von ca. 135–150 mmol/l halten, da eine Hypernatriämie v.a. die Leber- und Nierentransplantatfunktion verschlechtern kann." },
  { id: "fc-ll-288", module: "spezielle-anaesthesie", subtopic: "transplantationsanaesthesie", guideline: "Konsensus Organspender-Anästhesie (DBD)", front: "Welche Zielwerte ('Donor Management Goals') werden neben dem MAP für den hirntoten Organspender typischerweise angestrebt?", back: "Diurese ca. 0,5–3 ml/kg/h (meist ≥1 ml/kg/h), Serumnatrium ca. 135–150 mmol/l, Blutzucker ≤180 mg/dl (ca. 10 mmol/l) mittels Insulininfusion, Hb ≥7 g/dl, Normovolämie ohne Volumenüberladung (Lungenschutz), LVEF möglichst ≥45% sowie Normothermie und lungenprotektive Beatmung mit guter Oxygenierung (z.B. PaO2/FiO2 >300)." },
  { id: "fc-ll-289", module: "spezielle-anaesthesie", subtopic: "transplantationsanaesthesie", guideline: "Konsensus Organspender-Anästhesie (DBD)", front: "Welche Aufgaben hat die Anästhesie bei der Organentnahme unmittelbar vor und nach dem Abklemmen der Aorta?", back: "Vor dem Aortenklemmen: hochdosierte Heparingabe nach Absprache mit dem Entnahmeteam (typischerweise ca. 300 IE/kg bzw. 20.000–30.000 IE) wenige Minuten vor Kanülierung/Perfusion; Aufrechterhaltung der Organperfusion und Relaxierung. Mit dem Abklemmen der Aorta und Beginn der kalten Perfusion endet die kreislaufunterstützende Therapie (Vasopressoren und Monitoring werden beendet); bei Lungenentnahme wird die Beatmung nach Vorgabe des Teams fortgesetzt und die Lunge vor dem Absetzen der Trachea in moderater Inflation gehalten." },
  { id: "fc-ll-290", module: "spezielle-anaesthesie", subtopic: "transplantationsanaesthesie", guideline: "Konsensus Organspender-Anästhesie (DBD)", front: "Warum neigen hirntote Organspender zu Hypothermie und Gerinnungsstörungen, und wie wird darauf reagiert?", back: "Durch den Ausfall der hypothalamischen Thermoregulation (Poikilothermie) und die Vasodilatation kühlen Spender rasch aus; die Freisetzung von Gewebsthromboplastin aus nekrotischem Hirngewebe kann eine Verbrauchskoagulopathie (DIC) auslösen, verstärkt durch Hypothermie. Maßnahmen: aktive Wärmung (Wärmedecken, gewärmte Infusionen), gezielte, befundorientierte Substitution von Blutprodukten/Gerinnungsfaktoren und Erythrozyten erst unter Hb ca. 7 g/dl." },
  { id: "fc-ll-291", module: "pharmakologie", subtopic: "sonstige-pharmaka", guideline: "EHRA Practical Guide (DOAK perioperativ)", front: "Wie lange vor einem elektiven Eingriff soll Dabigatran laut EHRA Practical Guide abhängig von der Kreatinin-Clearance pausiert werden?", back: "CrCl ≥80 ml/min: ≥24 h (niedriges) bzw. ≥48 h (hohes Blutungsrisiko); CrCl 50–79 ml/min: ≥36 h bzw. ≥72 h; CrCl 30–49 ml/min: ≥48 h bzw. ≥96 h. Bei CrCl <30 ml/min ist Dabigatran nicht indiziert. Die starke renale Elimination (ca. 80%) erklärt die deutliche Abhängigkeit von der Nierenfunktion." },
  { id: "fc-ll-292", module: "pharmakologie", subtopic: "sonstige-pharmaka", guideline: "EHRA Practical Guide (DOAK perioperativ)", front: "Welche präoperativen Pausen gelten laut EHRA Practical Guide für die Faktor-Xa-Inhibitoren (Apixaban, Edoxaban, Rivaroxaban) bei eingeschränkter Nierenfunktion?", back: "Bei CrCl ≥30 ml/min: ≥24 h (niedriges) bzw. ≥48 h (hohes Blutungsrisiko). Bei CrCl 15–29 ml/min: ≥36 h vor Eingriffen mit niedrigem und ≥48 h vor Eingriffen mit hohem Blutungsrisiko. Anders als bei Dabigatran ist die Abhängigkeit von der Nierenfunktion wegen des geringeren renalen Anteils weniger ausgeprägt." },
  { id: "fc-ll-293", module: "pharmakologie", subtopic: "sonstige-pharmaka", guideline: "EHRA Practical Guide (DOAK perioperativ)", front: "Wie wird laut EHRA Practical Guide bei Eingriffen mit nur minimalem Blutungsrisiko (z.B. Extraktion von 1–3 Zähnen, Katarakt-OP, diagnostische Endoskopie ohne Biopsie, kleine Hauteingriffe) mit der DOAK-Therapie verfahren?", back: "Keine echte Pause erforderlich: Der Eingriff wird im Talspiegel durchgeführt, also ca. 12 h (zweimal tägliche Gabe) bzw. 24 h (einmal tägliche Gabe) nach der letzten Einnahme – ggf. durch Auslassen einer einzigen Dosis; kein Bridging. Die nächste Dosis kann bei gesicherter Hämostase meist am selben Tag (frühestens ca. 6 h nach dem Eingriff) oder am Folgetag gegeben werden." },
  { id: "fc-ll-294", module: "pharmakologie", subtopic: "sonstige-pharmaka", guideline: "EHRA Practical Guide (DOAK perioperativ)", front: "Wie wird bei einem dringlichen (nicht sofort lebensrettenden) Eingriff unter DOAK vorgegangen, und welche Plasmaspiegel dienen als Orientierung?", back: "Wenn klinisch vertretbar, den Eingriff aufschieben, bis mindestens 12 h, idealerweise 24 h seit der letzten Einnahme vergangen sind; Zeitpunkt der letzten Dosis und Nierenfunktion erfragen/bestimmen. Ist ein spezifischer DOAK-Spiegel verfügbar, gilt nach ISTH-Konsens ≤30 ng/ml als unbedenklich für die Operation; bei dringlichem Hochrisiko-Eingriff und Spiegel >30 ng/ml (bei Blutung >50 ng/ml) ist eine Antagonisierung zu erwägen." },
  { id: "fc-ll-295", module: "pharmakologie", subtopic: "sonstige-pharmaka", guideline: "EHRA Practical Guide (DOAK perioperativ)", front: "Welche unspezifischen Maßnahmen empfiehlt der EHRA Practical Guide bei relevanter, aber nicht lebensbedrohlicher Blutung unter DOAK?", back: "Nächste Dosis auslassen/pausieren, mechanische Kompression bzw. chirurgische/endoskopische Blutstillung, Volumen- und Transfusionstherapie, Erhalt der Diurese, Tranexamsäure erwägen; Aktivkohle bei sehr kurz zurückliegender Einnahme (v.a. ≤2 h, z.B. Überdosis). Dabigatran ist wegen geringer Plasmaeiweißbindung dialysierbar (Hämodialyse als Option, v.a. bei Niereninsuffizienz), die stark eiweißgebundenen Faktor-Xa-Inhibitoren dagegen kaum." },
  { id: "fc-ll-296", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", guideline: "DAS-Extubationsleitlinien (2012)", front: "Welche Risikofaktoren werden laut DAS-Extubationsleitlinien in Schritt 1 ('Plan') erfasst?", back: "Atemwegsrisiken (bekannt schwieriger Atemweg bei Intubation, eingeschränkter Zugang z.B. Halofixateur/Kieferfixation, Verschlechterung des Atemwegs durch Ödem, Blutung, Trauma oder Operation) und allgemeine Risiken (kardiovaskulär, respiratorisch, neurologisch, metabolisch, Aspirationsrisiko, besondere chirurgische Anforderungen)." },
  { id: "fc-ll-433", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", guideline: "DAS-Extubationsleitlinien (2012)", front: "Was umfasst Schritt 2 ('Prepare') der DAS-Extubationsleitlinien?", back: "Optimierung des Patienten (vollständige Reversierung der Relaxierung, Normothermie, Hämodynamik, Säure-Basen-/Elektrolythaushalt, Analgesie) und der Logistik (Zeitpunkt, Ausrüstung, erfahrenes Personal, Kommunikation mit dem Team)." },
  { id: "fc-ll-297", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", guideline: "DAS-Extubationsleitlinien (2012)", front: "Welche Schritte umfasst die 'Low-Risk'-Wachextubation nach DAS?", back: "Präoxygenierung mit FiO2 1,0; Absaugen (bei Bedarf unter Sicht); Beißschutz einlegen (verhindert Tubusokklusion durch Zubeißen und ein Unterdrucklungenödem); geeignete Lagerung (meist Oberkörperhochlagerung); vollständige Reversierung der Relaxierung und regelmäßige, suffiziente Spontanatmung; Patient wach und befolgt Aufforderungen; Kopf-/Halsbewegungen minimieren; unter positivem Beatmungsdruck (Blähmanöver) Cuff entblocken und Tubus entfernen; anschließend O2 über Maske, Atemwegsdurchgängigkeit prüfen und O2-Gabe im Aufwachraum fortsetzen." },
  { id: "fc-ll-298", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", guideline: "DAS-Extubationsleitlinien (2012)", front: "Was gilt laut DAS-Extubationsleitlinien für die Extubation in tiefer Narkose ('deep extubation')?", back: "Eine fortgeschrittene Technik, die nur bei Low-Risk-Patienten mit unkompliziertem Atemweg, problemloser Maskenbeatmung und ohne Aspirationsrisiko eingesetzt werden soll, und nur durch damit erfahrene Anästhesisten. Vorteil: weniger Husten und hämodynamische Reaktionen; Nachteil: Risiko von Atemwegsobstruktion und Hypoventilation bis zum Erwachen – daher bei At-Risk-Atemweg ungeeignet." },
  { id: "fc-ll-299", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", guideline: "DAS-Extubationsleitlinien (2012)", front: "Was ist die 'Remifentanil-Technik' im At-Risk-Algorithmus der DAS-Extubationsleitlinien, und wann ist sie sinnvoll?", back: "Die Hypnotika (Volatile/Propofol) werden beendet, während eine niedrig dosierte Remifentanil-Infusion fortgeführt wird; der Patient erwacht, toleriert den Tubus, befolgt Aufforderungen und wird ohne relevanten Husten extubiert. Sinnvoll, wenn Husten, Pressen und Kreislaufreaktionen vermieden werden sollen (z.B. Neurochirurgie, Kiefer-/Gesichts- und plastische Chirurgie, schwere kardiale Vorerkrankung); Risiko: opioidbedingte Atemdepression – daher sorgfältige Titration und Überwachung." },
  { id: "fc-ll-300", module: "allgemeinanaesthesie", subtopic: "atemwegsmanagement", guideline: "DAS-Extubationsleitlinien (2012)", front: "Welche Optionen sehen die DAS-Extubationsleitlinien vor, wenn eine Extubation wegen Atemwegsschwellung zu riskant erscheint?", back: "Aufschieben der Extubation (Nachbeatmung, z.B. auf der Intensivstation) oder eine elektive Tracheotomie bei voraussichtlich länger bestehender Atemwegsbeeinträchtigung. Bei Risiko eines Larynxödems können Kortikosteroide gegeben werden, die idealerweise frühzeitig (ca. 12 h vor Extubation) begonnen werden; ein fehlendes Cuff-Leak ist ein Warnzeichen, aber kein sicherer Prädiktor. Nach At-Risk-Extubation: Überwachung in einer geeigneten Einheit mit geschultem Personal, O2-Gabe, Oberkörperhochlagerung und klare Übergabe." },
  { id: "fc-ll-301", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", guideline: "AABB International Guidelines 2023 (Transfusion)", front: "Welchen Transfusionstrigger empfehlen die AABB International Guidelines 2023 für kritisch kranke, hämodynamisch stabile Kinder?", back: "Eine restriktive Strategie mit Transfusion erst bei Hb <7 g/dl (starke Empfehlung, moderate Evidenz) – gilt für kritisch kranke bzw. gefährdete Kinder ohne Hämoglobinopathie, ohne zyanotischen Herzfehler und ohne schwere Hypoxämie." },
  { id: "fc-ll-302", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", guideline: "AABB International Guidelines 2023 (Transfusion)", front: "Welche Hb-Schwellen schlagen die AABB International Guidelines 2023 für hämodynamisch stabile Kinder mit angeborenem Herzfehler vor?", back: "Abhängig von Anatomie und Korrekturstadium: 7 g/dl nach biventrikulärer Korrektur, 9 g/dl bei univentrikulärer Palliation (Einkammerherz) und 7–9 g/dl bei noch nicht korrigiertem Herzfehler (bedingte Empfehlung, niedrige Evidenz)." },
  { id: "fc-ll-303", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", guideline: "AABB International Guidelines 2023 (Transfusion)", front: "Welche Transfusionsstrategie empfehlen die AABB International Guidelines 2023 für hospitalisierte Erwachsene mit hämatologischen oder onkologischen Erkrankungen?", back: "Ebenfalls eine restriktive Strategie mit Erwägung der Transfusion bei Hb <7 g/dl (bedingte Empfehlung, niedrige Evidenz) – analog zu anderen hospitalisierten, hämodynamisch stabilen Erwachsenen." },
  { id: "fc-ll-304", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", guideline: "AABB International Guidelines 2023 (Transfusion); AABB-Leitlinie akuter Myokardinfarkt 2025", front: "Für welche Patientengruppen gelten die restriktiven Hb-Schwellen der AABB International Guidelines 2023 ausdrücklich NICHT?", back: "Für Patienten mit akutem Koronarsyndrom (die MINT-Studie 2023 deutete auf einen möglichen Nutzen einer liberaleren Strategie hin) – NEU (AABB-Leitlinie 2025 speziell zu akutem Myokardinfarkt): explizite bedingte Empfehlung für eine LIBERALE Transfusionsstrategie mit Hb-Trigger <10 g/dl bei hospitalisierten Patienten mit akutem MI, statt der früheren 'erheblichen Unsicherheit'; außerdem gelten die restriktiven Schwellen nicht bei schwerer Thrombozytopenie sowie bei chronisch transfusionsabhängiger Anämie (z.B. Hämoglobinopathien, MDS)." },
  { id: "fc-ll-305", module: "periop-sicherheit-ethik", subtopic: "gerinnung-transfusion", guideline: "AABB International Guidelines 2023 (Transfusion)", front: "Wie ist ein 'restriktiver Hb-Trigger' der AABB-Leitlinie 2023 in der Praxis zu interpretieren?", back: "Als Schwelle, unterhalb derer eine Transfusion ERWOGEN wird – nicht als automatische Transfusionsanordnung. Die Entscheidung berücksichtigt zusätzlich Symptome, laufende Blutung, Hämodynamik, Komorbiditäten und Patientenpräferenzen. Restriktive Strategien reduzieren die Transfusionsexposition deutlich (um etwa 40%), ohne die 30-Tage-Mortalität oder Morbidität zu erhöhen." },
  { id: "fc-ll-306", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", guideline: "WHO/WOMAN-Trial (Tranexamsäure bei PPH)", front: "Welche Hauptergebnisse lieferte der WOMAN-Trial (2017, ca. 20.000 Frauen mit PPH) zur Tranexamsäure?", back: "Signifikante Senkung der blutungsbedingten Mortalität (ca. 1,5% vs. 1,9%, RR ca. 0,81), besonders deutlich bei Gabe innerhalb von 3 h nach Geburt (ca. 1,2% vs. 1,7%, RR ca. 0,69), sowie weniger Laparotomien zur Blutstillung. KEINE Reduktion der Hysterektomierate und der Gesamtmortalität; kein Anstieg thromboembolischer Ereignisse." },
  { id: "fc-ll-307", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", guideline: "WHO/WOMAN-Trial (Tranexamsäure bei PPH)", front: "Warum betont die WHO den möglichst frühen Beginn der Tranexamsäure bei PPH, und was gilt nach mehr als 3 Stunden?", back: "Der Nutzen ist stark zeitabhängig: In gepoolten Daten (WOMAN und CRASH-2) nimmt der Überlebensvorteil mit jeder 15-minütigen Verzögerung um etwa 10% ab; nach 3 Stunden ist kein Nutzen mehr nachweisbar. Die WHO empfiehlt daher die Gabe sofort nach Diagnose und rät von einem Therapiebeginn später als 3 h nach der Geburt ab." },
  { id: "fc-ll-308", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", guideline: "WHO/WOMAN-Trial (Tranexamsäure bei PPH)", front: "Bei welchen PPH-Ursachen empfiehlt die WHO Tranexamsäure, und was zeigte der WOMAN-2-Trial zur prophylaktischen Gabe?", back: "Tranexamsäure i.v. wird bei jeder klinisch diagnostizierten PPH empfohlen – unabhängig von Ursache (Atonie, Geburtsverletzung, Plazentareste) und Geburtsmodus – als Ergänzung zur Standardtherapie, nicht als Ersatz für Uterotonika. Im WOMAN-2-Trial (2024; Frauen mit Hb <10 g/dl, vaginale Geburt) senkte eine prophylaktische Gabe nach Abnabelung die PPH-Rate nicht – eine routinemäßige Prophylaxe ist dadurch nicht gestützt." },
  { id: "fc-ll-309", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", guideline: "WHO/WOMAN-Trial (Tranexamsäure bei PPH)", front: "Wie definiert die konsolidierte WHO/FIGO/ICM-Leitlinie 2025 die postpartale Hämorrhagie neu?", back: "PPH liegt vor bei einem Blutverlust ≥500 ml ODER bereits ab ≥300 ml, wenn gleichzeitig Warnzeichen/abnorme Vitalparameter (z.B. Tachykardie, Hypotonie) bestehen, oder nach klinischer Einschätzung. Der Blutverlust soll objektiv gemessen werden (z.B. kalibriertes Auffangtuch/Drape), statt ihn visuell zu schätzen – Ziel ist eine frühere Diagnose und Behandlung." },
  { id: "fc-ll-310", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", guideline: "WHO/WOMAN-Trial (Tranexamsäure bei PPH)", front: "Was beinhaltet das von WHO/FIGO/ICM empfohlene MOTIVE-Bündel zur Erstbehandlung der PPH, und welche Evidenz stützt es?", back: "Sofort und gleichzeitig bei Diagnose: Uterus-Massage, Oxytocika (Uterotonika), Tranexamsäure, i.v.-Flüssigkeit sowie Examination (Untersuchung auf Ursache) und Eskalation. Im E-MOTIVE-Trial (2023) senkte die Kombination aus objektiver Blutverlustmessung (kalibrierter Drape) und diesem Bündel den kombinierten Endpunkt aus schwerer PPH (≥1000 ml), Laparotomie oder Tod um rund 60% (RR ca. 0,40)." },
  { id: "fc-ll-311", module: "regional-schmerz", subtopic: "neuraxial-verfahren", guideline: "ESRA-Leitlinie (Neuraxiale Verfahren & Antikoagulation)", front: "Welche Mindestabstände zur letzten Einnahme niedrig dosierter (prophylaktischer) DOAK nennt die gemeinsame ESAIC/ESRA-Leitlinie (2022) vor neuraxialen Verfahren?", back: "Rivaroxaban und Edoxaban mindestens 24 h, Apixaban mindestens 36 h, Dabigatran mindestens 48 h vor neuraxialer Punktion bzw. Katheteranlage (gilt gleichermaßen für tiefe, nicht komprimierbare periphere Blockaden)." },
  { id: "fc-ll-312", module: "regional-schmerz", subtopic: "neuraxial-verfahren", guideline: "ESRA-Leitlinie (Neuraxiale Verfahren & Antikoagulation)", front: "Welches Intervall empfiehlt die ESAIC/ESRA-Leitlinie (2022) nach therapeutisch (hoch) dosierten DOAK vor neuraxialen Verfahren, und was gilt bei Niereninsuffizienz?", back: "Mindestens 72 h seit der letzten Einnahme. Bei hochdosiertem Dabigatran mit CrCl <50 ml/min bzw. hochdosierten Faktor-Xa-Inhibitoren mit CrCl <30 ml/min soll das neuraxiale Verfahren nur erfolgen, wenn ein geeigneter substanzspezifischer Labortest (z.B. kalibrierte Anti-Xa-Aktivität bzw. dTT) im Normbereich liegt." },
  { id: "fc-ll-313", module: "regional-schmerz", subtopic: "neuraxial-verfahren", guideline: "ESRA-Leitlinie (Neuraxiale Verfahren & Antikoagulation)", front: "Welche Pausen gelten laut ESAIC/ESRA-Leitlinie (2022) für P2Y12-Hemmer vor und nach neuraxialen Verfahren?", back: "Vorher (dosisunabhängig): Ticagrelor mindestens 5 Tage, Clopidogrel 5–7 Tage, Prasugrel 7 Tage. Nachher: Clopidogrel 75 mg kann ohne Verzögerung, Prasugrel und Ticagrelor frühestens nach 24 h gegeben werden (Aufsättigungsdosen später). Bei liegendem neuraxialem Katheter wird der P2Y12-Hemmer erst nach dessen Entfernung wieder begonnen." },
  { id: "fc-ll-314", module: "regional-schmerz", subtopic: "neuraxial-verfahren", guideline: "ESRA-Leitlinie (Neuraxiale Verfahren & Antikoagulation)", front: "Welcher Gerinnungsbefund wird laut ESAIC/ESRA-Leitlinie (2022) bei Patienten unter Vitamin-K-Antagonisten vor neuraxialen oder tiefen Blockaden gefordert?", back: "Eine normalisierte INR (im Normbereich des lokalen Labors) – unabhängig davon, wie lange der VKA bereits pausiert wurde. Begründung: Schon leicht erhöhte INR-Werte (z.B. ≥1,3) können mit Faktorenaktivitäten <40% und relevanter Gerinnungsstörung einhergehen." },
  { id: "fc-ll-315", module: "regional-schmerz", subtopic: "neuraxial-verfahren", guideline: "ESRA-Leitlinie (Neuraxiale Verfahren & Antikoagulation)", front: "Für welche Regionalanästhesieverfahren gelten die Zeitintervalle der ESAIC/ESRA-Leitlinie (2022), und welche Faktoren verändern sie NICHT?", back: "Sie gelten für neuraxiale Verfahren und periphere Blockaden mit hohem Blutungsrisiko (tief, nicht komprimierbar, z.B. Plexus lumbalis, paravertebral); für oberflächliche, komprimierbare periphere Blockaden gelten sie nicht. Ultraschallsteuerung, Medikamentenkombinationen und Blutungsrisiko-Scores verändern die Intervalle nicht; relevant sind dagegen Substanz, Dosis, Nierenfunktion und ob eine traumatische Punktion erfolgte." },
  { id: "fc-ll-316", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", guideline: "ASA Practice Guidelines for Obstetric Anesthesia", front: "Ist laut ASA-Leitlinie zur geburtshilflichen Anästhesie vor einer neuraxialen Analgesie bei gesunden Gebärenden eine routinemäßige Thrombozytenzählung erforderlich?", back: "Nein – eine routinemäßige Thrombozytenzählung ist bei gesunden Schwangeren nicht notwendig. Sie wird individuell anhand von Anamnese, klinischer Untersuchung und Risikofaktoren angeordnet (z.B. Präeklampsie/HELLP-Syndrom, bekannte Gerinnungsstörung, Blutungsneigung)." },
  { id: "fc-ll-317", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", guideline: "ASA Practice Guidelines for Obstetric Anesthesia", front: "Soll eine Periduralanalgesie unter der Geburt laut ASA-Leitlinie erst ab einer bestimmten Muttermundsweite angelegt werden?", back: "Nein – die neuraxiale Analgesie soll nicht aufgrund einer willkürlichen Muttermundsweite (z.B. <4–5 cm) vorenthalten werden, sondern individuell auf Wunsch der Gebärenden angeboten werden; frühe und späte Anlage unterscheiden sich nicht relevant hinsichtlich Spontan-, vaginal-operativer oder Sectio-Entbindungsrate." },
  { id: "fc-ll-318", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", guideline: "ASA Practice Guidelines for Obstetric Anesthesia", front: "Wie soll die epidurale Geburtsanalgesie laut ASA-Leitlinie aufrechterhalten werden, um die motorische Blockade gering zu halten?", back: "Mit niedrig konzentrierten ('verdünnten') Lokalanästhetika in Kombination mit einem Opioid (z.B. Fentanyl/Sufentanil), wodurch die Lokalanästhetikadosis und die motorische Blockade reduziert werden; die patientenkontrollierte Epiduralanalgesie (PCEA, mit oder ohne Basalrate) wird als effektive, flexible Methode empfohlen. Eine kombinierte Spinal-Epidural-Analgesie ermöglicht einen besonders raschen Wirkeintritt." },
  { id: "fc-ll-319", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", guideline: "ASA Practice Guidelines for Obstetric Anesthesia", front: "Welchen Spinalnadeltyp empfiehlt die ASA-Leitlinie in der Geburtshilfe, und warum?", back: "Atraumatische Pencil-Point-Nadeln (z.B. Sprotte, Whitacre) statt schneidender (Quincke-)Nadeln, da sie die Inzidenz postpunktioneller Kopfschmerzen bei den besonders gefährdeten jungen Schwangeren deutlich senken." },
  { id: "fc-ll-320", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", guideline: "ASA Practice Guidelines for Obstetric Anesthesia", front: "Was empfiehlt die ASA-Leitlinie zur Behandlung der spinalanästhesiebedingten Hypotonie bei Sectio und zur postoperativen Analgesie?", back: "Hypotonie: i.v.-Phenylephrin oder Ephedrin sind beide geeignet; bei fehlender mütterlicher Bradykardie ist Phenylephrin zu bevorzugen, da es mit einem besseren fetalen Säure-Basen-Status einhergeht. Eine Volumen-Prä-/Koladung kann die Hypotonieinzidenz senken, soll die Anlage aber nicht verzögern. Postoperativ werden neuraxiale Opioide (z.B. intrathekales/epidurales Morphin) gegenüber intermittierenden parenteralen Opioidgaben bevorzugt." },
  { id: "fc-ll-321", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "ASA Practice Advisory (Intraoperative Awareness)", front: "Welche präinduktive Maßnahme empfiehlt die ASA Practice Advisory zur Vermeidung intraoperativer Awareness in Bezug auf die Geräte?", back: "Eine systematische Funktionsprüfung des Anästhesie-Equipments vor Einleitung (Checkliste), um eine unbeabsichtigte Unterdosierung zu verhindern: Narkosegerät und Verdampfer (Füllstand, korrekte Funktion), bei TIVA intakte, sichtbare und korrekt konnektierte i.v.-Zugänge, Spritzenpumpen und Leitungen." },
  { id: "fc-ll-322", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "ASA Practice Advisory (Intraoperative Awareness)", front: "Was empfiehlt die ASA Practice Advisory zum Einsatz von Benzodiazepinen im Zusammenhang mit intraoperativer Awareness?", back: "Keine Routinegabe: Die prophylaktische Benzodiazepingabe soll fallbezogen entschieden werden, v.a. bei Patienten, die nur geringe Anästhetikadosen tolerieren (z.B. hämodynamisch instabil). Auch wenn ein Patient intraoperativ unerwartet wach wird, wird neben der Vertiefung der Anästhesie fallbezogen über eine Benzodiazepingabe (Ziel: anterograde Amnesie) entschieden." },
  { id: "fc-ll-323", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "ASA Practice Advisory (Intraoperative Awareness)", front: "Worauf soll sich laut ASA Practice Advisory die intraoperative Beurteilung der Anästhesietiefe stützen, und welche Limitationen sind zu beachten?", back: "Auf mehrere Modalitäten gleichzeitig: klinische Zeichen (gezielte oder reflektorische Bewegungen, Augenöffnen, Tränenfluss, Schwitzen) und konventionelles Monitoring (EKG, Blutdruck, Herzfrequenz, endexspiratorische Anästhetikakonzentration, Kapnographie). Limitation: Muskelrelaxanzien maskieren Bewegungsreaktionen, und hämodynamische Zeichen sind unzuverlässig (z.B. unter Betablockern) – keines dieser Zeichen schließt Awareness sicher aus." },
  { id: "fc-ll-324", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "ASA Practice Advisory (Intraoperative Awareness)", front: "Wie ist intraoperative Awareness definiert, und wie häufig tritt sie auf?", back: "Awareness bezeichnet einen Bewusstseinszustand während der Allgemeinanästhesie mit anschließender expliziter Erinnerung an intraoperative Ereignisse (Träume zählen nicht dazu). Inzidenz in prospektiven Studien mit strukturierter Befragung ca. 0,1–0,2% (1–2/1000); bei spontaner Meldung (NAP5) deutlich seltener (ca. 1:19.000), mit erhöhter Rate bei Sectio und Herzchirurgie sowie unter Muskelrelaxierung." },
  { id: "fc-ll-325", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "ASA Practice Advisory (Intraoperative Awareness)", front: "Welche patientenbezogenen Risikofaktoren für intraoperative Awareness soll die präoperative Evaluation laut ASA Practice Advisory erfassen?", back: "Substanzgebrauch/-missbrauch (z.B. Opioide, Benzodiazepine, Amphetamine, Kokain, Alkohol), chronische Schmerzen mit hohem Opioidbedarf, frühere Awareness-Episode, erwartet schwieriger Atemweg, ASA-Klasse IV–V bzw. eingeschränkte hämodynamische Reserve – solche Patienten werden identifiziert und ggf. über das erhöhte Risiko informiert." },
  { id: "fc-ll-326", module: "notfall-reanimation", subtopic: "trauma", guideline: "Europäische Leitlinie: Schwere Blutung & Koagulopathie nach Trauma", front: "Welche Blutdruckziele nennt die europäische Trauma-Leitlinie (6. Auflage 2023) bis zur Blutungskontrolle – mit und ohne Schädel-Hirn-Trauma?", back: "Ohne SHT bzw. Rückenmarksverletzung: permissive Hypotonie mit systolischem Blutdruck von 80–90 mmHg (MAP ca. 50–60 mmHg) bis zur chirurgischen/interventionellen Blutungskontrolle. Bei schwerem SHT (GCS ≤8): MAP ≥80 mmHg, um den zerebralen Perfusionsdruck zu sichern." },
  { id: "fc-ll-327", module: "notfall-reanimation", subtopic: "trauma", guideline: "Europäische Leitlinie: Schwere Blutung & Koagulopathie nach Trauma", front: "Welche vasoaktiven Substanzen empfiehlt die europäische Trauma-Leitlinie, wenn das Blutdruckziel mit restriktiver Volumentherapie nicht erreicht wird?", back: "Noradrenalin zusätzlich zur Flüssigkeitstherapie bei lebensbedrohlicher Hypotonie, um den Ziel-Blutdruck zu halten (Grad 1C), sowie Dobutamin bei myokardialer Dysfunktion (Grad 1C)." },
  { id: "fc-ll-328", module: "notfall-reanimation", subtopic: "trauma", guideline: "Europäische Leitlinie: Schwere Blutung & Koagulopathie nach Trauma", front: "Welcher Hb-Zielbereich und welche initiale Gerinnungstherapie werden bei erwarteter Massivblutung nach Trauma empfohlen?", back: "Hb-Ziel bei Erythrozytentransfusion 7–9 g/dl (Grad 1C). Initial bei erwarteter Massivblutung eine von zwei Strategien: Plasma (FFP bzw. pathogeninaktiviertes Plasma) zu Erythrozytenkonzentrat im Verhältnis von mindestens 1:2, oder Fibrinogenkonzentrat plus Erythrozytenkonzentrate; danach zielgerichtete, befundgesteuerte Therapie (Standardlabor/viskoelastische Tests)." },
  { id: "fc-ll-329", module: "notfall-reanimation", subtopic: "trauma", guideline: "Europäische Leitlinie: Schwere Blutung & Koagulopathie nach Trauma", front: "Welche Thrombozytenzielwerte empfiehlt die europäische Trauma-Leitlinie (6. Auflage)?", back: "Thrombozytengabe, um eine Zahl >50.000/µl (>50 × 10^9/l) aufrechtzuerhalten; bei fortbestehender Blutung und/oder Schädel-Hirn-Trauma wird ein Wert >100.000/µl (>100 × 10^9/l) vorgeschlagen." },
  { id: "fc-ll-330", module: "notfall-reanimation", subtopic: "trauma", guideline: "Europäische Leitlinie: Schwere Blutung & Koagulopathie nach Trauma", front: "Wie werden orale Antikoagulanzien bei blutenden Traumapatienten laut europäischer Trauma-Leitlinie antagonisiert?", back: "Vitamin-K-Antagonisten: Prothrombinkomplexkonzentrat (PPSB) plus Vitamin K i.v.; Dabigatran: Idarucizumab; Faktor-Xa-Inhibitoren (Apixaban, Rivaroxaban): PPSB (25–50 IE/kg) ist die praktisch relevante Option – Andexanet alfa wurde wegen erhöhten Thromboserisikos (ANNEXA-I) Ende 2025 in den USA vom Markt genommen und ist nur noch eingeschränkt verfügbar. Die DOAK-Wirkung sollte (wenn möglich) mit substanzspezifischen Spiegeln abgeschätzt werden." },
  { id: "fc-ll-331", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "Resuscitation Council UK (Perioperative Anaphylaxie)", front: "Ab welchem Blutdruckwert empfiehlt der RCUK-Algorithmus zur perioperativen Anaphylaxie den Beginn einer kardiopulmonalen Reanimation, auch wenn noch kein formaler Kreislaufstillstand festgestellt wurde?", back: "Wenn der systolische Blutdruck trotz initialer Adrenalin- und Volumengabe unter 50 mmHg liegt, sollen Thoraxkompressionen begonnen werden, auch wenn noch ein Puls tastbar sein mag. Der Grenzwert stammt aus NAP6: Unter 50 mmHg ist die Perfusion von Herz und Gehirn unzureichend. Im Kreislaufstillstand wird Adrenalin nach dem ALS-Algorithmus gegeben (Erwachsene 1 mg i.v.)." },
  { id: "fc-ll-332", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "Resuscitation Council UK (Perioperative Anaphylaxie)", front: "Welche Initialdosen für i.v.-Adrenalin und Volumen nennt der RCUK-Algorithmus zur perioperativen Anaphylaxie für Kinder unter 12 Jahren?", back: "Adrenalin 1 µg/kg i.v. als titrierter Bolus (sorgfältige Verdünnung nötig, Wiederholung nach Wirkung); ab 12 Jahren wie bei Erwachsenen 50 µg (0,5 ml der 1:10.000-Lösung). Volumen: rascher Kristalloid-Bolus von 20 ml/kg, der wiederholt werden kann, da insgesamt große Volumina nötig sein können." },
  { id: "fc-ll-333", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "Resuscitation Council UK (Perioperative Anaphylaxie)", front: "Welche Sofortmaßnahmen stehen laut RCUK-Algorithmus bei Verdacht auf perioperative Anaphylaxie am Anfang, noch vor bzw. parallel zur ersten Adrenalingabe?", back: "Hilfe rufen und die Situation laut als Anaphylaxie-Notfall benennen, alle möglichen Auslöser sofort stoppen bzw. entfernen (z.B. laufende Antibiotika-, Kolloid- oder Blutinfusionen, chlorhexidinhaltige Materialien, Patentblau), Atemweg sichern und mit 100 % O2 beatmen, Beine anheben, Chirurg:innen informieren und den Eingriff wenn möglich unterbrechen bzw. rasch beenden." },
  { id: "fc-ll-334", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "Resuscitation Council UK (Perioperative Anaphylaxie)", front: "Wie wird eine niedrig dosierte periphere Adrenalin-Infusion bei refraktärer Anaphylaxie laut Resuscitation Council UK zubereitet und gestartet, und ab wann gilt eine Anaphylaxie als refraktär?", back: "Refraktär ist die Anaphylaxie, wenn Atem- oder Kreislaufprobleme trotz zwei adäquaten Adrenalindosen weiterbestehen. Dann wird eine Adrenalin-Infusion begonnen. Die periphere Niedrigdosis-Variante: 1 mg Adrenalin in 100 ml NaCl 0,9 % (10 µg/ml), Startrate 0,5–1 ml/kg/h, dann nach Wirkung titrieren. Unter kontinuierlichem Monitoring darf sie peripher laufen, bis ein ZVK liegt. Frühzeitig Intensivmedizin hinzuziehen." },
  { id: "fc-ll-335", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "Resuscitation Council UK (Perioperative Anaphylaxie)", front: "Welche Zusatztherapie kommt laut RCUK-Empfehlungen bei anaphylaktischem Bronchospasmus in Frage, der trotz Adrenalin fortbesteht?", back: "Adrenalin bleibt die Basistherapie und wird nicht ersetzt. Zusätzlich können Bronchodilatatoren eingesetzt werden: Salbutamol (inhalativ oder i.v.), Ipratropium, Magnesiumsulfat i.v., Aminophyllin oder in Narkose ein volatiles Anästhetikum. Wichtig: Beim beatmeten Patienten kann ein schwerer Bronchospasmus die Kapnographie-Kurve abflachen oder verschwinden lassen. Das darf nicht als Kreislaufstillstand oder Fehlintubation fehlgedeutet werden, ohne dass Tubuslage und Kreislauf geprüft werden." },
  { id: "fc-ll-336", module: "spezielle-anaesthesie", subtopic: "kinderanaesthesie", guideline: "APAGBI-Leitlinie (Kinderanästhesie)", front: "Welche medikamentöse Prophylaxe gegen postoperatives Erbrechen (POV) empfiehlt die APAGBI-Leitlinie (2016) für Kinder mit erhöhtem Risiko?", back: "Kinder mit erhöhtem POV-Risiko sollen Ondansetron 0,15 mg/kg erhalten. Bei hohem Risiko (z.B. Tonsillektomie, Strabismus-Operation) wird es mit Dexamethason 0,15 mg/kg kombiniert. Die Kombination wirkt besser als jede Einzelsubstanz. Dexamethason wirkt vor allem auch gegen spätes Erbrechen." },
  { id: "fc-ll-337", module: "spezielle-anaesthesie", subtopic: "kinderanaesthesie", guideline: "APAGBI-Leitlinie (Kinderanästhesie)", front: "Welche Risikofaktoren für postoperatives Erbrechen bei Kindern zieht die APAGBI-POV-Leitlinie zur Risikoeinschätzung heran?", back: "Alter ≥3 Jahre, Operationsdauer ≥30 Minuten, Strabismus-Chirurgie sowie eine Vorgeschichte von POV beim Kind oder von PONV bei Eltern/Geschwistern (Eberhart-Kriterien). Zusätzlich gelten Tonsillektomie/Adenotonsillektomie und die Gabe von Opioiden als relevante eingriffs- und medikamentenbezogene Risikofaktoren. Mit steigender Zahl der Faktoren wird die Prophylaxe gesteigert." },
  { id: "fc-ll-338", module: "spezielle-anaesthesie", subtopic: "kinderanaesthesie", guideline: "APAGBI-Leitlinie (Kinderanästhesie)", front: "Welche Empfehlung zu Codein bei Kindern unterstützt die APAGBI (in Übereinstimmung mit der britischen Arzneimittelbehörde MHRA), und warum?", back: "Codein soll bei Kindern unter 12 Jahren nicht zur Schmerztherapie eingesetzt werden. Nach Tonsillektomie/Adenotomie wegen obstruktiver Schlafapnoe ist es bei allen unter 18-Jährigen kontraindiziert. Grund: Die Umwandlung zu Morphin über CYP2D6 schwankt genetisch stark. Ultra-rapid metabolizer können toxische Morphinspiegel mit tödlicher Atemdepression entwickeln, schlechte Metabolisierer haben keine Analgesie." },
  { id: "fc-ll-339", module: "spezielle-anaesthesie", subtopic: "kinderanaesthesie", guideline: "APAGBI-Leitlinie (Kinderanästhesie)", front: "Welche Grundsätze enthält der gemeinsame APA/DAS-Algorithmus (2012) zur unerwartet schwierigen Intubation bei Kindern von 1–8 Jahren?", back: "Oxygenierung hat Vorrang vor der Intubation: Zwischen den Versuchen wird mit Maske und 100 % O2 oxygeniert. Die Zahl der Intubationsversuche wird begrenzt (maximal 4, dabei Lagerung, Spatel/Technik, Tubusgröße und externe Larynxmanipulation optimieren; Krikoiddruck ggf. lösen). Scheitert die Intubation, wird über eine supraglottische Atemwegshilfe oxygeniert. Dann wird entschieden: Kind aufwachen lassen, Eingriff über den SGA fortführen oder fiberoptisch über den SGA intubieren." },
  { id: "fc-ll-340", module: "spezielle-anaesthesie", subtopic: "kinderanaesthesie", guideline: "APAGBI-Leitlinie (Kinderanästhesie)", front: "Welches Vorgehen sieht der APA/DAS-Algorithmus für die 'Cannot intubate, cannot ventilate'-Situation (CICV) beim relaxierten Kind von 1–8 Jahren vor?", back: "Sofort Hilfe (inkl. HNO) rufen, weiter 100 % O2 über Maske/SGA anbieten und die Relaxierung sicherstellen. Der Notfall-Atemwegszugang erfolgt je nach Verfügbarkeit: Ist eine HNO-Chirurgin/ein HNO-Chirurg sofort da, erfolgt eine chirurgische Tracheotomie. Sonst folgt eine Kanülen-Krikothyreotomie mit anschließender Jet-/Druckoxygenierung. Scheitert diese, schließt sich ein chirurgischer Zugang (Tracheotomie bzw. Skalpell-Technik) an." },
  { id: "fc-ll-341", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", guideline: "ERAS-Cardiac-Society/STS-Konsensus 2024", front: "Welche Maßnahmen zur Prävention von postoperativem Vorhofflimmern (POAF) nennt der ERAS-Cardiac-Society/STS-Konsensus 2024?", back: "Eine bestehende Betablocker-Therapie wird perioperativ durchgehend fortgeführt. Bei Betablocker-naiven Patienten kann eine kurzzeitige, niedrig dosierte Betablockade erwogen werden. Amiodaron (prä- und/oder postoperativ) sollte zur POAF-Prophylaxe erwogen werden, vor allem bei hohem Risiko. Beide Substanzen senken nachweislich die POAF-Inzidenz. Die POAF-Prävention zählt 2024 zu den neuen organspezifischen Elementen." },
  { id: "fc-ll-342", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", guideline: "ERAS-Cardiac-Society/STS-Konsensus 2024", front: "Wie soll die Prävention postoperativer Wundinfektionen (SSI) nach Herzchirurgie laut ERAS-Cardiac-Society/STS-Konsensus 2024 organisiert sein?", back: "Als Maßnahmenbündel statt als Einzelmaßnahmen. Es umfasst u.a. Verhaltenselemente (z.B. Patientenschulung, präoperative Körperwaschung), Vorbereitung des OP-Gebiets (alkoholische Antiseptik, Clipping statt Rasur), korrekt getimte und dosierte Antibiotikaprophylaxe sowie konsequente Normoglykämie und Normothermie. Die SSI-Prävention gehört zu den nur drei Empfehlungen des Konsensus mit hoher Evidenzqualität." },
  { id: "fc-ll-343", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", guideline: "ERAS-Cardiac-Society/STS-Konsensus 2024", front: "Welche präoperativen und intraoperativen Bausteine des Patient Blood Managements (PBM) betont der ERAS-Cardiac-Society/STS-Konsensus 2024, über die restriktive Transfusionsschwelle hinaus?", back: "Präoperativ: Screening auf Anämie und Eisenmangel mit gezielter Therapie vor dem Eingriff (z.B. Eisensubstitution, wenn die Zeit reicht). Intraoperativ: möglichst wenig Blutverlust und Hämodilution (z.B. maschinelle Autotransfusion/Cell Salvage, kleines Priming-Volumen, sorgfältige Blutstillung). Dazu kommt eine bewusste Toleranz moderater intra- und postoperativer Anämie statt reflexhafter Transfusion." },
  { id: "fc-ll-344", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", guideline: "ERAS-Cardiac-Society/STS-Konsensus 2024", front: "Welche präoperativen Optimierungsmaßnahmen empfiehlt der ERAS-Cardiac-Society/STS-Konsensus 2024 (jeweils mit welchem Empfehlungsgrad)?", back: "Eine multimodale Prähabilitation (körperliches Training, ggf. Atemtraining und psychologische Vorbereitung) sollte erwogen werden (Klasse IIa, Evidenz C-LD). Ebenso eine Ernährungsoptimierung, wenn machbar (IIa, C-LD), und der Einsatz digitaler Plattformen/Apps zur Patienteneinbindung und -schulung (IIa, C-LD)." },
  { id: "fc-ll-345", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", guideline: "ERAS-Cardiac-Society/STS-Konsensus 2024", front: "Welche drei Empfehlungen des ERAS-Cardiac-Society/STS-Konsensus 2024 wurden als einzige mit hoher Evidenzqualität bewertet?", back: "(1) Delir-Screening und strukturierte Delirbehandlung, (2) Prävention postoperativer Wundinfektionen (SSI-Bündel) und (3) lungenprotektive Beatmung. Die lungenprotektive Beatmung (inkl. Beatmungsstrategie während der Herz-Lungen-Maschine) wurde 2024 neu aufgenommen, zusammen mit weiteren organspezifischen Elementen wie PBM, POAF-Prävention und ZNS-Monitoring." },
  { id: "fc-ll-346", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", guideline: "ASH-Leitlinie 2019 (VTE-Prophylaxe)", front: "Welche Form der mechanischen VTE-Prophylaxe bevorzugt die ASH-Leitlinie 2019 bei Patienten mit großen chirurgischen Eingriffen?", back: "Mechanische Prophylaxe wird gegenüber keiner Prophylaxe bevorzugt. Wird sie eingesetzt, ist die intermittierende pneumatische Kompression (IPC) den medizinischen Kompressionsstrümpfen (Graduated Compression Stockings) vorzuziehen. Beides sind bedingte (conditional) Empfehlungen bei sehr niedriger Evidenzsicherheit." },
  { id: "fc-ll-347", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", guideline: "ASH-Leitlinie 2019 (VTE-Prophylaxe)", front: "Wie positioniert sich die ASH-Leitlinie 2019 zu prophylaktisch implantierten Vena-cava-inferior-Filtern bei großen Operationen?", back: "Die ASH-Leitlinie rät davon ab, V.-cava-Filter prophylaktisch zur VTE-Vermeidung bei chirurgischen Patienten einzusetzen (bedingte Empfehlung). Es fehlt ein Nutzennachweis für Mortalität oder symptomatische Lungenembolie. Dem stehen filterbedingte Komplikationen gegenüber (Thrombose am Filter, Migration, Perforation, erhöhtes Risiko für spätere tiefe Venenthrombosen)." },
  { id: "fc-ll-348", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", guideline: "ASH-Leitlinie 2019 (VTE-Prophylaxe)", front: "Welche medikamentöse VTE-Prophylaxe empfiehlt die ASH-Leitlinie 2019 bei großen allgemeinchirurgischen und großen gynäkologischen Eingriffen?", back: "Medikamentöse Prophylaxe wird gegenüber keiner medikamentösen Prophylaxe bevorzugt (bedingte Empfehlung). Als Wirkstoffe werden niedermolekulares Heparin (NMH) oder unfraktioniertes Heparin (UFH) gleichwertig vorgeschlagen. Die Entscheidung richtet sich nach individuellem VTE- und Blutungsrisiko." },
  { id: "fc-ll-349", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", guideline: "ASH-Leitlinie 2019 (VTE-Prophylaxe)", front: "Was empfiehlt die ASH-Leitlinie 2019 zur medikamentösen VTE-Prophylaxe bei großen neurochirurgischen Eingriffen?", back: "Die ASH rät bei großen neurochirurgischen Eingriffen generell von einer medikamentösen Prophylaxe ab (bedingte Empfehlung), wegen des Risikos folgenschwerer intrakranieller/spinaler Blutungen. Stattdessen wird eine mechanische Prophylaxe eingesetzt. Wird bei einzelnen Hochrisikopatienten doch medikamentös prophylaktiert, wird NMH gegenüber UFH bevorzugt." },
  { id: "fc-ll-350", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", guideline: "ASH-Leitlinie 2019 (VTE-Prophylaxe)", front: "Was empfiehlt die ASH-Leitlinie 2019 zur medikamentösen VTE-Prophylaxe bei transurethraler Prostataresektion (TUR-P) und radikaler Prostatektomie?", back: "Für beide Eingriffe rät die ASH von einer routinemäßigen medikamentösen Prophylaxe ab (bedingte Empfehlungen). Grund ist das niedrige VTE-Grundrisiko bei relevantem Blutungsrisiko. Wird nach radikaler Prostatektomie wegen individuell hohem VTE-Risiko dennoch medikamentös prophylaktiert, werden NMH oder UFH vorgeschlagen." },
  { id: "fc-ll-351", module: "pharmakologie", subtopic: "muskelrelaxanzien", guideline: "ASA-Konsensus (Neuromuskuläres Monitoring & Reversal)", front: "An welchem Muskel soll laut ASA-Leitlinie 2023 das neuromuskuläre Monitoring erfolgen, und von welcher Messstelle wird ausdrücklich abgeraten?", back: "Empfohlen wird die Messung am M. adductor pollicis (Stimulation des N. ulnaris). Von den Augenmuskeln (M. orbicularis oculi, M. corrugator supercilii) wird abgeraten (starke Empfehlung). Sie sind gegenüber Relaxanzien resistenter und erholen sich schneller. Dadurch täuschen sie eine ausreichende Erholung vor, obwohl die Atemwegs- und Schluckmuskulatur noch relevant blockiert sein kann." },
  { id: "fc-ll-352", module: "pharmakologie", subtopic: "muskelrelaxanzien", guideline: "ASA-Konsensus (Neuromuskuläres Monitoring & Reversal)", front: "Wie definiert die ASA-Leitlinie 2023 die Tiefe einer neuromuskulären Blockade anhand von Post-Tetanic Count (PTC), TOF-Count (TOFC) und TOF-Ratio (TOFR)?", back: "Tief: TOFC 0, PTC ≥1. Moderat: TOFC 1–3. Flach (shallow): TOFC 4 mit Fading, TOFR <0,4. Minimal: TOFR 0,4 bis <0,9. Ausreichende Erholung: TOFR ≥0,9. Wichtig: Ab TOFR >0,4 ist Fading mit bloßem Auge/taktil kaum noch sicher zu erkennen. Deshalb braucht es für die Unterscheidung minimal vs. ausreichend eine quantitative Messung." },
  { id: "fc-ll-353", module: "pharmakologie", subtopic: "muskelrelaxanzien", guideline: "ASA-Konsensus (Neuromuskuläres Monitoring & Reversal)", front: "Wie soll laut ASA-Leitlinie 2023 eine Blockade mit Atracurium oder Cisatracurium antagonisiert werden, wenn nur ein qualitatives (visuell/taktiles) Monitoring zur Verfügung steht?", back: "Neostigmin wird erst bei minimaler Blockadetiefe gegeben: qualitativ ein TOF-Count von 4 ohne erkennbares Fading. Zwischen Neostigmin-Gabe und Extubation sollen dann mindestens 10 Minuten vergehen, weil ohne quantitative Messung eine Restblockade nicht ausgeschlossen werden kann. Sugammadex ist bei diesen Benzylisochinolinen wirkungslos." },
  { id: "fc-ll-354", module: "pharmakologie", subtopic: "muskelrelaxanzien", guideline: "ASA-Konsensus (Neuromuskuläres Monitoring & Reversal)", front: "Für welche Relaxanzien gilt die Empfehlung der ASA-Leitlinie 2023, Sugammadex bei tiefer, moderater und flacher Blockade gegenüber Neostigmin zu bevorzugen, und warum nicht für alle?", back: "Nur für Aminosteroid-Relaxanzien (Rocuronium, Vecuronium). Sugammadex ist ein modifiziertes γ-Cyclodextrin, das diese Moleküle einkapselt. Benzylisochinoline (Atracurium, Cisatracurium, Mivacurium) werden nicht gebunden. Für sie bleibt Neostigmin bei minimaler Blockadetiefe das Antagonisierungsmittel der Wahl." },
  { id: "fc-ll-355", module: "pharmakologie", subtopic: "muskelrelaxanzien", guideline: "ASA-Konsensus (Neuromuskuläres Monitoring & Reversal)", front: "Macht die Gabe von Sugammadex laut ASA-Leitlinie 2023 die quantitative Bestätigung einer TOF-Ratio ≥0,9 vor Extubation überflüssig?", back: "Nein. Die Forderung, vor der Extubation eine TOFR ≥0,9 quantitativ zu bestätigen, gilt unabhängig vom Antagonisten. Auch nach Sugammadex kommen Restblockaden vor, z.B. bei Unterdosierung im Verhältnis zur aktuellen Blockadetiefe oder bei erneuter Relaxansgabe. Die Dosis richtet sich nach der gemessenen Tiefe, deshalb ist ein Monitoring schon vor der Antagonisierung nötig." },
  { id: "fc-ll-356", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "ESC/ESAIC-Leitlinie 2022 (Perioperatives kardiovaskuläres Management)", front: "Bei welchen Patienten empfiehlt die ESC/ESAIC-Leitlinie 2022 ein präoperatives 12-Kanal-EKG, und wann ist es nicht indiziert?", back: "Empfohlen (Klasse I) bei Patienten mit bekannter kardiovaskulärer Erkrankung, kardiovaskulären Risikofaktoren (inkl. Alter ≥65 Jahre) oder entsprechenden Symptomen/Befunden vor intermediär- oder hochrisikoreichen Eingriffen. Bei Niedrigrisiko-Patienten vor Niedrigrisiko-Eingriffen wird ein routinemäßiges EKG nicht empfohlen." },
  { id: "fc-ll-357", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "ESC/ESAIC-Leitlinie 2022 (Perioperatives kardiovaskuläres Management)", front: "Welche Rolle weist die ESC/ESAIC-Leitlinie 2022 den natriuretischen Peptiden (BNP/NT-proBNP) und der präoperativen transthorakalen Echokardiographie zu?", back: "BNP/NT-proBNP sollte bei bekannter kardiovaskulärer Erkrankung oder Risikofaktoren (inkl. Alter ≥65) vor intermediär-/hochrisikoreichen Eingriffen bestimmt werden (IIa). Eine TTE wird empfohlen (I) bei eingeschränkter Belastbarkeit und/oder erhöhtem BNP/NT-proBNP oder neuem Herzgeräusch vor Hochrisikoeingriffen, sowie bei Symptomen/Zeichen einer Herzerkrankung. Eine routinemäßige präoperative Bestimmung der LV-Funktion ohne solchen Anlass wird nicht empfohlen (III)." },
  { id: "fc-ll-358", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "ESC/ESAIC-Leitlinie 2022 (Perioperatives kardiovaskuläres Management)", front: "Was empfiehlt die ESC/ESAIC-Leitlinie 2022 zu ACE-Hemmern/Sartanen und SGLT2-Inhibitoren vor nicht-kardiochirurgischen Eingriffen?", back: "Bei Patienten ohne Herzinsuffizienz sollte ein Pausieren von ACE-Hemmern/ARB am OP-Tag erwogen werden, um intraoperative Hypotonien zu vermeiden (IIa). Bei stabiler Herzinsuffizienz kann die Therapie fortgeführt werden. SGLT2-Inhibitoren sollten vor intermediär- und hochrisikoreichen Eingriffen mindestens 3 Tage vorher abgesetzt werden (IIa), wegen des Risikos einer (euglykämischen) Ketoazidose." },
  { id: "fc-ll-359", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "ESC/ESAIC-Leitlinie 2022 (Perioperatives kardiovaskuläres Management)", front: "Wie lange sollen direkte orale Antikoagulanzien (DOAK) laut ESC/ESAIC-Leitlinie 2022 vor elektiven Eingriffen pausiert werden, und wird ein Heparin-Bridging empfohlen?", back: "Faktor-Xa-Hemmer (Apixaban, Rivaroxaban, Edoxaban) bei Kreatinin-Clearance ≥30 ml/min: ≥24 h vor Eingriffen mit niedrigem und ≥48 h vor Eingriffen mit hohem Blutungsrisiko. Dabigatran hängt stärker von der Nierenfunktion ab (bei CrCl 30–49 ml/min z.B. ≥48 h bzw. ≥96 h). Ein Bridging mit Heparin wird bei DOAK nicht empfohlen (Klasse III)." },
  { id: "fc-ll-360", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "ESC/ESAIC-Leitlinie 2022 (Perioperatives kardiovaskuläres Management)", front: "Was empfiehlt die ESC/ESAIC-Leitlinie 2022 bei symptomatischer schwerer Aortenklappenstenose vor einer elektiven nicht-kardiochirurgischen Operation?", back: "Vor elektiven intermediär- oder hochrisikoreichen Eingriffen wird ein Aortenklappenersatz empfohlen, chirurgisch (SAVR) oder kathetergestützt (TAVI) (Klasse I). Die Wahl erfolgt im Heart Team. Der nicht-kardiale Eingriff sollte möglichst erst danach stattfinden, weil die symptomatische schwere AS mit einem hohen Risiko für perioperative Hypotonie, Ischämie und Herzversagen einhergeht." },
  { id: "fc-ll-361", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "ASA/ASRA Acute Pain Management Guideline", front: "Welchen Applikationsweg für Opioide bevorzugt die APS/ASRA/ASA-Leitlinie (2016) zur postoperativen Schmerztherapie, und welcher soll vermieden werden?", back: "Bei Patienten, die orale Medikamente einnehmen können, wird der orale Weg dem intravenösen vorgezogen (starke Empfehlung, moderate Evidenz). Die intramuskuläre Gabe soll vermieden werden (stark, moderat). Sie ist schmerzhaft, wird unzuverlässig resorbiert und führt zu schwankenden Wirkspiegeln." },
  { id: "fc-ll-362", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "ASA/ASRA Acute Pain Management Guideline", front: "Was empfiehlt die APS/ASRA/ASA-Leitlinie (2016) zur intravenösen patientenkontrollierten Analgesie (i.v.-PCA) bei opioidnaiven Erwachsenen?", back: "Die i.v.-PCA ist das bevorzugte Verfahren, wenn ein parenteraler Weg nötig ist (stark, moderat). Eine routinemäßige Basalinfusion (kontinuierliche Hintergrundrate) soll bei opioidnaiven Erwachsenen nicht eingesetzt werden (stark, moderat): Sie bringt keine bessere Analgesie, erhöht aber das Risiko von Übersedierung und Atemdepression. Unter systemischen Opioiden müssen Sedierung und Atmung regelmäßig überwacht werden." },
  { id: "fc-ll-363", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "ASA/ASRA Acute Pain Management Guideline", front: "Welche präoperative Einzelgabe eines Nicht-Opioid-Analgetikums empfiehlt die APS/ASRA/ASA-Leitlinie (2016) bei Erwachsenen ohne Kontraindikation?", back: "Eine präoperative orale Dosis Celecoxib (COX-2-selektiv) sollte erwogen werden (starke Empfehlung, moderate Evidenz). Sie senkt Schmerzintensität und Opioidbedarf und verursacht keine relevante Thrombozytenfunktionshemmung. Kontraindikationen (z.B. relevante Niereninsuffizienz, bestimmte kardiovaskuläre Erkrankungen, Sulfonamid-Allergie) sind zu beachten." },
  { id: "fc-ll-364", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "ASA/ASRA Acute Pain Management Guideline", front: "Welche Empfehlungen gibt die APS/ASRA/ASA-Leitlinie (2016) zu intravenösem Ketamin und intravenösem Lidocain als Bestandteil multimodaler Analgesie?", back: "Ketamin i.v. kann bei Erwachsenen vor allem bei großen Eingriffen erwogen werden (schwache Empfehlung, moderate Evidenz), besonders bei hohem Opioidbedarf oder Opioidtoleranz. Eine kontinuierliche Lidocain-Infusion i.v. kann bei offener und laparoskopischer Abdominalchirurgie ohne Kontraindikationen erwogen werden (schwach, moderat). Beide senken Schmerz und Opioidverbrauch." },
  { id: "fc-ll-365", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "ASA/ASRA Acute Pain Management Guideline", front: "Welche Substanzen sollen laut APS/ASRA/ASA-Leitlinie (2016) NICHT neuraxial (spinal/epidural) zur postoperativen Analgesie verabreicht werden?", back: "Magnesium, Benzodiazepine, Neostigmin, Tramadol und Ketamin (starke Empfehlung, moderate Evidenz). Für diese Substanzen fehlt ein klarer analgetischer Zusatznutzen bei neuraxialer Gabe, und die neurotoxische Sicherheit ist nicht ausreichend belegt (u.a. Konservierungsmittel). Neuraxial etabliert sind dagegen Lokalanästhetika und Opioide, ggf. Clonidin." },
  { id: "fc-ll-366", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "MHAUS (Maligne Hyperthermie)", front: "Ab welcher Körperkerntemperatur empfiehlt MHAUS in der MH-Krise aktive Kühlung, mit welchen Methoden, und wann wird die Kühlung beendet?", back: "Bei einer Kerntemperatur >39 °C: kalte Infusionslösung i.v., Eis/Kühlpacks auf die Körperoberfläche (Leisten, Achseln, Hals) und ggf. Spülung offener Körperhöhlen, Magen oder Blase mit kalter Lösung. Die Kühlung wird gestoppt, sobald die Temperatur unter 38 °C fällt, um eine überschießende Hypothermie zu vermeiden." },
  { id: "fc-ll-367", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "MHAUS (Maligne Hyperthermie)", front: "Wie behandelt man laut MHAUS eine Hyperkaliämie während einer MH-Krise (Grenzwert und Dosierungen)?", back: "Behandlung bei K+ >5,9 mmol/l oder niedrigerem Wert mit EKG-Veränderungen: Hyperventilation; Calciumchlorid 10 mg/kg (max. 2 g) oder Calciumgluconat (ca. 30 mg/kg, max. 3 g) bei lebensbedrohlicher Hyperkaliämie; Insulin/Glukose (Erwachsene 10 IE Normalinsulin i.v. + 50 ml Glukose 50 %; Kinder 0,1 IE/kg + 1 ml/kg Glukose 50 %) mit engmaschiger BZ-Kontrolle. Ggf. Natriumbikarbonat bei metabolischer Azidose. Die entscheidende Kausaltherapie bleibt ausreichend Dantrolen." },
  { id: "fc-ll-368", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "MHAUS (Maligne Hyperthermie)", front: "Welche Antiarrhythmika-Klasse ist laut MHAUS während einer MH-Krise kontraindiziert, und warum?", back: "Calciumkanalblocker (z.B. Verapamil, Diltiazem). In Kombination mit Dantrolen können sie Hyperkaliämie, schwere Myokarddepression und Kreislaufstillstand auslösen. Rhythmusstörungen bessern sich meist durch Behandlung von Azidose und Hyperkaliämie. Sonst werden Standard-Antiarrhythmika nach ACLS eingesetzt (z.B. Amiodaron, Betablocker)." },
  { id: "fc-ll-369", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "MHAUS (Maligne Hyperthermie)", front: "Wie viel Dantrolen soll laut MHAUS in jeder Einrichtung vorgehalten werden, in der MH-Trigger eingesetzt werden?", back: "36 Durchstechflaschen Dantrium/Revonto (je 20 mg, jeweils in 60 ml sterilem Wasser zu lösen; zusammen 720 mg) oder 3 Durchstechflaschen Ryanodex (je 250 mg, in 5 ml sterilem Wasser zu lösen). Das reicht für die Initialbehandlung eines ca. 70–100 kg schweren Erwachsenen. Das Dantrolen muss so gelagert sein, dass die erste Dosis rasch (Richtwert: innerhalb von etwa 10 Minuten nach der Therapieentscheidung) gegeben werden kann." },
  { id: "fc-ll-370", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "MHAUS (Maligne Hyperthermie)", front: "Wie wird Dantrolen laut MHAUS nach Kontrolle der akuten MH-Krise weiter dosiert, und wann kann es beendet werden?", back: "Erhaltungsdosis 1 mg/kg alle 4–6 Stunden oder als Infusion 0,25 mg/kg/h für mindestens 24 Stunden. Absetzen oder Intervall auf 8–12 h verlängern, wenn: Stoffwechsel 24 h stabil, Kerntemperatur <38 °C, CK fallend, keine Myoglobinurie mehr und Muskelrigidität verschwunden. Hintergrund ist das Risiko eines Rezidivs (Recrudescence)." },
  { id: "fc-ll-371", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", guideline: "WHO Global Guidelines (Surgical Site Infection)", front: "Was empfiehlt die WHO-Leitlinie zur SSI-Prävention bei bekannten nasalen Staphylococcus-aureus-Trägern vor herzthorax- und orthopädischen Eingriffen?", back: "Perioperative intranasale Anwendung von Mupirocin-2 %-Salbe, mit oder ohne Chlorhexidin-Körperwaschung (starke Empfehlung, moderate Evidenz). Für bekannte S.-aureus-Träger bei anderen Eingriffen soll dieselbe Dekolonisation erwogen werden (bedingte Empfehlung)." },
  { id: "fc-ll-372", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", guideline: "WHO Global Guidelines (Surgical Site Infection)", front: "Was empfiehlt die WHO-Leitlinie zur präoperativen Darmvorbereitung vor elektiver kolorektaler Chirurgie bei Erwachsenen?", back: "Eine mechanische Darmvorbereitung soll mit präoperativen oralen Antibiotika kombiniert werden (bedingte Empfehlung, moderate Evidenz). Eine mechanische Darmvorbereitung allein, ohne orale Antibiotika, soll nicht durchgeführt werden (starke Empfehlung, moderate Evidenz), da sie die SSI-Rate nicht senkt." },
  { id: "fc-ll-373", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", guideline: "WHO Global Guidelines (Surgical Site Infection)", front: "Welche Empfehlung gibt die WHO-Leitlinie zur intraoperativen Spülung der Inzisionswunde vor dem Wundverschluss?", back: "Eine Spülung der Inzisionswunde mit wässriger Povidon-Iod-Lösung vor dem Verschluss kann erwogen werden, vor allem bei sauberen und sauber-kontaminierten Wunden (bedingte Empfehlung). Von einer Wundspülung mit Antibiotika-Lösungen wird abgeraten (bedingte Empfehlung)." },
  { id: "fc-ll-374", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", guideline: "WHO Global Guidelines (Surgical Site Infection)", front: "Welche zwei im OP verbreiteten Maßnahmen sollen laut WHO-Leitlinie NICHT zur SSI-Prävention eingesetzt werden: Belüftungstechnik und Abdeckmaterial?", back: "(1) Laminar-Airflow-Belüftungssysteme sollen nicht mit dem Ziel eingesetzt werden, SSI bei totaler Gelenkendoprothetik zu senken (bedingte Empfehlung). (2) Selbstklebende Plastik-Inzisionsfolien, mit oder ohne antimikrobielle Beschichtung, sollen nicht zur SSI-Prävention verwendet werden (bedingte Empfehlung). Für beide fehlt ein Nutzennachweis." },
  { id: "fc-ll-375", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", guideline: "WHO Global Guidelines (Surgical Site Infection)", front: "Was empfiehlt die WHO-Leitlinie zu Antibiotikaprophylaxe bei liegenden Wunddrainagen und zu immunsuppressiver Dauermedikation vor Operationen?", back: "Die Antibiotikaprophylaxe soll nicht verlängert werden, nur weil eine Wunddrainage liegt. Drainagen werden entfernt, sobald es klinisch vertretbar ist. Immunsuppressiva sollen nicht allein zur SSI-Prävention präoperativ abgesetzt werden (jeweils bedingte Empfehlungen, niedrige bzw. sehr niedrige Evidenz)." },
  { id: "fc-ll-376", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "CPOC/JBDS (Perioperatives Diabetes-Management), Update 2026 (Levy et al., Anaesthesia 2026)", front: "Welcher HbA1c-Grenzwert gilt nach CPOC als Anlass, die Diabeteseinstellung vor einem elektiven Eingriff zu optimieren?", back: "Ein HbA1c >69 mmol/mol (ca. 8,5 %). Das HbA1c soll bei Überweisung zur Operation vorliegen und nicht älter als 3 Monate sein. Liegt es über 69 mmol/mol, soll die Einstellung vor elektiven Eingriffen möglichst verbessert werden. Zeitkritische Eingriffe (z.B. Tumorchirurgie) werden deswegen aber nicht aufgeschoben." },
  { id: "fc-ll-377", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "CPOC/JBDS (Perioperatives Diabetes-Management), Update 2026 (Levy et al., Anaesthesia 2026)", front: "Wie wird ein lang wirksames Basalinsulin (1× täglich) laut CPOC/JBDS perioperativ angepasst, und welcher Grundsatz gilt für Typ-1-Diabetiker?", back: "Das Basalinsulin wird am Vortag und am OP-Tag mit etwa 80 % der üblichen Dosis weitergegeben (Reduktion um 20 %), auch während einer VRIII. Menschen mit Typ-1-Diabetes dürfen nie ohne Insulin sein: Ein vollständiges Absetzen führt innerhalb von Stunden zur diabetischen Ketoazidose." },
  { id: "fc-ll-378", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "CPOC/JBDS (Perioperatives Diabetes-Management), Update 2026 (Levy et al., Anaesthesia 2026)", front: "Wie werden Sulfonylharnstoffe und Metformin laut CPOC am OP-Tag gehandhabt (bei kurzer Nüchternphase, max. eine ausgelassene Mahlzeit)?", back: "Sulfonylharnstoffe (z.B. Gliclazid) werden am OP-Tag pausiert, bis wieder gegessen wird, wegen des Hypoglykämierisikos im Nüchternzustand. Metformin wird bei 1–2× täglicher Einnahme normal weitergenommen, bei 3× täglicher Einnahme entfällt die Mittagsdosis. Bei eingeschränkter Nierenfunktion oder geplanter Kontrastmittelgabe wird Metformin pausiert." },
  { id: "fc-ll-379", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "CPOC/JBDS (Perioperatives Diabetes-Management), Update 2026 (Levy et al., Anaesthesia 2026)", front: "Wie wird eine perioperative Hypoglykämie (<4 mmol/l bzw. <72 mg/dl) bei einem nüchternen Diabetiker laut CPOC/JBDS behandelt?", back: "Ist orale Aufnahme erlaubt: 15–20 g schnell wirksame Kohlenhydrate (z.B. klarer, zuckerhaltiger Saft). Bei Nüchternheit/Narkose: i.v. Glukose, z.B. 75–100 ml Glukose 20 % oder 150–200 ml Glukose 10 % über etwa 15 Minuten. Nach 10–15 Minuten BZ kontrollieren und bei Bedarf wiederholen. Eine laufende Insulininfusion wird nicht einfach ohne Glukosezufuhr gestoppt, und die Ursache wird gesucht." },
  { id: "fc-ll-380", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "CPOC/JBDS (Perioperatives Diabetes-Management), Update 2026 (Levy et al., Anaesthesia 2026)", front: "Unter welchen Voraussetzungen kann eine Insulinpumpe (CSII) laut CPOC perioperativ weiterlaufen, und wie oft wird der Blutzucker intraoperativ kontrolliert?", back: "Die Pumpe kann bei kurzer Nüchternphase (höchstens eine ausgelassene Mahlzeit) weiterlaufen, wenn Patient:in bzw. Team die Pumpe sicher steuern kann und sie fern vom OP-Feld und von Elektrokauter liegt. Sonst wird auf eine VRIII umgestellt. Intraoperativ und im Aufwachraum wird der kapilläre Blutzucker mindestens stündlich kontrolliert (Ziel 6–10 mmol/l, bis 12 mmol/l akzeptabel)." },
  { id: "fc-ll-381", module: "intensivmedizin", subtopic: "sedierung-delir", guideline: "PADIS-Leitlinien (Sedierung & Delir)", front: "Wie soll Schmerz bei Intensivpatienten laut PADIS-Leitlinien erfasst werden, und welche Rolle spielen Vitalparameter?", back: "Goldstandard ist die Selbstauskunft (z.B. NRS 0–10). Kann der Patient sich nicht äußern, aber motorische Reaktionen zeigen, werden validierte Verhaltensskalen genutzt: Behavioral Pain Scale (BPS/BPS-NI) oder Critical-Care Pain Observation Tool (CPOT). Vitalparameter (HF, RR, AF, SpO2) sind kein valider Schmerzindikator. Sie dienen nur als Anlass für eine gezielte Schmerzerhebung." },
  { id: "fc-ll-382", module: "intensivmedizin", subtopic: "sedierung-delir", guideline: "PADIS-Leitlinien (Sedierung & Delir)", front: "Welche Nicht-Opioid-Adjuvanzien schlagen die PADIS-Leitlinien (2018) zur opioidsparenden Analgesie bei Intensivpatienten vor, und welche nicht?", back: "Vorgeschlagen: Paracetamol als Adjuvans zu Opioiden; niedrig dosiertes Ketamin (z.B. 0,5 mg/kg Bolus, dann 1–2 µg/kg/min) bei postoperativen Intensivpatienten; Neuropathie-Medikamente (Gabapentin, Pregabalin, Carbamazepin) bei neuropathischem Schmerz und nach kardiovaskulärer Chirurgie. Nicht routinemäßig: Lidocain i.v. und COX-1-selektive NSAR als Adjuvans." },
  { id: "fc-ll-383", module: "intensivmedizin", subtopic: "sedierung-delir", guideline: "PADIS-Leitlinien (Sedierung & Delir), Focused Update 2025", front: "Welche Empfehlungen geben die aktuellen PADIS-Leitlinien zur medikamentösen Prävention und Therapie des Delirs, und wann ist Dexmedetomidin vorgesehen?", back: "Weder Haloperidol noch atypische Antipsychotika, Dexmedetomidin, Statine oder Ketamin sollen routinemäßig zur Delir-PRÄVENTION gegeben werden. Zur Delir-BEHANDLUNG: Haloperidol/Atypika weiterhin nicht routinemäßig; das Focused Update 2025 gibt zum Einsatz von Antipsychotika bei manifestem Delir inzwischen bewusst KEINE Empfehlung dafür oder dagegen mehr ab (statt der früheren klaren Ablehnung) – Einzelfallentscheidung. Dexmedetomidin wird bei beatmeten Patienten vorgeschlagen, deren Agitation (Delir) das Weaning bzw. die Extubation verhindert." },
  { id: "fc-ll-384", module: "intensivmedizin", subtopic: "sedierung-delir", guideline: "PADIS-Leitlinien (Sedierung & Delir)", front: "Welche neuen bedingten Empfehlungen enthält das SCCM-PADIS-Focused-Update 2025?", back: "(1) Dexmedetomidin statt Propofol zur Sedierung beatmeter Erwachsener, wenn leichte Sedierung und/oder Delirreduktion im Vordergrund stehen. (2) Intensivierte Mobilisation/Rehabilitation statt üblicher Mobilisation. (3) Gabe von Melatonin statt keinem Melatonin. Zu Benzodiazepinen gegen Angst und zu Antipsychotika zur Delirbehandlung konnte das Panel mangels Evidenz keine Empfehlung aussprechen." },
  { id: "fc-ll-385", module: "intensivmedizin", subtopic: "sedierung-delir", guideline: "PADIS-Leitlinien (Sedierung & Delir)", front: "Welche Empfehlungen zur Schlafförderung auf der Intensivstation geben die PADIS-Leitlinien über die Lärm- und Lichtreduktion hinaus?", back: "Ein multimodales, schlafförderndes Protokoll einsetzen. Bei beatmeten Patienten nachts eine assistiert-kontrollierte Beatmung wählen (statt Druckunterstützung), um Schlaffragmentierung durch Apnoen/Asynchronie zu verringern. Propofol nicht gezielt zur Schlafverbesserung einsetzen, da es die physiologische Schlafarchitektur unterdrückt. Seit dem Update 2025 wird Melatonin vorgeschlagen." },
  { id: "fc-ll-386", module: "notfall-reanimation", subtopic: "trauma", guideline: "ATLS (Advanced Trauma Life Support)", front: "Welche strukturelle Änderung des Primary Survey führte die 11. ATLS-Auflage (2025) ein?", back: "Das ABCDE-Schema wurde zu xABCDE erweitert. 'x' steht für die sofortige Kontrolle exsanguinierender (lebensbedrohlicher äußerer) Blutungen, z.B. durch direkten Druck, Tourniquet oder hämostatische Verbände, noch vor Airway. Dahinter steht ein stärker physiologieorientiertes Vorgehen, weil Verbluten die häufigste vermeidbare frühe Traumatodesursache ist." },
  { id: "fc-ll-387", module: "notfall-reanimation", subtopic: "trauma", guideline: "ATLS (Advanced Trauma Life Support)", front: "Welche initiale Kristalloidmenge empfiehlt ATLS (11. Auflage 2025) beim hämorrhagischen Schock, und wie geht es danach weiter?", back: "Initial höchstens etwa 1 l isotone Lösung beim Erwachsenen (Kinder <40 kg: 20 ml/kg), statt früher 2 l. Mehr als ca. 1,5 l Kristalloid ist mit höherer Mortalität verbunden. Danach folgt eine frühe balancierte Transfusion (Erythrozyten:Plasma:Thrombozyten ca. 1:1:1) mit permissiver Hypotension bis zur Blutungskontrolle. Kristalloide dienen nur als Überbrückung, bis Blutprodukte da sind." },
  { id: "fc-ll-388", module: "notfall-reanimation", subtopic: "trauma", guideline: "ATLS (Advanced Trauma Life Support), 11. Auflage 2025", front: "Wann und wie wird Tranexamsäure laut ATLS bei blutenden Traumapatienten gegeben?", back: "Innerhalb von 3 Stunden nach dem Trauma (je früher, desto besser; nach 3 h kein Nutzen bzw. möglicher Schaden): 1 g i.v. über 10 Minuten, danach 1 g über 8 Stunden (CRASH-2-Schema). Die erste Dosis kann bereits präklinisch gegeben werden. Bei begleitendem Schädel-Hirn-Trauma wird (CRASH-3-Daten) als Alternative auch ein rascherer 2-g-Bolus diskutiert/erwogen." },
  { id: "fc-ll-389", module: "notfall-reanimation", subtopic: "trauma", guideline: "ATLS (Advanced Trauma Life Support)", front: "An welcher Stelle wird laut ATLS (11. Auflage 2025) die Nadeldekompression eines Spannungspneumothorax beim Erwachsenen durchgeführt, und wo bei Kindern?", back: "Erwachsene: 4./5. Interkostalraum knapp vor der mittleren Axillarlinie. Dort ist die Thoraxwand dünner als im 2. ICR medioklavikulär, und Nadeln verfehlen den Pleuraraum seltener. Kinder: weiterhin 2. ICR in der Medioklavikularlinie. Danach folgt immer eine definitive Thoraxdrainage." },
  { id: "fc-ll-390", module: "notfall-reanimation", subtopic: "trauma", guideline: "ATLS (Advanced Trauma Life Support)", front: "Welche Drainagemengen definieren laut ATLS einen massiven Hämatothorax mit Indikation zur Thorakotomie, und welche Drainagegröße wird empfohlen?", back: "Sofortige Blutmenge von >1500 ml nach Anlage der Thoraxdrainage oder anhaltend >200 ml/h über 2–4 Stunden, bzw. anhaltender Transfusionsbedarf. Dann soll eine (dringliche) Thorakotomie erwogen werden. Für den Hämatothorax empfiehlt ATLS (seit der 10., unverändert in der 11. Auflage 2025) eine Drainage von 28–32 Fr (statt früher 36–40 Fr)." },
  { id: "fc-ll-391", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "NAP6-Leitlinie (Perioperative Anaphylaxie)", front: "Welche Erstsymptome perioperativer Anaphylaxie waren in NAP6 am häufigsten, und welche Konsequenz ergibt sich daraus?", back: "Häufigstes Erstsymptom war die Hypotonie (46 %), dann Bronchospasmus (18 %), Tachykardie (ca. 10 %), Entsättigung (ca. 5 %), Bradykardie (3 %) und abgeschwächte/fehlende Kapnographiekurve (ca. 2 %). Hautsymptome fehlten oft oder traten verzögert auf. Konsequenz: Bei unerklärter schwerer Hypotonie oder Bronchospasmus in Narkose früh an Anaphylaxie denken, auch ohne Exanthem." },
  { id: "fc-ll-392", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "NAP6-Leitlinie (Perioperative Anaphylaxie)", front: "Welches Antibiotikum fiel in NAP6 durch ein unverhältnismäßig hohes Anaphylaxierisiko auf, und welche Rolle spielte dabei die Penicillinallergie-Anamnese?", back: "Teicoplanin: nur ca. 12 % der Antibiotika-Expositionen, aber ca. 38 % der antibiotikabedingten Anaphylaxien; die Inzidenz lag bei ca. 16/100.000 Gaben, deutlich über Penicillinen. Es wurde oft als Alternative bei angeblicher Penicillinallergie gegeben, obwohl die meisten solchen 'Allergie-Labels' falsch sind. Daraus folgt: aktive Abklärung und De-Labelling von Penicillinallergien." },
  { id: "fc-ll-393", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "NAP6-Leitlinie (Perioperative Anaphylaxie)", front: "Warum wird Chlorhexidin als Auslöser perioperativer Anaphylaxie laut NAP6 häufig übersehen, und was folgt daraus?", back: "In NAP6 verursachte Chlorhexidin 18 Fälle (ca. 9 %), wurde vom Anästhesieteam aber nur in etwa 28 % als möglicher Auslöser erkannt. Es steckt oft 'versteckt' in Produkten wie beschichteten ZVKs, Gleitgelen für Blasenkatheter oder Hautantiseptika. Chlorhexidin soll bei jeder Reaktion als Auslöser erwogen werden. Chlorhexidinhaltige Produkte sollen klar gekennzeichnet sein, und bei bekannter Allergie wird eine chlorhexidinfreie Umgebung geschaffen." },
  { id: "fc-ll-394", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "NAP6-Leitlinie (Perioperative Anaphylaxie)", front: "Welche Besonderheit im zeitlichen Verlauf zeigen Anaphylaxien durch Patentblau (z.B. bei Sentinel-Lymphknoten-Markierung) laut NAP6?", back: "Sie treten oft verzögert auf (häufig erst 30 Minuten oder später nach der Injektion) und können lange anhalten. Deshalb werden sie leicht anderen, zeitnah gegebenen Substanzen zugeschrieben. Patentblau muss bei verzögerten Reaktionen gezielt bedacht werden. Patient:innen sollen vorab über das Risiko informiert werden, ebenso über die harmlose Blau-/Grünverfärbung von Haut und Urin." },
  { id: "fc-ll-395", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "NAP6-Leitlinie (Perioperative Anaphylaxie)", front: "Welche Inzidenz, Letalität und Risikofaktoren für einen ungünstigen Verlauf ergab NAP6 für schwere perioperative Anaphylaxien?", back: "Inzidenz ca. 1:10.000 Anästhesien. Unter 266 schweren Fällen (Grad 3–5) gab es 40 Kreislaufstillstände und 10 Todesfälle (ca. 4 %). Die Arrests waren meist PEA, oft mit vorangehender Bradykardie. Risikofaktoren für schlechtes Outcome: höhere ASA-Klasse, Adipositas, KHK sowie Einnahme von Betablockern und/oder ACE-Hemmern. Asthma war kein Risikofaktor für einen tödlichen Verlauf." },
  { id: "fc-ll-396", module: "spezielle-anaesthesie", subtopic: "neuroanaesthesie", guideline: "Brain Trauma Foundation Guidelines (4. Auflage)", front: "Welche altersabhängigen systolischen Blutdruck-Untergrenzen empfiehlt die Brain Trauma Foundation (4. Auflage) bei schwerem Schädel-Hirn-Trauma?", back: "Systolisch ≥100 mmHg bei Patienten von 50–69 Jahren und ≥110 mmHg bei Patienten von 15–49 Jahren oder über 70 Jahren (Level III). Schon einzelne hypotensive Episoden verschlechtern das neurologische Outcome und erhöhen die Mortalität deutlich." },
  { id: "fc-ll-397", module: "spezielle-anaesthesie", subtopic: "neuroanaesthesie", guideline: "Brain Trauma Foundation Guidelines (4. Auflage)", front: "Was empfiehlt die Brain Trauma Foundation (4. Auflage) zur Hyperventilation bei schwerem SHT?", back: "Eine prolongierte prophylaktische Hyperventilation auf PaCO2 ≤25 mmHg wird nicht empfohlen (Level IIB). Hyperventilation darf nur kurzfristig zur Überbrückung einer akuten ICP-Krise eingesetzt werden. In den ersten 24 h nach dem Trauma soll sie vermieden werden, weil die Hirndurchblutung dann oft kritisch reduziert ist. Wird hyperventiliert, sollen jugularvenöse Sättigung (SjO2) oder Hirngewebs-pO2 (PbtO2) zur Ischämie-Erkennung überwacht werden." },
  { id: "fc-ll-398", module: "spezielle-anaesthesie", subtopic: "neuroanaesthesie", guideline: "Brain Trauma Foundation Guidelines (4. Auflage)", front: "Wie bewertet die Brain Trauma Foundation (4. Auflage) Kortikosteroide bei schwerem Schädel-Hirn-Trauma?", back: "Kortikosteroide werden zur Verbesserung des Outcomes oder zur ICP-Senkung nicht empfohlen (Level I). In der großen CRASH-Studie erhöhte hochdosiertes Methylprednisolon die Mortalität. Hochdosiertes Methylprednisolon ist beim schweren SHT deshalb kontraindiziert." },
  { id: "fc-ll-399", module: "spezielle-anaesthesie", subtopic: "neuroanaesthesie", guideline: "Brain Trauma Foundation Guidelines (4. Auflage)", front: "Welche Empfehlungen gibt die Brain Trauma Foundation (4. Auflage) zu Barbituraten und Propofol beim schweren SHT?", back: "Barbiturate zur prophylaktischen EEG-Burst-Suppression, um einer ICP-Erhöhung vorzubeugen, werden nicht empfohlen. Hochdosierte Barbiturate sind für einen trotz maximaler Standardtherapie refraktären ICP vorgesehen, bei hämodynamischer Stabilität. Propofol wird zur ICP-Kontrolle empfohlen, verbessert aber nachweislich weder Mortalität noch 6-Monats-Outcome. Hochdosiertes Propofol kann erhebliche Morbidität verursachen (Propofol-Infusionssyndrom)." },
  { id: "fc-ll-400", module: "spezielle-anaesthesie", subtopic: "neuroanaesthesie", guideline: "Brain Trauma Foundation Guidelines (4. Auflage)", front: "Bis wann soll laut Brain Trauma Foundation (4. Auflage) beim schweren SHT eine Ernährung mit mindestens basalem Kalorienersatz erreicht sein, und welcher Zugangsweg wird zur VAP-Reduktion empfohlen?", back: "Der basale Kalorienbedarf soll frühestens am 5. und spätestens am 7. Tag nach dem Trauma gedeckt sein (Level IIA, senkt die Mortalität). Eine transgastrale jejunale Ernährung wird empfohlen, um beatmungsassoziierte Pneumonien (VAP) zu reduzieren (Level IIB)." },
  { id: "fc-ll-401", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "Resuscitation Council UK (Perioperative Anaphylaxie)", front: "Welche Adrenalin-Dosis und welcher Applikationsweg sind laut Resuscitation Council UK vorgesehen, wenn bei Anaphylaxie (noch) kein i.v.-Zugang bzw. kein erfahrenes Personal für titriertes i.v.-Adrenalin verfügbar ist?", back: "Adrenalin intramuskulär in den anterolateralen Oberschenkel: Erwachsene und Kinder >12 Jahre 500 µg (0,5 ml der 1:1000-Lösung). Wiederholung nach etwa 5 Minuten, wenn keine Besserung eintritt. Titriertes i.v.-Adrenalin bleibt Erfahrenen mit kontinuierlichem Monitoring vorbehalten, typischerweise dem Anästhesieteam im OP." },
  { id: "fc-ll-402", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "Resuscitation Council UK (Perioperative Anaphylaxie)", front: "Welche Schritte der unmittelbaren Nachsorge nach perioperativer Anaphylaxie sieht der RCUK-Algorithmus vor?", back: "Tryptase-Proben abnehmen (so bald wie möglich, nach 1–2 h und Basalwert nach ≥24 h). Über Fortsetzung oder Abbruch des Eingriffs gemeinsam mit den Operateuren entscheiden (bei nicht dringlichen Eingriffen meist Abbruch). Weiterbehandlung auf Intensiv- oder Überwachungsstation festlegen. Patient:in und Hausarzt informieren, das Ereignis an die Arzneimittelbehörde melden und an eine spezialisierte Allergieklinik überweisen." },
  { id: "fc-ll-403", module: "spezielle-anaesthesie", subtopic: "kinderanaesthesie", guideline: "APAGBI-Leitlinie (Kinderanästhesie)", front: "Was gilt im APAGBI-/ESPA-Konsensus zur 1-Stunden-Nüchternheitsregel als 'klare Flüssigkeit', und sollen Kinder zum Trinken ermutigt werden?", back: "Klare Flüssigkeiten sind z.B. Wasser, verdünnter Fruchtsirup (Squash) und klarer Saft ohne Fruchtfleisch. Milch und milchhaltige Getränke zählen nicht dazu. Kinder ohne Kontraindikation sollen bis 1 Stunde vor der elektiven Narkose nicht nur trinken dürfen, sondern ausdrücklich dazu ermutigt werden." },
  { id: "fc-ll-404", module: "spezielle-anaesthesie", subtopic: "kinderanaesthesie", guideline: "APAGBI-Leitlinie (Kinderanästhesie)", front: "Wie wird ein Laryngospasmus bei schwieriger Maskenbeatmung eines Kindes (1–8 Jahre) nach dem APA/DAS-Algorithmus behandelt?", back: "Hilfe rufen, 100 % O2 mit CPAP über dicht sitzende Maske, Atemweg optimieren (Kopfposition, Esmarch-Handgriff, ggf. oropharyngealer Tubus) und die Narkose vertiefen (z.B. Propofol i.v.). Bei Persistenz und Entsättigung wird relaxiert (z.B. Succinylcholin, ggf. mit Atropin gegen Bradykardie) und anschließend beatmet bzw. intubiert." },
  { id: "fc-ll-405", module: "spezielle-anaesthesie", subtopic: "kardio-thorax", guideline: "ERAS-Cardiac-Society/STS-Konsensus 2024", front: "Welche Themen der ERAS-Cardiac-Empfehlungen von 2019 wurden im Konsensus 2024 nicht mehr behandelt?", back: "U.a. Tranexamsäure/ε-Aminocapronsäure, Thoraxdrainagen-Management (Durchgängigkeit), medikamentöse Thromboseprophylaxe sowie Rauchen/Alkoholkarenz. Diese Maßnahmen wurden nicht als unwirksam eingestuft, sondern im Konsensus 2024 nicht mehr adressiert, zugunsten neuer Elemente wie lungenprotektiver Beatmung, PBM, POAF-Prävention und ZNS-Monitoring." },
  { id: "fc-ll-406", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", guideline: "ASH-Leitlinie 2019 (VTE-Prophylaxe)", front: "Was empfiehlt die ASH-Leitlinie 2019 zur VTE-Prophylaxe nach schwerem Trauma bei niedrigem bis moderatem Blutungsrisiko?", back: "Medikamentöse Prophylaxe gegenüber keiner medikamentösen Prophylaxe (bedingte Empfehlung). Als Wirkstoffe werden NMH oder UFH vorgeschlagen. Bei hohem Blutungsrisiko wird zunächst mechanisch prophylaktiert und die medikamentöse Prophylaxe begonnen, sobald das Blutungsrisiko es erlaubt." },
  { id: "fc-ll-407", module: "spezielle-anaesthesie", subtopic: "orthopaedie-gefaesschirurgie", guideline: "ASH-Leitlinie 2019 (VTE-Prophylaxe)", front: "Wie positioniert sich die ASH-Leitlinie 2019 zur medikamentösen VTE-Prophylaxe bei Herzchirurgie und großer Gefäßchirurgie?", back: "Die ASH schlägt vor, entweder medikamentös oder nicht medikamentös zu prophylaktieren (bedingte Empfehlung, individuelle Entscheidung). Hintergrund sind das relevante Blutungsrisiko und die ohnehin meist erfolgende perioperative Antikoagulation bzw. Thrombozytenhemmung. Wird medikamentös prophylaktiert, werden NMH oder UFH vorgeschlagen." },
  { id: "fc-ll-408", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "ESC/ESAIC-Leitlinie 2022 (Perioperatives kardiovaskuläres Management)", front: "Wie lange vor einem elektiven Eingriff sollen P2Y12-Inhibitoren laut ESC/ESAIC-Leitlinie 2022 pausiert werden, wenn eine Unterbrechung nötig ist?", back: "Ticagrelor 3–5 Tage, Clopidogrel 5 Tage, Prasugrel 7 Tage vor dem Eingriff. Nach Stentimplantation wird Acetylsalicylsäure perioperativ möglichst fortgeführt, wenn das Blutungsrisiko es erlaubt (Klasse I). Der P2Y12-Inhibitor wird nach gesicherter Hämostase möglichst früh (innerhalb von ca. 24–48 h) wieder angesetzt." },
  { id: "fc-ll-409", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "ESC/ESAIC-Leitlinie 2022 (Perioperatives kardiovaskuläres Management)", front: "Was empfiehlt die ESC/ESAIC-Leitlinie 2022 bei neu aufgetretenem postoperativem Vorhofflimmern (POAF) nach nicht-kardiochirurgischem Eingriff?", back: "POAF gilt nicht als harmloses, rein vorübergehendes Ereignis, weil es mit erhöhtem Schlaganfallrisiko verbunden ist. Bei Patienten mit erhöhtem thromboembolischem Risiko sollte eine langfristige orale Antikoagulation erwogen werden (IIa). Dabei werden der erwartete Netto-Nutzen und die Präferenz der informierten Patient:innen berücksichtigt." },
  { id: "fc-ll-410", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "ASA/ASRA Acute Pain Management Guideline", front: "Wann empfiehlt die APS/ASRA/ASA-Leitlinie (2016) eine kontinuierliche periphere Katheteranalgesie statt einer Single-Shot-Blockade, und welches Adjuvans kann die Single-Shot-Blockade verlängern?", back: "Kontinuierliche, lokalanästhetikabasierte periphere Katheterverfahren werden empfohlen, wenn der Analgesiebedarf voraussichtlich länger dauert als die Wirkung einer Einzelinjektion (stark, moderat). Zur Verlängerung einer Single-Shot-Blockade kann Clonidin als Adjuvans erwogen werden (schwach, moderat)." },
  { id: "fc-ll-411", module: "regional-schmerz", subtopic: "schmerztherapie", guideline: "ASA/ASRA Acute Pain Management Guideline", front: "Welche nicht-medikamentösen Verfahren und organisatorischen Maßnahmen empfiehlt die APS/ASRA/ASA-Leitlinie (2016) ergänzend?", back: "Erwägen: kognitiv-behaviorale Verfahren und TENS als Ergänzung (schwache Empfehlungen). Zu Akupunktur, Massage und Kältetherapie gibt die Leitlinie keine Empfehlung. Organisatorisch: präoperative Erhebung von Begleiterkrankungen, Vormedikation, chronischen Schmerzen und Substanzgebrauch; altersgerechte Patientenschulung; bei Entlassung Aufklärung über Ausschleichen, sichere Lagerung und Entsorgung von Opioiden; Zugang zu Schmerzspezialisten bei unzureichender Kontrolle." },
  { id: "fc-ll-412", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "MHAUS (Maligne Hyperthermie)", front: "Welche Empfehlungen gibt MHAUS bei einer Masseter-Rigidität (Trismus) nach Succinylcholin?", back: "Die Masseter-Rigidität kann ein Frühzeichen einer MH sein. Der Eingriff wird entweder abgebrochen/verschoben oder triggerfrei fortgesetzt (volatile Anästhetika stoppen). Danach wird engmaschig auf MH-Zeichen überwacht (etCO2, Temperatur, Rigidität, Azidose). Eine Rhabdomyolyse ist zu erwarten: Überwachung über Nacht mit Kontrollen von CK (Gipfel nach ca. 12–24 h), Kalium und Urin-Myoglobin. Anschließend werden Patient:in und ggf. Familie zur MH-Diagnostik überwiesen." },
  { id: "fc-ll-413", module: "allgemeinanaesthesie", subtopic: "narkosefuehrung", guideline: "MHAUS (Maligne Hyperthermie)", front: "Welche klinischen Zeichen einer malignen Hyperthermie treten laut MHAUS früh auf, und welches ist typischerweise ein spätes Zeichen?", back: "Früh: unerklärter Anstieg des etCO2 trotz gesteigerter Ventilation, Tachykardie, Masseter- bzw. generalisierte Muskelrigidität, Tachypnoe (bei Spontanatmung) sowie gemischte respiratorisch-metabolische Azidose. Die Hyperthermie selbst ist oft ein spätes Zeichen. Auf ihr Auftreten darf mit der Dantrolen-Gabe nicht gewartet werden." },
  { id: "fc-ll-414", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", guideline: "WHO Global Guidelines (Surgical Site Infection)", front: "Welche Empfehlungen gibt die WHO-Leitlinie zu Triclosan-beschichtetem Nahtmaterial und zur prophylaktischen Unterdruck-Wundtherapie (NPWT)?", back: "Triclosan-beschichtetes Nahtmaterial kann unabhängig von der Art des Eingriffs zur SSI-Senkung eingesetzt werden (bedingte Empfehlung, moderate Evidenz). Eine prophylaktische NPWT kann auf primär verschlossenen Inzisionen bei Hochrisiko-Wunden erwogen werden, unter Berücksichtigung der Ressourcen (bedingte Empfehlung, niedrige Evidenz)." },
  { id: "fc-ll-415", module: "periop-sicherheit-ethik", subtopic: "patientensicherheit", guideline: "WHO Global Guidelines (Surgical Site Infection)", front: "Wie soll die chirurgische Händedesinfektion laut WHO-Leitlinie erfolgen?", back: "Vor dem Anziehen steriler Handschuhe entweder durch Waschen mit geeigneter antimikrobieller Seife und Wasser oder durch Einreiben eines geeigneten alkoholbasierten Händedesinfektionsmittels (starke Empfehlung, moderate Evidenz). Beide Verfahren gelten als gleichwertig. Alkoholische Präparate sind schneller und hautschonender." },
  { id: "fc-ll-416", module: "allgemeinanaesthesie", subtopic: "praeoperativ", guideline: "CPOC/JBDS (Perioperatives Diabetes-Management), Update 2026 (Levy et al., Anaesthesia 2026)", front: "Ab welchem Blutzuckerwert sollen laut JBDS/CPOC perioperativ Ketone kontrolliert werden, und warum ist das bei Typ-1-Diabetes besonders wichtig?", back: "Bei einem kapillären Blutzucker >12 mmol/l (ca. 216 mg/dl) sollen Blut- oder Urinketone bestimmt werden. Bei Typ-1-Diabetes (und unter SGLT2-Inhibitoren) kann sich perioperativ, z.B. durch Insulinmangel, Stress und Nüchternheit, rasch eine diabetische Ketoazidose entwickeln. Erhöhte Ketone erfordern eine Anpassung der Insulintherapie und ggf. die Behandlung nach DKA-Protokoll, bei elektiven Eingriffen meist mit Verschiebung." },
  { id: "fc-ll-417", module: "intensivmedizin", subtopic: "sedierung-delir", guideline: "PADIS-Leitlinien (Sedierung & Delir)", front: "Welche Risikofaktoren für ein Delir auf der Intensivstation nennen die PADIS-Leitlinien (2018), getrennt nach beeinflussbar und nicht beeinflussbar?", back: "Beeinflussbar: Benzodiazepin-Gabe und Bluttransfusionen. Nicht beeinflussbar: höheres Alter, Demenz, vorausgegangenes Koma, Notfalloperation oder Trauma vor der ICU-Aufnahme sowie höhere Krankheitsschwere (APACHE- und ASA-Score)." },
  { id: "fc-ll-418", module: "intensivmedizin", subtopic: "sedierung-delir", guideline: "PADIS-Leitlinien (Sedierung & Delir)", front: "Wie behandeln die PADIS-Leitlinien den Schmerz bei Prozeduren (z.B. Lagerung, Absaugen, Drainagenentfernung) auf der Intensivstation?", back: "Vor schmerzhaften Prozeduren wird ein Opioid in der niedrigsten wirksamen Dosis gegeben. Als Alternativen bzw. zur Opioideinsparung kommen u.a. NSAR (i.v., oral oder rektal) und lokale Verfahren in Frage. Nicht-medikamentöse Maßnahmen (z.B. Entspannungstechniken, Kälteanwendung, Musik) werden ergänzend eingesetzt." },
  { id: "fc-ll-419", module: "notfall-reanimation", subtopic: "trauma", guideline: "ATLS (Advanced Trauma Life Support)", front: "Wie wird der Base Deficit in der ATLS-Schockklassifikation (11. Auflage 2025) den vier Schockklassen zugeordnet?", back: "Klasse I: BD 0 bis −2 mmol/l. Klasse II: −2 bis −6 mmol/l. Klasse III: −6 bis −10 mmol/l. Klasse IV: unter −10 mmol/l. Der Base Deficit ergänzt die klinischen Parameter und hilft früh zu erkennen, ob Blutprodukte oder eine Massivtransfusion nötig werden." },
  { id: "fc-ll-420", module: "notfall-reanimation", subtopic: "trauma", guideline: "ATLS (Advanced Trauma Life Support)", front: "In welcher Höhe wird eine Beckenschlinge (Pelvic Binder) laut ATLS angelegt, und wozu dient sie?", back: "In Höhe der Trochanteres majores, nicht über den Beckenkämmen. Sie verkleinert das Beckenvolumen bei instabilen Beckenringverletzungen, stabilisiert die Frakturfragmente und reduziert dadurch venöse und spongiöse Blutungen. Sie ist eine Überbrückung bis zur definitiven Blutungskontrolle (Packing, Angioembolisation, externe Fixation)." },
  { id: "fc-ll-421", module: "notfall-reanimation", subtopic: "trauma", guideline: "ATLS (Advanced Trauma Life Support)", front: "Welche Indikationen für einen definitiven Atemweg (geblockter Endotrachealtubus) nennt ATLS?", back: "Atemwegsschutz: GCS ≤8, drohende Aspiration (Blut, Erbrochenes), schwere maxillofaziale Verletzungen, drohende Obstruktion (z.B. Inhalationstrauma, Halshämatom, Stridor). Ventilation/Oxygenierung: unzureichende Spontanatmung, Hypoxämie trotz O2, Apnoe, schwerer Schock oder Kreislaufstillstand. Vor der Intubation wird das Schädel-Hirn-Trauma möglichst kurz neurologisch dokumentiert." },
  { id: "fc-ll-422", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "NAP6-Leitlinie (Perioperative Anaphylaxie)", front: "Was zeigte NAP6 zu Antibiotika-Testdosen?", back: "18 Patienten reagierten bereits auf eine Antibiotika-Testdosis mit einer schweren Anaphylaxie. Eine kleine Testdosis schließt eine Anaphylaxie also nicht aus und kann selbst eine lebensbedrohliche Reaktion auslösen. Sie ist kein sicherer Ersatz für eine sorgfältige Allergieanamnese und die Bereitschaft, jederzeit eine Anaphylaxie zu behandeln." },
  { id: "fc-ll-423", module: "notfall-reanimation", subtopic: "anaphylaxie-transfusion", guideline: "NAP6-Leitlinie (Perioperative Anaphylaxie)", front: "Wer ist laut NAP6 für die Überweisung zur allergologischen Abklärung nach perioperativer Anaphylaxie verantwortlich, und was muss die Überweisung enthalten?", back: "Verantwortlich ist der Facharzt/die Fachärztin für Anästhesie, der/die den Patienten zum Zeitpunkt des Ereignisses betreut hat. Die Überweisung enthält die vollständige Medikation, eine genaue Beschreibung des Ereignisses und die exakten Zeitpunkte aller vor der Reaktion gegebenen Substanzen (inkl. Chlorhexidin, Latex, Farbstoffe), idealerweise auf einem standardisierten Formular (NAP6-/AAGBI-Vorlage)." },
  { id: "fc-ll-424", module: "spezielle-anaesthesie", subtopic: "neuroanaesthesie", guideline: "Brain Trauma Foundation Guidelines (4. Auflage)", front: "Was empfiehlt die Brain Trauma Foundation (4. Auflage) zur Anfallsprophylaxe nach schwerem SHT?", back: "Phenytoin wird zur Senkung früher posttraumatischer Anfälle (innerhalb der ersten 7 Tage) empfohlen, wenn der Nutzen die Nebenwirkungen überwiegt. Zur Prävention später Anfälle (>7 Tage) werden weder Phenytoin noch Valproat empfohlen. Für eine Überlegenheit von Levetiracetam gegenüber Phenytoin reichte die Evidenz nicht aus." },
  { id: "fc-ll-425", module: "spezielle-anaesthesie", subtopic: "neuroanaesthesie", guideline: "Brain Trauma Foundation Guidelines (4. Auflage)", front: "Wie unterscheidet das BTF-Update 2020 zur dekompressiven Kraniektomie zwischen früher und später refraktärer ICP-Erhöhung?", back: "Eine sekundäre Dekompression bei später refraktärer ICP-Erhöhung wird empfohlen, um Mortalität und günstiges Outcome zu verbessern (Level IIA, RESCUEicp). Eine sekundäre Dekompression bei früher refraktärer ICP-Erhöhung wird zur Verbesserung von Mortalität und Outcome nicht empfohlen (DECRA). Technisch wird eine große fronto-temporo-parietale Kraniektomie (mind. ca. 12 × 15 cm) bevorzugt." },
  { id: "fc-ll-426", module: "spezielle-anaesthesie", subtopic: "neuroanaesthesie", guideline: "Brain Trauma Foundation Guidelines (4. Auflage)", front: "Welche Empfehlungen gibt die Brain Trauma Foundation (4. Auflage) zur Liquordrainage über eine externe Ventrikeldrainage (EVD)?", back: "Eine auf Mittelhirnhöhe genullte EVD mit kontinuierlicher Liquordrainage kann erwogen werden, weil sie die ICP-Last wirksamer senkt als intermittierende Drainage. Bei initialem GCS <6 kann eine Liquordrainage in den ersten 12 Stunden nach dem Trauma zur ICP-Senkung erwogen werden. Antimikrobiell imprägnierte Katheter können zur Infektionsprävention erwogen werden." },
  { id: "fc-ll-427", module: "spezielle-anaesthesie", subtopic: "neuroanaesthesie", guideline: "Brain Trauma Foundation Guidelines (4. Auflage)", front: "Was empfiehlt die Brain Trauma Foundation (4. Auflage) zur Thromboseprophylaxe und zur Mundpflege mit Povidon-Iod bei schwerem SHT?", back: "Thromboseprophylaxe: Kompressionsstrümpfe bzw. mechanische Verfahren. NMH oder niedrig dosiertes UFH kann ergänzend eingesetzt werden, wenn die Hirnverletzung stabil ist und der Nutzen das Risiko einer Blutungsprogression überwiegt. Mundpflege mit Povidon-Iod zur VAP-Prävention wird nicht empfohlen, da sie das ARDS-Risiko erhöhen kann." },

  // ===== ERGÄNZUNGEN NACH INHALTLICHER LÜCKENANALYSE (Pylorusstenose, hintere
  // Schädelgrube/sitzende Position, Erector-spinae-Block, Karzinoid-Syndrom,
  // Fruchtwasserembolie, CRPS-Therapie) =====
  { id: "fc-spez-026", module: "spezielle-anaesthesie", subtopic: "kinderanaesthesie", front: "Ist die hypertrophe Pylorusstenose ein chirurgischer Notfall, und was muss vor der Narkose zwingend korrigiert werden?", back: "Nein – trotz des dramatischen klinischen Bildes (schwallartiges Erbrechen) ist sie KEIN Notfall, sondern eine internistische Dringlichkeit: Vor der Pyloromyotomie müssen Dehydratation und die typische hypochlorämische, hypokaliämische metabolische Alkalose (durch HCl- und Kaliumverlust im Erbrochenen) durch i.v.-Flüssigkeits- und Elektrolytkorrektur ausgeglichen werden. Operiert wird erst nach Normalisierung von Elektrolyten/Säure-Basen-Haushalt, nicht sofort bei Diagnosestellung." },
  { id: "fc-spez-027", module: "spezielle-anaesthesie", subtopic: "kinderanaesthesie", front: "Wie wird die Anästhesieeinleitung bei einem Säugling mit Pylorusstenose durchgeführt, und warum?", back: "Als Ileuseinleitung (Rapid Sequence Induction): Der Magen gilt trotz Nüchternheit als voll (Magenentleerungsstörung durch die Obstruktion), daher zuvor Magensonde legen und Mageninhalt großzügig absaugen (in mehreren Positionen), dann RSI mit Krikoiddruck zur Aspirationsprophylaxe." },
  { id: "fc-spez-028", module: "spezielle-anaesthesie", subtopic: "neuroanaesthesie", front: "Welche gefürchtete Komplikation ist mit der sitzenden Position bei Eingriffen an der hinteren Schädelgrube besonders assoziiert, und wie wird sie überwacht?", back: "Die venöse Luftembolie (VAE): Eröffnete, nicht kollabierende venöse Sinus/Diploe-Venen können bei negativem Druckgradienten (Kopf über Herzniveau) Luft ansaugen. Empfindlichstes Monitoring ist die präkordiale Doppler-Sonografie bzw. transösophageale Echokardiografie (TEE), dazu ein plötzlicher EtCO2-Abfall, Sättigungsabfall, Hypotonie und ggf. ein charakteristisches 'Mühlradgeräusch' auskultatorisch." },
  { id: "fc-spez-029", module: "spezielle-anaesthesie", subtopic: "neuroanaesthesie", front: "Was ist eine paradoxe Luftembolie, und warum ist sie bei der sitzenden Position besonders relevant?", back: "Bei einem persistierenden Foramen ovale (PFO, bei ca. 25–30% der Bevölkerung vorhanden) kann eingeschwemmte venöse Luft bei erhöhtem rechtsatrialem Druck auf die linke (arterielle) Seite übertreten und zu zerebraler/koronarer Luftembolie führen. Deshalb wird vor sitzenden Eingriffen häufig ein präoperativer PFO-Ausschluss (z.B. Kontrastmittel-Echokardiografie) diskutiert bzw. bei bekanntem PFO die sitzende Position eher gemieden." },
  { id: "fc-reg-031", module: "regional-schmerz", subtopic: "periphere-blockaden", front: "Was ist das Grundprinzip des Erector-spinae-plane-Blocks (ESP-Block), und wo wird injiziert?", back: "Ein Faszienebenen-Block (kein direkter Nervenblock): Lokalanästhetikum wird unter Ultraschallsicht tief unter den M. erector spinae, direkt auf den Querfortsatz der Wirbelsäule (meist auf Höhe der gewünschten Dermatome) injiziert. Von dort breitet sich das LA kraniokaudal in der Faszienebene aus und blockiert die ventralen und dorsalen Rami der Spinalnerven, wodurch sowohl somatische als auch teilweise viszerale Analgesie in Thorax und Abdomen erreicht wird." },
  { id: "fc-reg-032", module: "regional-schmerz", subtopic: "schmerztherapie", front: "Was sind die Grundpfeiler der Erstlinientherapie bei komplexem regionalem Schmerzsyndrom (CRPS)?", back: "Frühzeitige, aktive Physio-/Ergotherapie mit Fokus auf Bewegung und Desensibilisierung (nicht Ruhigstellung!), ergänzt durch Spiegeltherapie/Graded Motor Imagery zur Behandlung der zentralen Reorganisation. Medikamentös werden je nach Symptomatik u.a. Bisphosphonate (bei ausgeprägtem Knochenumbau), Gabapentinoide/trizyklische Antidepressiva bei neuropathischer Schmerzkomponente sowie kurzzeitig Kortikosteroide (v.a. in der warmen/entzündlichen Frühphase) eingesetzt. Invasive sympathische Blockaden gelten heute nur noch als Reserveoption bei unzureichendem Ansprechen." },
  { id: "fc-ga-031", module: "allgemeinanaesthesie", subtopic: "praeoperativ", front: "Was ist die Pathophysiologie des Karzinoid-Syndroms, und wann tritt es klinisch relevant in Erscheinung?", back: "Neuroendokrine Tumoren (meist gastrointestinal, seltener bronchial) sezernieren vasoaktive Substanzen (v.a. Serotonin, aber auch Histamin, Bradykinin, Tachykinine). Ein klinisches Karzinoid-Syndrom (Flush, Diarrhö, Bronchospasmus, rechtskardiale Klappenfibrose) tritt meist erst bei Lebermetastasierung auf, weil die Substanzen sonst über die Pfortader zur Leber gelangen und dort inaktiviert werden (First-Pass-Effekt)." },
  { id: "fc-ga-032", module: "allgemeinanaesthesie", subtopic: "praeoperativ", front: "Wie wird eine perioperative Karzinoid-Krise verhindert bzw. behandelt, und welche Medikamente sollten vermieden werden?", back: "Prophylaxe/Therapie: Octreotid (Somatostatin-Analogon) i.v. als Bolus/Infusion, präoperativ beginnend und bei hämodynamischer Instabilität/Tumormanipulation intraoperativ eskaliert – unterdrückt die Mediatorfreisetzung wirksam. VERMEIDEN werden sollten Histamin-freisetzende Substanzen (Morphin, Atracurium, Succinylcholin) und v.a. exogene Katecholamine/indirekte Sympathomimetika (Adrenalin, Noradrenalin, Ephedrin) zur Behandlung einer Hypotonie, da sie eine weitere Mediatorausschüttung und paradoxe Verschlechterung der Krise auslösen können – Volumengabe und Octreotid stehen im Vordergrund." },
  { id: "fc-spez-030", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", front: "Wie hat sich das Verständnis der Fruchtwasserembolie (FWE) gewandelt, und welche klinische Trias ist typisch?", back: "Der Begriff 'Embolie' ist irreführend: Heute wird die FWE eher als anaphylaktoide/immunologische Reaktion auf ins mütterliche Kreislaufsystem eingeschwemmtes Fruchtwasser/fetales Material verstanden ('Anaphylactoid Syndrome of Pregnancy'), nicht als reiner mechanischer Embolus. Klassische Trias: akute Hypoxie, kardiovaskulärer Kollaps/Hypotonie und Koagulopathie (DIC) – typischerweise peripartal, oft während oder kurz nach der Entbindung." },
  { id: "fc-spez-031", module: "spezielle-anaesthesie", subtopic: "geburtshilfe", front: "Wie wird eine Fruchtwasserembolie behandelt?", back: "Rein supportiv nach ABC-Schema, da keine spezifische Therapie existiert: sofortige CPR-Bereitschaft, hochdosierte Oxygenierung/Intubation, aggressive hämodynamische Unterstützung (Vasopressoren, ggf. ECMO bei therapierefraktärem Kreislaufversagen), frühzeitige und großzügige Substitution von Blutprodukten (EK, FFP, Fibrinogen/Thrombozyten) zur Beherrschung der DIC, und bei Herzstillstand vor Entbindung eine perimortale Sectio innerhalb weniger Minuten zur Verbesserung von mütterlichem und fetalem Outcome." },
];
